INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(1, 'Violet Evergarden Movie', 'Several years have passed since the end of The Great War. As the radio tower in Leidenschaftlich continues to be built, telephones will soon become more relevant, leading to a decline in demand for \"Auto Memory Dolls.\" Even so, Violet Evergarden continues to rise in fame after her constant success with writing letters. However, sometimes the one thing you long for is the one thing that does not appear.\n\nViolet Evergarden Movie follows Violet as she continues to comprehend the concept of emotion and the meaning of love. At the same time, she pursues a glimmer of hope that the man who once told her, \"I love you,\" may still be alive even after the many years that have passed.\n\n[Written by MAL Rewrite]', '2020-09-18', 'https://cdn.myanimelist.net/images/anime/1825/110716l.jpg', 'Award Winning, Drama', 'Anime'),
(2, 'Kageki Shoujo!!', 'After being forced to graduate from JPX48 following a controversial incident with a male fan, Ai Narata swears to never interact with another man ever again. Using her talents and strong desire to get away from men, Ai auditions for the exclusive all-female Kouka School of Musical and Theatrical Arts. The school is renowned for producing the best actresses that go on to perform in the famous all-female Kouka Theatre Troupe. Coming from the idol industry, Ai is the perfect candidate for the school\'s hundredth generation class, but her aloof demeanor alienates her from her classmates.\n\nThe eccentric Sarasa Watanabe is the only person who wishes to become Ai\'s friend. She enters Kouka with the goal of becoming a top \"otokoyaku\" performer—an actress that plays traditionally male roles. After seeing a Kouka performance of The Rose of Versailles when she was younger, Sarasa dreams of performing as Lady Oscar one day. Unfortunately, Sarasa\'s inability to read a room causes friction between her and her classmates, including Ai, who reluctantly becomes her roommate and partner in many of their classes. \n\nSucceeding at Kouka will involve more than just raw talent for these young girls as jealousy, deceit, and the harsh realities of show business put their mental fortitude to the test. Will Sarasa and Ai be able to rise to the top and stand on the silver bridge?\n\n[Written by MAL Rewrite]', '2021-07-04', 'https://cdn.myanimelist.net/images/anime/1944/114427l.jpg', 'Drama', 'Anime'),
(3, 'Bai Lian Cheng Shen 2nd Season', 'Second season of Bai Lian Cheng Shen.', '2023-12-08', 'https://cdn.myanimelist.net/images/anime/1393/139861l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(4, 'Soukyuu no Fafner: Dead Aggressor - The Beyond', NULL, '2019-05-17', 'https://cdn.myanimelist.net/images/anime/1512/94632l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(5, 'Arknights', 'A series of animated promotions for tower defense mobile game Arknights.', '2019-11-19', 'https://cdn.myanimelist.net/images/anime/1216/109447l.jpg', 'Action, Fantasy', 'Anime'),
(6, 'Overtake!', 'Ever since he published a picture that sparked a wave of online harassment, freelance photographer Kouya Madoka has lost everything: his wife Saeko Yukihira, his confidence, and his courage to photograph people. However, years later, a job offer introduces him to the exhilarating world of Formula 4 (F4). A single fierce battle between the amateur drivers in the junior category of open-wheel car racing becomes enough to make Madoka unable to put his camera down.\n\nWhen Komaki Motors\' Haruka Asahina bursts into tears on the track, Madoka manages to capture this vulnerable moment. This photo eventually leads Madoka to an impulsive decision: he will help sponsor both the Komaki team and Haruka himself. But the unreasonable costs of the sport quickly cause Madoka to reassess his ambitions, and he seeks different ways to support the severely underfunded F4 team. Despite the uphill battle, Madoka\'s determination for Haruka to succeed may be the trigger that can propel the young driver straight to the top.\n\n[Written by MAL Rewrite]', '2023-10-01', 'https://cdn.myanimelist.net/images/anime/1487/139955l.jpg', 'Drama', 'Anime'),
(7, 'Wu Shang Shen Di', 'Ten thousand years ago, the immortal king Muyun was conspired by others for holding the Zhu Xiantu. After ten thousand years of sleep, his remnant soul awakened on the famous \"Trash Muyun\" of the Southern Cloud Empire of the Heavenly Fate continent.\n\n(Source: LM ANIME)', '2020-05-18', 'https://cdn.myanimelist.net/images/anime/1845/108003l.jpg', 'Action, Adventure, Supernatural', 'Anime'),
(8, 'Seishun Buta Yarou wa Yumemiru Shoujo no Yume wo Minai', 'Six months ago, Sakuta Azusagawa had a chance encounter with a bunny girl in a library. Ever since then, he\'s been blissfully happy with his girlfriend: Mai Sakurajima, that same bunny girl. However, the reappearance of his mysterious first crush, the now-adult Shouko Makinohara, adds a new complication to his relationship with Mai. To make matters worse, he then encounters a middle school Shouko in the hospital, suffering from a grave illness. Mysteriously, his old scars begin throbbing whenever he\'s near her.\n\nWith Shouko\'s bizarre situation somehow revolving around him, Sakuta will need to come to terms with his own conflicting feelings, for better or worse. With a girl\'s life in his hands, just what can he do?\n\n[Written by MAL Rewrite]', '2019-06-15', 'https://cdn.myanimelist.net/images/anime/1613/102179l.jpg', 'Drama, Romance, Supernatural', 'Anime'),
(9, 'Tunshi Xingkong 3rd Season', 'Third season of Tunshi Xingkong.', '2022-09-14', 'https://cdn.myanimelist.net/images/anime/1250/138217l.jpg', 'Action, Adventure, Fantasy, Sci-Fi', 'Anime'),
(10, 'Puparia', 'Independent short animation by Shingo Tamagawa.', '2020-11-20', 'https://cdn.myanimelist.net/images/anime/1308/110285l.jpg', 'Avant Garde', 'Anime'),
(11, 'Shukusei!! Loli Kami Requiem ☆', 'Music video for the song Shukusei!! Loli Kami Requiem ☆ by Ui Shigure.', '2023-09-10', 'https://cdn.myanimelist.net/images/anime/1217/138638l.jpg', NULL, 'Anime'),
(12, 'Ane wa Yanmama Junyuu-chuu', 'This story about a married woman, as is usual in such stories sexually unsatisfied in married life, and decided to make up for lost time with her brother, who came to stay with her husband and children. What started as a harmless joke on a drunken bench, will grow into a constant frenzied sex always and everywhere, at any convenient opportunity.', '2020-06-05', 'https://cdn.myanimelist.net/images/anime/1810/105977l.jpg', 'Hentai', 'Anime'),
(13, 'Tenki no Ko', 'Tokyo is currently experiencing rain showers that seem to disrupt the usual pace of everyone living there to no end. Amidst this seemingly eternal downpour arrives the runaway high school student Hodaka Morishima, who struggles to financially support himself—ending up with a job at a small-time publisher. At the same time, the orphaned Hina Amano also strives to find work to sustain herself and her younger brother.\n\nBoth fates intertwine when Hodaka attempts to rescue Hina from shady men, deciding to run away together. Subsequently, Hodaka discovers that Hina has a strange yet astounding power: the ability to call out the sun whenever she prays for it. With Tokyo\'s unusual weather in mind, Hodaka sees the potential of this ability. He suggests that Hina should become a \"sunshine girl\"—someone who will clear the sky for people when they need it the most.\n\nThings begin looking up for them at first. However, it is common knowledge that power always comes with a hefty price...\n\n[Written by MAL Rewrite]', '2019-07-19', 'https://cdn.myanimelist.net/images/anime/1880/101146l.jpg', 'Award Winning, Drama, Romance, Supernatural', 'Anime'),
(14, 'Blue Lock vs. U-20 Japan', 'The next phase of the controversial Blue Lock project is underway with the candidate pool being dwindled down to just 35. Out of the remaining strikers, only a select few will be chosen to play in an upcoming exhibition game against the current U-20 Japanese soccer team. Playing in this match comes with a caveat: winning will grant the players the right to represent the nation as the new U-20 team, but losing will bring an end to Blue Lock in its entirety. Among the ones left in the running is Yoichi Isagi, who is coming to terms with his own abilities.\n\nTo further complicate matters, the six best players in the pool have already been named to the starting lineup and the remaining 29 will have to duke it out to claim a coveted spot. Each candidate must select a top six pairing to team up with for the selection to prove their competence. But if this mishmash of strikers wants to overthrow the current U-20 team, they will need to find a way to combine their playstyles effectively.\n\n[Written by MAL Rewrite]', '2024-10-06', 'https://cdn.myanimelist.net/images/anime/1584/144860l.jpg', 'Sports', 'Anime'),
(15, 'Shark\'d', 'Finding her life in the Lost City of Atlantis too boring, friendly but impulsive shark girl Gura Gawr swims to shore in search of fun. However, she soon finds out that she cannot enjoy life on the surface peacefully without clothes. Luckily, the nearby Blue Axolotl Beachwear shop presents Gura with a shark-themed outfit that speaks to her inner child.\n\nThanks to a flier posted for a Hololive Production audition, Gura has since become the internet\'s most beloved VTuber. But that has never stopped her origin story from being any less lovable than her YouTube antics.\n\n[Written by MAL Rewrite]', '2022-09-18', 'https://cdn.myanimelist.net/images/anime/1038/139632l.jpg', 'Comedy, Fantasy', 'Anime'),
(16, 'Bokura Mada Underground', 'Official music video for Eve\'s song Bokura Mada Underground from their album \"Otogi\" going on sale February 6, 2019.', '2019-01-24', 'https://cdn.myanimelist.net/images/anime/1477/98449l.jpg', NULL, 'Anime'),
(17, 'Nezha Zhi Mo Tong Jiang Shi', 'From the heavenly object known as the Chaos Pearl, two elements are extracted: the Spirit Pearl and the Demon Orb. In an attempt to suppress their power, the Lord of Heaven sends the Spirit Pearl to Earth to reincarnate as Ne Zha, the third son of Li Jing, while the Demon Orb is scheduled to be destroyed by a lightning strike. However, because of a conspiracy by the Dragon King to steal the Spirit Pearl for his own son, Ne Zha is instead reincarnated with the Demon Orb.\n\nWith no way to remove the cursed effects of the Demon Orb, Ne Zha is raised under the belief that he will become the great demon hunter the Spirit Pearl destined for him to be. Fighting against his chaotic and mischievous nature, Ne Zha must decide whether to accept his evil fate or rebel against it to prove he is worthy of the future his parents foretold.\n\n[Written by MAL Rewrite]', '2019-07-26', 'https://cdn.myanimelist.net/images/anime/1759/102055l.jpg', 'Action, Comedy, Drama, Fantasy', 'Anime'),
(18, 'Shuumatsu no Walküre II Part 2', 'Following the most recent brutal battle, the gods now hold the lead against mortals in the one-on-one tournament that will decide the fate of humanity. With three wins under the belt of the divine beings, the humans only have 10 matches left to save themselves from extermination. The Supreme God Zeus intends to take the upper hand by sending Buddha—a benevolent demigod loved by all of humanity—into the fray.\n\nIn a shocking twist, Buddha announces his intention to fight for humanity. Enraged by this betrayal, the gods call upon the Seven Gods of Fortune to take Buddha down. As their battle rages on, a mysterious entity manifests in the middle of the arena, throwing the entire competition into disarray.\n\n[Written by MAL Rewrite]', '2023-07-12', 'https://cdn.myanimelist.net/images/anime/1958/136099l.jpg', 'Action, Drama, Fantasy', 'Anime'),
(19, 'Jujutsu Kaisen 0 Movie', 'Violent misfortunes frequently occur around 16-year-old Yuuta Okkotsu, a timid victim of high school bullying. Yuuta is saddled with a monstrous curse, a power that dishes out brutal revenge against his bullies. Rika Orimoto, Yuuta\'s curse, is a shadow from his tragic childhood and a potentially lethal threat to anyone who dares wrong him.\n\nYuuta\'s unique situation catches the attention of Satoru Gojou, a powerful sorcerer who teaches at Tokyo Prefectural Jujutsu High School. Gojou sees immense potential in Yuuta, and he hopes to help the boy channel his deadly burden into a force for good. Yet Yuuta struggles to find his place among his talented classmates: the selectively mute Toge Inumaki, weapons expert Maki Zenin, and Panda.\n\nYuuta clumsily utilizes Rika on missions with the other first-year students, but the grisly aftermath of Rika\'s tremendous displays of power draws the interest of the calculating curse user Suguru Getou. As Getou strives to claim Rika\'s strength and use it to eliminate all non-jujutsu users from the world, Yuuta fights alongside his friends to stop the genocidal plot.\n\n[Written by MAL Rewrite]', '2021-12-24', 'https://cdn.myanimelist.net/images/anime/1121/119044l.jpg', 'Action, Supernatural', 'Anime'),
(20, 'Digimon Adventure: Last Evolution Kizuna', 'As the Chosen Children and their partner Digimon live happily together in the human world, Taichi Yagami and Yamato Ishida, alongside their friends, dedicate themselves to maintaining this hard-earned peace. Though united by this innate responsibility, each one has already started to take their first steps toward a future beyond being a Chosen Child. \n\nHowever, this new journey is interrupted by the appearance of Menoa Bellucci, an American professor specializing in Digimon research. She bears news of several Chosen Children from around the world being found comatose, with their partner Digimon nowhere to be found. Menoa\'s investigations indicate that a new breed of Digimon is behind the alarming phenomenon: Eosmon, who hides within the internet\'s depths. \n\nTo succeed in this mission, the team must endeavor through the growing distance between them and band together one last time.\n\n[Written by MAL Rewrite]', '2020-02-21', 'https://cdn.myanimelist.net/images/anime/1654/104884l.jpg', 'Action, Adventure, Comedy, Drama', 'Anime'),
(21, 'Kitarou Tanjou: Gegege no Nazo', 'A completely new feature-length animation commemorating the 100th anniversary of Shigeru Mizuki\'s birth. The story of Kitaro\'s father is revealed for the first time.\n\n(Source: Official site, translated)', '2023-11-17', 'https://cdn.myanimelist.net/images/anime/1643/138278l.jpg', 'Comedy, Supernatural', 'Anime'),
(22, 'Undead Girl Murder Farce', 'In 19th-century France, the wife of vampire noble Jean Duchet Godard is murdered in her own home. With the local human authorities unwilling to properly investigate the case, Godard hires a pair of private detectives known to specialize in the supernatural: Tsugaru Shinuchi, a man with a mysterious birdcage; and his partner, Aya Rindou. This enigmatic duo has come from faraway Japan for one purpose—to track down the man who stole both Aya\'s body and Tsugaru\'s humanity.\n\n[Written by MAL Rewrite]', '2023-07-06', 'https://cdn.myanimelist.net/images/anime/1946/136661l.jpg', 'Fantasy, Mystery', 'Anime'),
(23, 'High Score Girl: Extra Stage', 'Four years after they first met, Haruo Yaguchi , Akira Oono, and Koharu Hidaka remain the best of friends. Tensions start to build up as Akira\'s teacher, Gouda Moemi, becomes stricter than ever before, and Hidaka develops feelings for Haruo. Though he may not be the most composed and thoughtful person around, he has within him the one thing that started it all: his unconditional love for video games.\n\n[Written by MAL Rewrite]', '2019-03-20', 'https://cdn.myanimelist.net/images/anime/1057/111384l.jpg', 'Comedy, Romance', 'Anime'),
(24, 'Alien Stage', 'Humans once lived like Earth was the center of the universe. Some people embraced religion and believed that God would deliver them from suffering. After humanity was enslaved by aliens, no one spoke of God any longer.\n\nNow the grim truth is that humans are mere property of aliens. Recently, entering pet humans into the entertainment industry has become popular, and the biggest, most thrilling spectacle is known as Alien Stage. In this reality singing competition, alien sponsors flaunt their investments, while human contestants must battle to survive. No matter the relationship between opponents—whether it is love, hate, or something more extreme—only one victor can emerge each round.\n\n[Written by MAL Rewrite]', '2022-09-07', 'https://cdn.myanimelist.net/images/anime/1524/143502l.jpg', 'Drama, Sci-Fi, Suspense', 'Anime'),
(25, 'Bocchi the Rock!', 'Yearning to make friends and perform live with a band, lonely and socially anxious Hitori \"Bocchi\" Gotou devotes her time to playing the guitar. On a fateful day, Bocchi meets the outgoing drummer Nijika Ijichi, who invites her to join Kessoku Band when their guitarist, Ikuyo Kita, flees before their first show. Soon after, Bocchi meets her final bandmate—the cool bassist Ryou Yamada. \n\nAlthough their first performance together is subpar, the girls feel empowered by their shared love for music, and they are soon rejoined by Kita. Finding happiness in performing, Bocchi and her bandmates put their hearts into improving as musicians while making the most of their fleeting high school days.\n\n[Written by MAL Rewrite]', '2022-10-09', 'https://cdn.myanimelist.net/images/anime/1448/127956l.jpg', 'Comedy', 'Anime'),
(26, 'Watashi no Oshi wa Akuyaku Reijou.', 'Rei Oohashi is a burned-out office worker by day but otome game heroine Rae Taylor by night. After her long workdays, Rei immerses herself in the world of her favorite dating sim, Revolution, as a student at Bauer Kingdom\'s prestigious Royal Academy. Instead of focusing on the male love interests, Rei obsesses over the romantic rival: the game\'s villainess, Claire François. One evening, however, Rei\'s exhaustion catches up with her and she passes away.\n\nWhen Rei opens her eyes again, she finds herself reincarnated as Rae and in the presence of her beloved Claire. Given this miraculous opportunity, she wastes no time declaring her love for the golden-haired villainess and her endearing attempts at bullying. Winning Claire\'s heart is no easy feat, especially as the game persistently throws the three male leads at Rae—but she has no intention of allowing the dating sim logic to come between her and the one she truly loves.\n\n[Written by MAL Rewrite]', '2023-10-03', 'https://cdn.myanimelist.net/images/anime/1531/137711l.jpg', 'Comedy, Fantasy, Girls Love', 'Anime'),
(27, 'Teenage Blue', 'Music video for the song Teenage Blue by Eve. The song was used as the ending theme of the anime Ao no Hako.', '2024-11-22', 'https://cdn.myanimelist.net/images/anime/1761/147444l.jpg', NULL, 'Anime'),
(28, 'Kuraku Kuroku', 'Music video directed and animated by Koudai Watanabe for the song Kuraku Kuroku by ZUTOMAYO.', '2021-01-20', 'https://cdn.myanimelist.net/images/anime/1089/118595l.jpg', 'Supernatural', 'Anime'),
(29, 'Haikyuu!! To the Top Part 2', 'Once called a fallen powerhouse and known as \"Flightless Crows,\" Karasuno High School has finally taken flight at nationals. With a comprehensive performance against Tsubakihara Academy in their first match, the team is now facing its toughest opponent yet: the runners-up of the last Spring Tournament, Inarizaki High School. Furthermore, dealing with the formidable twin Miya brothers only makes things more difficult for Karasuno.\n\nAs soon as the match begins, Karasuno is overwhelmed by all the noise and jeers from the supporters of Inarizaki High but rekindles its strength thanks to its own loyal fans. Karasuno also gains some momentum by utilizing an attack centered on Shouyou Hinata, but the eccentric play of Atsumu and Osamu Miya delivers an unexpected blow that leaves their opponent astounded.\n\nThings are bound to get intense as the match progresses between these two teams. Will Karasuno be able to defeat Inarizaki High and overcome the hurdles that threaten its pursuit to the top?\n\n[Written by MAL Rewrite]', '2020-10-03', 'https://cdn.myanimelist.net/images/anime/1453/106768l.jpg', 'Sports', 'Anime'),
(30, 'Tsugu Tsugumomo', 'When \"ordinary boy\" Kagami Kazuya meets the beautiful tsukumogami Kiriha, his life gets turned upside-down. As a \"Taboo Child\" who draws the supernatural towards him, he receives orders from the God of the Land, Kukuri, to become an exorcist and defeat these evil forces. And so, he and Kiriha do battle.\n\nTo find out information on these supernatural beings, Kazuya and his friends set up a counselor\'s club at school. But behind the typical-seeming troubles he hears about, he uncovers a major plot to target Kukuri...\n\nIn addition to the sadistic-yet-beautiful tsukumogami Kiriha, the situation draws other girls to Kazuya to join the fray!\n\n(Source: Crunchyroll)', '2020-04-05', 'https://cdn.myanimelist.net/images/anime/1997/106184l.jpg', 'Action, Comedy, Supernatural, Ecchi', 'Anime'),
(31, 'Boku ni Harem Sexfriend ga Dekita Riyuu', NULL, '2024-06-28', 'https://cdn.myanimelist.net/images/anime/1875/142717l.jpg', 'Hentai', 'Anime'),
(32, 'Bishoujo Senshi Sailor Moon Eternal Movie 2', 'The threat of the Dead Moon Circus still looms over Usagi Tsukino and the Sailor Guardians. Driven into a corner, the Earth plunges further into darkness as nightmares continue to spread. The Outer Sailor Guardians sense that something is amiss when the young Hotaru Tomoe begins to rapidly age following the total solar eclipse. Believing that their prince and princess are in danger, the four reawaken their powers once more to reunite and aid their fellow Sailor Guardians. \n\nDue to the influence of the eclipse, Usagi and Mamoru Chiba\'s conditions begin to worsen, causing their powers to deteriorate. Without their leader, the Guardians are at a loss as to what they should do next. Frustrated by the situation, Hotaru and Chibiusa set off on their own to confront the Amazoness Quartet, who have been causing the brunt of the chaos thus far. As Queen Nehelenia\'s liberation quickly approaches, the Sailor Guardians are running out of time to stop her.\n\n[Written by MAL Rewrite]', '2021-02-11', 'https://cdn.myanimelist.net/images/anime/1710/111094l.jpg', 'Romance', 'Anime'),
(33, 'Meitantei Conan: Haibara Ai Monogatari - Kurogane no Mystery Train', 'The movie will focus on Ai Haibara\'s past and will reconstruct the Mystery Train arc from the television anime, which shows Haibara and Conan meeting for the first time. The movie will also include scenes from the Kurogane no Submarine (Black Iron Submarine) movie.\n\n(Source: MAL News)', '2023-01-06', 'https://cdn.myanimelist.net/images/anime/1285/131672l.jpg', 'Mystery', 'Anime'),
(34, 'Shinkiro', 'Music video for the song Shinkiro by Houshou Marine and Gawr Gura.', '2023-11-12', 'https://cdn.myanimelist.net/images/anime/1225/139618l.jpg', 'Slice of Life', 'Anime'),
(35, 'The iDOLM@STER Cinderella Girls: U149', 'Mature grade school student Arisu Tachibana is an aspiring idol who receives an invitation from her company president to participate in the Third Entertainment Section—a new idol project. Arisu and eight other young girls soon meet their producer before beginning idol-related activities.\n\nTo the girls\' surprise, their producer appears to be a childlike adult and nothing like what they had imagined. The producer, who is taking on the position for the first time, also had no idea that he would be meeting a group of short, young idols. The awkward situation leaves Arisu disappointed, and she wishes for a producer change.\n\nHowever, the producer, with his genuine love for idols and his desire to see them shine, will not let this opportunity pass and expresses that he is serious about working with the girls. Thankfully, the young idols accept the producer after seeing his unwavering passion for idols, serving as the start of their journey to the stage of dreams.\n\n[Written by MAL Rewrite]', '2023-04-06', 'https://cdn.myanimelist.net/images/anime/1875/133377l.jpg', 'Slice of Life', 'Anime'),
(36, 'Gridman Universe', 'A year has passed since the events of SSSS.Gridman. The world is at peace and no one except for Rikka and Utsumi remembers the kaiju, Gridman, or Akane Shinjou. This includes Yuuta, who despite serving as Gridman\'s host, has no memory of the most important moments of his life. So when a new Kaiju appears, he leaps at the chance to prove to himself that he too can be the hero by merging with Gridman once more.\n\n(Source: ANN)', '2023-03-24', 'https://cdn.myanimelist.net/images/anime/1897/133657l.jpg', 'Action, Sci-Fi', 'Anime'),
(37, 'Hataraku Saibou!!', 'The cells of the human body never rest for too long; there\'s always something new to do and learn every day. At least, that\'s what Hakkekkyuu U-1146 feels as he rushes to and fro, searching for any pathogens that could cause harm to the body. Despite his dangerous line of work, it\'s all worth it to protect the happy smiles of Sekkekkyuu AE3803, the platelet crew, his fellow neutrophils, and the other cells he meets along the way. \n\nIn his latest pathogen-hunting adventures, Hakkekkyuu U-1146 discovers how important cells can sometimes make mistakes, and that not all bacteria are actually bad. Everybody has their bad days, but everything eventually works out when their comrades have their backs. In the end, it\'s just another normal day for these hardworking cells!\n\n[Written by MAL Rewrite]', '2021-01-09', 'https://cdn.myanimelist.net/images/anime/1726/114552l.jpg', 'Comedy', 'Anime'),
(38, 'Shingeki no Kyojin: The Final Season Part 2', 'Turning against his former allies and enemies alike, Eren Yeager sets a disastrous plan in motion. Under the guidance of the Beast Titan, Zeke, Eren takes extreme measures to end the ancient conflict between Marley and Eldia—but his true intentions remain a mystery. Delving deep into his family\'s past, Eren fights to control his own destiny.\n\nMeanwhile, the long-feuding nations of Marley and Eldia utilize both soldiers and Titans in a brutal race to eliminate the other. Reiner Braun uses his own powers in a desperate bid to hold off Eren\'s own militaristic force, and his fellow Eldians—children Falco Grice and Gabi Braun—struggle to survive in the unfolding chaos.\n\nElsewhere, Eren\'s childhood friends Mikasa Ackerman and Armin Arlert remain imprisoned alongside Eren\'s former Survey Corps companions, all disturbed by Eren\'s monstrous transformation. Under the blind belief that Eren still secretly harbors good intentions, Mikasa and the others enter the fray in an attempt to save their friend\'s very soul.\n\n[Written by MAL Rewrite]', '2022-01-10', 'https://cdn.myanimelist.net/images/anime/1948/120625l.jpg', 'Action, Drama, Suspense', 'Anime'),
(39, 'Mahoutsukai no Yome: Nishi no Shounen to Seiran no Kishi', 'Every several decades, the Wild Hunt—a group of mounted fae knights—awakens and roams the land, its presence causing old plants to wither and allowing new ones to take their place. Unfortunately, when lightning strikes the stone monument that the Wild Hunt slumbers in, it chips off a fragment containing the band\'s guide. As a result, when the Wild Hunt rises once more, its members cannot maintain their formation, instead aimlessly wandering the forests and leaving death in their wake.\n\nIn an attempt to remedy this predicament, Spriggan tasks Elias Ainsworth with bringing the missing guide\'s steed back to its master. Meanwhile, Gabriel, an asthmatic young boy who longs for adventure, discovers the chipped-off rock and ends up summoning the knight within. With his only intact memory being the desire to return, the guide must reunite with his steed and his pack before his absence can cause irreparable damage.\n\n[Written by MAL Rewrite]', '2021-09-10', 'https://cdn.myanimelist.net/images/anime/1534/129413l.jpg', 'Drama, Fantasy', 'Anime'),
(40, 'Yahari Ore no Seishun Love Comedy wa Machigatteiru. Kan: Dakara, Shishunki wa Owarazu ni, Seishun wa Tsuzuiteiku.', 'Yahari Ore no Seishun Love Comedy wa Machigatteiru. Kan: Dakara, Shishunki wa Owarazu ni, Seishun wa Tsuzuiteiku. adapts selected events from the Shin bonus novels that were released with the Season 3 BDs.', '2023-04-27', 'https://cdn.myanimelist.net/images/anime/1334/132921l.jpg', 'Comedy, Romance', 'Anime'),
(41, 'Nomad: Megalo Box 2', 'Megalo Box is an advanced form of boxing where competitors wear metal frames called Gear. When the first ever Megalonia tournament took place, \"Gearless\" Joe became its champion and known to all as a legendary fighter. However, soon after, he lost an exhibition match against the second champion and vanished from the public eye.\n\nSeven years later, Joe now goes by \"Nomad\" and keeps a low profile, occasionally fighting in a few underground matches to get by. He is haunted by hallucinations and relies on a set of painkillers to numb his mind.\n\nDuring a match, Joe wins against an opponent, Chief, who purposefully loses for some extra cash from gamblers. Subsequently, Joe discovers that Chief is from a community of immigrants called the Casa. Chief is gradually trying to make enough money to purchase the land where they live illegally. At first, Joe hesitates to get involved, but eventually decides to lend the Casa a helping hand.\n\n[Written by MAL Rewrite]', '2021-04-04', 'https://cdn.myanimelist.net/images/anime/1190/113352l.jpg', 'Sci-Fi, Sports', 'Anime'),
(42, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV: Shin Shou - Yakusai-hen', 'Second part of Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV.', '2023-01-07', 'https://cdn.myanimelist.net/images/anime/1476/128693l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(43, 'Ghost (Music)', 'A new original song and music video to celebrate Suisei\'s 3rd Anniversary. Ghost was first revealed and sung at the end of Suisei\'s 4th YouTube live concert, SPACE for Virtual GHOST.\n\n(Source: Anilist)', '2021-04-13', 'https://cdn.myanimelist.net/images/anime/1220/118565l.jpg', NULL, 'Anime'),
(44, 'Feng Ling Yu Xiu 2nd Season', NULL, '2023-07-02', 'https://cdn.myanimelist.net/images/anime/1634/136523l.jpg', 'Action, Adventure', 'Anime'),
(45, 'Spy x Family Movie: Code: White', 'Loid Forger, an elite spy, is warned by his handler that he may potentially be reassigned from his ongoing mission, Operation Strix. To maintain his position, he must make significant progress toward the operation\'s objectives, which involves having his adoptive daughter Anya earn sufficient Stella Stars to become an Imperial Scholar at Eden Academy.\n\nAfter learning of a cooking contest that awards the winning student with a Stella Star, Loid researches the judge\'s preferred dessert to help increase Anya\'s odds. However, perfectly recreating the judge\'s favorite meremere requires more than just following a recipe. Thus, the Forgers embark on a vacation to the Frigis region to try an authentic meremere. Not all goes smoothly on the trip, as the Forger family ends up entwined in a sinister plot to reignite war between the countries of Ostania and Westalis.\n\n[Written by MAL Rewrite]', '2023-12-22', 'https://cdn.myanimelist.net/images/anime/1426/139388l.jpg', 'Action, Comedy', 'Anime'),
(46, 'Machikado Mazoku', 'After a strange dream of a mysterious ancestor, high school student Yuuko Yoshida wakes to see that she has grown demonic horns and a tail. Dazed and confused, her mother reveals to her a dark family secret: her family is descended from a Dark Clan that was banished to live powerless and destitute by their mortal enemies, the magical girls of the Light Clan. The only way to lift their ancestry\'s curse is for Yuuko to find a magical girl, murder her, and splatter her blood all over her ancestor\'s Demon God statue.\n\nFortunately for \"Shadow Mistress Yuuko,\" a magical girl saves her from being run over by an oncoming truck. Unfortunately, Momo Chiyoda happens to be Yuuko\'s classmate at Sakuragaoka High and is much stronger than her in both strength and endurance. Taking pity on her wimpy assailant, the magical girl agrees to train Yuuko and help her unlock her dormant powers. Now, Yuuko must rise up and defeat her generous frenemy to save her family from the terrible grip of poverty.\n\n[Written by MAL Rewrite]', '2019-07-12', 'https://cdn.myanimelist.net/images/anime/1633/111518l.jpg', 'Comedy', 'Anime'),
(47, 'Aishang Ta de Liyou Extra', NULL, '2024-02-13', 'https://cdn.myanimelist.net/images/anime/1569/141456l.jpg', 'Romance', 'Anime'),
(48, 'Sasaki to Miyano: Koi ni Kizuku Mae no Chotto Shita Hanashi.', 'After returning from a field trip, Yoshikazu Miyano—along with his friends—is ready to take over the Discipline Committee. But when a student loses their keychain, the now former chairman Masato Hanzawa uses this opportunity to create the First Lost Item Detective Squad in order to find the misplaced belonging.\n\nAmidst all this, Shuumei Sasaki is trying to determine how to define his relationship with Miyano going forward. Hoping to be helpful to Miyano, he joins the search party. Yet, even with Sasaki on board, the investigation remains unsuccessful. The group must continue to look everywhere and solve the mystery surrounding the keychain soon—as they discover that many more items have gone missing.\n\n[Written by MAL Rewrite]', '2022-07-27', 'https://cdn.myanimelist.net/images/anime/1669/145956l.jpg', 'Boys Love', 'Anime'),
(49, 'Mushoku Tensei II: Isekai Ittara Honki Dasu - Shugo Jutsushi Fitz', 'In the immediate aftermath of the mana calamity, Sylphiette finds herself teleported to the heart of the Asura Kingdom: the royal palace. Her sudden appearance accidentally saves the life of second princess Ariel Anemoi Asura, who has her sights set on becoming the ruler of the realm. Witnessing Sylphiette\'s talent with combat magic firsthand, Ariel recruits her as her bodyguard and right-hand woman, commencing their journey to power—which proves far more treacherous than first imagined.\n\n[Written by MAL Rewrite]', '2023-07-03', 'https://cdn.myanimelist.net/images/anime/1627/136934l.jpg', 'Adventure, Drama, Fantasy, Ecchi', 'Anime'),
(50, 'Kyuuketsuki Sugu Shinu 2', 'Second season of Kyuuketsuki Sugu Shinu.', '2023-01-09', 'https://cdn.myanimelist.net/images/anime/1254/131832l.jpg', 'Comedy, Fantasy', 'Anime'),
(51, 'Yuan Long', 'Special Forces Wang Sheng traveled to the soul world and was possessed by the waste carp Yuan soul, becoming a veritable waste person in the soul world. Wang Sheng used the knowledge he had learned in the world of master spirits like Yun Yuan to pass the battle, and even found a way to evolve the waste carp Yuan soul! The sparrow becomes a phoenix, and the carp leaps to the dragon gate. Wang Sheng has embarked on a road of Jackie Chan from the sinister soul dispute!\n\n(Source: Immortal Sun Scans)', '2020-07-11', 'https://cdn.myanimelist.net/images/anime/1430/108208l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(52, 'Saenai Heroine no Sodatekata Fine', 'With the second Winter Comiket just around the corner, Blessing Software has been vigorously producing its new game, \"How to Raise a Boring Girlfriend.\" Despite Utaha Kasumigaoka and Eriri Spencer Sawamura leaving the circle, Megumi Katou and Tomoya Aki are hopeful that, by sticking to Tomoya\'s original vision for the game, their upcoming creation will exceed Blessing Software\'s previous installment.\n\nWith the addition of new members Iori and Izumi Hashima, development ensues—but not without its share of setbacks. Things rarely go as planned in the dating sim industry, with numerous obstacles forcing Tomoya to decide between helping his friends or completing the game. \n\nSaenai Heroine no Sodatekata Fine draws the series to a close as Tomoya selects his final route, both within his personal life and Blessing Software.\n\n[Written by MAL Rewrite]', '2019-10-26', 'https://cdn.myanimelist.net/images/anime/1671/111411l.jpg', 'Comedy, Romance', 'Anime'),
(53, 'Wu Dong Qian Kun 2nd Season', 'Second season of Wu Dong Qian Kun.', '2020-07-12', 'https://cdn.myanimelist.net/images/anime/1288/108277l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(54, 'Boku no Hero Academia 6th Season', 'With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin \"Twice\" Bubaigawara and Gigantomachia.\n\nAs new intel from the covert hero Keigo \"Hawks\" Takami confirms that Shigaraki is nowhere to be seen, the Hero Association decides to strike the enemy headquarters with a surprise attack using the entirety of its assets—and the UA students find themselves on the battlefield once again. As the fight rages on, the unsuspecting villains must regroup and push back, but the brave heroes are determined to eradicate every last one of them.\n\n[Written by MAL Rewrite]', '2022-10-01', 'https://cdn.myanimelist.net/images/anime/1483/126005l.jpg', 'Action', 'Anime'),
(55, 'Cheng He Titong', 'Yu Wanyin is teleported into a novel about palace struggles. The female protagonist of the novel is also teleported into it. To reverse her fate as a villain, Yu Wanyin chooses to join forces with a tyrant, who also turns out to be a modern man teleported in. Yu Wanyin hopes for the three modern people to put aside the palace struggles and just play cards and eat hotpot together peacefully. However, the female protagonist believes she is the chosen one, and still chooses to go against Yu Wanyin and the male protagonist King Duan\'s team. Thus, Yu Wanyin has to carry out a series of actions in order to survive and help Xia dynasty prevent the drought crisis...\n\n(Source: Iqiyi EN)', '2024-06-14', 'https://cdn.myanimelist.net/images/anime/1340/143445l.jpg', 'Comedy, Romance', 'Anime'),
(56, 'Jin Zhan Fashi', 'It mainly tells the story of Gu Fei, a super warrior but a physical education teacher in school. He started playing online games on the recommendation of his students, but he mistakenly chose the profession of mage, and finally became a melee violent mage, embarking on a new game path. \n\n(Source: Tencent, Google translated)', '2023-11-02', 'https://cdn.myanimelist.net/images/anime/1228/139235l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(57, 'Ensemble Stars!! Tsuioku Selection Element', 'New Ensemble Stars!! web animated series based on the game story \"Element\".', '2023-04-06', 'https://cdn.myanimelist.net/images/anime/1328/133039l.jpg', NULL, 'Anime'),
(58, 'Tiger & Bunny 2', 'With Kotetsu back on the First League, the buddy system is now the big new project of HeroTV. Two heroes fighting crime back to back due to the popularity of the famous duo: Wild Tiger and Barnaby Brooks Jr.\n\nWith new heroes protecting Sternbild City, the ability of both veteran and rookies will be put to the test as they find what it means to rely on others to do to what is best for the city they are trying to protect.', '2022-04-08', 'https://cdn.myanimelist.net/images/anime/1678/121388l.jpg', 'Action, Comedy, Mystery, Sci-Fi', 'Anime'),
(59, 'Dead Mount Death Play', 'A powerful necromancer known as the Corpse God dies during a legendary battle, only to be reborn as Polka Shinoyama, a young boy in modern-day Tokyo. In the process of trying to adapt to his new physical body, he gets targeted by various groups that deal with the supernatural. Among them is Misaki Sakimiya, a high school girl who can see spirits and is out for his blood from the very moment they meet.\n\nAttempting to make sense of this situation where unknown parties want him dead, Polka eventually meets Takumi Kuruya, a contractor skilled in surveillance and hacking, and Lisa Kuraki, a crime boss operating out of Shinjuku. Alongside these—and other unexpected—allies, Polka braves danger to reveal the truth of his reincarnation and the fate awaiting the world he now lives in.\n\n[Written by MAL Rewrite]', '2023-04-11', 'https://cdn.myanimelist.net/images/anime/1930/133758l.jpg', 'Action, Fantasy', 'Anime'),
(60, 'Re:Zero kara Hajimeru Isekai Seikatsu 3rd Season', 'One year after the events at the Sanctuary, Subaru Natsuki trains hard to better face future challenges. The peaceful days come to an end when Emilia receives an invitation to a meeting in the Watergate City of Priestella from none other than Anastasia Hoshin, one of her rivals in the royal selection. Considering the meeting\'s significance and the potential dangers Emilia could face, Subaru and his friends accompany her.\n\nHowever, as Subaru reconnects with old associates and companions in Priestella, new formidable foes emerge. Driven by fanatical motivations and engaging in ruthless methods to achieve their ambitions, the new enemy targets Emilia and threaten the very existence of the city. Rallying his allies, Subaru must give his all once more to stop their nefarious goals from becoming a concrete reality.\n\n[Written by MAL Rewrite]', '2024-10-02', 'https://cdn.myanimelist.net/images/anime/1706/144725l.jpg', 'Drama, Fantasy, Suspense', 'Anime'),
(61, 'Hanhua Riji', 'In the twenty-first century, gods and demons can no longer maintain equilibrium due to the rapid development of people in society. In an effort to restore proper order, the gods began to take care of the world, for which they will send a group of gods and monsters to the world to find the \"key\" to salvation. Su Moting is a girl with the personality of a \"demon child\". When her parents asked her to leave their house so that she could become independent, the girl meets the beautiful and charming god Tianjin and the mysterious demon cat Dukui. So begins the new hectic life of Su Moting.', '2019-07-21', 'https://cdn.myanimelist.net/images/anime/1042/100435l.jpg', 'Comedy, Slice of Life, Supernatural', 'Anime'),
(62, 'Oshi ga Budoukan Ittekuretara Shinu', 'After receiving a flyer from Maina Ichii—a member of the idol group ChamJam—and seeing her perform at a local concert, Eripiyo falls in love with Maina and decides to devote her life to supporting the shy and reserved rising star. Eripiyo\'s charismatic presence and iconic red tracksuit soon give her recognition as Maina\'s one and only unrivaled fan. \n\nWhether it be a performance or a small fan gathering in the middle of nowhere, Eripiyo is guaranteed to be at every event Maina participates in. Not even an injury or Maina\'s seemingly cold attitude toward her can stop Eripiyo from pursuing her dream of seeing her beloved idol perform at the world-famous arena Budoukan.\n\n[Written by MAL Rewrite]', '2020-01-10', 'https://cdn.myanimelist.net/images/anime/1139/104708l.jpg', 'Comedy', 'Anime'),
(63, 'Boukyaku Battery (TV)', 'Haruka Kiyomine and Kei Kaname were once recognized as the most formidable pitcher-catcher duo in middle school baseball. Known as the \"General,\" Kaname paired his expert strategies with Kiyomine\'s explosive pitches, crushing the dreams of many starry-eyed players who hoped to one day make it to the big leagues.\n\nHigh school freshman Tarou Yamada is one such former player. Having given up on competing, he enrolls in Kotesashi High School—a completely average public school with no baseball team to speak of—where he discovers that his new classmates are the legendary pair who once destroyed his dreams. Adding to this shocking revelation, he learns that amnesia has reduced the once level-headed General to a vulgar class clown. Having lost all interest in baseball, Kaname dragged a disappointed Kiyomine to Kotesashi simply because the school was close to where they live.\n\nAs Kotesashi forms a fledgling baseball club, Yamada meets other players he once admired who also left baseball behind. While they might be unwilling now, Yamada believes that if he can convince such talented athletes to start playing again, it might be possible to achieve their dreams and win the national championship—as long as they can put up with Kaname\'s incessant joking.\n\n[Written by MAL Rewrite]', '2024-04-10', 'https://cdn.myanimelist.net/images/anime/1372/142242l.jpg', 'Comedy, Sports', 'Anime'),
(64, 'Heya Camp△', 'During an Outdoor Activities Club meeting, Nadeshiko Kagamihara, Aoi Inuyama, and Chiaki Oogaki debate what it means to be a real Yamanashi native. Somewhere along the line, Chiaki brings up the Yamanashi Kids\' Stamp Rally, which Nadeshiko has never heard of. The rally encourages one to visit famous places in the prefecture and collect stamps; those who complete the rally will win a year\'s worth of Minobu steamed buns. Enticed by the humongous food prize, Nadeshiko is set on participating.\n\nFollow the Outdoor Activities Club as they travel around the Yamanashi prefecture to collect stamps and explore what the region has to offer!\n\n[Written by MAL Rewrite]', '2020-01-06', 'https://cdn.myanimelist.net/images/anime/1228/104364l.jpg', 'Slice of Life', 'Anime'),
(65, 'Hoshiai no Sora', 'Constantly outperformed by the girls\' club, the boys\' soft tennis club faces disbandment due to their poor skills and lack of positive results in matches. In desperate need of members, Touma Shinjou is looking to recruit capable players, but he fails to scout anyone. Enter Maki Katsuragi, a new transfer student who demonstrates great reflexes when he catches a stray cat in his classroom, instantly capturing Touma\'s attention. With his interest piqued, Touma ambitiously asks Maki to join the boys\' team but is quickly rejected, as Maki doesn\'t wish to join any clubs. Touma refuses to back down and ends up persuading Maki—only under the condition that Touma will pay him for his participation and cover other club expenses. \n\nMaki joins the team, and his incredible form and quick learning allow him to immediately outshine the rest of the team. Although this gives rise to conflict among the boys, Maki challenges and pushes his fellow team members to not only keep up with his seemingly natural talent, but also drive them to devote themselves to the game they once neglected. \n\nAs the members of the boys\' soft tennis club discover their own capabilities, they endure personal hardships and deal with the darker side of growing up in middle school.\n\n[Written by MAL Rewrite]', '2019-10-11', 'https://cdn.myanimelist.net/images/anime/1807/103081l.jpg', 'Drama, Sports', 'Anime'),
(66, 'Tokyo Revengers: Tenjiku-hen', 'After succeeding in their winter conflict against Taiju Shiba and his Black Dragons, the Tokyo Manji Gang absorbs their group\'s remaining members. Due to his heroic courage and indomitable spirit, Takemichi Hanagaki should have accomplished his goal of defeating the tragic fate awaiting his girlfriend, Hinata Tachibana.\n\nIn reality, Takemichi\'s troubles are far from over. Although Takemichi\'s actions have exposed Tetta Kisaki\'s treachery, the conniving schemer has found power elsewhere: Tenjiku, a dangerous gang led by the enigmatic Izana Kurokawa. Izana sets his sights on Manjirou \"Mikey\" Sano, pursuing a vicious interest in the Tokyo Manji Gang\'s aloof leader.\n\nIn the future, Takemichi discovers that the machinations of Izana and Kisaki led to Mikey\'s moral ruin—a downfall that directly results in Hinata\'s death. Unfortunately, a terrible loss robs Takemichi of his time-leaping ability, stranding him in the past with one final chance to rescue everyone he loves.\n\n[Written by MAL Rewrite]', '2023-10-04', 'https://cdn.myanimelist.net/images/anime/1853/139843l.jpg', 'Action, Drama', 'Anime'),
(67, 'Bai Yao Pu 4th Season', 'Fourth season of Bai Yao Pu.', '2024-02-23', 'https://cdn.myanimelist.net/images/anime/1523/145774l.jpg', 'Adventure, Mystery, Supernatural', 'Anime'),
(68, 'Boku no Hero Academia the Movie 2: Heroes:Rising - Epilogue Plus - Yume wo Genjitsu ni', 'A picture drama epilogue to the film Boku no Hero Academia the Movie 2: Heroes:Rising, bundled with the BD/DVD release.', '2020-07-15', 'https://cdn.myanimelist.net/images/anime/1447/110165l.jpg', 'Comedy', 'Anime'),
(69, 'Uramichi Oniisan', 'In the studio of the morning childrens\' show \"Together with Mama,\" a crew of miserable adults prepares their facades of amicable smiles and cheerful exteriors to educate a group of innocent preschoolers. In the middle of it stands Uramichi Omota, a former gymnast who can\'t help but bring the kids down to earth by revealing the harsh and depressing reality of adulthood, even in front of the rolling cameras.\n\nBehind the scenes, Uramichi\'s much-desired peace is disturbed by his two bothersome juniors who work as the show\'s rabbit and bear mascots and singers: Utano Tadano, a woman who only wishes to get married; and Iketeru Daga, a handsome man with a crass sense of humor. From smoking and exercising to nihilistic outbursts, everyone\'s big brother Uramichi always brings up the not-so-moral side to his life lessons.\n\n[Written by MAL Rewrite]', '2021-07-06', 'https://cdn.myanimelist.net/images/anime/1126/115635l.jpg', 'Comedy', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(70, 'Look Back', 'Ayumu Fujino may only be in the fourth grade, but she already basks in high praise for her hand-drawn four-panel comics featured in the school\'s newspaper. However, when she is asked to share the page with Kyoumoto—a reclusive student she has never met—Fujino feels inadequate for the first time: her free-spirited drawings look embarrassingly amateurish next to Kyoumoto\'s breathtakingly detailed art.\n\nFor a year, Fujino shuts out the world, obsessively studying manga creation and drawing tirelessly to catch up to her faceless competition. But Kyoumoto\'s talent far exceeds hers, and Fujino quits it all. Another year passes, and on the day of their graduation, Fujino finally meets Kyoumoto. This unkempt, shy, and stuttering girl has actually been Fujino\'s biggest fan all along. Their encounter reignites Fujino\'s passion for art and sparks the beginning of a years-long friendship built on rivalry, admiration, and their shared love of manga.\n\n[Written by MAL Rewrite]', '2024-06-28', 'https://cdn.myanimelist.net/images/anime/1716/142633l.jpg', 'Drama', 'Anime'),
(71, 'Saimin Seishidou', 'Hajime Tanaka possesses powers quite unlike that of other students. Thanks to his hypnotic abilities, he can impose his will upon any individual he comes in contact with. He uses this skill to convince a government official to appoint him as a \"Sex Counsellor.\" Consequently, his word is absolute when it comes to sexual matters. Instituted by his new jurisdiction, every couple must undergo counseling under Hajime\'s watchful eye before engaging in any form of romantic activity.\n\nThe first couple to visit Hajime are Yui Obata and Daiki Tachibana. With unwavering hypnosis-induced faith in their Sex Counsellor, Yui subjects herself to the careful inspection of Hajime. Meanwhile, her boyfriend watches them attentively and records their intercourse so as not to miss out on any precious snippet of wisdom.\n\n[Written by MAL Rewrite]', '2019-02-01', 'https://cdn.myanimelist.net/images/anime/1008/103757l.jpg', 'Hentai', 'Anime'),
(72, 'Gimai Seikatsu', 'Yuuta Asamura gets a new stepsister after his father remarries, Saki Ayase, who happens to be the number one beauty of the school year. They promise each other not to be too close, not to be too opposing, and to simply keep a vague and comfortable distance, having learned important values about men and women relationships from their parents\' previous ones.\n\nSaki, who has worked alone for the sake of her family, doesn\'t know how to properly rely on others, whereas Yuuta is unsure of how to truly treat her. Standing on fairly equal ground, these two gradually learn the comfort of living together.\n\nTheir relationship progresses from strangers to friends as the days pass. This is a story that may one day lead to love.\n\n(Source: MAL News)', '2024-07-04', 'https://cdn.myanimelist.net/images/anime/1420/143707l.jpg', 'Romance', 'Anime'),
(73, 'Haikyuu!! (OVA)', 'A stop-motion anime that will bundle with the 42nd compiled book volume of Haruichi Furudate\'s Haikyu!! manga. Anime will have 10 short episodes featuring the Karasuno team as puppets.\n\n(Source: ANN)', '2020-03-04', 'https://cdn.myanimelist.net/images/anime/1618/102929l.jpg', 'Sports', 'Anime'),
(74, 'Macross Δ Movie 2: Zettai Live!!!', 'Walküre and Delta Flight used music to save people from the Vár Syndrome, a previously unknown disease that made humans and others go berserk. However, they find themselves facing a new threat…\n\n(Source: ANN)', '2021-10-08', 'https://cdn.myanimelist.net/images/anime/1687/117888l.jpg', 'Action, Sci-Fi', 'Anime'),
(75, 'Radiant 2nd Season', 'After fleeing from Rumble Town, Seth, Doc and Melie are back at the Artemis Institute. Thanks to Alma, Seth learns more about Piodon, his mysterious brother. But the quest for the Nemeses mythical nest Radiant has already waited too long, so the Horned Boy and his friends head to the island-continent of the Wizard Knights.\n\nThis location may be a new city for audiences, but it\'s a decaying world that\'s falling apart! Not only must Seth deal with these hardships, but he must also face a personal phenomenon where visions are invading his mind a little more each day.\n\n(Source: monstersandcritics)', '2019-10-02', 'https://cdn.myanimelist.net/images/anime/1974/108398l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(76, 'Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen 3rd Season', 'Winter is approaching, and Myne—now an apprentice priestess—must prepare for her stay at the church and the upcoming Dedication Ceremony. However, due to her immense knowledge and extraordinary amount of mana, she has garnered the attention of many dangerous people, who are willing to do anything to get their hands on Myne.\n\nTo keep her safe, the Head Priest assigns Myne a bodyguard and advises her to be adopted by a noble, a decision that will force her to leave her family behind. As Myne is opposed to the idea, the Head Priest gives her an ultimatum: she can be with her family until she turns 10, but if she is deemed too unstable, she will immediately be dealt with.\n\nPlaced in a tough position, Myne is uncertain about her future. Despite the twists that may lie ahead, she will do whatever she can to protect those that she loves—even if it means giving up on her dream.\n\n[Written by MAL Rewrite]', '2022-04-12', 'https://cdn.myanimelist.net/images/anime/1976/122302l.jpg', 'Fantasy', 'Anime'),
(77, 'Shiguang Dailiren: Yingdu Pian', 'Lu Guang loses everything when a mysterious man bursts into the photo studio that he is renting with his close friend Cheng Xiaoshi. The man, who comes to punish the members at the studio for playing with time, murders both Qiao Ling and Cheng Xiaoshi in cold blood. However, Lu Guang inherits his friend\'s power to go back in time and decides to save everyone from their grim fate.\n\nNow in the past, Lu Guang travels to Bridon to help Cheng Xiaoshi investigate his father\'s whereabouts; however, he discovers an uncanny series of small disparities that cause the situation to spiral into complete uncertainty. Suddenly unable to rely on his ability to predict the future, Lu Guang must invent a new strategy to foil the plans of the man who took everything from him.\n\n[Written by MAL Rewrite]', '2024-12-27', 'https://cdn.myanimelist.net/images/anime/1496/147189l.jpg', 'Drama', 'Anime'),
(78, 'Idol', 'Music video for the song Idol by YOASOBI.', '2023-04-12', 'https://cdn.myanimelist.net/images/anime/1921/135489l.jpg', NULL, 'Anime'),
(79, 'Hibike! Euphonium Movie 3: Chikai no Finale', 'A new year signifies a new beginning, and that seems to be the case for Kitauji High School’s concert band. Following the graduation of the third-year seniors comes the entrance of the first-year juniors. The band members put in their utmost effort in practicing for their goal—to enter nationals.\n\nThe now second-year Kumiko Oumae, along with her friends, is met with the new and quirky batch of first-years, resulting in friction and conflict between the band members. However, as time passes, their inner feelings slowly unravel, but not every conflict is as easy to solve as the other. The trust and bonds between the band members will be challenged as they push forward for their regionals.\n\n[Written by MAL Rewrite]', '2019-04-19', 'https://cdn.myanimelist.net/images/anime/1141/102223l.jpg', 'Drama', 'Anime'),
(80, 'Hello World', 'The year is 2027, and the city of Kyoto has undergone tremendous technological advancement. Within the city live two classmates: Naomi Katagaki, a socially awkward and introverted boy; and Ruri Ichigyou, a girl with a cold personality who is often blunt with people. Despite sharing Ruri\'s love of reading, Naomi is afraid to approach her due to her unfriendly nature.\n\nOne day, while out on a walk, Naomi witnesses a crimson aurora pierce through the sky for a brief moment before vanishing. Shortly after, he encounters a three-legged crow and a mysterious hooded man, who reveals himself to be Naomi from 10 years in the future, explaining that he has come to change an imminent tragic event that happens to Ruri soon after they start dating. Initially taking his words with a grain of salt, present-day Naomi follows his future self\'s instructions and starts getting closer to Ruri, determined to save her. Will he be able to change the future?\n\n[Written by MAL Rewrite]', '2019-09-20', 'https://cdn.myanimelist.net/images/anime/1147/112650l.jpg', 'Drama, Romance, Sci-Fi', 'Anime'),
(81, 'Xian Wang de Richang Shenghuo 4', 'Fourth season of Xian Wang de Richang Shenghuo.', '2023-12-17', 'https://cdn.myanimelist.net/images/anime/1443/138753l.jpg', 'Adventure, Comedy, Fantasy', 'Anime'),
(82, 'Isekai Harem Monogatari', 'A 16-year-old named Naoki Oikawa is addicted to masturbating. One day, while pleasuring himself as usual, his erotic magazine begins to glow and Naoki suddenly finds himself in a fantastic world. He appears among three female adventurers who later present themselves as the swordswoman Filia Shiora, the priestess Tiane Rutheim, and the elf Llusse. They explain to Naoki that the world is in danger of destruction due to the resurrection of the Demon King, and the only way to save it is for him to use his special power—feeding his semen to the three girls so as to increase their strength exponentially. Of course, the young hero agrees to join the party, and his erotic quest begins.\n\n[Written by MAL Rewrite]', '2020-07-31', 'https://cdn.myanimelist.net/images/anime/1798/112703l.jpg', 'Fantasy, Hentai', 'Anime'),
(83, 'Mashiro no Oto', 'Setsu Sawamura runs away from his small home village following the death of his grandfather, the legendary shamisen master Matsugorou Sawamura. On his deathbed, Matsugorou told Setsu to give up the shamisen if he was only going to imitate others instead of playing in his own way. Grieving, Setsu heads for Tokyo, hoping that the big city can inspire him to discover his own unique playing style. But Tokyo defies his expectations by drowning out all other sounds with the deafening noise of its city life. \n\nConcerned about her son, Setsu\'s rich and successful mother, Umeko, waltzes back into his life and forces him to enroll in Umezono Academy. At the school, he meets Shuri Maeda, a girl who is fascinated by the Tsugaru shamisen and wishes to perform a song her grandmother once heard a long time ago. Shuri starts up a shamisen appreciation club and convinces Setsu to teach the members how to play the instrument. As he becomes more involved with the club, will Setsu be able to recover his love for the shamisen and discover the unique sound he lacks?\n\n[Written by MAL Rewrite]', '2021-04-03', 'https://cdn.myanimelist.net/images/anime/1841/111554l.jpg', 'Drama', 'Anime'),
(84, 'Shiguang Dailiren II', 'The attempt to capture the mysterious perpetrator who possesses people ends tragically: Lu Guang is rushed to the hospital in a critical state, while Cheng Xiaoshi is arrested for the alleged crime. In light of recent events, the father of Liu Min unleashes his skilled, ruthless lawyer—Qian Jin—after Police Chief Li Xiao, who is spearheading the investigation related to the photo studio owned by Qiao Ling.\n\nIt appears that no one is safe from the unpredictable and fatal attacks of the adversary who painstakingly hides their identity. As he tries to learn from his past mistakes, Cheng Xiaoshi must act swiftly and decisively to put an end to this devastating trail of death.\n\n[Written by MAL Rewrite]', '2023-07-14', 'https://cdn.myanimelist.net/images/anime/1897/137108l.jpg', 'Drama, Mystery, Suspense', 'Anime'),
(85, 'Chiikawa', 'What\'s a Chiikawa? No one really knows, but everyone can see they\'re small, they\'re cute, and they\'re always having a fun time! Join them as they explore their surreal world with the sharp humor and clever antics that make the Chiikawa irresistible.\n\n(Source: HIDIVE, edited)', '2022-04-04', 'https://cdn.myanimelist.net/images/anime/1783/121944l.jpg', 'Comedy', 'Anime'),
(86, 'Sarazanmai', 'After the noble Kappa Kingdom falls to the Otter Empire, the Kappa prince Keppi loses much of his power and becomes helpless against the unseen Kapa-zombies. These zombies plague the world, and are the creations of the Otters and manifestations of people\'s deepest desires. With no other choice, Keppi must rely on three young boys: Kazuki Yasaka, who must carry a box with him wherever he goes; Enta Jinnai, Kazuki\'s childhood friend; and Tooi Kuji, a delinquent and a school truant.\n\nBy having the mythical organ called a shirikodama removed from them, the boys are able to become Kappa themselves and fight the Kapa-zombies. However, to defeat them, the boys must connect with each other via their minds, bodies, and—most importantly—secrets. As the Kappa Kingdom relies on these boys, they must reveal themselves as they have never done before, all the while learning that connections are fragile and truly precious things.\n\n[Written by MAL Rewrite]', '2019-04-12', 'https://cdn.myanimelist.net/images/anime/1159/100455l.jpg', 'Action, Supernatural', 'Anime'),
(87, 'Cider no You ni Kotoba ga Wakiagaru', 'Yui \"Cherry\" Sakura expresses himself better through the haiku he writes and posts on the internet, even though no one gives it attention. While preparing for him and his family to relocate in August, he spends the summer working part-time at a welfare facility. Meanwhile, Yuki \"Smile\" Hoshino is a budding influencer who wants everyone to smile. However, she feels uneasy about the braces on her protruding front teeth and conceals her own smile using a disposable mask.\n\nAfter an accidental encounter with Cherry, Smile finds herself becoming a part-time worker at the same facility as him. Soon, the two assist a senile man, Fujiyama, in searching for an old vinyl record he owns. Unable to remember its last location, he wishes to listen to it once more before his memories fade for good. Cherry and Smile only have the record\'s sleeve and the word \"yamazakura\" as clues, and their hunt in the hazy summer heat begins.\n\n[Written by MAL Rewrite]', '2021-07-22', 'https://cdn.myanimelist.net/images/anime/1952/116031l.jpg', 'Romance', 'Anime'),
(88, 'Nu Wushen de Canzhuo Spring Festival Special', 'The St. Freya squad returns with a bubbling hot pot! Let Valkyries introduce you to a very special Spring Festival~ \n\n(Source: YouTube)', '2021-02-11', 'https://cdn.myanimelist.net/images/anime/1903/111820l.jpg', 'Comedy, Gourmet', 'Anime'),
(89, 'Kimi no Iro', 'Totsuko is a high school student with the ability to see the \"colors\" of others. Colors of bliss, excitement, and serenity, plus a color she treasures as her favorite. Kimi, a classmate at her school, gives off the most beautiful color of all. Although she does not play an instrument, Totsuko forms a band with Kimi and Rui, a quiet music enthusiast they meet at a used bookstore in a far corner of town. As they practice at an old church on a remote island, music brings them together, forming friendships and stirring affections. Will they discover their true \"colors\"?\n\n(Source: GKIDS, edited)', '2024-08-30', 'https://cdn.myanimelist.net/images/anime/1971/142121l.jpg', 'Drama', 'Anime'),
(90, 'Pokemon Movie 23: Koko', 'Deep within the Forest of Okoya, the Mythical Pokémon Zarude live in a troop and maintain a strict rule that forbids outsiders from entering their territory. Elsewhere in the jungle lives Koko, a human boy raised by a lone Zarude who left the troop. Koko has grown up never doubting that he is a Zarude. But one day, a chance meeting with Satoshi and Pikachu leaves Koko with his first human friend. Is he truly a Pokémon? Or is he, in fact, a human? When danger threatens the jungle, the bonds between Pokémon and human—and the love between parent and child—will be put to the test.\n\n(Source: Official site)', '2020-12-25', 'https://cdn.myanimelist.net/images/anime/1029/106237l.jpg', 'Action, Adventure, Comedy, Fantasy', 'Anime'),
(91, 'Psycho-Pass: Sinners of the System Case.2 - First Guardian', 'Enforcer Teppei Sugou, former ace pilot of the National Defence Army\'s 15th Integrated Task Force, is visited by a scout from the Ministry of Foreign Affairs and invited to rejoin the military. While considering the offer, he recalls his last months of service.\n\nHis last mission, Operation Foot Stamp, had been a highly classified military strike against the Southeast Asian Union. The operation quickly went south for the ground forces, and Sugou\'s First Guardian drone was ordered in as air support to drop emergency supplies for the ground units and then return to base. Following orders against his own judgement, Sugou abandoned his comrades on the field.\n\nMany lives were lost during the operation, including Itsuki Ootomo, Sugou\'s commanding officer. However, three months later, following a massacre at the Ministry of Defence, Otomo was spotted at the scene on camera. Now a suspect in an act of terrorism, Sugou cooperates with Enforcer Tomomi Masaoka and Criminal Investigation Department\'s Division 01 as they hunt his former mentor down.\n\n[Written by MAL Rewrite]', '2019-02-15', 'https://cdn.myanimelist.net/images/anime/1357/96879l.jpg', 'Action, Mystery, Sci-Fi, Suspense', 'Anime'),
(92, 'Psycho-Pass 3: First Inspector', 'Inspectors Arata Shindou and Mikhail Kei Ignatov have uncovered a dangerous conspiracy. The Sybil System, the ultimate judge of human character in Japan, is being undermined by a criminal syndicate that is amassing wealth and power in the shadows.\n\nNow, Bifrost agent Kouichi Azusawa launches a direct assault upon the Criminal Investigation Department (CID) by occupying its headquarters and taking Inspector Shindou and everyone with him hostage. CID Unit 01 supervisor, along with Chief Mika Shimotsuki and former unit members Shinya Kougami and Nobuchika Ginoza, face the task of reclaiming the building and saving everyone inside.\n\nAlongside the hostage situation and Azusawa\'s demands for Tokyo governor Karina Komiya\'s resignation, there is a sinister plot hatching in the background—a secret plan that will force Inspector Shindou to confront not only Azusawa but also his own past. These events slowly bring him closer to unshrouding the mystery that has eluded him and his best friend, Ignatov, for many years.\n\n[Written by MAL Rewrite]', '2020-03-27', 'https://cdn.myanimelist.net/images/anime/1085/110722l.jpg', 'Action, Mystery, Sci-Fi, Suspense', 'Anime'),
(93, 'Re:Zero kara Hajimeru Break Time 2nd Season', 'Afraid that his life may end at any moment, Otto Suwen begins writing a diary documenting all of his experiences. Now part of Subaru Natsuki\'s eccentric band of colorful characters, the apprehensive merchant is certain that new dangers lie ahead in their mission at Sanctuary. But amid the rising tensions, there are still moments of respite and reflection, ripe with opportunities to make vivid memories.\n\n[Written by MAL Rewrite]', '2020-07-10', 'https://cdn.myanimelist.net/images/anime/1586/108326l.jpg', 'Comedy', 'Anime'),
(94, 'Akudama Drive', 'The bustling metropolis of Kansai, where cybernetic screens litter the neon landscape, may seem like a technological utopia at first glance. But in the dark alleys around the brightly-lit buildings, an unforgiving criminal underbelly still exists in the form of fugitives known as \"Akudama.\" \n\nNo stranger to these individuals, Kansai police begin the countdown to the public execution of an infamous Akudama \"Cutthroat,\" guilty of killing 999 people. However, a mysterious message is sent to several elite Akudama, enlisting them to free Cutthroat for a substantial amount of money. An invisible hand seeks to gather these dangerous personas in one place, ensuring that the execution is well underway to becoming a full-blown bloodbath.\n\n[Written by MAL Rewrite]', '2020-10-08', 'https://cdn.myanimelist.net/images/anime/1468/109172l.jpg', 'Action, Sci-Fi, Suspense', 'Anime'),
(95, 'Dekiru Neko wa Kyou mo Yuuutsu', 'The Maine Coon is one of the largest domesticated cat breeds, standing out among other cats for its impressive size and intelligence. But regular salarywoman Saku Fukuzawa has a hard time explaining why her rescued black cat now towers over her. Yukichi is no run-of-the-mill cat; he is a masterful feline who has taken charge of the chores in the Fukuzawa household. While his master rushes to catch the train during the morning rush hour and works late into the night, the giant cat is diligently packing Saku\'s lunch, cooking her meals, cleaning their home, and buying groceries.\n\n[Written by MAL Rewrite]', '2023-07-08', 'https://cdn.myanimelist.net/images/anime/1074/136720l.jpg', 'Comedy', 'Anime'),
(96, 'Karakai Jouzu no Takagi-san Movie', 'Takagi and Nishikata\'s final summer in junior high is about to begin, and it\'s already off to a heartwarming start! When the pair find an abandoned kitten, they decide to work together and take care of their adorable new companion until they can locate its missing mother.\n\n(Source: Sentai Filmworks)', '2022-06-10', 'https://cdn.myanimelist.net/images/anime/1376/123398l.jpg', 'Romance', 'Anime'),
(97, 'Bocchi the Rock! Movie', 'Theatrical compilation of Bocchi the Rock!', '2024-06-07', 'https://cdn.myanimelist.net/images/anime/1256/142261l.jpg', 'Comedy', 'Anime'),
(98, 'Sengoku Youko: Senma Konton-hen', 'The chaotic aftermath of a confrontation between Jinka Yamato and Yazen results in the power dynamics between the magically gifted katawara and humans being turned upside down. As the news of the downfall of dangaishu—the katawara-hunting monks led by Yazen—spreads across the country, rogue groups of katawara start to form, worsening the already-fragile relationship between them and humanity.\n\nHaving lost faith in his abilities, Shinsuke Hyoudou now spends his time heavily drinking in the company of Senya, a former enemy of his who controls one thousand katawara within his body. Senya indirectly causes the death of the father of Tsukiko, his newfound friend, after a surprise attack of a local god gone berserk.\n\nDespite the circumstances, Tsukiko holds no grudge against Senya and is determined to become Shinsuke\'s disciple no matter what. Although Shinsuke refuses to become Tsukiko\'s sword instructor, he reluctantly agrees to let her travel with him and Senya. While the unlikely trio heads towards their next destination, Tama Youko continues her journey to find the trail of Jinka, the nine-tailed fox who has the power to destroy the world.\n\n[Written by MAL Rewrite]', '2024-07-18', 'https://cdn.myanimelist.net/images/anime/1948/143550l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(99, 'Kimetsu no Yaiba: Hashira Geiko-hen', 'After a series of mighty clashes with Upper Rank Demons, the Ubuyashiki clan prepares for one last battle with the hellish forces of Muzan Kibutsuji. In order to finally defeat the Demon leader once and for all, the clan devises a training camp for the Demon Slayer Corps, one led by the remaining Hashira—the most elite warriors in the organization. Each Hashira forms a specialized exercise that will hone both their own abilities and the skills of the ordinary soldiers.\n\nTanjirou Kamado, a boy at the heart of the brewing conflict, recovers from wounds received in a recent fight. While his half-Demon sister Nezuko is studied by researchers like Shinobu Kochou, Tanjirou embarks to train with the Hashira, seeking mastery in each of their assigned areas of expertise to be best prepared for the coming war—skills vital to Tanjirou, as he has vowed to be the very warrior who will eliminate Muzan for good.\n\n[Written by MAL Rewrite]', '2024-05-12', 'https://cdn.myanimelist.net/images/anime/1565/142711l.jpg', 'Action, Supernatural', 'Anime'),
(100, 'Transformers 40th Anniversary Special Movie', 'A video uploaded to the Takara Tomy YouTube channel in order to celebrate the 40th anniversary of the franchise.', '2024-09-12', 'https://cdn.myanimelist.net/images/anime/1351/145437l.jpg', 'Action', 'Anime'),
(101, 'Tonikaku Kawaii: Joshikou-hen', 'Nasa, at the request of his former junior high school teacher, Ms. Yanagi, finds himself entrusted with teaching a programming class at a high school. But here\'s the catch—it\'s an all-girls\' school. Surrounded by the limitless energy of teenage girls, Nasa tries to maintain his composure, but deep down, he can\'t help feeling nervous.\n\nA capricious boyfriend, secret admiration for someone, and a multitude of romantic dilemmas that can\'t be solved by programming, Nasa wonders if he can crack the equation of love!\n\n(Source: MAL News)', '2023-07-12', 'https://cdn.myanimelist.net/images/anime/1922/136453l.jpg', 'Comedy, Romance', 'Anime'),
(102, 'Kidou Senshi Gundam SEED Freedom', 'In C.E.75, the fighting still continues.\n\nThere are independence movements, and aggression by Blue Cosmos... In order to calm the situation, a global peace monitoring agency called COMPASS is established, with Lacus as its first president. As members of COMPASS, Kira and his comrades intervene into various regional battles. Then a newly established nation called Foundation proposes a joint operation against a Blue Cosmos stronghold.\n\n(Source: sugoi.co)', '2024-01-26', 'https://cdn.myanimelist.net/images/anime/1999/139748l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(103, 'Ore dake Level Up na Ken', 'Humanity was caught at a precipice a decade ago when the first gates—portals linked with other dimensions that harbor monsters immune to conventional weaponry—emerged around the world. Alongside the appearance of the gates, various humans were transformed into hunters and bestowed superhuman abilities. Responsible for entering the gates and clearing the dungeons within, many hunters chose to form guilds to secure their livelihoods.\n\nSung Jin-Woo is an E-rank hunter dubbed as the weakest hunter of all mankind. While exploring a supposedly safe dungeon, he and his party encounter an unusual tunnel leading to a deeper area. Enticed by the prospect of treasure, the group presses forward, only to be confronted with horrors beyond their imagination. Miraculously, Jin-Woo survives the incident and soon finds that he now has access to an interface visible only to him. This mysterious system promises him the power he has long dreamed of—but everything comes at a price.\n\n[Written by MAL Rewrite]', '2024-01-07', 'https://cdn.myanimelist.net/images/anime/1801/142390l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(104, 'Black Clover: Mahou Tei no Ken', 'As a lionhearted boy who can’t wield magic strives for the title of Wizard King, four banished Wizard Kings of yore return to crush the Clover Kingdom.\n\n(Source: Netflix)', '2023-06-16', 'https://cdn.myanimelist.net/images/anime/1337/136363l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(105, 'Nanatsu no Taizai: Mokushiroku no Yonkishi', 'Percival has always lived with his grandfather on God\'s Finger, a remote haven that sits high above the clouds. And though he loves the simple life, he secretly longs for adventure. But Percival\'s life is changed forever when an intruder—who shares a shocking connection with him—tears away everything he\'s ever known.\n\nWith nothing left to do but chase down the one who took everything from him, Percival sets out on his own. During his journey, the sheltered boy discovers that there are a lot of things he doesn\'t know about normal life. Luckily, he meets friends along the way who can help him get by—but how will they react when they find out about Percival\'s destiny... and how it\'s connected to the end of the world?\n\n(Source: Kodansha USA)', '2023-10-08', 'https://cdn.myanimelist.net/images/anime/1229/141256l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(106, 'Kengan Ashura Season 2', 'Second season of Kengan Ashura.', '2023-09-21', 'https://cdn.myanimelist.net/images/anime/1513/134619l.jpg', 'Action', 'Anime'),
(107, 'Ecchi na Oneechan ni Shiboraretai', 'Based on the doujin manga by Joy Ride/Yorokobi No Kuni.', '2019-07-05', 'https://cdn.myanimelist.net/images/anime/1150/113905l.jpg', 'Hentai', 'Anime'),
(108, 'Boku ga Aishita Subete no Kimi e', 'A world where it has been established that people routinely swing between slightly different parallel worlds...\n\nKoyomi Takasaki, who lives with his mother following his parents\' divorce, enrolls in a local university prep school. Due to the atmosphere concentrated on studies and his social awkwardness, Koyomi is unable to make friends. One day, he is suddenly approached by his classmate Kazune Takigawa, who tells him that she has travelled from the 85th world where she and Koyomi are lovers.\n\n(Source: MAL News)', '2022-10-07', 'https://cdn.myanimelist.net/images/anime/1145/127594l.jpg', 'Romance, Sci-Fi', 'Anime'),
(109, 'Xie Wang Zhui Qi 3: Shen Nu Guilai', 'Su Luo was kidnapped by her love rival Li Yaoyao and her master Fairy Yanxia, who forcefully used the Appearance-Alterning Spell to reveal her true face. In order to escape from their control, Su Luo destroyed Fairy Yanxia\'s cave and the spell, but she was also seriously injured and fell into the sea. Lifting the spell revealed her mysterious background. \n\nThe one who rescued her from the sea was actually her lover who assassinated her on Earth—Yun Qi. Shocked, Yun Qi revealed that he knew Su Luo\'s life secret and could tell her about it.\n\nDid Su Luo choose a shortcut for the secret about her past and go with Yun Qi who betrayed her, or will she return to her life with Nangong Liuyun? \n\n(Source: iQIYI; translated and edited)', '2021-09-29', 'https://cdn.myanimelist.net/images/anime/1697/117842l.jpg', 'Drama, Fantasy, Romance', 'Anime'),
(110, 'Saikyou no Shienshoku \"Wajutsushi\" de Aru Ore wa Sekai Saikyou Clan wo Shitagaeru', 'Noel longs to be a Seeker like his heroic grandfather, slaying the beasts that emerge from Abysses and exploring far-off lands. Unfortunately, it turns out he\'s nothing but a measly Talker–a job with no combat skills whatsoever. Undaunted, Noel sets out to establish the strongest clan in all the land, using his silver-tongued Talker skills to unite assassins and heroes under his leadership.\n\n(Source: Seven Seas Entertainment)', '2024-10-07', 'https://cdn.myanimelist.net/images/anime/1683/145446l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(111, 'Xiong Shi Shaonian', 'A young Cantonese village boy must overcome self-doubt, ridicule and classism to realise his dream of competing in the Guangzhou Lion Dancing championship.\n\n(Source: IMDB)', '2021-12-17', 'https://cdn.myanimelist.net/images/anime/1948/127051l.jpg', 'Comedy, Drama, Fantasy', 'Anime'),
(112, 'Gintama: The Semi-Final', 'As the war temporarily calms down and Edo rebuilds, Gintoki finds Shinpachi—who is still unaware of his return—on a bridge. However, as a fight quickly breaks out between the Yorozuya and the Tenshouin Naraku, suspicion grows, forcing Gintoki to use what is nearest—a loincloth—to mask his identity. Saved for the time being, Gintoki enters the Yorozuya office, but unbeknownst to him, someone else is already waiting there...\n\nMeanwhile, Kondou departs Earth to marry Princess Bubbles in an attempt to improve diplomatic relations. After boarding the Gorilla Amanto mother ship, he realizes that he doesn\'t speak their language. Confused, Kondou tries conversing with them, only to inadvertently gain their support. However, someone associated with the princess crashes the ongoing ceremony. Will the wedding continue, or has Kondou just been saved from becoming the next Gorilla Prince?\n\n[Written by MAL Rewrite]', '2021-01-15', 'https://cdn.myanimelist.net/images/anime/1694/110521l.jpg', 'Action, Comedy', 'Anime'),
(113, 'Mini Dragon Specials', 'Includes 3 special Mini Dragon episodes released within Kobayashi-san Chi no Maid Dragon S\'s broadcast period and 5 BD/DVD extras.', '2021-07-08', 'https://cdn.myanimelist.net/images/anime/1100/116698l.jpg', 'Slice of Life, Supernatural', 'Anime'),
(114, 'Blue Lock: Episode Nagi', 'A spin-off of Blue Lock focusing on Seishirou Nagi.', '2024-04-19', 'https://cdn.myanimelist.net/images/anime/1239/139928l.jpg', 'Sports', 'Anime'),
(115, 'Shadows House 2nd Season', 'After the resolution of the debut, Kate and her Doll Emilico have officially become residents of the Shadows House. However, they are under constant vigilance by the Star Bearers—an elite group in charge of the children\'s wing. In order to escape from their surveillance and the morbid methods they use to keep everyone\'s loyalty in check, Kate and Emilico must be wary of who to trust and aim to become Star Bearers themselves.\n\nMeanwhile, the Star Bearers have encountered their own problems. A mysterious robed figure dubbed \"Master Robe\" has trespassed and roams around the children\'s wing. At first, Master Robe is deemed harmless, but more incidents start occurring that endanger the Dolls\' lives—all of them pointing to the suspicious individual.\n\nTo improve her reputation, Kate decides to solve the mystery herself. Yet, with so few clues and so many suspects, searching for Master Robe and their motive for attacking the mansion proves more challenging than she imagined.\n\n[Written by MAL Rewrite]', '2022-07-09', 'https://cdn.myanimelist.net/images/anime/1634/124231l.jpg', 'Fantasy, Mystery', 'Anime'),
(116, 'Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su 2nd Season', 'Ever since Rakurou \"Sunraku\" Hizutome started to play the extremely popular virtual reality game Shangri-La Frontier, he has truly fallen in love with it. Sunraku has quickly made a big name for himself by fighting two of the seven unique, nearly unbeatable monsters, which is unthinkable for most players. To progress the game\'s story, he sets out on an adventure with his leporine guide, Emul, to acquire a magic operation unit from an ancient workshop.\n\nThough Sunraku breezes through this quest alongside his clanmates Towa \"Arthur Pencilgon\" Amane and Kei \"OiKatzo\" Uomi, there seems to be an ulterior motive as to why the two of them decided to help Sunraku in the first place. Nevertheless, Sunraku gains valuable knowledge and allies, critical for his advancement in the game. By seeking out powerful enemies and unraveling the inner workings of the game\'s world, Sunraku may just change Shangri-La Frontier forever.\n\n[Written by MAL Rewrite]', '2024-10-13', 'https://cdn.myanimelist.net/images/anime/1996/147601l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(117, 'Kono Oto Tomare!', 'Gen Kudou, a koto maker, believes that his delinquent grandson Chika would never understand the profoundness of the traditional musical instrument. In an attempt to make up for his naivety and understand the words of his late grandfather, Chika tries to join the Tokise High School Koto Club. \n\nEven though the club is in dire need of members, new club president Takezou Kurata is unwilling to easily accept Chika\'s application due to his bad reputation. Nonetheless, after seeing Chika\'s seriousness and enthusiasm, Takezou allows the problem child to join, along with koto prodigy Satowa Houzuki and three of Chika\'s energetic friends. Kono Oto Tomare! follows the merry band of musicians as they aspire to play at the national competition.\n\n[Written by MAL Rewrite]', '2019-04-07', 'https://cdn.myanimelist.net/images/anime/1464/99881l.jpg', 'Drama', 'Anime'),
(118, 'Shinmai Ossan Boukensha, Saikyou Party ni Shinu hodo Kitaerarete Muteki ni Naru.', 'Determined to pursue his glorious childhood dreams, 30-year-old Rick Gladiatol, a modest clerk in the adventurers\' guild, is offered a once-in-a-lifetime opportunity after he fatefully encounters the dark elf Reanette Elfelt. Reanette happens to be an elite adventurer of the legendary party Orichalcum Fist, whose members welcome Rick under the condition that he follow a Spartan training.\n\nTwo years later, Rick is finally ready to take the E-Rank exam officially qualifying him as an adventurer. However, raw magical power can only be developed until one turns 20. As such, Rick faces the general hostility of fellow participants and examiners alike, leaving him no choice but to show the world that his hellish training has turned him into an invincible warrior.\n\n[Written by MAL Rewrite]', '2024-07-02', 'https://cdn.myanimelist.net/images/anime/1212/144711l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(119, 'Kui Cheng Shoufu Cong Youxi Kaishi', 'Pei Qian, an ordinary migrant worker, was accidentally bound to the wealth conversion system, which gave him a good opportunity to spend money in business and start his life over again. However, the system stipulates that you can only earn one yuan if you make a profit of 100 yuan, but all the money you lose can go into your own pocket. In order to lose money, Pei Qian chose the high-risk, money-burning game industry, and deliberately produced \"alternative\" games that went against the rules of the market. However, he unexpectedly became popular time and time again, earning a lot of money, and painfully became Pei Qian is the \"business wizard\" admired by everyone, but only Pei Qian understands that I really just want to lose money...\n\n(Source: Bilibili, Google translated)', '2024-02-03', 'https://cdn.myanimelist.net/images/anime/1635/140669l.jpg', 'Comedy, Fantasy', 'Anime'),
(120, 'Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen OVA', 'Eustachius no Shitamachi Sennyuu Dai Sakusen (Eustachius\' Incognito Operation Downtown)\nTo get more information about Myne and her strange background, Head Priest Ferdinand sends two nobles, Eustachius and Eckhard, to investigate everything regarding her life within her hometown. However, things do not go the way they expected.\n\nCorinna-sama no Otaku Houmon (Visiting Missus Corinna)\nOtto\'s wife, Corinna, takes an interest in the outfit that Myne wore at her baptism. Corinna summons her alongside her mother, Eva, and sister, Turi, wishing to know the procedure in making such sophisticated attire and accessories. Naturally, for Myne, she sees an excellent opportunity for profit.\n\n[Written by MAL Rewrite]', '2020-03-10', 'https://cdn.myanimelist.net/images/anime/1931/114311l.jpg', 'Fantasy', 'Anime'),
(121, 'Odo', 'Music video for the song Odo by Ado.', '2021-04-27', 'https://cdn.myanimelist.net/images/anime/1191/127266l.jpg', 'Action', 'Anime'),
(122, 'Sand Land', 'In the far future, war has destroyed the entire Earth, leaving only a barren wasteland where the supply of water is controlled by the greedy king. In search of a long-lost lake, Sheriff Rao asked the king of the demons for help...and got the king\'s son, Beelzebub, and his assistant, Thief. Together the unlikely trio sets off across the desert, facing dragons, bandits and the deadliest foe of all... the King\'s army itself! \n\n(Source: VIZ Media)', '2023-08-18', 'https://cdn.myanimelist.net/images/anime/1834/136339l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(123, 'Kidou Senshi Gundam: Suisei no Majo Season 2', 'After surviving a brutal terrorist attack on Plant Quetta, Suletta Mercury returns to dueling at the Asticassia School of Technology, while Miorine Rembran sits at her injured father\'s side, waiting to see if he will recover. As the residents of Earth House are preoccupied with their respective troubles, two members of Dawn of Fold—the perpetrators of the attack—secretly infiltrate the school, putting Suletta and her friends at risk.\n\nAt the same time, Prospera, Suletta\'s mother, approaches Miorine to propose the continuation of \"Quiet Zero\"—a project headed by Miorine\'s father that can allegedly end all war. Prospera seems to be another political figure with hidden, opposing motives, and whether she truly has Suletta\'s well-being at heart remains to be seen.\n\n[Written by MAL Rewrite]', '2023-04-09', 'https://cdn.myanimelist.net/images/anime/1023/134768l.jpg', 'Action, Sci-Fi', 'Anime'),
(124, 'Ya She', 'In a busy and bustling city, history is soundlessly scattered throughout. Those legends that speak of rare treasures, lost in the flowing river of time. At this place, in this time, they are here--in an antique shop named \"Ya She\".', '2024-10-04', 'https://cdn.myanimelist.net/images/anime/1380/126700l.jpg', 'Mystery, Supernatural', 'Anime'),
(125, 'Major 2nd 2nd Season', 'After recovering from the inner struggles he faced in the past, Daigo Shigeno continues to play baseball and is now the captain of Fuurin Private Academy Middle School\'s baseball team. Alongside Mutsuko Sakura, his classmate from elementary school, he aims to lead the team to glory. However, due to unexpected circumstances, Fuurin\'s baseball team is left with only six members: Daigo, Mutsuko, Yayoi Sawa, Tao Sagara, Seira Kandori, and Hiromu Tanba. Left with mostly female players and lacking in experience, the team struggles to gain confidence and trust from the new recruits—Akira Nishina, Anita Kabashima, and Chisato Fujii. Facing challenges such as having no proper coach, problematic recruits, and a limited number of members, Daigo\'s resolution is put to the test as he tries to bring the team together in time to participate in their first ever tournament.\n\n[Written by MAL Rewrite]', '2020-04-04', 'https://cdn.myanimelist.net/images/anime/1025/105319l.jpg', 'Sports', 'Anime'),
(126, 'Oomuro-ke: Dear Friends', 'Part two of the spin-off of Yuru Yuri featuring Sakurako and her sisters.', '2024-06-21', 'https://cdn.myanimelist.net/images/anime/1613/141223l.jpg', 'Comedy, Girls Love', 'Anime'),
(127, 'Wanmei Shijie Movie: Huo Zhi Huijin', 'The reunion of Huo Sang plays the tragic song of sin and blood, and the stone spirit is reborn from the desperate situation when the ashes fall.\n\n(Source: v.qq, translated)', '2024-09-14', 'https://cdn.myanimelist.net/images/anime/1730/145386l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(128, 'Mayonaka Punch', 'Masaki\'s career on NewTube ends abruptly when the Harikiri Sisters decide to kick her out of their group during a livestream. With her bad reputation, Masaki has a slim chance of returning to popularity with a solo channel and she is plagued by comments of hate.\n\nMasaki soon meets Live, a vampire who just woke up from her slumber in which she dreamed of Masaki and developed an obsession with her. Believing this discovery will be the next internet sensation, Masaki forms a pact with Live: in exchange for Masaki\'s blood, Live will help her reach the milestone of a million subscribers.\n\nNow, with the other vampires in Live\'s house on board with Masaki\'s ambitious plan, she and Live work together to film videos and restore her to career glory.\n\n[Written by MAL Rewrite]', '2024-07-08', 'https://cdn.myanimelist.net/images/anime/1700/143395l.jpg', 'Comedy, Supernatural', 'Anime'),
(129, 'Seijo no Maryoku wa Bannou desu', 'Since ancient times, the citizens of Slantania have lived within a shroud of miasma, a force that brings forth monsters creating havoc around the world. When the kingdom\'s Order of Knights becomes incapable of containing the monsters, the Grand Magus summons a holy maiden—the legendary \"Saint\"—to obliterate the horrid creatures and restore peace.\n\nOne evening, as Sei Takanashi returns home from a long day at work, a magical force pulls her into a foreign world. Upon her arrival to the kingdom of Slantania, she overhears that the Grand Magus inadvertently summoned two Saints—Sei and a brown-haired girl. Needing only one holy maiden, the prince declares the other girl as the Saint, leaving Sei to her own devices.\n\nSei sets her sight on the Medicinal Flora Research Institute, an establishment known for its studies regarding herbs and potions. While indulging in her latest passion, Sei has a fateful encounter with the commander of the Third Order of Knights. But little does she know, her aptitude as a Saint will continue to exert its influence over her new life.\n\n[Written by MAL Rewrite]', '2021-04-06', 'https://cdn.myanimelist.net/images/anime/1947/114235l.jpg', 'Fantasy, Romance', 'Anime'),
(130, 'Karakai Jouzu no Takagi-san 2', 'Even after spending a considerable amount of time with Takagi, Nishikata is still struggling to find a perfect plan to defeat the expert teaser. A battle of wits, a contest of physical prowess, a test of courage—any strategy he employs to expose her weaknesses is to no avail. On the contrary, Nishikata\'s pitiful attempts only reveal more of his own flaws, which Takagi takes advantage of to become increasingly daring in her teasing attempts. To make things worse for Nishikata, rumors about him and Takagi may have spread in class due to the frequent interactions between them.\n\nHowever, the optimistic Nishikata believes that wisdom comes with age and that as the days go by, his experience with her constant teasing will eventually bear fruit, leading him to the awaited moment of victory. Thus, Nishikata continues to strive for the seemingly impossible—to outsmart Takagi and make her blush with embarrassment.\n\n[Written by MAL Rewrite]', '2019-07-07', 'https://cdn.myanimelist.net/images/anime/1393/107033l.jpg', 'Comedy, Romance', 'Anime'),
(131, 'Biao Ren: Blades of the Guardians', 'An extraordinary guard walks in the desert of the western regions escaping the slaughter by the government. He took a surveillance assignment bound for the Chang capital. The task was thought of as something simple, but in reality it is a path full of crises and dangers. Here begins a journey that will affect the fate of the world.', '2023-06-01', 'https://cdn.myanimelist.net/images/anime/1968/110585l.jpg', 'Action', 'Anime'),
(132, 'Free! Movie 5: The Final Stroke - Kouhen', 'After his first appearance on the competitive world stage, Haruka is held captive by the swimming of the unmistakable champion, Albert, and feels like he\'s lost his way. With the current state of things, his swimming and what the water means to him are called into question. Haruka begins to sink to the bottom of the murky water as he struggles on his own.\n\nPushed on by a restless urge in his heart, Haruka purposefully puts himself through a rigorous and intensive training regiment, relentlessly devoting himself to practice. In his heart, Haruka knows that he\'s pushing himself beyond his limits both physically and mentally. His friends can do nothing but watch over and have faith in him.\n\nMemories of Albert\'s cold, dry swimming keep replaying in his mind.\nI have to get faster, I have to become stronger.\nI have to compete against Albert again.\n\nHaruka unleashes his stroke to cut through the heavy, indifferent water.\nHis friends draw closer to watch.\n\nWhat scenery will Haruka see at the end of this struggle＊──!\n\n(Source: Free! website, Translated)', '2022-04-22', 'https://cdn.myanimelist.net/images/anime/1417/124151l.jpg', 'Sports', 'Anime'),
(133, 'Wan Jie Du Zun', 'On this day, Lin Feng was condensing his martial soul in the Lin Mansion. He didn\'t want to, he had just cultivated his sword martial soul into a prototype, and his fiancee Ji Manyao took the opportunity to take away his martial soul, causing him to vomit blood and die. At the same time, Lin Feng\'s spirit entered the place where the gods were buried. The mysterious woman in the place told Lin Feng that he could gain huge martial arts power and knowledge by destroying the ancient gods buried here. In the real world, Lin Feng, who was originally the eldest young master of the Lin family, was no longer respected by his servants because he lost his sword spirit. It was not until Lin Feng used the power obtained from the place of burial to defeat Lin Yuhong, the powerhouse of Huangjie Wuhun, that the Lin family\'s attitude towards Lin Feng changed. On the other hand, Lin Feng killed Qin Xiao who was fighting with him because he couldn\'t control the newly acquired power well. Qin Xiao is the grandson of the first elder of the Qin family, and has always been favored by the elders. Now that Qin Xiao was killed, the elders of the Qin family were unwilling.\n\n(Source: Tencent Video)', '2021-04-06', 'https://cdn.myanimelist.net/images/anime/1571/114240l.jpg', 'Fantasy', 'Anime'),
(134, 'Yamato yo, Towa ni: Rebel 3199', 'Sequel to Uchuu Senkan Yamato 2205: Aratanaru Tabidachi.', '2024-07-19', 'https://cdn.myanimelist.net/images/anime/1856/143246l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(135, 'Oemojisangjuui', 'Violence, name-calling, and humiliation are a daily reality for high school student Park Hyung Suk. Chubby and insecure, he is often used as a plaything and punching bag for bullies, which leads him to wish he could just disappear. Unexpectedly, when he transfers schools in the hopes of starting anew, a miraculous opportunity emerges: he awakens in a tall, handsome, and strangely athletic body. Hyung Suk quickly realizes that he is now the owner of two disparate bodies; when one falls asleep, he wakes up in the other.\n\nFeeling like he has won the lottery of life, Hyung Suk enters his new school as this attractive and strong young man. However, it soon becomes evident that being a popular student is not all smooth sailing. From girls wanting him only for his good looks to delinquents picking fights out of jealousy, he can never seem to escape trouble. In trying to balance his two different lives, Hyung Suk may find both of them to be sources of ceaseless challenges.\n\n[Written by MAL Rewrite]', '2022-12-08', 'https://cdn.myanimelist.net/images/anime/1456/131788l.jpg', 'Action, Drama, Supernatural', 'Anime'),
(136, '5-toubun no Hanayome∽', 'Featuring stories from the manga not adapted in the main anime.', '2023-09-02', 'https://cdn.myanimelist.net/images/anime/1567/135752l.jpg', 'Comedy, Romance', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(137, 'Star☆Twinkle Precure: Hoshi no Uta ni Omoi wo Komete', 'When a meteor shower causes a mysterious star-shaped alien to land in Lala Hagoromo and Hikaru Hoshina\'s home, the girls find themselves having to take care of the mischievous creature whom they name \"Yuma.\" Although their relationship gets off to a rocky start, Lala and Yuma eventually connect through their similar passions for music and exploration. \n\nHowever, when strange alien hunters targeting Yuma arrive on Earth, the girls learn that there is more to Yuma than what meets the eye. In protecting Yuma, the Star☆Twinkle Precure find themselves entangled in an astronomical battle where the fate of the galaxy is at stake! Will Yuma feel the Precure\'s emotions through their melody, and can they make the necessary sacrifices to defend everything they love?\n\n[Written by MAL Rewrite]', '2019-10-19', 'https://cdn.myanimelist.net/images/anime/1324/101596l.jpg', 'Action', 'Anime'),
(138, 'Xian Wang de Richang Shenghuo 2', 'Wang Ling has been living a quiet life ever since resolving a particular incident, but thanks to his previous tampering with the laws of nature, the level of psionic powers in the world has dropped drastically. To stop the levels from plummeting further, his spirit sword Jingke comes to the rescue. But due to the excessive use of power, Jingke ends up ripping a crack in space. This crack allows demons to infiltrate the world and steal spiritual energy essential to powering human society. Now the only person who has the power to thwart their plans is none other than Wang Ling.\n\nIn an attempt to balance his high school life with his supernatural one, Wang Ling must confront challenges ranging from teacher home visits, crafting spiritual swords, grappling with his growing feelings for Sun Rong, and battling invading demons!\n\n[Written by MAL Rewrite]', '2021-10-30', 'https://cdn.myanimelist.net/images/anime/1323/119210l.jpg', 'Adventure, Comedy, Fantasy', 'Anime'),
(139, 'Overlord Movie 3: Sei Oukoku-hen', 'The Sacred Kingdom has enjoyed a great many years without war thanks to a colossal wall constructed after a historic tragedy. They understand best how fragile peace can be. When the terrible demon Jaldabaoth takes to the field at the head of a united army of monstrous tribes, the Sacred Kingdom\'s leaders know their defenses are not enough. With the very existence of the country at stake, the pious have no choice but to seek help wherever they can get it, even if it means breaking taboo and parlaying with the undead king of the Nation of Darkness!\n\n(Source: Yen Press)', '2024-09-20', 'https://cdn.myanimelist.net/images/anime/1954/144101l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(140, 'Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru', 'The world\'s greatest assassin had sworn lifelong allegiance to the organization that raised him. However, despite his loyalty, that very same organization takes action to silence him, ultimately leading to his demise. Drowning in frustration and regrets he can no longer suppress, he finds himself in an audience with a goddess attracted by his exceptional skills. The goddess offers him reincarnation into a magnificent world of swords and magic so he can perform a crucial mission: prevent that world\'s destruction by slaying its hero.\n\nAccepting the goddess\' request, he is reborn as Lugh Tuatha Dé, the son of a noble family of assassins serving the Alvan Kingdom. Under the guidance of his father, Lugh learns new assassination techniques that significantly differ from the cold-blooded and unsympathetic killing style of his previous life. Furthermore, his other talents bloom, allowing him to meet new allies and acquaintances. Even so, Lugh knows that his efforts are far from adequate, because a monumental adversary such as the hero can only be defeated with perfection.\n\n[Written by MAL Rewrite]', '2021-10-06', 'https://cdn.myanimelist.net/images/anime/1928/117620l.jpg', 'Action, Drama, Fantasy, Mystery, Romance', 'Anime'),
(141, 'Soukyuu no Fafner: Dead Aggressor - The Beyond Part 2', 'Episodes 4-6 of the Soukyuu no Fafner: Dead Aggressor - The Beyond series.', '2019-11-08', 'https://cdn.myanimelist.net/images/anime/1276/102048l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(142, 'Kimitachi wa Dou Ikiru ka', 'Three years into the war, Mahito Maki loses his mother in a tragic fire at the hospital. Shortly thereafter, his father marries Natsuko, the younger sister of Mahito\'s mother. They take Mahito out of Tokyo to seek refuge in his late mother\'s rural family home. There, Mahito is constantly taunted by a strange gray heron, who seems to have taken an interest in him.\n\nUnable to come to terms with his loss and struggling to adjust to a new life in an unfamiliar place, the boy is shocked to discover that Natsuko is pregnant. To make matters worse, the pesky heron can speak—and claims that Mahito\'s mother is still alive. Luring him into a mysterious tower near the residence, the heron says that Mahito can save her from death, but the boy is not easily swayed.\n\nWhen Natsuko disappears one day, however, Mahito watches her walk into the tower and becomes compelled to venture in to rescue her. He soon finds himself falling into another world below his, where life and death seem to be entwined. As he navigates through this foreign realm to find Natsuko, Mahito must understand what it means to live if he wants to safely return home.\n\n[Written by MAL Rewrite]', '2023-07-14', 'https://cdn.myanimelist.net/images/anime/1126/139654l.jpg', 'Adventure, Award Winning, Drama, Fantasy', 'Anime'),
(143, 'Akebi-chan no Sailor-fuku', 'Ever since she was young, Komichi Akebi has always adored sailor uniforms, even going so far as to ask her mother to sew one if she succeeds in getting into her mother\'s alma mater, Roubai Academy. And thus, when she gets accepted into the prestigious school, Komichi is ecstatic. However, much to her surprise, the middle school no longer uses sailor uniforms as its dress code—making Komichi stand out from her schoolmates. Despite this, Komichi is granted permission to continue wearing the traditional attire. \n\nWith renewed confidence, Komichi meets fascinating classmates as they experience school life together. Under the colorful shower of blossoming prospects, an exciting tomorrow awaits them!\n\n[Written by MAL Rewrite]', '2022-01-09', 'https://cdn.myanimelist.net/images/anime/1820/120520l.jpg', 'Slice of Life', 'Anime'),
(144, 'Otogi', 'Eve\'s first press limited edition release of their Otogi album CD includes an accompanying DVD. Eve is known as a musician and lyricist for Vocaloid videos but this CD+DVD release features only his \"self-covers\" where he is providing the vocals rather than a Vocaloid.\n\nThis entry encompasses the official music videos published on the Otogi DVD release. Refer to the More Info section for details.', '2019-02-06', 'https://cdn.myanimelist.net/images/anime/1547/98672l.jpg', NULL, 'Anime'),
(145, 'Fanren Xiu Xian Chuan: Xinghai Feichi', 'Third season of Fanren Xiu Xian Chuan.', '2023-11-25', 'https://cdn.myanimelist.net/images/anime/1119/139470l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(146, 'Love Me: Kaede to Suzu The Animation', 'Kaede is the student council president and is also twin sisters with Suzu. Both are childhood friends with Hayato, of which all three are part of the student council. \nThrough their time together, Kaede and Suzu both both fell in love with Hayato. Both try to compete for Hayato\'s love and sexual favor.', '2022-03-25', 'https://cdn.myanimelist.net/images/anime/1881/120300l.jpg', 'Hentai', 'Anime'),
(147, 'Summer Ghost', 'It is said that fireworks can calm the souls of the dead. For Tomoya Sugisaki, Aoi Harukawa, and Ryou Kobayashi, fireworks are what allowed them to meet the Summer Ghost. Believed to be the spirit of a young woman who committed suicide, the Summer Ghost only appears in a specific area and can only be seen by those who are within arm\'s reach of death. \n\nTomoya is a creative soul being crushed by his academic obligation to get into a good university. Aoi is a meek girl who is relentlessly bullied by her classmates. Ryou is a former basketball star who had to forfeit his passion following a grim diagnosis. The only thing these three have in common is their ability to see the Summer Ghost. The Summer Ghost is said to be able to answer any and all questions pertaining to death—something the three teenagers desperately want to know more about.\n\nDissatisfied with their initial meeting, Tomoya sets out to find the Summer Ghost once again. But the more time he spends with the ghost, the more the mystery surrounding her existence unravels.\n\n[Written by MAL Rewrite]', '2021-11-12', 'https://cdn.myanimelist.net/images/anime/1651/117943l.jpg', 'Drama, Supernatural', 'Anime'),
(148, 'Wan Jie Fa Shen', 'At the end of the calendar 2020, the continent of Stern, which has reached the end of civilization due to the exhaustion of magic elements, ushered in the destruction of the continent under the void storm. Ye Xuan, the last god of law in the mainland, unexpectedly awakened in the era of the prosperous magic civilization three thousand years ago and became an ordinary student at the Sith Magic Academy on the border of the Kingdom of Orlando in the northwest of the mainland. In order to save the mainland and prevent the end from coming, Ye Xuan began to explore the mystery of the dark turmoil that led to the depletion of magical elements in the mainland three thousand years ago, to prevent the mainland crisis.\n\n(Source: Donghua Info)', '2020-12-21', 'https://cdn.myanimelist.net/images/anime/1077/111009l.jpg', 'Adventure, Fantasy, Romance', 'Anime'),
(149, 'Cang Yuan Tu 2nd Season', 'The second season of Cang Yuan Tu.', '2024-12-06', 'https://cdn.myanimelist.net/images/anime/1530/146755l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(150, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka III', 'Upon his run-in with a Vouivre—a monster known to be very dangerous—Hestia Familia\'s captain Bell Cranel is struck with incomprehension. Despite its preceding reputation, the supposed bloodthirsty creature happens to be crying and flees from a group of adventurers. The monster, taking the form of a terrified little girl, prompts Bell to swiftly decide to hide her. Unbeknownst to him, this act of kindness will cause massive repercussions that will soon echo throughout the entire city of Orario.\n\n[Written by MAL Rewrite]', '2020-10-03', 'https://cdn.myanimelist.net/images/anime/1523/108380l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(151, 'Kimi wo Aishita Hitori no Boku e', 'With the divorce of his parents, seven-year-old Koyomi Hidaka makes the important decision to live with his father. As a researcher at the Japanese Institute of Virtual Science, Koyomi\'s father is involved in the investigation of the phenomenon of parallel worlds. Through his father\'s job, the young boy meets Shiori Satou, the daughter of another divorced researcher. Soon becoming friends, the two spend much of their childhood together.\n\nAs Koyomi and Shiori grow closer together over the years, the two intend to marry in the future. However, their plan comes to a halt when their parents decide to marry each other. Now fated to being step-siblings, the two friends refuse to accept their new reality. Using their parents\' research, Koyomi and Shiori escape to a parallel world to start their lives anew together, only to face repercussions that will put the very futures they strove for in danger. \n\n[Written by MAL Rewrite]', '2022-10-07', 'https://cdn.myanimelist.net/images/anime/1332/127596l.jpg', 'Romance, Sci-Fi', 'Anime'),
(152, 'Kubo-san wa Mob wo Yurusanai', 'Junta Shiraishi is a high school student with one simple goal—to enjoy his youth. However, achieving this goal is not so straightforward since Shiraishi is effectively invisible to his peers; even his teachers routinely fail to notice his presence. In fact, there is a rumor circulating that whoever manages to spot him will receive good luck. \n\nBut there is one person who notices Shiraishi\'s presence without fail. Seated right next to him, Nagisa Kubo is determined not to let him quietly fade into the background. Unfortunately for him, this means that Shiraishi finds himself in some peculiar situations, all orchestrated by Kubo. Despite this, Kubo\'s playful antics might just be the catalyst needed to spark the thrilling youth that Shiraishi longs for.\n\n[Written by MAL Rewrite]', '2023-01-10', 'https://cdn.myanimelist.net/images/anime/1818/132330l.jpg', 'Comedy, Romance', 'Anime'),
(153, 'Boku no Hero Academia 7th Season', 'Following an all-out battle with the Paranormal Liberation Front, it is difficult for the people of Japan to continue placing faith in their heroes. To combat the combined power of Tomura Shigaraki and All For One, All Might calls for his ally from the West—the strongest woman on the planet, Star and Stripe.\n\nHowever, All For One decides to intercept Star and her fleet to get his hands on her overpowered quirk before she can enter Japanese airspace. Although Endeavor, Hawks, and Best Jeanist are headed to the rendezvous point, Star makes a gamble in the present to save her comrades.\n\n[Written by MAL Rewrite]', '2024-05-04', 'https://cdn.myanimelist.net/images/anime/1529/140306l.jpg', 'Action', 'Anime'),
(154, 'Yuru Camp△ Movie', 'As time marches forward, Rin Shima, Nadeshiko Kagamihara, and their friends have grown into full-fledged adults. Now with careers and responsibilities, they can no longer freely spend their days camping and adventuring. However, Chiaki Oogaki, who currently works for the Yamanashi Tourism Organization, reunites the group as she comes up with an exciting proposal—to build a campground together to revitalize an abandoned patch of land from their homeplace, the Yamanashi Prefecture.\n\nMotivated by this ambitious project, the girls combine their efforts to create an environment where future generations can enjoy unique moments as they once did, all while reminiscing the charms of camping from their high school days.\n\n[Written by MAL Rewrite]', '2022-07-01', 'https://cdn.myanimelist.net/images/anime/1806/124396l.jpg', 'Slice of Life', 'Anime'),
(155, 'Doupo Cangqiong 4th Season', 'To awaken his teacher Yao Cheng, Xiao Yan travels to the capital for a meeting of the pill masters. His power was immediately noticed, people who wanted to use it, but at the decisive moment Xiao Yan still becomes a champion and defends the honor of the empire. But Xiao Yan is waiting for a meeting, for which he has been preparing for three whole years...', '2021-03-28', 'https://cdn.myanimelist.net/images/anime/1887/112452l.jpg', 'Action, Adventure, Fantasy, Romance, Supernatural', 'Anime'),
(156, 'Readymade', 'Music video for the song Readymade by Ado.', '2020-12-24', 'https://cdn.myanimelist.net/images/anime/1772/127705l.jpg', NULL, 'Anime'),
(157, 'Do It Yourself!!', 'The Fourth Industrial Revolution has led to the development of cutting-edge technologies that have rapidly evolved the world. As a result, schools have begun incorporating these technologies into their curriculum, leaving behind the ways of the old. One such institution is the elite Yuyu Girls\' Vocational High School, where both Serufu Yua and her childhood friend, Miku \"Purin\" Suride, have applied. Although the tech-savvy Purin is accepted to Yuyu High, the accident-prone Serufu is rejected and enters the traditional Gatagata Girls\' High School instead, driving a wedge into their friendship.\n\nOn her way to class one day, Serufu gets into a bike accident, and Rei Yasaku, a passerby who attends the same school, fixes her damaged bicycle. Serufu later finds out that Rei has a passion for old-fashioned crafts and is the head of the school\'s Do-It-Yourself (DIY) Club—which is in danger of closing due to a lack of members.\n\nRealizing that this may be her chance to repair her relationship with Purin, Serufu joins the club in hopes of creating projects that could bring them together once more. As the DIY Club welcomes new faces, Serufu learns to build not only handicrafts but also new friendships along the way!\n\n[Written by MAL Rewrite]', '2022-10-06', 'https://cdn.myanimelist.net/images/anime/1408/127129l.jpg', 'Slice of Life', 'Anime'),
(158, 'Red Shoes', 'Princes who have been turned into Dwarfs seek the red shoes of a lady in order to break the spell, although it will not be easy. A parody with a twist.', '2019-07-25', 'https://cdn.myanimelist.net/images/anime/1403/112558l.jpg', 'Comedy, Romance', 'Anime'),
(159, 'Heroine Tarumono! Kiraware Heroine to Naisho no Oshigoto', 'Freshly graduating middle school, energetic 15-year-old Hiyori Suzumi moves from her coastal hometown to Tokyo, pursuing her dream of being a track and field runner. Unfortunately, as soon as her first high school year begins, she faces an imminent problem that ultimately causes her to find a part-time job to cover living costs.\n\nAfter searching through countless prospective workplaces, Hiyori stumbles upon a posting looking for event staff, to which she gets accepted against all odds. It is revealed that she will be working as a manager-in-training for LIPxLIP, a rising male idol group composed of Yuujirou Someya and Aizou Shibasaki—both of whom are coincidentally her classmates. Despite this shocking revelation, Hiyori is resolved to do her best with balancing her studies, her ambition, and most importantly, her role as LIPxLIP\'s attendant.\n\n[Written by MAL Rewrite]', '2022-04-07', 'https://cdn.myanimelist.net/images/anime/1311/120270l.jpg', NULL, 'Anime'),
(160, 'Girls Band Cry', 'Everyone yearns to find their true purpose in life. This is also true for Nina Iseri, a 17-year-old girl looking to enroll in a good university, but the world always seems to work against her. On her very first day in Tokyo, she gets lost, ignored, and locked out of her new apartment. However, an unexpected opportunity arises when Nina meets Momoka Kawaragi, one of her favorite guitarists.\n\nAfter Nina joins Momoka for a street performance, Momoka decides they should start a band together. While Nina initially hesitates, her determination grows as they start acquiring more bandmates—the beautiful drummer Subaru Awa, the aloof keyboardist Tomo Ebizuka, and the intelligent bassist Rupa. The five girls face challenges both in the music industry and within themselves, but their shared passion for music never lets them give up on their dreams.\n\n[Written by MAL Rewrite]', '2024-04-06', 'https://cdn.myanimelist.net/images/anime/1711/140515l.jpg', 'Drama', 'Anime'),
(161, 'Bleach: Sennen Kessen-hen - Ketsubetsu-tan', 'After a brutal surprise attack by the forces of Quincy King Yhwach, the resident Reapers of the Soul Society lick their wounds and mourn their losses. Many of the surviving Soul Reaper captains train to battle without their Bankai, the ultimate technique wielded by the fiercest warriors.\n\nIn the previous assault, Ichigo Kurosaki narrowly managed to help fend off Yhwach\'s fearsome wrath. However, to ultimately defeat his godly adversary and save his allies, Ichigo must now undergo severe training that will push him beyond his physical, emotional, and mental limits.\n\nThough Yhwach already holds the upper hand in this ongoing blood feud, he also successfully recruits Uryuu Ishida, Ichigo\'s close friend and rival, to be his successor. Yhwach strikes out once again at the weakened Soul Society, intent on finally obliterating his long-standing enemies. As Ichigo struggles to attain new power, the Soul Reaper captains fight for survival and borrowed time.\n\n[Written by MAL Rewrite]', '2023-07-08', 'https://cdn.myanimelist.net/images/anime/1164/138058l.jpg', 'Action, Adventure, Supernatural', 'Anime'),
(162, 'Pui Pui Molcar: Driving School', 'New series for Pui Pui Molcar.', '2022-10-08', 'https://cdn.myanimelist.net/images/anime/1382/125361l.jpg', 'Comedy', 'Anime'),
(163, 'BanG Dream! Morfonication', 'Two special episodes featuring a violin rock band, Morfonica.', '2022-07-28', 'https://cdn.myanimelist.net/images/anime/1411/124237l.jpg', NULL, 'Anime'),
(164, 'Haikyuu!! Riku vs. Kuu', 'An intense battle rages on at the Tokyo Qualifiers for the three remaining spots in the national volleyball competition. Nekoma High School, Fukurodani High School, Nohebi Academy, and Itachiyama Academy all passionately strive to participate in the tournament. Despite various issues on the court, Nekoma especially wishes to prove they are worthy of moving on to the national level. \n\nAs the teams aim to secure their place by overcoming both their opponents and their own weaknesses, the Tokyo Qualifiers determine which teams will reign victorious and join the national competition.\n\n[Written by MAL Rewrite]', '2020-01-22', 'https://cdn.myanimelist.net/images/anime/1527/102671l.jpg', 'Sports', 'Anime'),
(165, 'Ani ni Tsukeru Kusuri wa Nai! 5', 'The Shi siblings have a lot on their plates, such as needing to stay frugal, passing their exams, and constantly dealing with each others\' antics. Older brother Fen\'s frivolous demeanor often gets on his younger sister Miao\'s nerves, leading to physical but comedic altercations. Fortunately, their friends are always around to offer a helping hand.\n\nKai Xin is Fen\'s well-meaning best friend who rivals Fen\'s absentmindedness but makes up for it with his athleticism. Miao, on the other hand, is often accompanied by her bubbly companion Miaomiao. The most recent addition to the group is Wan Sui, who is desperate to conceal his wealth but remains tirelessly loyal to his peers—sometimes roping his younger brother Xing into their excursions.\n\nSometimes, the friends\' roundabout means of problem-solving backfire. However, no predicament is going to prevent them from discovering how fun high school life can be.\n\n[Written by MAL Rewrite]', '2022-06-29', 'https://cdn.myanimelist.net/images/anime/1611/129197l.jpg', 'Comedy', 'Anime'),
(166, 'Helck', 'Three months have passed since the Demon King was defeated by a hero. Mankind rejoices over their victory, but dwellers of the demon world do not share the same sentiment. With the loss of their king, they must now hold a tournament to decide who will become his successor. \n\nMonitoring the competition is the hot-headed yet powerful Vamirio—one of the Four Heavenly Kings. Among all the participants, she is extremely distrustful of one: Helck, a human hero who claims to hate humanity. As much as she wants to get rid of him, it is impossible due to Helck\'s incredible strength and popularity. \n\nAmidst the competition, Vamirio discovers that humans have vanished from various towns. As a result of this puzzling turn of events, Vamirio grows desperate to reveal Helck\'s true intentions by carefully crafting a plan to make Helck lose. If she proves to be successful, she might uncover where his loyalty truly lies before the demon world is endangered.\n\n[Written by MAL Rewrite]', '2023-07-12', 'https://cdn.myanimelist.net/images/anime/1002/138524l.jpg', 'Action, Fantasy', 'Anime'),
(167, 'Raise wa Tanin ga Ii', 'After years of animosity, the leaders of Osaka\'s Somei and Tokyo\'s Miyama yakuza groups have called a truce—by arranging an engagement between their respective grandchildren, Yoshino Somei and Kirishima Miyama. To this end, 17-year-old Yoshino moves to Tokyo to live with the Miyama family and attend school with her new fiancé. Although Kirishima is all smiles and perfectly polite, there is something unsettling about his demeanor that Yoshino cannot put her finger on.\n\nYoshino\'s suspicions are soon confirmed: despite his manners, Kirishima is a masochistic maniac. He hurts people without batting an eye and also revels in being punished verbally and physically himself. What he wants most is a spoiled and arrogant fiancée who will ruin his life. When Yoshino does not quite meet his expectations, he reveals his true colors and openly insults her. However, instead of running away in fear, Yoshino decides to take revenge by making Kirishima fall in love with her and then ruthlessly breaking his heart.\n\n[Written by MAL Rewrite]', '2024-10-07', 'https://cdn.myanimelist.net/images/anime/1428/143773l.jpg', 'Romance', 'Anime'),
(168, 'Wu Dong Qian Kun', 'The Great Yan Empire exists in a world where respect can only be earned through strength. Within this Great Yan Empire, the four great clans have always stood above the rest. Among them, a particular incident in the Lin Clan resulted in the banishment of a certain individual who went on to start his own family, in hopes of one day being recognized again by the Lin Clan, and rejoining them…\n\nHailing from a banished family of the Great Lin Clan, when Lin Dong was very young, he watched, powerless, as his talented father was easily crushed and crippled by the overwhelming genius of the great Lin Clan, Lin Langtian.\n\nWith a despairing father, a heartbroken grandfather, and a suffering family, ever since that fateful day, Lin Dong has been driven by a deep purpose; to take revenge on the man who had taken everything and more from his family.\n\nArmed with nothing but willpower and determination, join Lin Dong as he unknowingly discovers a destiny greater than he could ever hope to imagine when he stumbles upon a mysterious stone talisman…\n\n(Source: Novel Updates)', '2019-01-27', 'https://cdn.myanimelist.net/images/anime/1857/98299l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(169, 'Kakushigoto', 'Kakushi Gotou is a somewhat popular manga artist whose works are known for inappropriate content. Because of this raunchiness, when his daughter Hime was born, he vowed to keep his profession hidden from her, believing that she will be disillusioned if she finds out. \n\nThis paranoia-induced belief leads Kakushi into hectic situations. Despite being a single father, he does his best and often resorts to extreme ends just to protect his secret, such as guising as a salaryman every day or holding emergency drills in case Hime somehow finds her way to his workplace.\n\nKakushigoto tells the story of a father and daughter living side by side, maintaining their peaceful existence as the father attempts to preserve the status quo. However, there is a saying: \"there are no secrets that time cannot reveal.\" In time, Hime must learn the reality behind the things she took for granted as she grew up.\n\n[Written by MAL Rewrite]', '2020-04-02', 'https://cdn.myanimelist.net/images/anime/1048/128385l.jpg', 'Comedy', 'Anime'),
(170, 'Girls & Panzer: Saishuushou Part 4 Specials', 'Specials included with Girls &amp; Panzer: Saishuushou Part 4 Blu-ray and DVD.', '2024-03-27', 'https://cdn.myanimelist.net/images/anime/1079/142459l.jpg', 'Comedy', 'Anime'),
(171, 'Mairimashita! Iruma-kun', 'Fourteen-year-old Iruma Suzuki has been unfortunate all his life, having to work to earn money for his irresponsible parents despite being underage. One day, he finds out that his parents sold him to the demon Sullivan. However, Iruma\'s worries about what will become of him are soon relieved, for Sullivan merely wants a grandchild, pampering him and making him attend the demon school Babyls. \n\nAt first, Iruma tries to keep a low profile in fear of his peers discovering that he is human. Unfortunately, this ends up being more difficult than he expected. It turns out that Sullivan himself is the chairman of the school, and everyone expects him to become the next Demon King!\n\nIruma immediately finds himself in an outrageous situation when he has to chant a forbidden spell in front of the entire school. With this, Iruma instantly earns a reputation he does not want. Even so, he is bound to be roped into more bizarre circumstances.\n\n[Written by MAL Rewrite]', '2019-10-05', 'https://cdn.myanimelist.net/images/anime/1009/103187l.jpg', 'Comedy, Fantasy', 'Anime'),
(172, 'Ani ni Tsukeru Kusuri wa Nai! 4', 'Shi Miao has a lot of experience dealing with her older brother\'s peculiar habits. After all her scolding, it is natural to expect that Shi Fen\'s antics would come to an end. But having spent their whole life together, it is obvious to Miao that some things never change—and maybe that is for the best.\n\nDespite his recklessness, Fen usually means well. As a result, a tight-knit friend group has formed around him and his sister. Joined by their classmates—Kai Xin, Wan Sui, and Miaomiao—the Shi siblings\' tenure at high school continues to be an absolute spectacle.\n\n[Written by MAL Rewrite]', '2020-10-02', 'https://cdn.myanimelist.net/images/anime/1416/129199l.jpg', 'Comedy', 'Anime'),
(173, 'Kami no Tou', 'There is a tower that summons chosen people called \"Regulars\" with the promise of granting their deepest desires. Whether it be wealth, fame, authority, or something that surpasses them all—everything awaits those who reach the top.\n\nTwenty-Fifth Bam is a boy who had only known a dark cave, a dirty cloth, and an unreachable light his entire life. So when a girl named Rachel came to him through the light, his entire world changed. Becoming close friends with Rachel, he learned various things about the outside world from her. But when Rachel says she must leave him to climb the Tower, his world shatters around him. Vowing to follow after her no matter what it takes, he sets his sight on the tower, and a miracle occurs.\n\nThus begins the journey of Bam, a young boy who was not chosen by the Tower but opened its gates by himself. They call his kind \"Irregulars\"—beings that have shaken the very foundation of the Tower each time they set foot inside it.\n\n[Written by MAL Rewrite]', '2020-04-02', 'https://cdn.myanimelist.net/images/anime/1702/106229l.jpg', 'Action, Adventure, Drama, Fantasy, Mystery', 'Anime'),
(174, 'Selection Project', 'Due to a weak heart, Suzune Miyama has remained bedridden for most of her childhood. However, despite her illness, she has always dreamed of becoming an idol. Eventually, her opportunity comes in the form of the seventh Selection Project—a brutal series of competitions best known as the starting point of the legendary idol Akari Amasawa.\n\nAnxious but excited, Suzune enters the preliminary round of Selection Project. Though her singing dazzles the judges and her fellow competitors, Suzune is unfortunately overcome by her nerves and freezes up in the middle of her performance. She recovers quickly, but the stumble is great enough that she loses the winning spot and is disqualified.\n\nOr so it seems—until Seira Kurusu, the girl Suzune lost to, announces that she plans to drop out of Selection Project, believing Suzune is a more talented singer and therefore deserves the right to compete. Suzune is caught off guard by the decision, but promises Seira that they will meet again as top idols. She prepares herself for the challenging obstacles that lie ahead.\n\n[Written by MAL Rewrite]', '2021-10-01', 'https://cdn.myanimelist.net/images/anime/1174/113554l.jpg', NULL, 'Anime'),
(175, 'Shingeki no Kyojin: The Final Season', 'Gabi Braun and Falco Grice have been training their entire lives to inherit one of the seven Titans under Marley\'s control and aid their nation in eradicating the Eldians on Paradis. However, just as all seems well for the two cadets, their peace is suddenly shaken by the arrival of Eren Yeager and the remaining members of the Survey Corps.\n\nHaving finally reached the Yeager family basement and learned about the dark history surrounding the Titans, the Survey Corps has at long last found the answer they so desperately fought to uncover. With the truth now in their hands, the group set out for the world beyond the walls.\n\nIn Shingeki no Kyojin: The Final Season, two utterly different worlds collide as each party pursues its own agenda in the long-awaited conclusion to Paradis\' fight for freedom.\n\n[Written by MAL Rewrite]', '2020-12-07', 'https://cdn.myanimelist.net/images/anime/1000/110531l.jpg', 'Action, Drama, Suspense', 'Anime'),
(176, 'MILGЯAM', 'Es awakens in the facility Milgram to find a strange talking animal named Jackalope staring them down. Soon, they learn their purpose: as the prison guard, Es must delve into the psyches of 10 inmates, each of them imprisoned for causing the loss of life in some form or another. Their fates rest in Es\' hands. Do the means justify an end, and how much does intent matter if the result is death? No matter how the lines between good and evil, right and wrong, and just and cruel are blurred, there are only two options Es can choose between: innocent or guilty.\n\n[Written by MAL Rewrite]', '2020-05-01', 'https://cdn.myanimelist.net/images/anime/1497/112023l.jpg', 'Suspense', 'Anime'),
(177, 'Kingdom 4th Season', 'Following the conclusion of the large-scale coalition campaign, the entirety of China is in a state of economic recovery. The victor of the battle, the state of Qin, is no different. There, the political parties led by Ying Zheng and Buwei Lü continue their inner conflict. Having played the role of king in the coalition battle, Zheng has the trust of the people—but Lü is far from out of the fight. In 18 months, he plans to interrupt Zheng\'s coming-of-age ceremony.\n\nMeanwhile, a Zhao army numbering 20,000 troops has set out toward Qin. In the royal court, due to the lack of generals capable of responding to the incoming threat, Lü slyly suggests that Zheng take command. However, Cheng Jiao, Zheng\'s half-brother, volunteers instead. As they grew to trust each other during the coalition battle, Zheng now accepts Jiao as his replacement.\n\nHowever, the Zhao forces retreat a mere half-day after clashing with Jiao\'s army. With trouble quickly brewing in the shadows, the internal struggle of Qin is only complicated further. There are only two men Zheng feels he can rely on: Bi, a general who commands 30,000 men; and Xin, the leader of the Fei Xin force.\n\n[Written by MAL Rewrite]', '2022-04-10', 'https://cdn.myanimelist.net/images/anime/1566/122794l.jpg', 'Action', 'Anime'),
(178, 'Blue Lock', 'Yoichi Isagi was mere moments away from scoring a goal that would have sent his high school soccer team to the nationals, but a split-second decision to pass the ball to his teammate cost him that reality. Bitter, confused, and disappointed, Isagi wonders if the outcome would have been different had he not made the pass. When the young striker returns home, an invitation from the Japan Football Union awaits him. Through an arbitrary and biased decision-making process, Isagi is one of three hundred U-18 strikers selected for a controversial project named Blue Lock. \n\nThe project\'s ultimate goal is to turn one of the selected players into the star striker for the Japanese national team. To find the best participant, each diamond in the rough must compete against others through a series of solo and team competitions to rise to the top. Putting aside his ethical objections to the project, Isagi feels compelled to fight his way to the top, even if it means ruthlessly crushing the dreams of 299 aspiring young strikers.\n\n[Written by MAL Rewrite]', '2022-10-09', 'https://cdn.myanimelist.net/images/anime/1258/126929l.jpg', 'Sports', 'Anime'),
(179, 'World Dai Star', 'In the 20th century, the world is experiencing a musical theater boom. Top performers known as Dai Stars enthrall the audience with their marvelous acting and singing. Among them, the greatest performers are given the title World Dai Star.\n\nYoung and inexperienced Kokona Ootori dreams of being recognized as a World Dai Star. After multiple failures, she finally gets another chance to audition for the world-renowned theater troupe Sirius. Inspired by her best friend Shizuka, Kokona takes the first steps toward her goal and works hard to improve her acting. However, the world of theater is fiercely competitive, as many other girls seek the spotlight—including Kathrina Griebel, a talented performer from Germany. In order to fulfill her dream, Kokona needs to earn the right to stand on stage above all else.\n\n[Written by MAL Rewrite]', '2023-04-09', 'https://cdn.myanimelist.net/images/anime/1203/133808l.jpg', NULL, 'Anime'),
(180, 'Gokushufudou', 'Who would have ever thought that the most feared gangster of his time now spends his days as a modest househusband? Seemingly giving up the way of the yakuza, the legendary \"Immortal Dragon\" Tatsu, best known for his prolific skirmishes against rival gangs, has abruptly vanished. Unbeknownst to most, however, Tatsu is currently staying at an apartment with his wife, doing his best to live a peaceful life.\n\nDonning his trusty apron, Tatsu is now striving to become an efficient homemaker. Because of this, he has mastered the required skills—be it cooking the most delicious dishes, making sure to get the best deals at supermarkets, and everything in between—garnering the surprise of both of his former subordinates and enemies alike. Despite being a man with quite a controversial past, Tatsu\'s new way of life will only be more eccentric from here on out!\n\n[Written by MAL Rewrite]', '2021-04-08', 'https://cdn.myanimelist.net/images/anime/1535/117726l.jpg', 'Comedy', 'Anime'),
(181, 'Ame wo Tsugeru Hyouryuu Danchi', 'Ever since the death of his grandfather, Yasuji, Kousuke Kumagaya has grown distant from his close friend, Natsume Tonai. Having grown up together like siblings in the same apartment building, the two now find themselves at odds with one another due to Natsume\'s inability to let go of the past. This rift is further exacerbated by the news that their former complex will soon be demolished.\n\nHearing about a ghost that is supposedly haunting the old complex, Kousuke\'s friends drag him into the demolition site to look around. When Kousuke finds that Natsume is also there, they get into an argument over an old camera that once belonged to Yasuji. This results in Natsume running off with it, but just as she is about to fall off the rooftop, a torrential downpour envelops the entire building, flooding the ground around it.\n\nThe young children now find themselves drifting at sea with the apartment building acting as their ship. Unable to communicate with the rest of the world, Natsume and Kousuke must reconcile their differences if they want to stand a chance at finding their way home.\n\n[Written by MAL Rewrite]', '2022-09-16', 'https://cdn.myanimelist.net/images/anime/1263/124155l.jpg', 'Fantasy', 'Anime'),
(182, 'Tiger & Bunny 2 Part 2', 'Second half of the second season of Tiger &amp; Bunny.', '2022-10-07', 'https://cdn.myanimelist.net/images/anime/1941/128060l.jpg', 'Action, Comedy, Mystery', 'Anime'),
(183, 'Love x Holic: Miwaku no Otome to Hakudaku Kankei - The Animation', 'Based on the erotic game by Atelier Kaguya Bare &amp; Bunny.\n\nIn a world where humans and demi-humans coexist, Taichi Amano has by accident drank some blood of Kuon Aoe, the most popular girl in the school. Drinking her blood changed his body to have a special constitution which awakens demi-humans.\nIn exchange for protecting Taichi from whoever would target him, the Aoe house made him cooperate with awakening Kuon...\n\n(Source: VNDB)', '2019-11-29', 'https://cdn.myanimelist.net/images/anime/1638/103708l.jpg', 'Fantasy, Hentai', 'Anime'),
(184, 'Arte', 'In the 16th century, the city of Florence booms with cultural and creative revival in celebration of the Renaissance. Arte, a delightful young lady from an aristocratic family, dreams of being an artist and contributing to the renewal of civilization. However, with her father\'s death, she ends up losing the only person who believed in her passion for art. Now she is expected to marry a nobleman and live as a refined housewife without disgracing her family name. Reluctant to accept her fate, the headstrong Arte steps into the streets in search of a master artisan to take her on as an apprentice.\n\nIn her quest for a mentor, Arte has to face harsh reality when she is completely shunned for being a female artist. No one believes that women are capable of fine craftsmanship, and therefore none are willing to accept her. Luckily, a renowned artisan by the name of Leo is persuaded to take her as his disciple since he has none anyway. And thus, Arte\'s new life begins, far from the comfort of her noble upbringing. As an apprentice, she must earn her keep while tackling various challenges along the difficult path to becoming a full-fledged, master artisan.\n\n[Written by MAL Rewrite]', '2020-04-04', 'https://cdn.myanimelist.net/images/anime/1284/106945l.jpg', 'Drama', 'Anime'),
(185, 'Ore wo Suki nano wa Omae dake ka yo', 'Amatsuyu \"Jouro\" Kisaragi is a completely average second-year high school student who has two dates over one weekend⁠—with the student council president Sakura \"Cosmos\" Akino on Saturday, then with his childhood friend Aoi \"Himawari\" Hinata on Sunday. Sadly for Jouro, both girls proclaim their love for his best friend Taiyou \"Sun-chan\" Ooga, the ace of the baseball team. Accepting each of their requests for advice and guidance, he is now responsible for helping the two girls win the heart of the same guy.\n\nUnbeknownst to his friends, Jouro\'s friendly and obtuse image is all but a ruse designed to cast himself as the clueless protagonist of a textbook romantic comedy. A schemer under his cheery facade, he makes the best of this unexpected turn of events with a new plan: get Sun-chan to fall for either Cosmos or Himawari and take the other as his own prize. But Jouro\'s last-ditch effort is threatened by the gloomy, four-eyed Sumireko \"Pansy\" Sanshokuin, who surprises Jouro with not only her knowledge of his secret personality but also a confession to the true self he hid for all this time.\n\nStuck in this hilariously messy situation, each of the five students must navigate countless lies, traps, and misunderstandings to come out on top.\n\n[Written by MAL Rewrite]', '2019-10-03', 'https://cdn.myanimelist.net/images/anime/1348/102797l.jpg', 'Comedy, Romance', 'Anime'),
(186, 'Uchuu Senkan Yamato 2205: Aratanaru Tabidachi', 'Gamilans are facing their biggest hurdle yet: their planet is dying at an alarming pace. To save his people and relocate them to habitable land, Aberdt Desler feigns submission to the oppressive rule of the planet Galman, which houses a race almost identical to the Gamilans. Desler\'s true objective is to seize control and accelerate the salvation of his nation. However, as Gamilans begin their migration, an unidentified massive power attacks them and completely warps their twin planet—Iscandar, Queen Starsha\'s home.\n\nMeanwhile, Earth is celebrating the success of the magnificent Space Battleship Yamato and its heroic crew. A new generation of promising recruits joins Yamato and its two new support ships, led by Yuki Mori and Shirou Sanada. But not everyone agrees with the past decisions of its captain, Susumu Kodai. During the Yamato\'s six-month-long training mission and diplomatic meeting with the Gamilans, the crew learns of the recent catastrophe, and against all orders, Kodai commands the fleet to Iscandar to aid the surviving refugees.\n\n[Written by MAL Rewrite]', '2021-10-08', 'https://cdn.myanimelist.net/images/anime/1888/117889l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(187, 'Tonikaku Kawaii: SNS', 'When Tsukasa Yuzaki receives a brand new smartphone as a surprise gift from her husband Nasa, she is delighted, quickly adding in contacts and mastering the arts of LINE and sticker-sending. However, her joy is short-lived: a former coworker calls in Nasa for a difficult job, and Tsukasa is dismayed to learn that her beloved might have to work through the night.\n\nFaced with her first night alone since her marriage to Nasa, will Tsukasa and her new phone be able to overcome the distance that separates the young couple and defeat the loneliness that threatens to pull her under?\n\n[Written by MAL Rewrite]', '2021-08-18', 'https://cdn.myanimelist.net/images/anime/1765/122768l.jpg', 'Comedy, Romance', 'Anime'),
(188, 'Edomae Elf', 'For more than four hundred years, the Takamimi Shrine has stood in Tokyo, enshrining the local goddess: Elda, a magical elf summoned from another world. The immortal elf has been served for 15 generations by the family who summoned her in the Edo period. Now, after Koito Koganei turns 16 years old, this responsibility falls onto her.\n\nServing as Elda\'s shrine maiden, Koito must balance her responsibilities with her daily school life. This proves to be difficult because Elda is a total social recluse who loves video games, collecting toys, and eating snacks. In an effort to get the lazy shut-in to experience more of the outside world, Koito juggles her time between indulging Elda\'s various hobbies and getting her to interact with the rest of humanity. Along the way, Koito learns more about the history of the area and what makes the goddess so loved and spoiled by the locals.\n\n[Written by MAL Rewrite]', '2023-04-08', 'https://cdn.myanimelist.net/images/anime/1171/133777l.jpg', 'Comedy, Supernatural', 'Anime'),
(189, 'Yowamushi Pedal: Limit Break', 'Unable to achieve the desired results on the first and second days of the Inter-High competition, members of the Souhoku High Bicycle Racing Club use their frustration as motivation to perform better on the final day of the race. However, it is easier said than done as they are up against the overwhelming talent of Hakone Academy and the shrewd strategies of Kyoto Fushimi High.\n\nDespite the challenge, Souhoku members are not disheartened by the obstacles that they need to overcome. After all, no matter what their opponents try, Souhoku will have the last laugh as long as they are the first to cross the finish line.\n\n[Written by MAL Rewrite]', '2022-10-09', 'https://cdn.myanimelist.net/images/anime/1853/135275l.jpg', 'Sports', 'Anime'),
(190, 'You Shou Yan', 'In the wake of scientific advancement, the once majestic mythological animals can\'t be compared to the olden days now. The mythological animal Sibuxiang received orders to descend to the mortal world and to help out other mythological animals in dire straits wandering the human world. In the secular world, he met his old colleague Pixiu in a tight spot, his drinking buddy Tuye down in his luck, and the gold and silver Jue brothers who were demoted to the mortal world... what kind of stories will happen between them?\n\n(Source: AC.QQ, translated)', '2023-04-14', 'https://cdn.myanimelist.net/images/anime/1859/135657l.jpg', 'Comedy, Fantasy', 'Anime'),
(191, '5-toubun no Hanayome ∬', 'Through their tutor Fuutarou Uesugi\'s diligent guidance, the Nakano quintuplets\' academic performance shows signs of improvement, even if their path to graduation is still rocky. However, as they continue to cause various situations that delay any actual tutoring, Fuutarou becomes increasingly involved with their personal lives, further complicating their relationship with each other.\n\nOn another note, Fuutarou slowly begins to realize the existence of a possible connection between him and the past he believes to have shared with one of the five girls. With everyone\'s feelings beginning to develop and overlap, will they be able to keep their bond strictly to that of a teacher and his students—or will it mature into something else entirely?\n\n[Written by MAL Rewrite]', '2021-01-08', 'https://cdn.myanimelist.net/images/anime/1775/109514l.jpg', 'Comedy, Romance', 'Anime'),
(192, 'Hirano to Kagiura', 'The diligent high school freshman Akira Kagiura and his senior Taiga Hirano have been roommates for half a year. Kagiura used to be anxious about his future dormitory life, but thanks to his energetic senior looking out for him, he has come to feel content and at ease. As he continues to rely on Hirano more and more each day, he develops strong feelings for his selfless friend. In the six months they have left as roommates, Kagiura is determined to put a name to the relationship he cherishes so dearly before it comes to an end. \n\n[Written by MAL Rewrite]', '2023-02-17', 'https://cdn.myanimelist.net/images/anime/1818/134200l.jpg', 'Boys Love', 'Anime'),
(193, 'IDOLiSH7 Third Beat! Part 2', 'IDOLiSH7 is more successful than ever, but no one is smiling because a new threat has taken the stage: the debuting idol group ŹOOĻ. Managed by the nefarious entertainment executive Ryou Tsukumo, they will stop at nothing to get their way, resorting to all kinds of underhanded tactics to bring down their rivals. TRIGGER\'s image has already been ruined by scandal, and IDOLiSH7 and Re:vale are headed for the same fate—or worse.\n\nMeanwhile, Zero, the legendary idol who disappeared 15 years ago, continues to haunt the present through those he left behind. His manager seems to be in contact with Tsukumo for his own schemes, and Zero\'s songwriter reveals himself in a letter after having been missing for years. IDOLiSH7 finds an ally in Re:vale to thwart ŹOOĻ\'s plans while trying to make sense of Zero\'s colleagues\' actions, but it may be impossible for everyone to emerge unscathed.\n\n[Written by MAL Rewrite]', '2022-10-02', 'https://cdn.myanimelist.net/images/anime/1458/125998l.jpg', 'Drama', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(194, 'Kagami no Kojou', 'In a tranquil neighborhood of Tokyo, seven students are avoiding going to school—hiding in their darkened bedrooms, unable to face their family and friends—until the moment they find the mirrors in their bedrooms are shining.\n\nAt a single touch, they are pulled from their lonely lives into a wondrous castle straight out of a Grimm\'s fairy tale. This whimsical place, oddly lacking in food and running water but full of electrical sockets, is home to a petulant girl in a mask, named Wolf Queen and becomes their playground and refuge during school hours. Hidden within the walls, they\'re told there\'s a key that will grant one wish, as well as a set of clues to find it. But there\'s a catch: the key must be found by the end of the school year and they must leave the premises by five o\'clock each day or else suffer a fatal end.\n\nAs time passes, a devastating truth emerges: only those brave enough to share their stories will be saved. And so they begin to unlock each other\'s stories: how a boy is showered with more gadgets than love; how another suffers a painful and unexplained rejection, and how a girl lives in fear of her predatory stepfather. As they struggle to abide by the rules of the game, a moving story unfolds, of seven characters trapped in a cycle of misunderstanding and loneliness, who are ultimately set free by the power of friendship, empathy, and sacrifice. \n\n(Source: Erewhon Books, edited)', '2022-12-23', 'https://cdn.myanimelist.net/images/anime/1954/129158l.jpg', 'Drama, Fantasy, Mystery', 'Anime'),
(195, 'Shingeki no Kyojin: The Final Season Specials', 'Shingeki no Kyojin Season 4 DVD/BD specials. They are chibi parody shorts; one video was included on each of the DVD/BDs. Each video contained eight stories (essentially chibi parody short episode 60–75) which continued the chibi parody story from the previous chibi parody specials included on the DVD/BDs of the previous seasons.', '2021-07-07', 'https://cdn.myanimelist.net/images/anime/1470/117265l.jpg', 'Comedy', 'Anime'),
(196, 'NieR:Automata Ver1.1a', 'In a post-apocalyptic world overrun by alien-crafted \"Machine Lifeforms,\" humanity is preparing for its last stand. Forced to retreat to the Moon for safety, humans are pinning their hopes on a group of man-made androids known as YoRHa soldiers. Led by the all-purpose battle android YoRHa 2-gou B-gata \"2B,\" the group will fight to take control of the Earth back from its invaders.\n\nAs war against the machines rages on, the YoRHa slowly begin to see the first shards of truth underlying the brutal conflict. Facing the harsh reality before her, the unwavering warrior 2B starts to question her very existence and just how much she must sacrifice for the sake of humanity.\n\n[Written by MAL Rewrite]', '2023-01-08', 'https://cdn.myanimelist.net/images/anime/1399/128318l.jpg', 'Action, Fantasy, Sci-Fi', 'Anime'),
(197, 'Shukufuku', 'Music video for Shukufuku by YOASOBI, the opening theme from Mobile Suit Gundam: The Witch From Mercury, containing new animation.', '2022-10-02', 'https://cdn.myanimelist.net/images/anime/1724/137431l.jpg', NULL, 'Anime'),
(198, 'Undead', 'Music video for the song Undead by YOASOBI.\n\nThe song was used as the ending theme of the anime Monogatari Series: Off &amp; Monster Season.', '2024-09-14', 'https://cdn.myanimelist.net/images/anime/1760/145472l.jpg', NULL, 'Anime'),
(199, 'Shaonian Ge Xing: Feng Hua Xue Yue Pian Part 1', 'Part one of the second season of Shaonian Ge Xing.', '2021-07-28', 'https://cdn.myanimelist.net/images/anime/1777/110315l.jpg', 'Action, Adventure, Mystery', 'Anime'),
(200, '2.5-jigen no Ririsa', 'After a disastrous romantic confession, Masamune Okumura finds solace in the fictional world of anime and manga. Now a second-year high school student and the president of the Manga Research Club, Masamune spends a peaceful existence watching the adventures of the angel Liliel, his favorite character.\n\nIn the beginning of the academic year, Masamune’s life is turned upside down when he meets first-year student Ririsa Amano, a passionate cosplay practitioner. Despite Masamune\'s initial reluctance, the determined young woman manages to convince him to become her personal photographer for the production of a collection dedicated to their common favorite character: Liliel.\n\nAs Masamune enthusiastically discovers the world of cosplay and photo editing, he is unexpectedly reunited with his childhood friend Mikari Tachibana, who has become a model in the hope of impressing her beloved upperclassman. Realizing that modeling is not enough to intrigue the hopeless otaku, Mikari decides to join the club and become a cosplayer herself, all to finally have a chance at winning Masamune\'s heart. However, Masamune\'s love for fictional characters may not be capable of extending to those who impersonate them.\n\n[Written by MAL Rewrite]', '2024-07-05', 'https://cdn.myanimelist.net/images/anime/1779/143584l.jpg', 'Comedy, Ecchi', 'Anime'),
(201, 'Fate/Grand Carnival', 'The first episode of \"season\" one was pre-aired on the Fate Project New Year\'s Eve TV Special 2020 program.', '2020-12-31', 'https://cdn.myanimelist.net/images/anime/1239/117596l.jpg', 'Comedy, Fantasy', 'Anime'),
(202, 'MF Ghost 2nd Season', 'The second race in the MFG tournament at the notoriously difficult Lake Ashinoko track is underway. Though his car is severely disadvantaged in terms of horsepower, tune-ups to Kanata Katagiri\'s Toyota 86 GT allow him to quickly soar into a qualifying position. However, torrential downpour on the final day of racing brings tire traction woes and causes all drivers to struggle. \n\nThanks to the environment he grew up in and his extensive training, Kanata surprises everyone when he is able to pull ahead of the pack—albeit with some very risky maneuvers. However, there are still two formidable competitors ahead of Kanata: last race\'s winner Michael Beckenbauer and Lake Ashinoko record holder Kouki Sawatari. But even if Kanata can close the gap, he still needs to watch out for the drivers in his rearview preying on even a single mistake that they can take advantage of. \n\n[Written by MAL Rewrite]', '2024-10-07', 'https://cdn.myanimelist.net/images/anime/1037/145338l.jpg', 'Drama', 'Anime'),
(203, 'Aggressive Retsuko (ONA) 5th Season', 'The red panda accountant Retsuko and her hyena coworker, Haida, have finally started dating. Things seem to be looking up in Retsuko\'s life; however, Haida is now grappling with unemployment and an evolving gaming addiction. As Haida attempts to keep his struggles from his girlfriend, cracks begin to form in their relationship. Moreover, Haida is evicted from his apartment and seeks refuge in an internet cafe, where he meets his online friend, a skunk named Shikabane.\n\nAs the secrets Haida hides from Retsuko pile up, their romantic journey reaches a tumultuous climax while a major presidential election looms ahead. To make matters worse, one of the candidates takes a particular interest in Retsuko and her singing talent, complicating their already hectic lives.\n\n[Written by MAL Rewrite]', '2023-02-16', 'https://cdn.myanimelist.net/images/anime/1321/132900l.jpg', 'Comedy', 'Anime'),
(204, 'Shinkai (2020)', 'Music video arranged by Numa for the song Shinkai by Eve.', '2020-12-07', 'https://cdn.myanimelist.net/images/anime/1156/110603l.jpg', NULL, 'Anime'),
(205, 'Healer Girl', 'An established discipline on par with conventional medical approaches, \"vocal medicine\" is the practice of using songs to treat health conditions and injuries. Young people around the world strive to master the art and become \"healers\" to help people through the power of their voices.\n\nAmong the many healers in training is Kana Fujii, a naturally talented singer who was inspired to pursue the profession after a life-changing experience. Along with the driven Reimi Itsushiro and the easygoing Hibiki Morishima, Kana trains at Karasuma Phoniatric Clinic under the stern yet kind mentorship of Ria Karasuma.\n\nAs they endeavor to achieve their dreams, Kana and her friends meet various colorful healers along the way, discovering that there is much more to vocal medicine than just diligent studying!\n\n[Written by MAL Rewrite]', '2022-04-04', 'https://cdn.myanimelist.net/images/anime/1727/122415l.jpg', 'Fantasy, Slice of Life', 'Anime'),
(206, 'Yuru Camp△ Season 2', 'Having spent Christmas camping with her new friends, Rin Shima embarks on a solo-camping trip to see the New Year sunrise by the sea. All goes according to plan until unforeseen weather blocks the roads back home, making a return trip impossible. Rin, who is now stranded for a few days, is invited by Nadeshiko Kagamihara to stay at her grandmother\'s house. \n\nWhat is supposed to be a two-day trip becomes an extended period of sightseeing and new experiences for Rin, and she encounters some new and old faces along the way. Yuru Camp△ Season 2 continues the story of Rin, Nadeshiko, and their friends as they further explore the joys of camping.\n\n[Written by MAL Rewrite]', '2021-01-07', 'https://cdn.myanimelist.net/images/anime/1255/110636l.jpg', 'Slice of Life', 'Anime'),
(207, 'Fuuto Tantei', 'Shoutarou Hidari, a hard-boiled private investigator from the Narumi Detective Agency, lives for the sake of protecting the peace in the city of Fuuto alongside his inquisitive partner, Philip. One fine night, Shoutarou encounters a mysterious woman named Tokime, who is soon linked to several cases of homicide and theft. Shoutarou\'s investigation leads him to people using \"Gaia Memories\"—memory units similar to thumb drives holding vast amounts of data—to turn into formidable beasts called \"Dopants.\" While the majority of Gaia users were put down by the detective team in the past, a number of them still remain, posing a great threat to public safety.\n\nOnce more, Shoutarou and Philip, Gaia users on the side of justice, must fight as Kamen Rider W—the renowned hero safeguarding Fuuto—to eradicate the nest of villainous Dopants, all while uncovering Tokime\'s true identity and confronting the long-forgotten past.\n\n[Written by MAL Rewrite]', '2022-08-08', 'https://cdn.myanimelist.net/images/anime/1945/123588l.jpg', 'Action, Mystery, Supernatural', 'Anime'),
(208, 'Dorohedoro', 'Hole—a dark, decrepit, and disorderly district where the strong prey on the weak and death is an ordinary occurrence—is all but befitting of the name given to it. A realm separated from law and ethics, it is a testing ground to the magic users who dominate it. As a race occupying the highest rungs of their society, the magic users think of the denizens of Hole as no more than insects. Murdered, mutilated, and made experiments without a second thought, the powerless Hole dwellers litter the halls of Hole\'s hospital on a daily basis.\n\nPossessing free access to and from the cesspool, and with little challenge to their authority, the magic users appear indomitable to most—aside for a few. Caiman, more reptile than man, is one such individual. He hunts them on a heedless quest for answers with only a trusted pair of bayonets and his immunity to magic. Cursed by his appearance and tormented by nightmares, magic users are his only clue to restoring his life to normal. With his biggest obstacle being his stomach, his female companion Nikaidou, who runs the restaurant Hungry Bug, is his greatest ally.\n\n[Written by MAL Rewrite]', '2020-01-13', 'https://cdn.myanimelist.net/images/anime/1230/119278l.jpg', 'Action, Comedy, Fantasy, Horror', 'Anime'),
(209, 'Komi-san wa, Comyushou desu. 2nd Season', 'After an exciting and momentous cultural festival, Shouko Komi continues her endeavor to make one hundred friends alongside her friend and classmate Hitohito Tadano. As winter begins, the class is joined by the seemingly delinquent student Makoto Katai, who has been absent since the first week of school. Despite his intimidating appearance, Katai has difficulty communicating with others and just wants to befriend his classmates.\n\nAs new friendships form and current ones deepen, Komi and Tadano’s relationship begins to change—though not necessarily for the worse.\n\n[Written by MAL Rewrite]', '2022-04-07', 'https://cdn.myanimelist.net/images/anime/1108/121157l.jpg', 'Comedy', 'Anime'),
(210, 'Zhui Xu', 'The business elite—Yi Ning traveled to the Wu Dynasty in an alternate history, and became a son-in-law with a low status—surnamed Ning, named Yi, and a courtesy name Liheng. Because Yi Ning dreamed of martial arts since childhood, he simply hid his already familiar business skills in the second life, and aspired to become a generation of heroes. Unexpectedly, the morals of the world are not as simple as he thought. After becoming Ning Yi, not only was he involved in important court cases, but the Su family that he had joined was also threatened by powerful enemies... \n\n(Source: Bilibili, Google translated &amp; edited)', '2023-04-23', 'https://cdn.myanimelist.net/images/anime/1574/134825l.jpg', 'Action, Comedy', 'Anime'),
(211, 'Dragon Ball Daima', 'After saving the world from the destructive might of Majin Buu, Gokuu Son and his allies look forward to a well-earned rest. However, unbeknownst to them, their battle was recorded and observed by Gomah, an evil being who assumes the title of King in the Demon Realm, filling the void left behind with the death of former ruler Dabura.\n\nAt Gomah\'s side is Degesu, the younger brother of Higashi no Kaioshin, a being who lords over the universe. Jealous of his brother\'s power, Degesu works alongside Gomah to steal Earth\'s Dragon Balls and preemptively subdue any potential future enemies. Calling upon the power of the legendary dragon Shenron, Gomah wishes for Gokuu and his friends to be reverted into children, intending to rob them of the limitless power that defeated Buu. With Earth\'s greatest warriors shrunken down, Gomah abducts Dende, the planet\'s acting god.\n\nBut Gokuu refuses to be set back by his new body, working to master his younger form to fight as proficiently as he could as an adult. Joined by Kaioshin and Glorio—a mysterious but seemingly rebellious demon—Gokuu pursues Gomah to the Demon Realm in order to rescue Dende and restore his friends to their natural ages.\n\n[Written by MAL Rewrite]', '2024-10-11', 'https://cdn.myanimelist.net/images/anime/1723/145231l.jpg', 'Action, Adventure, Comedy, Fantasy', 'Anime'),
(212, 'Atarashii Joushi wa Do Tennen', 'After 26-year-old Kentarou Momose develops health problems due to his boss\' abuse, he quits his job and joins a different company. Now, he hopes to start anew under the care of his mentor and direct supervisor, 34-year-old Yuusei Shirosaki.\n\nShirosaki is a capable boss admired by his coworkers, which makes Momose fear letting him down and reliving the past traumas. However, Momose can rest easy, as Shirosaki is always delighted to help—even if he looks absolutely ridiculous doing it. Although it may take some adjusting, Momose realizes that there is no need for caution around his new, endearingly eccentric boss after all.\n\n[Written by MAL Rewrite]', '2023-10-07', 'https://cdn.myanimelist.net/images/anime/1630/138388l.jpg', 'Slice of Life', 'Anime'),
(213, 'Tsuma, Shougakusei ni Naru.', 'The moments Keisuke Niijima shared with his wife, Takae, were the happiest in his life. After their first meeting as coworkers, the bond between them gradually became stronger. They eventually married and were blessed with a daughter named Mai soon after. However, following Takae\'s death, time seems to have stopped for Keisuke, resulting in his inability to build a proper relationship with his daughter.\n\nTen years later, the gloomy Niijima household is bound for change when a little girl knocks at the door—claiming to be Takae\'s reincarnation. After confirming her identity, Keisuke\'s world brightens once more as he revels at the thought of making new memories with his beloved family. Unfortunately, this fortuitous miracle comes with its obvious drawbacks, and one mistake will spell more tragic consequences for Keisuke and everyone else involved.\n\n[Written by MAL Rewrite]', '2024-10-06', 'https://cdn.myanimelist.net/images/anime/1752/145548l.jpg', 'Comedy, Romance', 'Anime'),
(214, 'Tokyo Autumn Session', 'What does it mean to become an adult? While it may seem like it brings freedom, the transition into adulthood can also create a gap between loved ones. For the teenagers who once laughed together, work, distance, and responsibilities widen the rift between them. Reminiscence reminds them of the joy-filled times when they were more carefree, and even now, through thick and thin, their love perseveres.\n\n[Written by MAL Rewrite]', '2020-01-24', 'https://cdn.myanimelist.net/images/anime/1685/105598l.jpg', NULL, 'Anime'),
(215, 'Bleach 20th PV', 'In celebration of 20 years of Bleach, the PV is a compilation of newly reworked scenes from Bleach containing new animation.', '2024-10-05', 'https://cdn.myanimelist.net/images/anime/1357/145984l.jpg', 'Action, Supernatural', 'Anime'),
(216, 'Tenchi Souzou Design-bu: Idea 13', 'Hatching an original idea is not always easy for the Heaven\'s Design Team. With a meticulous client such as God, even the most confident of its members may doubt their ability to create a perfect creature that satisfies his demands. The whole team is then put to the test when God requests a single animal possessing five particular qualities. This strange animal may be one of the design team\'s biggest jobs yet!\n\n[Written by MAL Rewrite]', '2021-04-02', 'https://cdn.myanimelist.net/images/anime/1298/113966l.jpg', 'Comedy, Fantasy', 'Anime'),
(217, 'Eizouken ni wa Te wo Dasu na!', 'Midori Asakusa sees the world a bit differently. Always having her nose in a sketchbook, Asakusa draws detailed landscapes and backgrounds of both the world around her and the one within her boundless imagination. Even the simple act of doodling on a wall evolves into an emergency repair on the outer hull of her spaceship. She is only brought back to reality by her best friend Sayaka Kanamori. The pair are stark opposites, with Asakusa\'s childlike wonder contrasted by Kanamori\'s calculated approach to life. \n\nAfter a chance encounter where the two \"save\" the young model Tsubame Misuzaki from her overprotective bodyguard, a connection instantly sparks between Asakusa and Misuzaki, as both share an intense passion for art and animation. Whereas Asakusa is interested in backgrounds and settings, Misuzaki loves drawing the human form. Sensing a money-making opportunity, Kanamori suggests that they start an animation club, which they disguise as a motion picture club since the school already has an anime club. Thus begins the trio\'s journey of producing animation that will awe the world. \n\nFrom the brilliant mind of Masaaki Yuasa, Eizouken ni wa Te wo Dasu na! is a love letter to animation, wildly creative in its approach, and a testament to the potential of the medium.\n\n[Written by MAL Rewrite]', '2020-01-06', 'https://cdn.myanimelist.net/images/anime/1680/110451l.jpg', 'Adventure, Award Winning, Comedy', 'Anime'),
(218, 'Kidou Senshi Gundam: The Origin - Zenya Akai Suisei', 'What was the tragedy that decided the fates of Char Aznable, the man later nicknamed the \"Red Comet\" as an ace pilot of the Zeon forces, and his sister Sayla Mass?\n\nThe two siblings\' journeys, brought on by the sudden death of their father Zeon Zum Deikun who was a leader of the Spacenoids, are depicted in the four episodes of \"Chronicle of Char and Sayla.\"\n\nThe Zabi family who seize control of Side 3 and lead the Principality of Zeon, the early days of many renowned Zeon ace pilots who later fight in the One Year War, the secrets of mobile suit development, conflicts with the Earth Federation Forces, and the road leading to the outbreak of war—all will be revealed.\n\n(Source: Official Website)', '2019-04-29', 'https://cdn.myanimelist.net/images/anime/1897/100015l.jpg', 'Action, Sci-Fi', 'Anime'),
(219, 'Chihayafuru 3', 'Winning the high school team tournament was a great accomplishment for the Mizusawa members. Each of them has made great strides in improving themselves, and the victory symbolizes how far they have come. But after accomplishing one goal, their individual aims are within reach. Chihaya Ayase has her sights set on Shinobu Wakamiya and the title of Queen, and now that Taichi Mashima has made it into Class A, he can finally compete against Arata Wataya. Everyone in Mizusawa wants to get better, and there is no telling what the future holds if they keep trying.\n\n[Written by MAL Rewrite]', '2019-10-23', 'https://cdn.myanimelist.net/images/anime/1898/110709l.jpg', 'Drama, Sports', 'Anime'),
(220, 'Tensei shitara Ken deshita', 'A nameless sword wakes up to discover he has been reincarnated from his former life as a human. With his power of telekinesis, he moves around this new world, acquiring several skills and abilities. When the sword comes upon a forest filled with monsters, he meets a young girl fleeing from a beast. Grabbing the sword, the girl easily defeats the monster. After introducing herself as Fran, she names the sword \"Shishou\" and officially becomes his wielder.\n\nThe two set out to become adventurers, but unfortunately for Fran, she is a member of the Black Cat Tribe—a Beastkin group with a bad reputation. No member of this tribe has ever evolved into a mightier beast, but Fran plans to be the first and achieve her parents\' dream. As Shishou promises to remain her sword until she attains her goal, they form an unstoppable partnership of impressive strength.\n\n[Written by MAL Rewrite]', '2022-10-05', 'https://cdn.myanimelist.net/images/anime/1191/127909l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(221, 'Kororon', 'Music video for the song Kororon by Eve.', '2023-08-27', 'https://cdn.myanimelist.net/images/anime/1559/138265l.jpg', NULL, 'Anime'),
(222, 'Horimiya', 'On the surface, the thought of Kyouko Hori and Izumi Miyamura getting along would be the last thing in people\'s minds. After all, Hori has a perfect combination of beauty and brains, while Miyamura appears meek and distant to his fellow classmates. However, a fateful meeting between the two lays both of their hidden selves bare. Even though she is popular at school, Hori has little time to socialize with her friends due to housework. On the other hand, Miyamura lives under the noses of his peers, his body bearing secret tattoos and piercings that make him look like a gentle delinquent.\n\nHaving opposite personalities yet sharing odd similarities, the two quickly become friends and often spend time together in Hori\'s home. As they both emerge from their shells, they share with each other a side of themselves concealed from the outside world.\n\n[Written by MAL Rewrite]', '2021-01-10', 'https://cdn.myanimelist.net/images/anime/1695/111486l.jpg', 'Romance', 'Anime'),
(223, 'Vanitas no Karte Part 2', 'Vanitas and Noé Archiviste head out to the town of Gévaudan in search of the \"Beast,\" an enormous wolf-like creature that has slaughtered hundreds of people. Suspecting that the Beast is a curse-bearing vampire, Vanitas primarily aims to heal it using the powers of his grimoire.\n\nAlong the way, the two get separated and suddenly travel back to the past—to the exact moment the Beast is lurking in the woods. After a battle against the gigantic wolf and a vampire hunter, Vanitas decides to team up with Jeanne in order to find Noé. Despite being allies, Jeanne\'s goal is the opposite of Vanitas\', as she was tasked to kill the Beast—suspecting it may be someone she used to know.\n\nMeanwhile, a severely wounded Noé is picked up by the mysterious Chloé d\'Apchier and her servant. Like Noé, Chloé is a vampire whose existence was erased from the public\'s knowledge. She has been a guardian for future generations and once tried to find a way to become human again. While Noé is grateful to Chloé for her hospitality, little does he know that she might be siding with forces far more dangerous than the Beast itself.\n\n[Written by MAL Rewrite]', '2022-01-15', 'https://cdn.myanimelist.net/images/anime/1247/120579l.jpg', 'Action, Fantasy, Mystery', 'Anime'),
(224, 'Shen Yin Wangzuo 2nd Season', 'Revealing himself to be a Dual Knight, Long Hao Chen triumphs in his match within his temple and advances to the finals. But before the grand finals can begin, ranking matches are conducted in each temple to determine the strongest within. During the rankings, Hao Chen is injured, enraging Sheng Cai\'er and driving her to seek vengeance for what happened to him. Her actions cause a fight between the Knight Temple and Assassin Temple, only to be subdued after a shocking revelation—that Sheng Cai\'er is a Reincarnated Saint.\n\nThe finals for the Demon Hunting Team Competition begin with the division of the sixty remaining participants into six groups. The top sixteen participants are then further pitted against each other to determine the top three. Each of the top three will be rewarded with a spiritual stove and the right to pick their teammates.\n\nIn order to become a knight that is capable of defeating the Demon Lord, Long Hao Chen must strive to be first in this competition so he can select the best teammates to give him a fighting chance.\n\n[Written by MAL Rewrite]', '2022-11-10', 'https://cdn.myanimelist.net/images/anime/1279/126735l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(225, 'Psycho-Pass Movie: Providence', 'In 2113, the Ministry of Foreign Affairs (MFA) dissolved their secret paramilitary unit known as the Peacebreakers. However, the squad disappeared, and their activities remained a mystery. Five years later, the Peacebreakers resurface when they murder Milcia Stronskaya, a scientist in possession of highly classified documents essential to the future of the Sybil System—Japan\'s surveillance structure that detects potential criminals in society.\n\nTo investigate the incident and prepare for a clash against the Peacebreakers in coordination with the MFA, the chief of the Public Safety Bureau decides to recruit the former Enforcer Shinya Kougami back into the force. Having defected years ago, Kougami currently works for the MFA under Frederica Hanashiro\'s command. Kougami\'s return creates tensions between him and his former colleagues Akane Tsunemori and Nobuchika Ginoza, but they must set aside their past grudges to focus on ensuring the security of the Sybil System.\n\n[Written by MAL Rewrite]', '2023-05-12', 'https://cdn.myanimelist.net/images/anime/1244/134653l.jpg', 'Action, Mystery, Sci-Fi, Suspense', 'Anime'),
(226, 'Yuuki Bakuhatsu Bang Bravern', 'In a world where humanoid armored weapons known as \"Titatonostrider\" (\"TS\" for short) are used in warfare, troops from various countries converge on the island of Oahu, Hawaii, including Ao Isami of the Japan Ground Self-Defense Force and Lewis Smith of the United States Marine Corps. Isami and Smith cross paths during battle, but suddenly, their teams are attacked by an unknown enemy, scattering soldiers and sending their forces into disarray. In order to save their friends and survive on the deadly battlefield, they must fight with every ounce of courage and pride that they can muster.\n\n(Source: Crunchyroll News, edited)', '2024-01-11', 'https://cdn.myanimelist.net/images/anime/1872/140863l.jpg', 'Action, Comedy, Sci-Fi', 'Anime'),
(227, 'Zhu Xian', 'Zhang Xiaofan, who was tragically orphaned overnight, was accepted as a disciple by Qingyunmen. After five years of hard training, he excelled in the martial arts of the Seven Vessels of the Mastermen. Senior sister Lu Xueqi was in danger and met Baguio, the woman who rescued the demon sect. At the same time, new dangers were also waiting for him.\n\n(Source: Tencent Video)', '2022-08-02', 'https://cdn.myanimelist.net/images/anime/1830/117534l.jpg', 'Adventure, Fantasy', 'Anime'),
(228, 'Pokemon Concierge', 'After a series of misfortunes, the stressed-out Haru quits her corporate job in favor of working as a concierge at the Pokémon Resort. Managed by the cheerful Watanabe, the Pokémon Resort is a place where both people and Pokémon come to unwind. While Haru finds it difficult to abandon the priorities of her past life, this new job is just right for learning to relax and focus on what matters the most in life: companionship.\n\n[Written by MAL Rewrite]', '2023-12-28', 'https://cdn.myanimelist.net/images/anime/1064/139658l.jpg', 'Fantasy', 'Anime'),
(229, 'Gotcha!', 'In a bright, grandiose city, a young boy and girl look for their partners amidst a technicolor tour de force. As the two embark on their respective quests, they encounter the familiar faces of those who have made their mark on the Pokémon world. Villains, champions, rivals, and professors alike grace the tallest skyscrapers and largest screens while the adventurous teens carry on in the search for their companions.\n\nGotcha! takes its viewers on a nostalgic trip to the riveting realm of Pokémon, encapsulating the electrifying essence of the franchise.\n\n[Written by MAL Rewrite]', '2020-09-29', 'https://cdn.myanimelist.net/images/anime/1637/109512l.jpg', 'Fantasy', 'Anime'),
(230, 'Semantic Error', 'No matter how hard Chu Sangwoo tries to resist it, every part of his body wants to grab onto Jang Jaeyoung and never let go. With the spontaneous Jaeyoung by his side, Sangwoo learns that breaking free from his routine and acting on impulse is not always a bad thing. Perhaps submitting to his true feelings will bring him even closer to Jaeyoung, more than he could ever imagine.\n\n[Written by MAL Rewrite]', '2021-03-12', 'https://cdn.myanimelist.net/images/anime/1362/115895l.jpg', 'Boys Love', 'Anime'),
(231, 'Yong Sheng', 'Fang Han, a humble family slave, held the belief since childhood that \"I would rather be a beggar than a slave\", and traversed the world by himself. With an unyielding stubbornness, he broke through the mystery of supernatural powers and forged his body into an immortal body. Work hard to step into the fairyland step by step, and eventually become the peak king.\n\n(Source: bilibili)', '2022-01-29', 'https://cdn.myanimelist.net/images/anime/1799/119635l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(232, 'Wu Liuqi: Xuanwu Guo Pian', 'In order to protect the residents of Xiaoji Island and the peaceful life here, Wu Liuqi and his partners Dabao and Xiaofei embark on a journey to the Xuanwu Kingdom to find out the truth about his identity and a way to save the island. Waiting for them is more unknowns and adventures.\n\n(Source: bilibili, edited)', '2021-01-21', 'https://cdn.myanimelist.net/images/anime/1884/111224l.jpg', 'Action, Adventure, Comedy, Drama, Mystery', 'Anime'),
(233, 'Fate/Grand Order: Shuukyoku Tokuiten - Kani Jikan Shinden Solomon', 'After battling their way through all seven Singularities, the Chaldea Security Organization has finally arrived at the endpoint of the Grand Order: The Final Singularity, Grand Temple of Time: Solomon. Now is the time to defeat the root of all evil, Solomon, the King of Mages. Now is the time to reclaim the future. With the final operation looming large, Romani Archaman considers the choices he will soon have to make, Mash Kyrielight dwells on life\'s limitations, and Fujimaru prepares to receive a new Mystic Code. All their many encounters have led to this moment as Fujimaru and Mash at last embark on their final operation...\n\n(Source: anime.fate-go.us)', '2021-07-30', 'https://cdn.myanimelist.net/images/anime/1507/114957l.jpg', 'Action, Fantasy', 'Anime'),
(234, 'Shiroi Suna no Aquatope', 'After leaving her idol career behind, Fuuka Miyazawa finds herself on a spontaneous flight to Okinawa instead of returning home to her pity party in Morioka. Bearing a heavy heart and nowhere to go, she aimlessly wanders around the area until she stumbles upon Gama Gama Aquarium—an aging aquarium on the verge of closing down.\n\nWith a lack of visitors and costly but necessary repairs needed to keep its doors open, the director is faced with shutting down the establishment for good by the end of the summer. The director\'s aquatic life-loving granddaughter—Kukuru Misakino—cannot stand the thought of the aquarium closing and is determined to make enough money by the end of the season to keep the doors open.\n\nSeeing the unique magic of the aquarium, Fuuka begs Kukuru for a job; however, she soon finds that her lack of experience makes her more of a hindrance than anything else. At the same time, Kukuru realizes that her ambitious goal might be more than she can handle. With mounting pressure from all around them, will Kukuru and Fuuka be able to save the one place they hold close to their hearts?\n\n[Written by MAL Rewrite]', '2021-07-09', 'https://cdn.myanimelist.net/images/anime/1932/114952l.jpg', 'Drama', 'Anime'),
(235, 'Wagaya no Liliana-san The Animation', 'The story of Wagaya no Liliana-san spins around relationship between  Liliana, girl sensitive to mana due to her species as \"Magi\" and Tatsuya, a student. They first meet when Tatsuya finds her unconscious in dark alley surrounded by wild dogs which he banished. After that, Liliana decided to give Tatsuya her heart and body so she becomes Tatsuya´s girlfriend.\n\n[Written by B1NARE]', '2019-01-31', 'https://cdn.myanimelist.net/images/anime/1269/103734l.jpg', 'Hentai', 'Anime'),
(236, '** Kouhai', 'A special governmental program has been introduced to counteract the declining birth rates of demi-human races suffering due to a lack of male members. Through a so-called \"assistance system,\" randomly selected humans are required to mate with designated partners—be it elves, sirens, or even dragons.\n\nIris Thea Eaderlindt, an elven princess known for her open-mindedness and friendly attitude towards humans, is transferred to the Ark Metropolitan Academy. Coincidentally, her new teacher has been selected as her mating partner. Anxious yet determined to fulfill her duty of securing the future of her race, she starts partaking in sexual activities with him. To her surprise, Iris discovers that her partner\'s ancestors were orcs, well known for their extraordinary sexual prowess.\n\nAs more demi-human students join the class and find out about their teacher\'s \"side job,\" it becomes increasingly difficult for Iris to keep her partner\'s attention solely on her.\n\n[Written by MAL Rewrite]', '2020-01-31', 'https://cdn.myanimelist.net/images/anime/1839/104009l.jpg', 'Fantasy, Hentai', 'Anime'),
(237, 'Fate/stay night Movie: Heaven\'s Feel - II. Lost Butterfly', 'The Fifth Holy Grail War continues, and the ensuing chaos results in higher stakes for all participants. Shirou Emiya continues to participate in the war, aspiring to be a hero of justice who saves everyone. He sets out in search of the truth behind a mysterious dark shadow and its murder spree, determined to defeat it.\n\nMeanwhile, Shinji Matou sets his own plans into motion, threatening Shirou through his sister Sakura Matou. Shirou and Rin Toosaka battle Shinji, hoping to relieve Sakura from the abuses of her brother. But the ugly truth of the Matou siblings begins to surface, and many dark secrets are exposed.\n\nFate/stay night Movie: Heaven\'s Feel - II. Lost Butterfly continues to focus on the remaining Masters and Servants as they fight each other in the hopes of obtaining the Holy Grail. However, as darkness arises within Fuyuki City, even the state of their sacred war could be in danger.\n\n[Written by MAL Rewrite]', '2019-01-12', 'https://cdn.myanimelist.net/images/anime/1974/98158l.jpg', 'Action, Fantasy', 'Anime'),
(238, 'Cang Yuan Tu: Dongning Fu Fanwai Pian', NULL, '2024-07-13', 'https://cdn.myanimelist.net/images/anime/1747/144105l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(239, 'Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen 2nd Season', 'When Myne learns that the Holy Church is in need of mana for their relics, she sees it as her chance to be cured of her life-threatening mana disorder. After seeing their bountiful library, she throws herself headfirst into the Church\'s grasp and begs to join their order. In exchange for her service and her unusually bountiful supply of mana, Myne is given the blue robes of a noble-born apprentice priestess, despite being a commoner. To Myne, all this talk of mana and nobility is trivial, as she now has access to an unlimited supply of books!\n\nAs Myne transitions into the next phase of her life in this new world, she soon learns that achieving her dream has come at a heavy cost. Noble society is severe, unforgiving, and fueled by politics and neglect. She must now deal with the class conflict between the noble-born blue robes and the common-born grey robes, the High Priest\'s attempts to oust her, and constant behavioral issues from her new retainers. With the help of her family, friends, and the enigmatic Head Priest whose loyalties and motives remain unknown, Myne seeks to overcome these obstacles and continue on the path to becoming her ideal self—the ultimate librarian!\n\n[Written by MAL Rewrite]', '2020-04-05', 'https://cdn.myanimelist.net/images/anime/1464/107998l.jpg', 'Fantasy', 'Anime'),
(240, 'Sand Land: The Series', 'In the far future, war has destroyed the entire Earth, leaving only a barren wasteland where the supply of water is controlled by the greedy king. In search of a long-lost lake, Sheriff Rao asked the king of the demons for help...and got the king\'s son, Beelzebub, and his assistant, Thief. Together the unlikely trio sets off across the desert, facing dragons, bandits and the deadliest foe of all... the King\'s army itself! \n\n(Source: Viz Media)', '2024-03-20', 'https://cdn.myanimelist.net/images/anime/1004/142114l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(241, 'Trinity Seven Movie 2: Heavens Library to Crimson Lord', 'Heavens Library to Crimson Lord brings back Arata, Lilith, and the rest of the Trinity Seven to face off against the greatest enemy in the history of the Trinity Seven; Lilith\'s own father, who is revealed to be the strongest Demon Lord, challenges Arata who is now a Demon Lord candidate.\n\n(Source: Avex Pictures, edited)', '2019-03-29', 'https://cdn.myanimelist.net/images/anime/1215/100764l.jpg', 'Action, Comedy, Fantasy, Romance, Ecchi', 'Anime'),
(242, 'Kimetsu no Yaiba Movie: Mugen Ressha-hen', 'After a string of mysterious disappearances begin to plague a train, the Demon Slayer Corps\' multiple attempts to remedy the problem prove fruitless. To prevent further casualties, the Flame Pillar, Kyoujurou Rengoku, takes it upon himself to eliminate the threat. Accompanying him are some of the Corps\' most promising new blood: Tanjirou Kamado, Zenitsu Agatsuma, and Inosuke Hashibira, who all hope to witness the fiery feats of this model demon slayer firsthand.\n\nUnbeknownst to them, the demonic forces responsible for the disappearances have already put their sinister plan in motion. Under this demonic presence, the group must muster every ounce of their willpower and draw their swords to save all two hundred passengers onboard. As things begin to spiral out of control, Tanjirou\'s resolve and commitment to duty are put to the test.\n\n[Written by MAL Rewrite]', '2020-10-16', 'https://cdn.myanimelist.net/images/anime/1704/106947l.jpg', 'Action, Supernatural', 'Anime'),
(243, '86', 'According to the Republic of San Magnolia, their ongoing war against the Giadian Empire has no casualties—however, that is mere propaganda. While the silver-haired Alba of the Republic\'s eighty-five sectors live safely behind protective walls, those of different appearances are interned in a secret eighty-sixth faction. Known within the military as the Eighty-Six, they are forced to fight against the Empire\'s autonomous Legion under the command of the Republican \"Handlers.\"\n\nVladilena Milizé is assigned to the Spearhead squadron to replace their previous Handler. Shunned by her peers for being a fellow Eighty-Six supporter, she continues to fight against their inhumane discrimination. Shinei Nouzen is the captain of the Spearhead squadron. Infamous for being the sole survivor of every squadron he\'s been in, he insists on shouldering the names and wishes of his fallen comrades. When the fates of these young souls from two different worlds collide, will it ignite the spark that lights their path to salvation, or will they burn themselves in the flames of despair?\n\n[Written by MAL Rewrite]', '2021-04-11', 'https://cdn.myanimelist.net/images/anime/1987/117507l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(244, 'Boku no Kokoro no Yabai Yatsu 2nd Season', 'After an eventful winter break, Kyoutarou Ichikawa and Anna Yamada reunite with a stronger bond. They continue to grow in their own ways, with Yamada taking on more challenging photoshoots and Ichikawa maturing both physically and emotionally as he tackles his affections for Yamada. However, spending time together outside of school allows for their relationship to deepen, and it becomes increasingly difficult to deny their budding romantic feelings.\n\nGrappling with these unexpected and new emotions, Ichikawa and Yamada realize that, with the passage of time, their relationship is bound to change—and they must ultimately decide whether they wish to remain close friends or finally become a couple.\n\n[Written by MAL Rewrite]', '2024-01-07', 'https://cdn.myanimelist.net/images/anime/1643/138581l.jpg', 'Comedy, Romance', 'Anime'),
(245, 'Hua Jianghu: Bu Liang Ren VI', 'Sixth season of Hua Jianghu: Bu Liang Ren.', '2023-03-02', 'https://cdn.myanimelist.net/images/anime/1364/126727l.jpg', 'Action, Drama, Fantasy, Romance', 'Anime'),
(246, 'Watashi no Shiawase na Kekkon: Watashi no Shiawase na Katachi', 'Though hesitant, Miyo Saimori decides she is finally ready to attend a party with her fiancé Kiyoka Kudou. She has been practicing the etiquette needed for such an occasion with the help of Kiyoka\'s sister, Hazuki. At first, Miyo feels pressured by all the attention she receives; however, she eventually grows used to the unfamiliar environment and makes new acquaintances. Through these encounters, Miyo learns more about her family\'s past and the significance of creating connections with others.\n\n[Written by MAL Rewrite]', '2024-03-15', 'https://cdn.myanimelist.net/images/anime/1508/137052l.jpg', 'Fantasy, Romance', 'Anime'),
(247, 'Kaibutsu', 'Beastars-themed animated music video for the song Kaibutsu by YOASOBI.', '2021-01-13', 'https://cdn.myanimelist.net/images/anime/1959/128937l.jpg', NULL, 'Anime'),
(248, 'Bishoujo Senshi Sailor Moon Cosmos Movie', 'The final battle for the Sailor Guardians begins as they face Sailor Iron Mouse, Sailor Aluminum Siren, Sailor Lead Crow, Sailor Tin Nyanko and more.\n\n(Source: Netflix)', '2023-06-09', 'https://cdn.myanimelist.net/images/anime/1388/133092l.jpg', 'Romance', 'Anime'),
(249, 'Yao Shen Ji 7th Season', 'Seventh season of Yao Shen Ji.', '2023-01-14', 'https://cdn.myanimelist.net/images/anime/1814/145610l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(250, 'Tensei shitara Slime Datta Ken 2nd Season Part 2', 'The nation of Tempest is in a festive mood after successfully overcoming the surprise attack from the Falmuth Army and the Western Holy Church. Beyond the festivities lies a meeting between Tempest and its allies to decide the future of the Nation of Monsters. The aftermath of the Falmuth invasion, Milim Nava\'s suspicious behavior, and the disappearance of Demon Lord Carrion—the problems seem to keep on piling up.\n\nRimuru Tempest, now awakened as a True Demon Lord, decides to go on the offensive against Clayman. With the fully revived Storm Dragon Veldora, Ultimate Skill Raphael, and other powerful comrades, the ruler of the Tempest is confident in taking down his enemies one by one until he can face the man pulling the strings.\n\n[Written by MAL Rewrite]', '2021-07-06', 'https://cdn.myanimelist.net/images/anime/1033/118296l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(251, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 2nd Season', 'Life back on the cruise following the Island Special Examination is anything but smooth sailing. Almost immediately after their return, the first-year students of Tokyo Metropolitan Advanced Nurturing High School face yet another special exam, with both class and individual points on the line.\n\nIn addition to the complicated ruleset, more issues arise in the form of Kakeru Ryuuen and Kei Karuizawa. Angered by the previous test\'s outcome, Ryuuen is dead set on outdoing every class in the new challenge using any means necessary. Meanwhile, Karuizawa, a crucial pillar of Class D, is close to crumbling under the pressure of her past.\n\nThe stage is now set for Kiyotaka Ayanokouji to once again—using the full extent of his planning, foresight, and ruthless manipulation—steer Class D to victory as dangerously close enemy forces try to bring it down.\n\n[Written by MAL Rewrite]', '2022-07-04', 'https://cdn.myanimelist.net/images/anime/1010/124180l.jpg', 'Drama, Suspense', 'Anime'),
(252, 'Yama no Susume: Next Summit', 'While reminiscing about her journey so far, Aoi Yukimura finds herself eager to go mountaineering once more. A likely opportunity arises when Koharu Senjuin invites Aoi to check out the Mountaineering Club after school. As the head of the club, Koharu speaks enthusiastically of the activities she and the other members partake in, especially as they strive to reach the top in various competitions.\n\nAlthough impressed by the club\'s dedication to its goals, Aoi feels reluctant to join, preferring to learn and enjoy mountaineering at her own pace. Her experience during this brief visit, however, leaves her wondering why she climbs mountains in the first place. With the support of her friends, Aoi searches for the true motivation behind her hobby, all while continuing to train for the highly anticipated second trip to the summit of Mt. Fuji.\n\n[Written by MAL Rewrite]', '2022-10-05', 'https://cdn.myanimelist.net/images/anime/1942/126897l.jpg', 'Adventure, Slice of Life', 'Anime'),
(253, 'Masamune-kun no Revenge R', 'With the tumultuous cultural festival behind him, Masamune Makabe continues his efforts to carry out his revenge: to make the \"Cruel Princess\" Aki Adagaki deeply fall for him and then immediately dump her. As his class is going on a trip to Paris, widely known as the City of Love, Masamune has the perfect opportunity to get even for his childhood heartbreak.\n\nBefore Masamune can impress Aki, the two meet Muriel Besson, a French high school otaku who aspires to create a romantic comedy manga series. Muriel believes Masamune is the ideal model for the protagonist and asks for his help. The boy reluctantly agrees, dragging Aki along to provide inspiration for the love interest\'s character. But to do so, the two must show Muriel what Japanese love is like.\n\nTo make matters more complicated, Kanetsugu Gasou is masquerading as Aki\'s childhood friend, Masamune, to trick and use her. With mix-ups and love rivals galore, Masamune\'s revenge is proving to be quite the difficult task.\n\n[Written by MAL Rewrite]', '2023-07-03', 'https://cdn.myanimelist.net/images/anime/1667/135587l.jpg', 'Comedy, Romance', 'Anime'),
(254, 'Ai no Utagoe wo Kikasete', 'Satomi Amano is a model student as well as the daughter of the leading project manager of Hoshima, a company that has revolutionized AI technology. However, due to her standing, Satomi\'s presence has isolated her from her classmates—an obstacle she knows she may never overcome.\n\nOn an otherwise uneventful day, while preparing for school, Satomi uncovers her mother\'s latest exciting proposition: an AI that will prove whether robots can live alongside humans. Intrigued by how her mother will commence the project, Satomi makes her way to school, but standing in front of the class is none other than the AI herself.\n\nAs the subject of research, Shion Ashimori is tasked to fit in like a normal teenage girl without exposing her true identity. However, Shion has another goal in mind—to make Satomi happy instead. With her talent for singing, Shion strives to compose harmonious melodies that not only connect her with her newfound friends but also dispel the dissonance within Satomi\'s heart.\n\n[Written by MAL Rewrite]', '2021-10-29', 'https://cdn.myanimelist.net/images/anime/1535/116583l.jpg', 'Drama, Sci-Fi', 'Anime'),
(255, 'Ashura-chan', 'Music video for the song Ashura-chan by Ado.', '2021-10-28', 'https://cdn.myanimelist.net/images/anime/1923/127760l.jpg', NULL, 'Anime'),
(256, 'Boku no Hero Academia the Movie 1: Futari no Hero Specials', 'Episode 1 is based on one-shot manga released in Vol. Origin, it explores the back-story of All Might\'s past and his journey into becoming the No.1 hero.\n\nEpisode 2 is an epilogue picture drama for Boku no Hero Academia the Movie: Futari no Hero.\n\nShort specials included with the Blu-ray/DVD release of Boku no Hero Academia the Movie: Futari no Hero.', '2019-02-13', 'https://cdn.myanimelist.net/images/anime/1420/96793l.jpg', 'Action', 'Anime'),
(257, 'Meng Qi Shi Shen: Huanxi Zhui Hun', 'The third season of Meng Qi Shi Shen.', '2022-07-05', 'https://cdn.myanimelist.net/images/anime/1511/125055l.jpg', 'Comedy, Drama, Gourmet, Romance', 'Anime'),
(258, 'Marine Shukkou!!', 'Animated music video for the song Marine Shukkou!! by Marine Houshou.', '2022-04-27', 'https://cdn.myanimelist.net/images/anime/1450/123348l.jpg', NULL, 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(259, 'Fairy Tail: 100-nen Quest', 'For over one hundred years, a special quest has been waiting for a wizard skilled enough to complete it. On the northern continent of Guiltina, there are five immensely powerful Dragon Gods who possess great destructive force that can only be quelled by sealing them away. Natsu Dragneel and his friends from the Fairy Tail guild—Lucy Heartfilia, Gray Fullbuster, Erza Scarlet, Wendy Marvell, and the exceeds Happy and Charlés—consider this the perfect challenge to take on.\n\nThe Fairy Tail mages are not the only ones searching for the Dragon Gods. Diabolos, a guild exclusive for \"Dragon Eaters,\" seeks to enhance their Dragon Slayer magic by devouring the dragons. Meanwhile, Fairy Tail\'s newest addition, Touka, appears to be hiding something sinister from her new companions—and her secrets may bring disaster to the guild while its strongest wizards are away.\n\n[Written by MAL Rewrite]', '2024-07-07', 'https://cdn.myanimelist.net/images/anime/1087/144083l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(260, 'Baise Shandian', NULL, '2024-07-20', 'https://cdn.myanimelist.net/images/anime/1444/148779l.jpg', 'Sports', 'Anime'),
(261, 'Shirayuki', 'Music video for Eve\'s song Shirayuki.', '2022-12-23', 'https://cdn.myanimelist.net/images/anime/1273/143710l.jpg', NULL, 'Anime'),
(262, 'Tsuki ga Michibiku Isekai Douchuu', 'As part of a mysterious contract agreed upon by a goddess and his parents years ago, Makoto Misumi finds himself sent to another world to meet the goddess and become the hero. However, the deity deems Makoto to be \"hideous,\" refusing to even lay eyes upon him and revokes his heroic title. Disdainfully giving him the ability to understand all languages except the human language as compensation, the goddess drives Makoto off to the farthest edges of the wasteland, far from human civilization.\n\nDue to the disparity between Earth and this new world, Makoto\'s inherent physical and magical capabilities awaken, making him extremely powerful. He meets various demihumans and mythical beings who all end up being captivated with his characteristics and join Makoto in building a new community where all of them can peacefully coexist.\n\nNevertheless, despite this success, Makoto still yearns to meet fellow humans. In a world where the goddess herself has barred him from interacting with his kind, it is up to Makoto and his companions to fulfill his desire—and perhaps reform society along the way.\n\n[Written by MAL Rewrite]', '2021-07-07', 'https://cdn.myanimelist.net/images/anime/1950/116474l.jpg', 'Action, Adventure, Comedy, Fantasy', 'Anime'),
(263, 'Jujutsu Kaisen', 'Idly indulging in baseless paranormal activities with the Occult Club, high schooler Yuuji Itadori spends his days at either the clubroom or the hospital, where he visits his bedridden grandfather. However, this leisurely lifestyle soon takes a turn for the strange when he unknowingly encounters a cursed item. Triggering a chain of supernatural occurrences, Yuuji finds himself suddenly thrust into the world of Curses—dreadful beings formed from human malice and negativity—after swallowing the said item, revealed to be a finger belonging to the demon Sukuna Ryoumen, the King of Curses.\n\nYuuji experiences first-hand the threat these Curses pose to society as he discovers his own newfound powers. Introduced to the Tokyo Prefectural Jujutsu High School, he begins to walk down a path from which he cannot return—the path of a Jujutsu sorcerer.\n\n[Written by MAL Rewrite]', '2020-10-03', 'https://cdn.myanimelist.net/images/anime/1171/109222l.jpg', 'Action, Award Winning, Supernatural', 'Anime'),
(264, 'Vinland Saga Season 2: Drowning in the Shadow', 'Thorfinn, shown initially as he appears as a member of Askeladd\'s raiders, cuts down some men in the middle of a raid. When he enters a nearby house, he finds a family cowering within.\n\n(Source: ANN, edited)', '2023-02-14', 'https://cdn.myanimelist.net/images/anime/1118/133378l.jpg', 'Action, Adventure, Drama', 'Anime'),
(265, 'Planetarian: Snow Globe', 'The new OVA will feature the prequel short story \"Snow Globe,\" which debuted as part of a light novel volume that bundled with a limited-edition version of the original PC game.', '2021-01-20', 'https://cdn.myanimelist.net/images/anime/1169/113365l.jpg', 'Drama, Sci-Fi', 'Anime'),
(266, 'Boku no Kokoro no Yabai Yatsu: Twi-Yaba', 'Side stories of Boku no Kokoro no Yabai Yatsu, based on a series of shorts that were posted on X (formerly Twitter).', '2023-12-10', 'https://cdn.myanimelist.net/images/anime/1869/140298l.jpg', 'Comedy, Romance', 'Anime'),
(267, 'One Piece Fan Letter', 'Although the golden age of piracy is about to reach new heights, most people do not seek the glory of finding the elusive One Piece—a treasure signifying a new conqueror of all seas that was once embodied by the legendary King of the Pirates, Gol D. Roger. However, even if civilians generally despise pirates, they secretly cheer for at least one of them. \n\nOne red-headed girl from Sabaody Archipelago is no exception: She reveres Nami, the ingenious female navigator of Monkey D. Luffy\'s Straw Hat crew. Determined to deliver a fan letter to her idol, the Sabaody child is prepared to challenge forces of authority who strive to prevent Luffy and his friends from departing for their next destination: the New World. But to succeed, Nami\'s fan may need to risk her life and interfere with the Marines\' plans, potentially causing devastating consequences for the wider world.\n\n[Written by MAL Rewrite]', '2024-10-20', 'https://cdn.myanimelist.net/images/anime/1455/146229l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(268, 'Oomuro-ke: Dear Sisters', 'A spin-off of Yuru Yuri featuring Sakurako and her sisters.', '2024-02-02', 'https://cdn.myanimelist.net/images/anime/1401/140053l.jpg', 'Comedy, Girls Love', 'Anime'),
(269, 'Aiyou de Mishi', 'After going out for late-night drinks, Yan Yuechu and his colleague Hu Zhi find refuge from the rain in a rather unusual place: the building harboring Xu Aiyou\'s escape game, XY. Despite the game\'s infamy and its mysterious owner, the duo decides to give it a try. With one hour to solve riddles and find their way out of a maze of eerie rooms, Yan Yuechu and Hu Zhi manage to clear the game in time. However, glimpses of what appears to be Xu Aiyou\'s troubled past scattered throughout the game leave a deep impression on the men—an impression so lasting that vivid scenes from new escape games creep into their dreams.\n\nThe following day, Yan Yuechu receives a letter advising him to stay away from escape games. Although he does not receive conclusive answers from Xu Aiyou, he dreams once more that he must solve a puzzle to escape from his own bedroom. But was it truly a dream? Unsure where reality ends and illusions begin, Yan Yuechu will have to uncover the truth behind XY if he wishes to preserve his sanity.\n\n[Written by MAL Rewrite]', '2023-04-12', 'https://cdn.myanimelist.net/images/anime/1667/135309l.jpg', 'Mystery, Suspense', 'Anime'),
(270, 'Shin Jidai', 'Music video for the song Shin Jidai by Ado.', '2022-06-15', 'https://cdn.myanimelist.net/images/anime/1183/129386l.jpg', NULL, 'Anime'),
(271, 'Totsukuni no Shoujo (2022)', 'OVA bundled with the special edition of the manga\'s side story.', '2022-03-10', 'https://cdn.myanimelist.net/images/anime/1957/113267l.jpg', 'Supernatural', 'Anime'),
(272, 'Futari-bun no Shoumei', 'The story follows three friends grappling with school, studies, and relationships. Kouki Uchiyama will play Takuya Amano, a boy who will move to Hokkaido after finishing middle school. Yui Ishikawa plays Haruka Kishi, Takuya\'s childhood friend. Daisuke Fujita plays Tsubasa Miyake, a mutual friend of Takuya and Haruka who attends the Eikoh Seminar school. \n\n(Source: Anime News Network)', '2022-12-23', 'https://cdn.myanimelist.net/images/anime/1794/132547l.jpg', 'Drama', 'Anime'),
(273, 'Kao Ni La Zhanshen Xitong', 'An Lin, an ordinary young man in the city, encounters a powerful practitioner, who gives him a set of God of War system and sends him to the spiritual world to practice. When he first arrived in the spiritual world, An Lin, who had average aptitude, was humiliated as \"the strongest relationship household\". In order to wash away the stigma, the optimistic An Lin improved his cultivation skills with the help of the system. With several outstanding performances, he made a group of close friends and embarked on the road of counterattack.\n\n(Source: bilibili)', '2022-07-27', 'https://cdn.myanimelist.net/images/anime/1544/124684l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(274, 'Girls & Panzer: Saishuushou Part 4', 'The Winter Continuous Track Cup semifinals are underway and Ooarai Girls’ Academy find themselves in deep trouble early in their match against Continuation High School. The Anglerfish Team are knocked out by Continuation\'s sharpshooter, forcing the rest of the team to use a different game plan. Stepping up in the absence of her star teammates, Azusa Sawa shows her leadership potential by temporarily taking over as Ooarai\'s commander. However, the match proves that it will take more than a new strategy for Ooarai to survive this time around.\n\nOn the other side of the tournament, Kuromorimine Girls\' Academy and St. Gloriana Girls\' College are locked in a fiery desert battle. Having developed her own unorthodox tactical style, Erika Itsumi rallies Kuromorimine from the brink of defeat into a fierce showdown against their opponent\'s veteran commander, Darjeeling. But St. Gloriana have bolstered their ranks with a familiar face who recently transferred to their school, hampering Kuromorimine\'s quest for victory.\n\nThe championship round is within striking distance for these four schools, but only two will have what it takes to move on!\n\n[Written by MAL Rewrite]', '2023-10-06', 'https://cdn.myanimelist.net/images/anime/1652/138188l.jpg', NULL, 'Anime'),
(275, 'Xue Ying Ling Zhu Zhi Qi Yu Pian', NULL, '2020-01-02', 'https://cdn.myanimelist.net/images/anime/1520/105226l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(276, 'Dr. Stone: Stone Wars', 'Senkuu has made it his goal to bring back two million years of human achievement and revive the entirety of those turned to statues. However, one man stands in his way: Tsukasa Shishiou, who believes that only the fittest of those petrified should be revived.\n\nAs the snow melts and spring approaches, Senkuu and his allies in Ishigami Village finish the preparations for their attack on the Tsukasa Empire. With a reinvented cell phone model now at their disposal, the Kingdom of Science is ready to launch its newest scheme to recruit the sizable numbers of Tsukasa\'s army to their side. However, it is a race against time; for every day the Kingdom of Science spends perfecting their inventions, the empire rapidly grows in number.\n\nReuniting with old friends and gaining new allies, Senkuu and the Kingdom of Science must stop Tsukasa\'s forces in order to fulfill their goal of restoring humanity and all its creations. With the two sides each in pursuit of their ideal world, the Stone Wars have now begun!\n\n[Written by MAL Rewrite]', '2021-01-14', 'https://cdn.myanimelist.net/images/anime/1711/110614l.jpg', 'Adventure, Comedy, Sci-Fi', 'Anime'),
(277, 'Mushoku Tensei: Isekai Ittara Honki Dasu Part 2', 'After the mysterious mana calamity, Rudeus Greyrat and his fierce student Eris Boreas Greyrat are teleported to the Demon Continent. There, they team up with their newfound companion Ruijerd Supardia—the former leader of the Superd\'s Warrior group—to form \"Dead End,\" a successful adventurer party. Making a name for themselves, the trio journeys across the continent to make their way back home to Fittoa.\n\nFollowing the advice he received from the faceless god Hitogami, Rudeus saves Kishirika Kishirisu, the Great Emperor of the Demon World, who rewards him by granting him a strange power. Now, as Rudeus masters the powerful ability that offers a number of new opportunities, it might prove to be more than what he bargained for when unexpected dangers threaten to hinder their travels.\n\n[Written by MAL Rewrite]', '2021-10-04', 'https://cdn.myanimelist.net/images/anime/1028/117777l.jpg', 'Adventure, Drama, Fantasy, Ecchi', 'Anime'),
(278, 'Dance Dance Danseur', 'Junpei Murao\'s love affair with ballet began at a young age during his sister\'s ballet recital, when a male ballet dancer roused his interest with a gripping performance. But for Junpei, nothing could be worse than his peers finding out about his secret passion for ballet and perceiving him as effeminate. That is why he is in the soccer club, trains Jeet Kune Do, and is intent on following in his father\'s footsteps of becoming a stunt coordinator: all very \"manly\" activities.\n\nWhen Junpei\'s classmate Miyako Godai spots him demonstrating an impressive kick that combines skills from ballet and Jeet Kune Do to his friends, she suddenly recruits him to join her mother\'s ballet studio. He resists at first, and although he has abandoned his dreams of formally pursuing ballet, nothing quite captures the euphoria that ballet elicits. After suppressing his desire to pursue ballet for so long, it is not so easy to shake off his hesitation and break free of the shackles of masculinity. Junpei has to be willing to make certain sacrifices and fully commit to ballet, all while risking losing some friends.\n\n[Written by MAL Rewrite]', '2022-04-09', 'https://cdn.myanimelist.net/images/anime/1571/121381l.jpg', 'Drama', 'Anime'),
(279, 'Sewayaki Kitsune no Senko-san', 'Like many hardworking members of the workforce, Kuroto Nakano is perpetually stressed out by his job. Still, since he lives alone, he must carry on to sustain himself. Little do humans like Kuroto know, this stress takes the form of darkness residing within a person\'s body and will bring one\'s life to ruin. \n\nFox deities can see this darkness and have the duty to save people before it is too late. To help rid Kuroto of his stress,  Senko-san, an eight hundred-year-old foxgirl, volunteers to take care of him, and will do everything she can to ease the tension in his weary soul.\n\n[Written by MAL Rewrite]', '2019-04-10', 'https://cdn.myanimelist.net/images/anime/1814/99677l.jpg', 'Slice of Life, Supernatural', 'Anime'),
(280, 'Shoujo☆Kageki Revue Starlight: Rondo Rondo Rondo', 'At the performing arts division of Seishou Music Academy, the ever-evolving stage threads the lives of its students together as they tirelessly hone their craft. Yet, as the girls prepare for a new rendition of the previous year\'s performance, the carefree Karen Aijou begins to settle for a smaller role. However, her waning passion is reignited by the return of her childhood friend Hikari Kagura, whose sudden transfer to the academy triggers a flurry of changes in the class dynamics.\n\nSubsequently, Karen chances upon a secret battleground underneath the school, which houses a set of auditions that will crown its ultimate victor as \"Top Star.\" As she dives headfirst into these enigmatic trials, Karen begins to learn about the tribulations that come with vying for the top. Even if fate wills them apart, Karen and Hikari must fight in hopes of fulfilling their childhood promise: to become stars together.\n\n[Written by MAL Rewrite]', '2020-08-07', 'https://cdn.myanimelist.net/images/anime/1542/108494l.jpg', NULL, 'Anime'),
(281, 'Isekai Yakkyoku', 'World-class medical researcher Kanji Yakutani lost his little sister to a tumor years ago due to ineffective treatment. To honor her legacy, he has dedicated his research to developing new medications for such conditions. But as fate would have it, he overworks himself and passes away at the age of 31, only to be given a second chance at life in another world.\n\nWhen he wakes up, Kanji finds himself in the body of a 10-year-old boy named Falma de Médicis, the son of an esteemed family of medical practitioners in the Sain Fleuve Empire. Bearing the mark of a deity\'s divine blessing, Falma is capable of performing a unique divine art, allowing him to create and reduce any substance with the knowledge of its chemical properties.\n\nAfter reading through some pharmacology books, Falma realizes that this world is operating on similar medical practices as in ancient times. He also learns that medicine is an exclusive privilege to the nobility, depriving commoners of proper medical care. Using the knowledge from his past life and the divine abilities granted to him, Falma resolves to make medicine available to those who need it—irrespective of class.\n\n[Written by MAL Rewrite]', '2022-07-10', 'https://cdn.myanimelist.net/images/anime/1120/124644l.jpg', 'Fantasy', 'Anime'),
(282, 'Ling Long: Incarnation Final Chapter', 'Final installment of Ling Long: Incarnation.', '2021-05-01', 'https://cdn.myanimelist.net/images/anime/1916/114704l.jpg', 'Action, Drama, Horror, Sci-Fi, Suspense', 'Anime'),
(283, 'Carole & Tuesday', 'It has been 50 years since mankind began its migration to the terraformed Mars, where they live in comfort due to advancements in AI. Carole lives in the metropolis of Alba City, working part-time by day and playing keyboard by night. Tuesday has run away from her home in Hershell City to escape the grip of her wealthy family, and instead hopes to pursue music with her acoustic guitar.\n\nAfter a fateful encounter, the two decide to perform music together. Up against the AI singers that dominate the music world, the two of them believe that together they can convey their feelings through their songs. Will hard work and luck be enough for the duo to create the biggest miracle that Mars has ever seen?\n\n[Written by MAL Rewrite]', '2019-04-11', 'https://cdn.myanimelist.net/images/anime/1611/96157l.jpg', 'Drama, Sci-Fi', 'Anime'),
(284, 'Meikyuu Black Company', 'After working tirelessly toward his goal of a self-sustainable NEET lifestyle, Kinji Ninomiya has finally achieved his dreams. Now looking down on common folk commuting during a typhoon from the penthouse of one of his apartment buildings, Kinji gets ready to start his new, slothful life. However, all of his hard work goes to waste when a portal appears beneath him from out of nowhere.\n\nTeleported to another world, Kinji is forced to work for a mining company that focuses solely on profits and has no care whatsoever for the safety and well-being of its employees. Refusing to live in such conditions, he begins devising plans to get rich quickly, building connections with others in this new world and making his best efforts to escape the stringent corporate life. Will Kinji be able to overcome his restraints and attain financial freedom once more?\n\n[Written by MAL Rewrite]', '2021-07-09', 'https://cdn.myanimelist.net/images/anime/1753/116290l.jpg', 'Comedy, Fantasy', 'Anime'),
(285, 'Haru (2024)', 'Music video for the song Haru by Yorushika.\n\nThe song was used as the second opening theme of the anime Sousou no Frieren.', '2024-03-05', 'https://cdn.myanimelist.net/images/anime/1434/142159l.jpg', NULL, 'Anime'),
(286, 'Yoru ni Kakeru', 'Music video of the song Yoru ni Kakeru by Yoasobi.', '2019-11-16', 'https://cdn.myanimelist.net/images/anime/1548/124083l.jpg', NULL, 'Anime'),
(287, 'Voy@ger', 'Voy@ger is conceptual movie produced in commemoration of the 16th anniversary of the iDOLM@STER franchise. It features an image song of the same name, gathering 15 different idols from 5 different sub-franchises.\n\n(Source: ANN)', '2021-08-25', 'https://cdn.myanimelist.net/images/anime/1280/142023l.jpg', 'Sci-Fi', 'Anime'),
(288, 'Koutetsujou no Kabaneri Movie 3: Unato Kessen', 'Half a year has passed. Arriving in the Iron Fortress, Ikoma and Mumei set foot in Unato: another ravaged zone that fell into the grip of the deadly Kabane.\n\nIn this war-torn zone, the group fends off more dangerous Kabane that are attacking with patterns they had never seen before. The Iron Fortress crew eventually meet up with a survival group which requests their aid in reclaiming the zone. The newly forged alliance ventures deeper into the area of the castle and investigates the peculiar case of these new Kabane. But their search for answers unearths truths that are far more horrifying than they imagined. Forced to confront the reality behind the Kabane, Ikoma, Mumei, and their allies come to realize the despair buried within Unato.\n\n[Written by MAL Rewrite]', '2019-05-10', 'https://cdn.myanimelist.net/images/anime/1749/99713l.jpg', 'Action, Fantasy, Horror, Suspense', 'Anime'),
(289, 'Ooi! Tonbo 2nd Season', 'After graduating middle school, Tonbo Ooi sets sail from the isolated island of Tokara to Kumamoto in hopes of advancing her golf career. Using his connections, Tonbo\'s mentor Kazuyoshi Igarashi is able to convince coach Hajime Udou to train her. While Tonbo initially has trouble showing off her abilities with her peculiar playstyle and inexperience with using a variety of golf clubs, she quickly proves her worth at her course debut by making use of her unique skills.\n\nLeaving an impression on Hajime and the people around her, Tonbo is sent to compete in the Kyushu Women\'s Championship. Met with familiar faces and new rivals, she is determined to dive deeper into the professional world of golf.\n\n[Written by MAL Rewrite]', '2024-10-05', 'https://cdn.myanimelist.net/images/anime/1115/145549l.jpg', 'Drama, Sports', 'Anime'),
(290, 'Bouto', 'Music video for the song Bouto by Eve.', '2022-05-23', 'https://cdn.myanimelist.net/images/anime/1032/124044l.jpg', 'Action', 'Anime'),
(291, 'Meng Qi Shi Shen: Zaijie Liangyuan', 'Ye Jiayao is a modern-day celebrity chef who loves traditional Chinese recipes and often experiments with them. However, when a food experiment goes wrong, she travels back in time to the ancient times, where she becomes the daughter of a magistrate with the name Ye Jin Xuan. When she wakes up she is suddenly kidnapped to Hei Fang Camp where she meets the leader of the bandits, Xia Chun Yu, the young master of the Jing An Marquis manor, who is actually an undercover agent for the king. He had infiltrated the Black Wind Fortress bandits to investigate a plot to overthrow the king. The two then get engaged in a fake marriage. Ye Jia Yao starts to win over hearts, including Xia Chun Yu\'s, with her superb cooking skills and modern street smarts.\n\n(Source: Wikipedia)', '2021-10-09', 'https://cdn.myanimelist.net/images/anime/1576/117778l.jpg', 'Adventure, Comedy, Drama, Gourmet, Romance', 'Anime'),
(292, 'Kin no Kuni Mizu no Kuni', 'Once upon a time, there were two rival kingdoms that did not get along. Every day, they argued over insignificant matters. When a dispute over removing dog waste ultimately turned into a war, God swiftly intervened and directed the two nation\'s leaders to exchange the most beautiful girl and the most intelligent young man for bride and bridegroom, respectively.\n\nSaara, the princess of country A, meets the prince of country B, Naranbayar. As they pretend to be a married couple to protect the peace between the countries, they find themselves gradually falling in love.\n\n(Source: MAL News)', '2023-01-27', 'https://cdn.myanimelist.net/images/anime/1872/131491l.jpg', 'Fantasy, Romance', 'Anime'),
(293, 'Uma Musume: Pretty Derby - Shin Jidai no Tobira', 'A film adaptation of the Uma Musume: Pretty Derby franchise.', '2024-05-24', 'https://cdn.myanimelist.net/images/anime/1427/142210l.jpg', 'Sports', 'Anime'),
(294, 'Deca-Dence', 'Far in the future, the lifeforms known as Gadoll suddenly arose as a threat to humanity. The last surviving humans on Earth confine themselves to the Tank, a lower district in the giant mobile fortress Deca-Dence. While the Gears who live on the upper floors are warriors who go out to fight as part of the Power, most Tankers are content to provide support from the backlines, butchering Gadoll meat and reinforcing defenses. Natsume is among those who would rather go to the front lines; undeterred by her prosthetic right arm, she seeks to join the small number of Tanker soldiers who join the Gears in combat. \n\nBut despite her peers at the orphanage each receiving their work assignments, Natsume’s enlistment to the Power remains unapproved. In the meantime, she begins a job as a cleaner in an armor repair team led by the hard-nosed and apathetic Kaburagi, who seems to be more than he lets on. Though initially cold to his idealistic subordinate, he soon recognizes in her the potential to upset the status quo of the world. As Natsume’s new mentor, Kaburagi prepares her for the special and unique role as a game-changing bug in the system.\n\n[Written by MAL Rewrite]', '2020-07-08', 'https://cdn.myanimelist.net/images/anime/1787/132772l.jpg', 'Action, Adventure, Sci-Fi', 'Anime'),
(295, 'Raison d\'être', 'Music video for Eve\'s second major single Raison d\'être.', '2019-10-11', 'https://cdn.myanimelist.net/images/anime/1989/103550l.jpg', NULL, 'Anime'),
(296, 'Beastars Final Season', 'The anthropomorphic animal society stands at a precipice. Following the unmasking of the carnivorous murderer at Cherryton Academy, the school introduces a new segregation policy to protect herbivores, further fueling public disdain for carnivores. Meanwhile, the black market for meat thrives like never before, and the Shishi-gumi, a powerful gang of lions, faces upheaval after losing their leader. A shadowy, violent figure emerges, intending to seize control of the Shishi-gumi with the introduction of an appetizing energy drink for carnivores.\n\nHaving left school, Legoshi, a gentle gray wolf at odds with his predatory instincts, attempts to lead an unassuming life; he only uses his innate strength to protect the weak. However, his involvement with the academy\'s murder investigation draws the attention of the current Beastar—society\'s leading authority. For the sake of his controversial relationship with white dwarf rabbit Haru, Legoshi clings to his sense of justice, even when he sinks into the chaos caused by rising tensions between carnivores and herbivores.\n\n[Written by MAL Rewrite]', '2024-12-05', 'https://cdn.myanimelist.net/images/anime/1699/142187l.jpg', 'Drama, Suspense', 'Anime'),
(297, 'Tianbao Fuyao Lu', 'Having lived his entire life on Mount Taiheng, half-yao Kong Hongjun is at last presented with the chance to explore the human world. He is assigned three tasks: uncover his father\'s murderer, eliminate the Black Jiao and its yao tribes that have infiltrated Chang\'an, and return the Heart Lamp to a descendent of the Chen family. However, on his first night in the city, the Heart Lamp is mistakenly absorbed by military general Li Jinglong.\n\nAfter receiving a mysterious invitation to join Chang\'an\'s Court of Exorcism, Kong Hongjun is reunited with a disgraced Li Jinglong as his captain. Alongside a fellow yao, a noble from a foreign land, and a cowardly scholar, Kong Hongjun and Li Jinglong must work together to purge Chang\'an of the yao lurking in its streets. In the meantime, Kong Hongjun also needs to hide his true identity from Li Jinglong who loathes yao—all while attempting to retrieve the Heart Lamp from his body.\n\n[Written by MAL Rewrite]', '2020-07-05', 'https://cdn.myanimelist.net/images/anime/1432/105225l.jpg', 'Action, Adventure, Comedy, Fantasy, Mystery', 'Anime'),
(298, 'Sasaki to Miyano Movie: Sotsugyou-hen', 'With university entrance exams and graduation drawing close, high school senior Shuumei Sasaki has to start taking his future more seriously. However, Sasaki is increasingly finding it hard to study; all he can think about is his boyfriend and junior, Yoshikazu Miyano. Having only recently made their relationship official, Sasaki cannot help but yearn to hold his boyfriend close. But with Sasaki\'s graduation on their minds, the couple begins to wonder what lies ahead for them both—especially as a public relationship can garner scrutiny from friends and family.\n\n[Written by MAL Rewrite]', '2023-02-17', 'https://cdn.myanimelist.net/images/anime/1574/128922l.jpg', 'Boys Love', 'Anime'),
(299, 'Rising Impact', 'A young boy, Gawain, lives in a mountainous, rural area with an incredible love for baseball and making the ball really fly. One day he runs into a visitor to the small area and she introduces him to a sport that can really make a ball take to flight: golf! It just takes one shot and Gawain is hooked. With his grandpa\'s approval he sets off to Tokyo with this mysterious woman to learn all he can about golf, encountering many colorful characters and obstacles along the way.\n\n(Source: mangatraders)', '2024-06-22', 'https://cdn.myanimelist.net/images/anime/1002/142134l.jpg', 'Sports', 'Anime'),
(300, 'Healin\' Good♡Precure Movie: Yume no Machi de Kyun! Tto GoGo! Daihenshin!!', NULL, '2021-03-20', 'https://cdn.myanimelist.net/images/anime/1973/110449l.jpg', 'Action', 'Anime'),
(301, 'Given Movie 2: Hiiragi Mix', 'Hiiragi Kashima and Shizusumi \"Shizu\" Yagi\'s band \"syh\" is set to debut, but they run into trouble when their support guitarist leaves. Although Hiiragi often clashes with Ritsuka Uenoyama—the smug boyfriend of his childhood friend Mafuyu Satou—Hiiragi convinces him to perform as their temporary member.\n\nDespite their friction, Hiiragi acknowledges Uenoyama\'s talent and respects his hard work—to the point of asking him to complete an old song that Mafuyu\'s ex-boyfriend, Yuki Yoshida, left behind. In between writing, recording, and filming a music video, Hiiragi comes to terms with his love for the aloof Shizu and wrestles with how to convey his feelings.\n\nMeanwhile, \"given\"—composed of Uenoyama, Mafuyu, and their bandmates Haruki Nakayama and Akihiko Kaji—receives an offer to debut as well. The members are ready and beyond excited, save for Mafuyu, who has never before thought about playing music professionally. As Uenoyama attempts to understand Yuki and replicate his unique sound, Mafuyu steps back to ponder over the looming changes in his life, fearing what the uncertain future may bring.\n\n[Written by MAL Rewrite]', '2024-01-27', 'https://cdn.myanimelist.net/images/anime/1095/140582l.jpg', 'Boys Love, Drama', 'Anime'),
(302, 'IDOLiSH7 Movie: LIVE 4bit - BEYOND THE PERiOD', 'A live performance by IDOLiSH7, TRIGGER, Re:vale, and ŹOOĻ , 4 groups with different charms, will meet in one place, and the grand live entertainment will begin! \n\n(Source: Translated, edited from official website)', '2023-05-20', 'https://cdn.myanimelist.net/images/anime/1698/136186l.jpg', NULL, 'Anime'),
(303, 'Hanhua Riji 4th Season', 'Fourth season of Hanhua Riji.', '2024-03-10', 'https://cdn.myanimelist.net/images/anime/1477/138814l.jpg', 'Comedy, Supernatural', 'Anime'),
(304, 'Given', 'Tightly clutching his Gibson guitar, Mafuyu Satou steps out of his dark apartment to begin another day of his high school life. While taking a nap in a quiet spot on the gymnasium staircase, he has a chance encounter with fellow student Ritsuka Uenoyama, who berates him for letting his guitar\'s strings rust and break. Noticing Uenoyama\'s knowledge of the instrument, Satou pleads for him to fix it and to teach him how to play. Uenoyama eventually agrees and invites him to sit in on a jam session with his two band mates: bassist Haruki Nakayama and drummer Akihiko Kaji.\n    \nSatou\'s voice is strikingly beautiful, filling Uenoyama with the determination to make Satou the lead singer of the band. Though reticent at first, Satou takes the offer after an emotional meeting with an old friend. With the support of his new friends, Satou must not only learn how to play guitar, but also come to terms with the mysterious circumstances that led him to be its owner.\n\n[Written by MAL Rewrite]', '2019-07-12', 'https://cdn.myanimelist.net/images/anime/1666/102238l.jpg', 'Boys Love, Drama', 'Anime'),
(305, 'Zoku Owarimonogatari', 'Graduation day is finally here, marking the end of Koyomi Araragi\'s eccentric high school life full of peculiar relationships with otherworldly beings.\n\nHowever, Araragi is unexpectedly absorbed into his own bathroom mirror and trapped inside a bizarre world where everything he knows is completely reversed—the haughty Karen Araragi is shorter than usual, poker-faced Yotsugi Ononoki is brimming with emotion, and cute ghost girl Mayoi Hachikuji is a grown woman! But not everything is as it seems.\n\nZoku Owarimonogatari details the story of Araragi\'s endeavors in this new world as he struggles to return to his home and understand the nature of this bizarre dimension.\n\n[Written by MAL Rewrite]', '2019-05-19', 'https://cdn.myanimelist.net/images/anime/1022/96168l.jpg', 'Comedy, Mystery, Supernatural', 'Anime'),
(306, 'Sword Art Online: Progressive Movie - Kuraki Yuuyami no Scherzo', 'After vanquishing another boss and stepping through the gates of the fifth floor, the misfit duo Kazuto \"Kirito\" Kirigaya and Asuna Yuuki are greeted with a beautiful landscape of crumbling ruins and catacombs steeped in mystery. This idyllic adventure is short-lived, however. Tensions between the Dragon’s Knights Brigade and the Aincrad Liberation Squad—the two leading guilds focused on clearing Sword Art Online—continue to rise and threaten the fragile stability of the frontline raiding group. \n\nKirito and Asuna are forced to act quickly, making a desperate gamble and gathering a small number of allies for a dangerous mission. As a result, Asuna and Misumi \"Mito\" Tozawa must come to terms with their relationship after the near-tragedy that forced them apart on the first floor.\n\n[Written by MAL Rewrite]', '2022-10-22', 'https://cdn.myanimelist.net/images/anime/1656/126446l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(307, 'Sugar Apple Fairy Tale Part 2', 'Despite having accomplished a lifelong dream of hers, Ann Halford faces further challenges ahead. Bridget Paige, the daughter of the Paige Workshop\'s owner, still possesses the wing of Shall Fen Shall, Ann\'s former fairy companion. In determination to save Shall from the obsessive Bridget, Ann decides to join the Paige Workshop, hoping at the same time to perhaps reunite with her close friend.\n\nHaving been appointed head of the workshop, Ann becomes entrusted with rebuilding it to its former glory. She quickly discovers that the Paige Workshop has a unique focus on tradition and individuality, and recognizes that she will need to learn about her team and completely revamp the workshop in order to succeed. Motivated by her strong desire to rescue Shall and her obligations as a sugar artisan, Ann wholeheartedly dedicates herself to her new position.\n\n[Written by MAL Rewrite]', '2023-07-07', 'https://cdn.myanimelist.net/images/anime/1693/138042l.jpg', 'Adventure, Drama, Fantasy, Romance', 'Anime'),
(308, 'Star☆Twinkle Precure', 'Hikaru Hoshina is an energetic middle school student with a love for space and the occult. As she draws constellations in her notebook, a small and fluffy creature suddenly appears from it! The creature, which she names Fuwa, turns out to be an alien with the ability to create warp holes. \n\nWhen Fuwa\'s companions, the aliens Lala Hagoromo and Prunce, arrive on Earth, they declare that they are searching for the Precure, legendary warriors who will save the universe. But an organization known as the Notraiders soon follows and attacks, intending to capture Fuwa and its power. Overcome by a desire to protect Fuwa, Hikaru finds herself transforming into \"Cure Star,\" one of the Precure that Lala and the others have been searching for!\n\nIt is now up to Hikaru and the rest to fend off the Notraiders\' onslaught, discover the rest of the Precure, and find the Star Color Pens, artifacts that will awaken the 12 Star Princess who keep the universe in balance.\n\n[Written by MAL Rewrite]', '2019-02-03', 'https://cdn.myanimelist.net/images/anime/1585/97907l.jpg', 'Action', 'Anime'),
(309, 'Lupin III: Part 6 - Jidai', 'Episode 0 of Lupin III: Part 6 series.', '2021-10-10', 'https://cdn.myanimelist.net/images/anime/1589/118735l.jpg', 'Action, Adventure, Comedy, Mystery', 'Anime'),
(310, 'Yi Nian Yong Heng: Chuan Cheng Pian', 'Second season of Yi Nian Yong Heng.', '2022-07-20', 'https://cdn.myanimelist.net/images/anime/1902/137109l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(311, 'Soukyuu no Fafner: Dead Aggressor - The Beyond Part 3', 'Episodes 7-9 of the Soukyuu no Fafner: Dead Aggressor - The Beyond series.', '2020-11-13', 'https://cdn.myanimelist.net/images/anime/1023/107083l.jpg', 'Action, Drama, Sci-Fi', 'Anime'),
(312, 'Bokutachi wa Benkyou ga Dekinai: Nagisa ni Usemono Arite Senjin wa Enzen to [X] Suru', 'The episode adapts chapters 48 and 49, which follow Yuiga and Asumi going on a fake date, and Yuiga encountering his teacher Mafuyu Kirisu after she accidentally loses her swimsuit top.\n\n(Source: MAL News)', '2019-11-01', 'https://cdn.myanimelist.net/images/anime/1530/102782l.jpg', 'Comedy, Romance', 'Anime'),
(313, 'Gundam Build Divers Re:Rise 2nd Season', 'The massive beam of light fired from Eldora\'s moon has completely shattered the BUILD DiVERS\' conception of Gunpla Battle Nexus Online (GBN). This has forced Hiroto Kuga and his teammates to reevaluate their mission on Eldora now that they are faced with potentially very real consequences. Despite this, the BUILD DiVERS rejoin the fight against the One-Eyed to protect what they hold dear. In the battle that concerns the fate of both Earth and Eldora, sparks fly as Hiroto is forced to confront his past amidst the revelations of GBN\'s shocking secrets.\n\n[Written by MAL Rewrite]', '2020-04-09', 'https://cdn.myanimelist.net/images/anime/1962/105909l.jpg', 'Action, Sci-Fi', 'Anime'),
(314, 'Mashle', 'In this magical world, one is easily identified as having magical abilities by a distinctive mark on their face. Those unable to practice magic are swiftly exterminated to maintain the magical integrity of society. However, deep within a forest lies an anomaly in Mash Burnedead, who can be found pumping iron with one arm and lifting a cream puff with the other. This aloof boy with superhuman strength—but no magical abilities—leads a quiet life with his father, far removed from society.\n\nMash\'s peace is soon disturbed when the authorities discover his lack of magical powers. They issue him an ultimatum: compete to become a Divine Visionary, which would force everyone to accept him, or be persecuted forever. To protect his family, he enrolls in the prestigious Easton Magic Academy, which only the most elite and gifted students are allowed to attend. Now, Mash must overcome his shortcomings as a magic-less being and surpass the other students—relying solely on his muscles.\n\n[Written by MAL Rewrite]', '2023-04-08', 'https://cdn.myanimelist.net/images/anime/1218/135107l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(315, 'Wu Shan Wu Xing (2020)', 'A legend tells that a long time ago, monsters could give the ability to certain elected officials to master the five elements. But for that, you have to go through the dangerous foggy mountains...\n\nWe follow the adventures of one of these elected officials.\n\n(Source: Nautiljon)', '2020-07-26', 'https://cdn.myanimelist.net/images/anime/1141/112764l.jpg', 'Action, Fantasy', 'Anime'),
(316, 'Shine Post', 'Haru Nabatame, Rio Seibu, and Kyouka Tamaki\'s idol unit, TiNgS, is on the verge of disbandment. However, if they can fill all two thousand seats in their upcoming anniversary concert, their idol careers will live to see another day. This quota is seemingly impossible for a group like them, especially when the most people they have had at a show is 37. Fortunately, they are placed under a new talented manager—Naoki Hinase.\n\nWhile initially reluctant due to past experiences, Naoki takes charge of TiNgS after sensing Haru\'s genuine passion for idols with his own remarkable ability to see the shine of someone who is lying. Despite the challenges she faces in this ambitious endeavor, Haru wants everyone in the world to love idols, even willing to become the shining guidepost—shine post—to accomplish her dream.\n\n[Written by MAL Rewrite]', '2022-07-13', 'https://cdn.myanimelist.net/images/anime/1976/123710l.jpg', 'Drama', 'Anime'),
(317, 'Ore dake Level Up na Ken: ReAwakening', 'Movie compilation of season one of Ore dake Level Up na Ken, with the addition of the first two episodes of the second season.', '2024-11-29', 'https://cdn.myanimelist.net/images/anime/1983/146190l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(318, 'Sword Art Online: Progressive Movie - Hoshi Naki Yoru no Aria', 'Excelling socially and academically, Asuna Yuuki is on track to ace her high school entrance exams. Her friend and classmate, Misumi \"Mito\" Tozawa, advises her to take a short break from studying and join her on the launch day of Sword Art Online (SAO)—the highly anticipated online virtual reality multiplayer game. Asuna accepts her offer and soon meets her in the game.\n\nIn a cruel twist of fate, Asuna, Mito, and every other player logged into SAO find themselves trapped in the game permanently. The only way out is to clear all one hundred floors of the game, and to make matters worse, dying inside the game will kill the player in real life. With SAO now turned into a nightmare death trap, Asuna and other gamers—such as the lone swordsman Kazuto \"Kirito\" Kirigaya—must adapt and survive, all whilst attempting to beat the unforgiving competition to the top.\n\n[Written by MAL Rewrite]', '2021-10-30', 'https://cdn.myanimelist.net/images/anime/1590/116274l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(319, 'J* Fuuzoku Gakuensai', NULL, '2021-04-02', 'https://cdn.myanimelist.net/images/anime/1804/116238l.jpg', 'Hentai', 'Anime'),
(320, 'Meitantei Conan Movie 27: 100-man Dollar no Michishirube', 'Twenty seventh Detective Conan movie.', '2024-04-12', 'https://cdn.myanimelist.net/images/anime/1888/141209l.jpg', 'Mystery', 'Anime'),
(321, 'Shen Lan Qi Yu Wushuang Zhu', 'In the 2501st year of the Glacier Calendar, the asteroid where the demons and the orcs survive flew to and hit the only continent on the phalanx - the fairy continent, known as the cataclysm in history. After the human ancestor Tianxing predicted the cataclysm with the Book of Prophecy, the two great powers, the demons and the spirits, joined all races to refine the seven-sacred artifact to fight against the collision and avoid the destruction of the world. The Fairy Continent was then torn apart and turned into seven seas and six regions. More than 300 years after the cataclysm, the demons gradually awakened and extended their minions to the Seven Seas and Six Regions... By chance, the two human teenagers obtained the Peerless Pearl among the Seven Gods Pearls, giving them the ability to The ability to summon each other. And the fate of mankind is about to be rewritten!\n\n(Source: iQIYI)', '2022-07-23', 'https://cdn.myanimelist.net/images/anime/1907/125403l.jpg', 'Action, Fantasy', 'Anime'),
(322, 'Taikutsu wo Saien Shinaide', 'Music video for the song Taikutsu wo Saien Shinaide by Eve.', '2022-03-11', 'https://cdn.myanimelist.net/images/anime/1349/121403l.jpg', NULL, 'Anime'),
(323, 'Rising Impact Season 2', 'Second season of Rising Impact.', '2024-08-06', 'https://cdn.myanimelist.net/images/anime/1161/144669l.jpg', 'Sports', 'Anime'),
(324, 'Mononogatari 2nd Season', 'Although Hyouma Kunato has begun to feel comfortable around Botan Nagatsuki and her family of tsukumogami—objects possessed by spirits called marebito—he has not forgotten about his main goal in life: revenge.\n\nUnbeknownst to Hyouma, while he is training in Kyoto under the supervision of the Kadomori family, the Bureau of Traditional Music, a group of three musical instrument tsukumogami, begins to enact its plan. The trio questions Botan\'s family about their intentions regarding Hyouma\'s presence near the person embodying the frontier between the human and marebito worlds. Soon after, the paper umbrella tsukumogami that Hyouma had been pursuing for years suddenly reappears and abducts Botan along with her university friends. Rushing to save the one he swore to protect, Hyouma might have to change his priorities if he wants to keep his promise to Botan.\n\n[Written by MAL Rewrite]', '2023-07-04', 'https://cdn.myanimelist.net/images/anime/1111/135927l.jpg', 'Action, Supernatural', 'Anime'),
(325, 'Uzaki-chan wa Asobitai! Double', 'During the summer holidays, energetic Hana Uzaki spent most of her time accompanying her lonesome upperclassman, Shinichi Sakurai. Now that school has resumed, Uzaki\'s teasing continues to ramp up, much to Sakurai\'s constant annoyance. Nevertheless, no amount of ridicule can damage the pair\'s relationship—which only seems to be getting better as their college days fly by!\n\n[Written by MAL Rewrite]', '2022-10-01', 'https://cdn.myanimelist.net/images/anime/1539/128058l.jpg', 'Comedy, Romance', 'Anime'),
(326, 'Enen no Shouboutai: Ni no Shou', 'After his confrontation in the Nether with his younger brother Shou, Shinra Kusakabe\'s resolve to become a hero that saves lives from the flame terror strengthens. Finding a way to turn the Infernals back into people, unraveling the mystery of the Evangelist and Adolla Burst, and saving his mother and Shou—these are the goals Shinra has in mind. However, he has come to realize that attaining these goals will not be easy, especially with the imminent danger the Evangelist poses.\n\nThe Evangelist\'s plan is clear: to gather the eight pillars—the individuals who possess Adolla Burst—and sacrifice them to recreate the Great Cataclysm from 250 years ago. Having been revealed by the First Pillar that the birth of a new pillar is approaching, Shinra is determined to protect his fellow pillars from the Evangelist. Thus, the fiery battle between the Special Fire Force and the Evangelist ignites. Together with the Special Fire Force, Shinra\'s fight continues as he uncovers the truth about the Great Cataclysm and the nature of Adolla Bursts, as well as the mysteries behind human combustion. \n\n[Written by MAL Rewrite]', '2020-07-04', 'https://cdn.myanimelist.net/images/anime/1673/107657l.jpg', 'Action, Fantasy, Sci-Fi', 'Anime'),
(327, 'Tsurune: Kazemai Koukou Kyuudou-bu - Yabai', 'Unaired episode pre-screened at the event and later included with the 5th Blu-ray/DVD release.', '2019-03-03', 'https://cdn.myanimelist.net/images/anime/1377/100872l.jpg', 'Sports', 'Anime'),
(328, 'Precure All Stars Movie F', 'A great Pretty Cure gathering! Or so we thought. They\'ve actually been separated~!?\n\n\"Where am I...?\" --When Sora wakes up, she finds herself in a mysterious world... It seems that she has lost Mashiro and the others.... But there she meets Yui, Manatsu, and Prim! What\'s more, Prim transforms into Cure Supreme! Mashiro meets Laura, Amane, and Nodoka on a small island in the sea, and rescues Puka from a monster attack! Tsubasa meets Saaya, Ha-chan, and Haruka, where they take a walk in the hanging garden! Ageha meets Asumi, Lala and Yukari, but Lala and Yukari are having trouble getting along! They meet a lot of friends, but for some reason, their memories are all a little hazy... And it seems that the only people in this world are Precure...? We want to go back to our own world! The clue is a castle in the distance-- Onward! Our journey begins here! Let\'s go on a great adventure to the castle!\n\n(Source: Official Site, translated)', '2023-09-15', 'https://cdn.myanimelist.net/images/anime/1959/137024l.jpg', 'Action', 'Anime'),
(329, 'Hokkyoku Hyakkaten no Concierge-san', '\"The word \'no\' doesn\'t exist in a concierge\'s dictionary.\" That\'s just one of the demanding rules that Akino must abide by in her new job as a saleswoman at the elegant and expansive Hokkyoku Department Store. It\'s a very special store — the customers are all animals, and the most valued among them are of extinct species. Sea minks, laughing owls, Japanese wolves, even an enormous mammoth — that\'s Mr. Woolly, the celebrated sculptor whose works are showcased at the store. It\'s still a luxury retail space, though, and anxious Akino finds her hands full with the customers\' challenging requests. These range from hard-to-find merchandise to more complicated matters of the heart. Can the inexperienced Akino fulfill their whims and meet their expectations? If she wants to keep her job, she\'ll have to succeed while under constant observation by the fussy floor manager Mr. Todo, a creepy consultant eager to downsize the staff, and the store\'s enigmatic president (who is not a penguin, by the way!).\n\n(Source: Fantasia Festival)', '2023-10-20', 'https://cdn.myanimelist.net/images/anime/1736/137966l.jpg', 'Fantasy, Slice of Life', 'Anime'),
(330, 'Gintama: Monster Strike-hen', 'Collaboration anime between Gintama and Monster Strike.', '2019-08-29', 'https://cdn.myanimelist.net/images/anime/1806/124660l.jpg', 'Action, Comedy', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(331, 'Tian Guan Cifu', 'The heavens shake, the thunder rumbles, and Xie Lian appears with an apologetic smile—again! Eight hundred years prior, he was a beloved martial god, known as the Crown Prince of Xianle. Now, he ascends to the heavenly realm for the third time, but simply as a pitiful scrap-collecting god with no followers behind him. \n\nOn his first mission, Xie Lian finds himself alone in the dark moonlit night. There, a gentle man dressed in red guides him through the forest. However, as abruptly as he appeared, the man suddenly dissipates into a swarm of silver butterflies.\n\nXie Lian later learns that this mysterious stranger was none other than Hua Cheng, the Crimson Rain Sought Flower, a Ghost King feared by both demons and gods alike. But before Xie Lian can figure out why Hua Cheng would help a Heavenly Official like himself, he meets San Lang. A young man possessing great knowledge on not only the Ghost King, but also the now forgotten Crown Prince, San Lang decides to accompany Xie Lian on his journey of unveiling the mysteries of the past.\n\n[Written by MAL Rewrite]', '2020-10-31', 'https://cdn.myanimelist.net/images/anime/1319/109301l.jpg', 'Action, Adventure, Drama, Fantasy', 'Anime'),
(332, 'Super Cub', 'Koguma, a reserved second-year high school student, has nothing—no parents, hobbies, friends, or goals. On her way home one afternoon, she visits a vehicle shop in hopes of acquiring a motor scooter. With only enough money to make ends meet, she is disheartened by the price tags and prepares to turn back. However, as she is about to leave, the shop\'s owner offers her a pre-owned Honda Super Cub for ten thousand yen. Believing that the motorcycle will help brighten her monotonous world, she accepts the deal. As Koguma journeys through her town on small adventures with her Super Cub, she begins to build irreplaceable friendships and eagerly advances toward her new life.\n\n[Written by MAL Rewrite]', '2021-04-07', 'https://cdn.myanimelist.net/images/anime/1776/111172l.jpg', 'Slice of Life', 'Anime'),
(333, 'Tomodachi Game', 'High school student Yuuichi Katagiri cherishes his close circle of friends, composed of four classmates: Yutori Kokorogi, Shiho Sawaragi, Makoto Shibe, and Tenji Mikasa. However, when the funds for the upcoming school trip are stolen, the incident causes Shiho and Makoto—who had been tasked with collecting the money—to distance themselves from the rest of their class.\n\nSoon after, Yuuichi and his friends are deceived into meeting up and knocked unconscious by unknown assailants. After waking, the group find themselves confined in a white room with controversial figure Manabu-kun, who reveals that one of the five has gathered them together to clear their personal debt of twenty million yen. To pay off the amount, they must participate in a variety of psychological games that will test the true nature of their friendship and humanity.\n\nDistressed and isolated from the outside world, Yuuichi and his friends need to cooperate to complete the games. But as their concealed feelings and problematic pasts begin to surface, their seemingly unbreakable bond may soon shatter into irreparable pieces.\n\n[Written by MAL Rewrite]', '2022-04-06', 'https://cdn.myanimelist.net/images/anime/1247/121345l.jpg', 'Suspense', 'Anime'),
(334, 'Yoru wa Honoka', 'Music video for the song Yoru wa Honoka by Eve. Directed by Zemyata.', '2021-04-30', 'https://cdn.myanimelist.net/images/anime/1341/114716l.jpg', 'Supernatural', 'Anime'),
(335, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 3rd Season', 'Third season of Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e.', '2024-01-03', 'https://cdn.myanimelist.net/images/anime/1332/139318l.jpg', 'Drama, Suspense', 'Anime'),
(336, 'Cang Lan Jue', 'A donghua based on the novel of the same name written by Jiu Lu Fei Xiang. The story revolves around the relationship between Xiao Lanhua, a low-ranking flower fairy, and the powerful \"Moon Supreme\" Dongfang Qingcang. After being locked away for thousands of years, Xiao Lanhua mistakenly revives Dongfang Qingcang. The two of them become connected as a result, with the powerful and stoic Moon Supreme forced to experience everything she does, both physical and emotional.', '2022-07-15', 'https://cdn.myanimelist.net/images/anime/1927/125119l.jpg', 'Fantasy, Romance', 'Anime'),
(337, 'Bungou Stray Dogs 5th Season', 'The Armed Detective Agency is still on the run from the Hunting Dogs, but not all hope is lost. Detective Ranpo Edogawa has a plan to prove the Agency\'s innocence and save the world from chaos: to find and capture Kamui—the leader of the terrorist organization Decay of the Angel. \n\nIn order to determine Kamui\'s whereabouts, Ranpo and his colleague Atsushi Nakajima must convince Ouchi Fukuchi, the renowned captain of the Hunting Dogs, for amnesty. Although Fukuchi was tasked with arresting the members of the Agency, his past with the Agency\'s president, Yukichi Fukuzawa, may be the key to earning his trust. But unbeknownst to them, Fukuchi might not be as honorable as he proclaims.\n\n[Written by MAL Rewrite]', '2023-07-12', 'https://cdn.myanimelist.net/images/anime/1161/136691l.jpg', 'Action, Mystery', 'Anime'),
(338, 'Ishuzoku Reviewers', 'Countless diverse races, from perky fairies to oozing slimes, inhabit the world. Naturally, such a melting pot of creatures has a broad and alluring variety of brothels. With so many options to choose from, it is hard to decide with which succu-girl to have a meaningful, interpersonal experience.\n\nFortunately, a tight group of brave warriors has come together to enlighten the public. These perverted adventurers take it upon themselves to assess the appeal of all types of succu-girls through hands-on research. Whether it be the scorchingly hot salamanders or the udderly hu-moo-ngous cow-girls, the Yoruno Gloss reviewers leave no species behind.\n\nDirected by the mastermind behind Miru Tights, Ishuzoku Reviewers seeks to answer one of the most pressing questions there is: which species is the sexiest?\n\n[Written by MAL Rewrite]', '2020-01-11', 'https://cdn.myanimelist.net/images/anime/1870/105970l.jpg', 'Comedy, Fantasy, Erotica', 'Anime'),
(339, 'One Piece Movie 14: Stampede', 'Monkey D. Luffy and the Straw Hats arrive aboard the Sunny to the Pirates Festival, the world\'s largest celebration created by and for pirates. Buena Festa, the festival organizer, invites the Straw Hats and all Worst Generation crews to partake in the festivities. Luring even Shichibukai and Marines to its shores, it seems that no pirate or sailor can resist the enticing secrets that the event hides behind its glamor.\n\nThe festival\'s contest is simple: find one of the treasures Gol D. Roger left behind. As the competition progresses, the various pirate crews fight each other in a free-for-all battle royale—that is, until the sudden appearance of an unexpected pirate drastically changes the game.\n\n[Written by MAL Rewrite]', '2019-08-09', 'https://cdn.myanimelist.net/images/anime/1221/100550l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(340, 'Wan Sheng Jie', 'In this world, angels, demons, and other supernatural beings peacefully coexist with humans. Neil Bowman is a demon who is unlike most; he is mesmerized with human culture, and no matter how hard he tries, he can\'t do anything evil. Thus, he runs away from Hell and up to Earth.\n\nNeil moves in with his online friend and vampire, Ira Blood, along with Ira\'s many roommates. Despite coming to Earth to meet humans, Neil discovers that not a single one of his new roommates is actually human. Along with Ira, there\'s Lynn Angel, the stern angel landlord; Lynn\'s little sister, Lily, who falls from Heaven; Abu, a mummy who never speaks; and Vladimir Eliot Kirilenko, a werewolf tasked with monitoring Neil.\n\nWhat most of them don\'t realize—not even Neil himself—is that Neil possesses the powers of the Demon King. What effect will this have on the residents of Apartment 1031 on All Saints Street?\n\n[Written by MAL Rewrite]', '2020-04-01', 'https://cdn.myanimelist.net/images/anime/1854/106930l.jpg', 'Comedy, Fantasy', 'Anime'),
(341, 'Rurouni Kenshin: Meiji Kenkaku Romantan (2023)', 'In the late 19th century, as the cruel times of the Bakumatsu period came to a close, a new Meiji era marked the age of restoration for Japan. With the war over, its infamous hero Hitokiri Battousai disappeared into thin air, leaving only his legend behind.\n\nYears later, a seemingly plain wanderer named Kenshin Himura encounters Kaoru Kamiya, the owner of a struggling local dojo in Tokyo. Kaoru pursues a self-proclaimed Battousai who roams the streets, indiscriminately killing citizens and police officers. Furthermore, the warrior professes to use the Kamiya Kasshin-ryu—a sword style developed by Kaoru\'s father deeply rooted in the essence of life, not death.\n\nKenshin decides to help Kaoru take down the impostor and restore her father\'s dojo. Unbeknownst to all, Kenshin is none other than the real warrior whose name still terrifies the people. Although Kaoru eventually learns the truth, his oath to atone for his murderous history by bloodlessly protecting the weak moves her, and she welcomes Kenshin to stay at her dojo. However, Kenshin\'s ideals are soon challenged by ghosts of the past and enemies of the present.\n\n[Written by MAL Rewrite]', '2023-07-07', 'https://cdn.myanimelist.net/images/anime/1599/136532l.jpg', 'Action', 'Anime'),
(342, 'Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su', 'High school student Rakurou Hizutome has a peculiar hobby of playing poorly made games—ones that are unbalanced or are filled with so many bugs that make them borderline unplayable. The few who share his hobby might recognize him by his in-game name, Sunraku. For his next game, Rakurou is recommended Shangri-La Frontier, a popular and well-received virtual reality game as a breather from the terrible games he has been playing recently.\n\nOnce he boots up the game, Rakurou decides to sell off most of his starting gear to gain extra money, leaving himself with only a pair of boxers, a bird mask, and some weapons. He is instantly hooked as he meticulously levels up his avatar. However, after encountering some intimidating monsters, he realizes that he may have underestimated the challenge that a mainstream game can offer. As Rakurou progresses, he must draw on all the skills he has perfected from his previous gaming experience. Before long, Sunraku\'s eccentric playstyle takes Shangri-La Frontier by storm.\n\n[Written by MAL Rewrite]', '2023-10-01', 'https://cdn.myanimelist.net/images/anime/1500/139931l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(343, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka Movie: Orion no Ya', 'Continuing his adventure to get stronger in order to traverse deeper into the \"Dungeon,\" Bell Cranel wanders the Orario city streets with his friends and the goddess Hestia. That evening, the city is filled with stalls and games as it celebrates the Holy Moon Festival.\n\nHermes, a god, hosts one such activity where participants are asked to pull a spear embedded in a crystal boulder; those who succeed will receive a special gift: a trip around the world and a divine blessing from the gods! Bell and his merry group challenge one another to claim the prize. But behind the facade of an innocent party game lies a preface for a daring quest ahead.\n\n[Written by MAL Rewrite]', '2019-02-15', 'https://cdn.myanimelist.net/images/anime/1239/96949l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(344, 'NieR:Automata Ver1.1a Part 2', 'As the machine war progresses, YoRHa Command and the Resistance prepare for a final decisive assault against the \"Machine Lifeforms,\" the militarized robots who roam the earth\'s surface. While preparations are underway, YoRHa 9-gou S-gata \"9S\" and YoRHa 2-gou B-gata \"2B\" continue their advanced scouting mission. However, 9S and 2B struggle with their respective roles, their loyalty to each other, and their loyalty toward Command.\n\nAlthough the nefarious Adam and Eve have been defeated, it appears the machines are not down for the count. An ominous presence in the form of the \"Red Girl\" continues to observe the androids from afar, waiting for the perfect opportunity to attack them.\n\n[Written by MAL Rewrite]', '2024-07-05', 'https://cdn.myanimelist.net/images/anime/1364/143539l.jpg', 'Action, Fantasy, Sci-Fi', 'Anime'),
(345, 'IDOLiSH7 Third Beat!', 'Nearing their first debut anniversary and with their popularity still on the rise, IDOLiSH7 set a date for a live tour to express their gratitude toward their fans. Meanwhile, the Black or White event draws closer—and as the previous year\'s winners—the group must prepare to take on the challengers. Looking to solidify their reputation in the world of idols, IDOLiSH7 are determined to come out victorious and settle the score once and for all with their rival, TRIGGER.\n\nWhile working around their packed schedules, IDOLiSH7, TRIGGER, and Re:vale meet powerful figures in the entertainment industry. In the midst of the hectic period, some members catch wind of a scandalous rumor regarding IDOLiSH7. As the members of IDOLiSH7 begin to worry about their image, their bonds are put to the test, all while a spiteful figure begins to carry out a certain plan behind the scenes.\n\n[Written by MAL Rewrite]', '2021-07-04', 'https://cdn.myanimelist.net/images/anime/1646/115723l.jpg', 'Drama', 'Anime'),
(346, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV: Shin Shou - Meikyuu-hen', 'Intrepid adventurer Bell Cranel has leveled up, but he can’t rest on his dungeoneering laurels just yet. The Hestia Familia still has a long way to go before it can stand toe-to-toe with the other Familias of Orario — but before Bell can set out on his next mission, reports of a brutal murder rock the adventuring community! One of Bell’s trusted allies stands accused of the horrible crime, and it’s up to Bell and his friends to clear their name and uncover a nefarious plot brewing in the dungeon’s dark depths.\n\n(Source: Sentai Filmworks)', '2022-07-23', 'https://cdn.myanimelist.net/images/anime/1318/126474l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(347, 'Wanmei Shijie', 'Born into a unique world where villages fight to gain power and control, the main character, Shi Hao, is a genius blessed by the heavens born under the poorest of conditions.\n\nHis clan, however, has a mysterious past. To rise up and become the genius he is meant to be, the clan goes through every effort to aid his cultivation as they battle through fanatical monsters and engage in power struggles with other clans.\n\nHis journey will bring him through unknown lands until he is able to become a person that can truly shake the world.\n\n(Source: Novels Xianxia&amp;Xuanhuan Wiki)', '2021-04-23', 'https://cdn.myanimelist.net/images/anime/1619/137928l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(348, 'Tonikaku Kawaii: Seifuku', 'Special episode of Tonikaku Kawaii released Fall 2022.', '2022-11-22', 'https://cdn.myanimelist.net/images/anime/1085/126580l.jpg', 'Comedy, Romance', 'Anime'),
(349, 'Yoku', 'Music video directed by Mai Yoneyama for the song YOKU by Eve. The song is inspired by the KATE YOKU Collection makeup line from KATE TOKYO.', '2022-03-18', 'https://cdn.myanimelist.net/images/anime/1807/121603l.jpg', NULL, 'Anime'),
(350, 'Tunshi Xingkong 2nd Season', 'Second season of Tunshi Xingkong.', '2021-12-29', 'https://cdn.myanimelist.net/images/anime/1558/117008l.jpg', 'Action, Adventure, Fantasy, Sci-Fi', 'Anime'),
(351, 'Atri: My Dear Moments', 'Due to the dramatic rise of the sea levels, humanity has lost a significant part of its inhabitable lands, forcing it to rely on pre-existing technology to survive. Among the many people affected by the tragedy, Natsuki Ikaruga, a brilliant recent graduate who had lost a leg in a submarine accident, is now reduced to living a miserable life on a near-deserted island.\n\nAfter Natsuki encounters a mysterious woman named Catherine, he uncovers an advanced humanoid robot that belonged to his grandmother Nonko, a renowned climatologist. Atri, the salvaged robot with the appearance and demeanor of a young girl, reveals to Natsuki that Nonko has tasked her with an important mission, but she has forgotten what it was.\n\nAlthough Natsuki was initially planning to sell Atri, the opportunity to connect with his grandmother\'s research through Atri makes him rethink his decision. Natsuki once had to sacrifice his dream to partake in a prestigious scientific mission. But as he opens up to his fellow islanders, he discovers that he can still make a difference in a desolate world.\n\n[Written by MAL Rewrite]', '2024-07-14', 'https://cdn.myanimelist.net/images/anime/1825/143408l.jpg', 'Drama, Romance, Sci-Fi', 'Anime'),
(352, 'Rikei ga Koi ni Ochita no de Shoumei shitemita. Heart', 'Following the events of their trip to Okinawa, Saitama University graduate students Shinya Yukimura and Ayame Himuro have failed to obtain the data necessary to scientifically prove their love for each other. Unable to replicate the exact conditions of the trip, the two stubborn scientists decide to seek help from elsewhere in the university—the Biological Sciences department.\n\nAssisted by fellow graduate students and longtime couple Chris Floret and Suiu Fujiwara, Yukimura and Himuro begin to quantify their feelings by measuring their output of oxytocin in various romantic situations. The two scientists soon find that their feelings for each other are nothing compared to that of a mature couple. It is here that Chris poses a question to both Yukimura and Himuro: what will they do if their \"affection\" is proven not to be love after all?\n\nDesperate to find a scientific rationale for the discrepancy, Yukimura puts everything on the line to prove that their \"love\" is real.\n\n[Written by MAL Rewrite]', '2022-04-02', 'https://cdn.myanimelist.net/images/anime/1109/118948l.jpg', 'Comedy, Romance', 'Anime'),
(353, 'Shixiong A Shixiong', 'After being reborn in ancient times before the Great God-Conferment War, Li Changshou became a small cultivator.\n\nTo survive in the cruel Primordial Times, Li Changshou tries hard not to accumulate any karma. He always plans thoroughly before doing anything and never allows himself to walk into dangerous situations. He hides his trump cards well, trains himself in escape techniques, refines poisonous pills, and masters mystical abilities.\nLi Changshou originally planned to remain hidden and safe in the mountain until his ascension to immortality. However, everything changed one year when his master brought home a junior sister…\n\n(Source: Realm Scans)', '2023-01-19', 'https://cdn.myanimelist.net/images/anime/1209/132496l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(354, 'Boku no Hero Academia the Movie 3: World Heroes\' Mission', 'Under the doctrines of Quirk Doomsday Theory, the ideological group Humarise is convinced that all humans with quirks are diseased and must be eradicated. In order to rebuild the world, the group\'s extremists have constructed a lethal device known as a \"Trigger Bomb\" that causes people with quirks to lose control and die. Their leader, Flect Turn, evades capture from the Pro Heroes deployed around the world.\n\nDuring his work study in the country of Otheon with Japan\'s number one Pro Hero, Izuku \"Deku\" Midoriya is accused of a crime he did not commit. Unintentionally involving Roddy Soul, a local, Deku soon finds himself on the run with the boy. It is now up to Rody, Deku, and Deku\'s classmates to stop the Trigger Bomb plot set in motion by Flect, all while eluding the other persistent members of Humarise.\n\n[Written by MAL Rewrite]', '2021-08-06', 'https://cdn.myanimelist.net/images/anime/1049/115605l.jpg', 'Action', 'Anime'),
(355, 'Bokutachi wa Benkyou ga Dekinai!', 'Under Nariyuki Yuiga\'s devoted tutelage, his classmates Rizu Ogata, Fumino Furuhashi, and Uruka Takemoto are finally pulling average test scores on their worst subjects. But time is ticking, and there is still a long way to go before the three geniuses of Ichinose Academy are ready for their upcoming university exams. Meanwhile, the girls still struggle to balance the pursuit of their dreams with their growing affections for their unsuspecting tutor.\n\nJoining them are Mafuyu Kirisu, a teacher with strong views about education and talent because of her past as a rising figure skater, and Asumi Kominami, a graduate from their school aiming to attend a national medical university. With these two additions, the group of six is livelier than ever before. Completely caught up in hilarious antics with his new friends, Yuiga finds that his last year of high school now includes a lot more than just going to class and studying.\n\n[Written by MAL Rewrite]', '2019-10-06', 'https://cdn.myanimelist.net/images/anime/1974/102960l.jpg', 'Comedy, Romance', 'Anime'),
(356, 'Yubisaki to Renren', 'For hearing-impaired university student Yuki Itose, silence has been a natural part of life since birth. Her world is small and isolated; she commutes to campus, interacts with her best friend Rin Fujishiro, and communicates through writing and text messages—a lifestyle that offers little to no change. One day, during her commute, Yuki meets fellow student Itsuomi Nagi, a multilingual travel enthusiast and friend of Rin. When Itsuomi learns of Yuki\'s condition, he takes it in stride, moving Yuki\'s heart. From this one simple gesture, Yuki and Itsuomi\'s lives start changing day by day as they let each other into their own worlds.\n\n[Written by MAL Rewrite]', '2024-01-06', 'https://cdn.myanimelist.net/images/anime/1478/140828l.jpg', 'Romance', 'Anime'),
(357, 'Xian Wu Chuan 2nd Season', 'Ye Chen, the outcast disciple, is banished from the sect and becomes homeless. Through a series of coincidences, he receives a True Flame and once again steps on the path of cultivation. This is a world where demons and deities co-exist and an era where all realms in the world are overrun by chaos. Ye Chen\'s journey to defying heaven begins, and after going through all kinds of trials and tribulations, he finally reaches the pinnacle of cultivation.\n\n(Source: Youku)', '2023-09-24', 'https://cdn.myanimelist.net/images/anime/1320/139789l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(358, 'Watashi no Shiawase na Kekkon', 'Misery seems everlasting in Miyo Saimori\'s life. Born from an arranged marriage, she was quickly discarded after her mother\'s tragic death. Her father remarried, and her younger half-sister Kaya received all the affection, while Miyo was degraded to a lowly servant. Lacking the strength to fight against her family\'s abuse, Miyo loses hope that her luck will ever turn.\n\nUnexpectedly, Miyo\'s father summons her to deliver surprising news: she is to marry Kiyoka Kudou, the head of the distinguished Kudou family. Despite his noble background, Kiyoka is known to be a callous man who has thus far dismissed all of his former fiancées.\n\nUpon arriving at the Kudou household, Miyo expects coarse treatment and to be tossed aside. However, contrary to her assumptions, Kiyoka shows her the kindness and love that she has desperately needed. Marrying Kiyoka may be Miyo\'s one chance to break free from her neglectful family and embrace a life of happiness.\n\n[Written by MAL Rewrite]', '2023-07-05', 'https://cdn.myanimelist.net/images/anime/1147/122444l.jpg', 'Drama, Fantasy, Romance', 'Anime'),
(359, 'Shinigami Bocchan to Kuro Maid', 'As the elegant, frail flower petals wither away into lifeless ashes, the young duke is tragically reminded of the despicable power forced upon him—the ability to kill anything he touches. Scorned by his family, he is sent away to live in near isolation. Fortunately, he is not entirely alone, as the manor\'s staff—his dutiful butler Rob and the flirtatious maid Alice—keep him company and make his life less miserable.\n\nAs the duke\'s romantic feelings for Alice grow, so does his continued frustration for the limits set by his unfortunate ability. Therefore, he resolves to break the curse cast upon him all those years ago, not only for his sake, but Alice\'s as well—for he is painfully aware of how difficult it is to avoid the touch of a loved one.\n\n[Written by MAL Rewrite]', '2021-07-04', 'https://cdn.myanimelist.net/images/anime/1471/115593l.jpg', 'Comedy, Fantasy, Romance', 'Anime'),
(360, 'Stand By Me Doraemon 2', 'After reminiscing about his late grandmother, Nobita Nobi wishes to see her again and asks Doraemon to return them to the past. Following the wholesome reunion of the two, Nobita\'s grandmother confesses that she hopes to meet his future bride. Nobita accepts her request out of filial love and quickly scrambles into the time machine as he and Doraemon journey forward in time.\n\nHowever, when the duo warps to Nobita\'s wedding day, they discover that the future Nobita is missing from the ceremony! Determined to set things right, Doraemon and Nobita embark on a mission to search for Nobita\'s future self and encourage him to discover the happiness he deserves.\n\n[Written by MAL Rewrite]', '2020-11-20', 'https://cdn.myanimelist.net/images/anime/1842/109657l.jpg', 'Comedy, Sci-Fi', 'Anime'),
(361, 'Golden Kamuy 3rd Season', 'After obtaining information about Asirpa from the foreteller Inkarmat, Saichi \"The Immortal\" Sugimoto, Genjirou Tanigaki, and Cikapasi join the Seventh Division\'s Otonoshin Koito and Hajime Tsukishima on a journey to Karafuto. Heading further north into the freezing Russian territory, they collect any clues about Asirpa\'s whereabouts they can find and rush after her.\n\nMeanwhile, Asirpa is unaware of what truly transpired at Abashiri Prison. Deeply disturbed and confused by her father Wilk\'s past actions, Asirpa follows his old friend Kiroranke to the place where Wilk was born and raised in order to better understand his motives. However, Kiroranke and the master sniper Hyakunosuke Ogata are scheming behind her back.\n\nEven if they were to obtain all 24 tattooed skins that form a map to the lost Ainu gold, the various factions searching for it now understand that the map is useless without Asirpa. Realizing the danger she could be in, Sugimoto desperately hopes to reach Asirpa first and protect her from the greedy clutches of those who plan to drag her into their sins.\n\n[Written by MAL Rewrite]', '2020-10-05', 'https://cdn.myanimelist.net/images/anime/1763/108108l.jpg', 'Action, Adventure', 'Anime'),
(362, 'Seishun Buta Yarou wa Odekake Sister no Yume wo Minai', 'Sakuta Azusagawa\'s little sister, Kaede, is wrapping up middle school and needs to make an important decision. The school counselor believes it is in Kaede\'s best interest to attend an online high school, given her history of being a shut-in and her crippling phobia of traditional classrooms. However, Kaede wishes to enroll in Minegahara High School, just like her brother, as she desperately hopes for a typical high school experience. She pleads with Sakuta; his girlfriend, Mai Sakurajima; and Mai\'s half-sister, Nodoka Toyohama, to help her study for the entrance exam—and they enthusiastically agree. But her envisioned high school life does not unfold as planned. With her unresolved trauma coming to a head, Kaede grapples with the conflict of determining what sort of future path she truly wants to embark upon.\n\n[Written by MAL Rewrite]', '2023-06-23', 'https://cdn.myanimelist.net/images/anime/1540/134808l.jpg', 'Drama, Romance, Supernatural', 'Anime'),
(363, 'I\'m Your Treasure Box: Anata wa Marine Senchou wo Takarabako kara Mitsuketa.', 'Animated music video for Houshou Marine\'s single I\'m Your Treasure Box.', '2022-07-30', 'https://cdn.myanimelist.net/images/anime/1012/126441l.jpg', 'Ecchi', 'Anime'),
(364, 'Meitantei Conan Movie 25: Halloween no Hanayome', 'Shibuya, Tokyo, is bustling with the Halloween season. A wedding is being held at Shibuya Hikarie, where Sato is dressed in a wedding dress. While Conan and the other invited guests are watching, an assailant suddenly bursts in, and Takagi, who was trying to protect Sato, is injured. Takagi survived and the situation was settled, but in Sato\'s eyes, the image of the grim reaper that she had seen when Jinpei Matsuda, the man she had been in love with, had been killed in a series of bombings three years ago, overlapped with Takagi\'s.\n\nAt the same time, the perpetrator of the bombings escapes from prison. Rei Furuya/Toru Amuro, a member of the public safety police, is hunting down the man who killed his classmate, but a mysterious person in disguise suddenly appears and puts a collar bomb on him.\n\nConan visits the underground shelter where Amuro is hiding out to disarm the collar bomb, and hears about an incident three years ago when he and his now deceased classmates from the police academy encountered an unidentified virtual bomber named \"Plamya\" in Shibuya. As Conan and his team investigate, a disturbing shadow begins to loom over them.\n\n(Source: Detective Conan World)', '2022-04-15', 'https://cdn.myanimelist.net/images/anime/1744/120789l.jpg', 'Action, Mystery', 'Anime'),
(365, 'Tropical-Rouge! Precure', 'It\'s an exciting day for fashionable teenager Manatsu Natsumi, who is moving into the big city for the first time. Upon arriving, Manatsu is immediately charmed by the city\'s spectacles. However, things take an unbelievable turn when she encounters Laura—a real-life mermaid!\n\nLaura is searching for the Precure, a group of radiant warriors who may have the key to rescuing Grand Ocean, Laura\'s home. This duty soon falls upon Manatsu, whose unwavering determination causes her to awaken as one of the Precure: the vivid Cure Summer. As new friends join the team, Manatsu needs to adapt to her hectic, new life while protecting humanity\'s liveliness from oceanic invaders! With each battle more difficult than the last, the girls must discover what is truly valuable to them.\n\n[Written by MAL Rewrite]', '2021-02-28', 'https://cdn.myanimelist.net/images/anime/1184/110907l.jpg', 'Action', 'Anime'),
(366, 'You Shou Yan 4th Season', NULL, '2024-08-02', 'https://cdn.myanimelist.net/images/anime/1805/144449l.jpg', 'Comedy, Fantasy', 'Anime'),
(367, 'Journey: Taiko Arabia Hantou de no Kiseki to Tatakai no Monogatari', 'From the south of the Arabian Peninsula, the great General Abraha and his mighty army trample their way north to the holy city of Mecca. Their demands are ruthless: Mecca\'s surrender, its people\'s enslavement, and the Kaaba\'s destruction. Despite advice to withdraw and save themselves, a few brave Meccan men remain to fight. Among them is Aws Ibn Jubair, a humble potter who abandoned a life of sin to dedicate himself to honor and faith.\n\nAs the enemy troops approach in the dead of night, the vastly outnumbered Meccans work to raise morale. The night takes an unexpected shift with the reappearance of an atheist mercenary named Zurara—Aws\' old accomplice who never went straight. Although Zurara joins only for food and pay, the intriguing tale of Aws\' path to religion convinces him that Mecca is worth protecting. Bracing for the inevitable bloodbath, the two former friends reunite to defend the only land and faith that allow them to truly forgive themselves.\n\n[Written by MAL Rewrite]', '2021-06-25', 'https://cdn.myanimelist.net/images/anime/1660/114383l.jpg', 'Action, Adventure', 'Anime'),
(368, 'Kaze no Yukue', 'Music video for the song Kaze no Yukue by Ado.', '2022-08-24', 'https://cdn.myanimelist.net/images/anime/1816/127367l.jpg', NULL, 'Anime'),
(369, 'Tsundere Akuyaku Reijou Liselotte to Jikkyou no Endou-kun to Kaisetsu no Kobayashi-san', 'Broadcasting club member Shihono Kobayashi always gushes to her friend Aoto Endou about MagiKoi, an otome game where protagonist Fiene attends the Royal Academy of Magic. But despite the colorful cast, the one character Kobayashi is most obsessed with is the villainess Lieselotte Riefenstahl. Contrary to her rude remarks toward Fiene, Lieselotte longs to be her friend. Lieselotte is also deeply in love with her own fiancé, Prince Siegwald Fitzenhagen—the game\'s main love interest. Unfortunately, in almost every route, Lieselotte is doomed to a tragic end.\n\nKobayashi manages to convince Endou to play MagiKoi to practice his speaking skills. What begins as a normal playthrough turns extraordinary when Siegwald suddenly hears the players\' voices inside the game! Now labeled as \"gods,\" Endou and Kobayashi use their comments and analyses to save their beloved tsundere villainess from her fated demise.\n\n[Written by MAL Rewrite]', '2023-01-07', 'https://cdn.myanimelist.net/images/anime/1997/131327l.jpg', 'Comedy, Fantasy, Romance', 'Anime'),
(370, 'Uma Musume: Pretty Derby Season 3', 'Since childhood, horse girls Kitasan Black and Satono Diamond have admired and aspired to be like their fellow horse girl named Tokai Teiou. Chasing their dreams, they enroll in Tracen Academy, an institution dedicated to training horse girls and preparing them for legendary races. Soon after, Kitasan Black lands on Team Spica, the same team as Teiou. Beaming with motivation, she remains undefeated until she fails to win her first Grade 1 (G1) race—the most prestigious type of race in the league—but she is determined to unleash her true potential as a horse girl.\n\nMeanwhile, Satono Diamond comes from a long line of horse girls who, despite sporting incredible running prowess, have never won a G1 race. It is up to her to finally break this curse and bring the Satono clan the glory it deserves.\n\n[Written by MAL Rewrite]', '2023-10-05', 'https://cdn.myanimelist.net/images/anime/1475/138948l.jpg', 'Sports', 'Anime'),
(371, 'Shoushimin Series', 'Jougorou Kobato has a habit of inserting himself into other people\'s problems. After realizing his detective skills are neither wanted nor appreciated, he makes an agreement with his shy friend Yuki Osanai to become ordinary together. Now entering high school, they aim to be perceived as regular people, yet Kobato cannot help but fall back into his deductive ways when faced with everyday mysteries.\n\nUnfortunately, mundane occurrences are not all the duo stumbles across. As they go through their school days trying to avoid drawing attention to themselves, Kobato and Osanai at times get caught up in incidents that put their plan of a peaceful, average life at risk.\n\n[Written by MAL Rewrite]', '2024-07-07', 'https://cdn.myanimelist.net/images/anime/1164/143459l.jpg', 'Mystery', 'Anime'),
(372, 'Maou 2099', 'Five hundred years ago, the fantasy world of Alneath was torn apart by a war between magically gifted immortals and mortals armed with magical artifacts. The conflict came to an end when mortals\' hero, Gram, slayed the Demon Lord Veltol Velvet Velsvolt. In 2099, the world looks a bit different. Alneath and technologically advanced Earth have fused in an event known as Fantasion. Immortals have been hunted down to near extinction, and technological implants called Familia allow mortals to use magic.\n\nAs the new world slowly recovers, Veltol\'s vassal Machina Solege resurrects him in Shinjuku, a techno-magical city constructed in the middle of devastated lands. However, Veltol\'s magic is severely weakened, and his former ally Marcus has betrayed him. To regain his fame and magical abilities, Veltol follows the advice of Takahashi—Machina\'s friend and a professional hacker—to start an unusual career: live streaming. His sharp tongue and comically poor gaming skills quickly secure him followers, but to dominate the world once again, Veltol must first uncover Shinjuku\'s secrets and thwart Marcus\' vile plans.\n\n[Written by MAL Rewrite]', '2024-10-13', 'https://cdn.myanimelist.net/images/anime/1675/144605l.jpg', 'Action, Fantasy, Sci-Fi', 'Anime'),
(373, 'Tensei Kizoku, Kantei Skill de Nariagaru 2nd Season', 'Second season of Tensei Kizoku, Kantei Skill de Nariagaru.', '2024-09-29', 'https://cdn.myanimelist.net/images/anime/1280/143705l.jpg', 'Adventure, Fantasy', 'Anime'),
(374, 'Rekishi ni Nokoru Akujo ni Naru zo', 'The kind and compassionate heroine of an otome game may be as flawless as she is admirable, but a certain young woman from Japan much prefers the villainess, Alicia Williams. She sees sense in Alicia\'s ruthless verbal abuse and values her discipline and fortitude. On the other hand, aside from always toying with Prince Duke Seeker\'s emotions, the commoner heroine seems to only spout lip service.\n\nGiven the choice, the young woman would love to be reincarnated as Alicia—and her wish suddenly comes true! Seven-year-old Alicia awakens with the memories of her past life, now aware of all the future events, outcomes, and the world\'s secrets. She has no fear; to outsmart the heroine and avoid a bad ending, all Alicia needs is hard work, mastery of her noble family\'s dark magic, and the determination to become the greatest villainess in history.\n\n[Written by MAL Rewrite]', '2024-10-02', 'https://cdn.myanimelist.net/images/anime/1005/145339l.jpg', 'Comedy, Fantasy, Romance', 'Anime'),
(375, 'Tearmoon Teikoku Monogatari: Dantoudai kara Hajimaru, Hime no Tensei Gyakuten Story', 'Due to poor finances, an epidemic, and famine, the once prosperous Tearmoon Empire ultimately falls to a revolution instigated by its citizens and supported by neighboring nations. The rebellion also brings dire consequences for Mia Luna Tearmoon, the empire\'s extremely spoiled princess, who endures three years in the dungeons before facing execution.\n\nBy some miracle, Mia finds herself reincarnated as her 12-year-old self, retaining full memories of everything that had transpired. With the pain of the guillotine blade freshly imprinted on her neck, Mia is determined to use this second chance at life to avoid the grim fate that awaits her. She utilizes all her knowledge to improve the state of the kingdom and gather personal allies, inadvertently winning over the people\'s hearts and becoming beloved as a saint.\n\n[Written by MAL Rewrite]', '2023-10-08', 'https://cdn.myanimelist.net/images/anime/1901/139910l.jpg', 'Comedy', 'Anime'),
(376, 'Slow Loop', 'Since childhood, Hiyori Yamakawa has witnessed her father\'s various eccentricities, but one activity she has always loved doing with him is fly fishing—a complicated yet rewarding method of catching fish. Even after his sudden death, Hiyori still visits the seaside in her spare time, savoring the joy that her father\'s memento brings her.\n\nThree years later, Hiyori\'s mother decides to remarry and arranges a dinner with her fiancé, his daughter, and Hiyori to celebrate. Anxious and wanting to pass the time, Hiyori goes to her usual fishing spot when a rather energetic girl named Koharu Minagi suddenly appears before her. The two soon become acquainted, with Koharu taking an interest in fly fishing herself. However, their meeting is more than just a coincidence: Koharu turns out to be Hiyori\'s future stepsibling, which is only the beginning of treasured memories the both of them will reel in as they foster their sisterhood.\n\n[Written by MAL Rewrite]', '2022-01-07', 'https://cdn.myanimelist.net/images/anime/1360/119608l.jpg', 'Gourmet, Slice of Life', 'Anime'),
(377, 'Kanojo ga Koushaku-tei ni Itta Riyuu', 'When, after her sudden death, Rinko Hanasaki is reborn as Raeliana McMillan, she is not sure whether to curse her luck. Raeliana was a minor character in a novel Rinko read, and as the eldest daughter of a nouveau-riche baron, she led a carefree life until her unfortunate demise at the hands of her fiancé, Lord Francis Brooks. To avoid her destined fate, Raeliana is determined to end her engagement with Francis.\n\nHowever, when Francis refuses to break things off, Raeliana decides to seek help from someone of higher standing and approaches Duke Noah Wynknight—the novel\'s male protagonist. Using her knowledge of the plot, Raeliana captures the duke\'s interest by proposing a deal: she will not expose his secrets if Noah agrees to act as her fiancé. Little does she know that getting involved with a duke who only shows his true colors around her may lead to more than she bargained for.\n\n[Written by MAL Rewrite]', '2023-04-10', 'https://cdn.myanimelist.net/images/anime/1109/130452l.jpg', 'Fantasy, Romance', 'Anime'),
(378, 'Yuru Yuri,', 'Akari Akaza, Chinatsu Yoshikawa, Kyouko Toshinou, and Yui Funami return to commemorate an exciting occasion! Despite their initial bizarre celebration ideas, they decide to hold a party at their Amusement Club room. With the help of friends from the Student Council, they start preparing for the big day—with a surprise planned for a special someone.\n\nJoin the girls as they work together to create an enjoyable and memorable party, all the while interacting with one another with their cute and unique quirks.\n\n[Written by MAL Rewrite]', '2019-09-18', 'https://cdn.myanimelist.net/images/anime/1138/99547l.jpg', 'Comedy, Girls Love', 'Anime'),
(379, 'Jujutsu Kaisen 2nd Season', 'The year is 2006, and the halls of Tokyo Prefectural Jujutsu High School echo with the endless bickering and intense debate between two inseparable best friends. Exuding unshakeable confidence, Satoru Gojou and Suguru Getou believe there is no challenge too great for young and powerful Special Grade sorcerers such as themselves. They are tasked with safely delivering a sensible girl named Riko Amanai to the entity whose existence is the very essence of the jujutsu world. However, the mission plunges them into an exhausting swirl of moral conflict that threatens to destroy the already feeble amity between sorcerers and ordinary humans.\n\nTwelve years later, students and sorcerers are the frontline defense against the rising number of high-level curses born from humans\' negative emotions. As the entities grow in power, their self-awareness and ambition increase too. The curses unite for the common goal of eradicating humans and creating a world of only cursed energy users, led by a dangerous, ancient cursed spirit. To dispose of their greatest obstacle—the strongest sorcerer, Gojou—they orchestrate an attack at Shibuya Station on Halloween. Dividing into teams, the sorcerers enter the fight prepared to risk everything to protect the innocent and their own kind.\n\n[Written by MAL Rewrite]', '2023-07-06', 'https://cdn.myanimelist.net/images/anime/1792/138022l.jpg', 'Action, Supernatural', 'Anime'),
(380, 'Ni Tian Zhizun', 'The entire universe is divided into the inner universe and the outer universe. The two universes are enemies of each other. The outer universe is ruled by demons, and the inner universe is divided into The Realm of gods, the Eternal Realm, and the Mortal Realm. In the universe, there are countless mortal worlds like the Tianfa Continent, and they are collectively referred to as the Jiutian Xin Region. In the field of Jiutian Xin, nine immortal emperors commanded all star fields in nine layers. Above the nine heavens is the realm of purification of immortal gods. \n\n(Source: AnimeXin)', '2021-07-16', 'https://cdn.myanimelist.net/images/anime/1557/117031l.jpg', 'Action, Fantasy', 'Anime'),
(381, 'Ijiranaide, Nagatoro-san', 'Every day, Naoto Hachiouji is teased relentlessly by Hayase Nagatoro, a first year student he meets one day in the library while working on his manga. After reading his story and seeing his awkward demeanor, she decides from that moment on to toy with him, even calling him \"Senpai\" in lieu of using his real name.\n\nAt first, Nagatoro\'s relentless antics are more bothersome than anything and leave him feeling embarrassed, as he is forced to cater to her whims. However, as they spend more time together, a strange sort of friendship develops between them, and Naoto finds that life with Nagatoro can even be fun. But one thing\'s for sure: his days will never be dull again.\n\n[Written by MAL Rewrite]', '2021-04-11', 'https://cdn.myanimelist.net/images/anime/1900/110097l.jpg', 'Comedy, Romance', 'Anime'),
(382, 'Kamonohashi Ron no Kindan Suiri', 'Ron Kamonohashi, the best student in the history of the elite Detective Training Academy BLUE, has been living as a recluse since BLUE expelled him five years ago. Moreover, he is forbidden to work as a detective, having barely escaped execution after getting involved in a murder case while he was still attending the school. Ron\'s situation changes drastically when police detective Totomaru Isshiki, following the advice of a senior colleague, seeks him out for help with a criminal case that has remained unsolved for months. Ron reluctantly agrees to help Totomaru and uses his phenomenal intuition to discover the culprit in less than a day. However, it appears that Ron suffers from a mysterious condition that can cause those around him to lose their lives. To Ron\'s great surprise, Totomaru manages to save the life of someone whom Ron put in jeopardy.\n\nAs the unlikely duo starts solving crimes one after another, BLUE sends operatives after its former student to find out if he has resumed investigative work. Fighting against murderers, rogue detectives, and the Metropolitan Police Department, Ron and Totomaru must join forces if they want to survive and see justice prevail.\n\n[Written by MAL Rewrite]', '2023-10-02', 'https://cdn.myanimelist.net/images/anime/1799/137123l.jpg', 'Comedy, Mystery', 'Anime'),
(383, 'Kimetsu no Yaiba: Yuukaku-hen', 'The devastation of the Mugen Train incident still weighs heavily on the members of the Demon Slayer Corps. Despite being given time to recover, life must go on, as the wicked never sleep: a vicious demon is terrorizing the alluring women of the Yoshiwara Entertainment District. The Sound Hashira, Tengen Uzui, and his three wives are on the case. However, when he soon loses contact with his spouses, Tengen fears the worst and enlists the help of Tanjirou Kamado, Zenitsu Agatsuma, and Inosuke Hashibira to infiltrate the district\'s most prominent houses and locate the depraved Upper Rank Demon.\n\n[Written by MAL Rewrite]', '2021-12-05', 'https://cdn.myanimelist.net/images/anime/1908/120036l.jpg', 'Action, Supernatural', 'Anime'),
(384, 'D4DJ First Mix', 'Having lived abroad in Africa for most of her life, Rinku Aimoto is now returning to Japan to attend Yoba Academy, a school where DJ units—groups made up of DJs, vocalists, and dancers—are extremely popular. There, she meets Maho Akashi, an aspiring DJ who teaches Rinku the basics of DJing. The girls attend a performance by Yoba\'s famous DJ unit Peaky P-key, and struck by inspiration, they decide to form a unit of their own.\n\nRinku and Maho soon recruit Muni Oonaruto, a talented artist and Rinku\'s childhood friend, as well as Rei Togetsu, a shy and caring pianist. Newly named Happy Around, the group aims to use the budding friendships and combined talents of its members to become one of the top DJ units in the country.\n\n[Written by MAL Rewrite]', '2020-10-30', 'https://cdn.myanimelist.net/images/anime/1765/109713l.jpg', NULL, 'Anime'),
(385, 'Onnanoko ni Naritai', 'Music video for the song Onnanoko ni Naritai by Japanese utaite singer Mafumafu that was featured on his fifth full-length album \"Kagura Iro Artifact\". The music video was animated by MONO-Devoid.\n\nA boy doesn\'t want to be one anymore and instead would much prefer to a cute girl and live out the fantasy of Cinderella.', '2019-10-18', 'https://cdn.myanimelist.net/images/anime/1240/104659l.jpg', NULL, 'Anime'),
(386, 'Senki Zesshou Symphogear XV', 'Humanity is finally confronted with the threat of the Custodians—the ancient, sentient species held responsible for cursing humanity to speak different languages thousands of years ago. The Symphogear wielders—Hibiki Tachibana, Tsubasa Kazanari, Chris Yukine, Maria Cadenzavna Eve, Kirika Akatsuki, and Shirabe Tsukuyomi—are sent to the Antarctic in order to retrieve an ancient relic. After securing it and rescuing the scientific staff present there from a Coffin, the automated defense mechanism protecting it, the relic is given to American researchers due to international agreements.\n\nThe criminal organization Noble Red, a remnant of the previously fought Bavarian Illuminati, starts targeting the relic. Will the Symphogear wielders and their supporting organization S.O.N.G. be able to foil the plans of the organizations conspiring against them?\n\n[Written by MAL Rewrite]', '2019-07-07', 'https://cdn.myanimelist.net/images/anime/1899/101966l.jpg', 'Action, Sci-Fi', 'Anime'),
(387, 'Kaguya-sama wa Kokurasetai: Ultra Romantic Teaser PV - Ishigami Yuu wa Kataritai', 'Every Thursday, Shuchiin Academy student council secretary Yuu Ishigami can be found in a state of anxiety. He counts down the hours until he can escape to the student council chamber to read the latest chapter of the popular seinen manga series, \"Momo Doesn\'t Think.\" Joining Ishigami in his weekly reading, student council president Miyuki Shirogane swiftly grows excited at the news of a third season of the manga\'s anime adaptation.\n\nHowever, it is only a matter of time before vice president Kaguya Shinomiya discovers what has been engrossing the two boys. With the stigma of being labeled an otaku looming over his head, Shirogane must do everything he can to keep his embarrassing secret from coming to light.\n\n[Written by MAL Rewrite]', '2021-10-21', 'https://cdn.myanimelist.net/images/anime/1265/119435l.jpg', 'Comedy', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(388, 'Kage no Jitsuryokusha ni Naritakute!', 'For as long as he can remember, Minoru Kagenou has been fixated on becoming as strong as possible, which has led him to undertake all kinds of rigorous training. This wish, however, does not stem from a desire to be recognized by others; rather, Minoru does everything he can to blend in with the crowd. So, while pretending to be a completely average student during the day, he arms himself with a crowbar and ruthlessly thrashes local biker gangs at night. Yet when Minoru finds himself in a truck accident, his ambitions seemingly come to a sudden end. In his final moments, he laments his powerlessness—no matter how much he trained, there was nothing he could do to overcome his human limitations.\n\nBut instead of dying, Minoru reawakens as Cid, the second child of the noble Kagenou family, in another world—one where magic is commonplace. With the power he so desired finally within his grasp, he dons the moniker \"Shadow\" and establishes Shadow Garden: a group whose sole purpose is to combat the enigmatic Cult of Diablos, an organization born from Cid\'s imagination. However, as Shadow Garden grows in both membership and influence, it becomes increasingly apparent that the Cult of Diablos is not as fictional as Cid had intended.\n\n[Written by MAL Rewrite]', '2022-10-05', 'https://cdn.myanimelist.net/images/anime/1091/128729l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(389, 'Sidonia no Kishi: Ai Tsumugu Hoshi', 'After the Earth was destroyed by mysterious alien lifeforms known as the Gauna, surviving remnants of the human race escaped to space in the enormous generation ship Sidonia. Having drifted through space for millennia, the Sidonia found itself once more under attack from Gauna for the first time in a century.\n\nOnce again facing the threat of extinction, a temporary victory against the Gauna was eked out thanks to the human-Gauna hybrid Tsumugi Shiraui and ace Guardian mech pilot Nagate Tanikaze.\n\n10 years later... The people of Sidonia enjoy a brief respite. Peaceful days pass, during which Tsumugi begins to realize her feelings for Nagate, who is now celebrated as a hero of Sidonia. However, as Captain Kobayashi has always known, as long as the Gauna remain, peace cannot last.\n\nThe decision is made: a final battle, upon which rests the fate of humanity\'s last survivors. As the end approaches, will the crew be able to protect those they love?\n\n(Source: Polygon Pictures)', '2021-06-04', 'https://cdn.myanimelist.net/images/anime/1222/108354l.jpg', 'Action, Sci-Fi', 'Anime'),
(390, 'Girls & Panzer: Saishuushou Part 3 Specials', 'Specials included with Girls &amp; Panzer: Saishuushou Part 3 Blu-ray and DVD.', '2021-12-24', 'https://cdn.myanimelist.net/images/anime/1050/117977l.jpg', 'Comedy', 'Anime'),
(391, 'Doupo Cangqiong: San Nian Zhi Yue', 'Three years ago, Na lan Yan Ran dropped her engagement, which made the Xiao family a laughing stock in the eyes of the Empire. Xiao Yan trained for three whole years through mountains and deserts to regain his honor. He will prove by himself that everything in this world can be changed, so do not underestimate the young. Today he will put an end to the history of his past, because the future awaits him!', '2021-10-31', 'https://cdn.myanimelist.net/images/anime/1029/118861l.jpg', 'Action, Fantasy', 'Anime'),
(392, 'BanG Dream! Movie: Episode of Roselia - II: Song I Am.', 'After overcoming numerous tribulations, the members of Roselia promised to appear on FUTURE WORLD FES.\nIt is now Autumn...\n\nThrough writing the lyrics of \"Promise,\" Lisa has matured.\nWatching the change of color in the autumn leaves, Yukina and Sayo expressed their resolve in a picture letter to their future selves.\nDriven by the wish to do something for Roselia, Rinko has started to compose a new song.\n\"The remaining quests are the contest, the tournament, and FUTURE WORLD FES...\"\nReflecting on their goals, Ako starts to feel anxious.\n\nWhat view will the five of them see beyond FUTURE WORLD FES?\n\n(Source: official site)', '2021-06-25', 'https://cdn.myanimelist.net/images/anime/1246/115689l.jpg', NULL, 'Anime'),
(393, '3D Kanojo: Real Girl 2nd Season', 'Teenage otaku Tsutsui is finally starting to feel comfortable in his relationship with his beautiful classmate Iroha, but the real world continues to make things tough for both of them. With the school cultural festival coming up, Tsutsui gets stuck working on the festival committee while Iroha\'s classmates pressure her to enter the beauty contest. Meanwhile, Tsutsui\'s best friend Itou finally works up the courage to confess his feelings to Ayado, but she turns him down. As Itou works to get over this rejection and Tsutsui struggles just to survive the festival, they both decide to do whatever they can to become better people. Will their good intentions pave the way to a happy outcome, or will more hearts be broken along the way?\n\n(Source: ANN)', '2019-01-09', 'https://cdn.myanimelist.net/images/anime/1237/113435l.jpg', 'Romance', 'Anime'),
(394, 'Hitoribocchi no Marumaru Seikatsu', 'Many of us know what it is like to transition to a new school with few to no friends in a new environment, going through the arduous process of getting to know people again. Bocchi Hitori knows this struggle all too well, having just graduated from elementary school and thrown into middle school. Unfortunately, she suffers from extreme social anxiety: she faints when overwhelmed, vomits when nervous, and draws up ridiculously convoluted plans to avoid social contact. It does not help that her only friend from elementary school, Kai Yawara, will not be attending the same middle school as Bocchi. However, wanting to help her, Kai severs ties with Bocchi and promises to reconcile with her when she befriends all of her classmates in her new middle school class.\n\nEven though Bocchi has no faith in herself, she is determined to be friends with Kai again. Summoning all of her courage, Bocchi takes on the daunting challenge of making friends with her entire class, starting with the delinquent-looking girl sitting in front of her...\n\n[Written by MAL Rewrite]', '2019-04-06', 'https://cdn.myanimelist.net/images/anime/1612/145601l.jpg', 'Comedy', 'Anime'),
(395, 'Wu Liuqi: Jiyi Suipian', 'In order to find his cherished partner, Wu Liuqi returns to Xuanwu Country and faces those forgotten fragments of memory. The dusty truth brings pain and anger, but now he is no longer alone. What is the purpose of having power? This time, Wu Liuqi has to make a new choice for his life...\n\n(Source: Official Site)', '2024-10-02', 'https://cdn.myanimelist.net/images/anime/1126/145681l.jpg', 'Action, Adventure, Comedy, Drama, Mystery, Sci-Fi, Supernatural', 'Anime'),
(396, 'Kamonohashi Ron no Kindan Suiri 2nd Season', 'Not long after forming their partnership, detectives Ron Kamonohashi and Totomaru Isshiki have proven adept at solving various cases together. However, the two are further motivated to continue their work when they discover that the House of M—an infamous crime syndicate—orchestrated Ron\'s expulsion from the prestigious Detective Training Academy BLUE five years prior. It appears that this group is also linked to Ron\'s mysterious ability that causes those around him to lose their lives, a phenomenon which Ron is desperate to stop.\n\nA member of the House of M soon starts to commit boastful serial murders around Shibuya as an act of provocation toward Ron. Consequently, the investigative pair must do their best to apprehend the culprit for the sake of justice as well as learning more about Ron\'s dark past and present condition.\n\n[Written by MAL Rewrite]', '2024-10-07', 'https://cdn.myanimelist.net/images/anime/1917/144334l.jpg', 'Comedy, Mystery', 'Anime'),
(397, 'Obenkyou Shitoite yo', 'Music video for the song Obenkyou Shitoite yo by the band Zutto Mayonaka de Iinoni. (ZUTOMAYO).', '2020-05-14', 'https://cdn.myanimelist.net/images/anime/1691/110177l.jpg', NULL, 'Anime'),
(398, 'Buddy Daddies', 'On Christmas Eve, four-year-old Miri Unasaka arrives in Tokyo completely alone, in search of her father. The bright lights and merry atmosphere guide Miri to a big hotel and a man with a delicious-looking cake. However, the child has just unknowingly walked into the center of an elaborate, foolproof plan for assassinating a dangerous mafia boss.\n\nProfessional assassins Kazuki Kurusu and Rei Suwa live together, fleeing memories of their grim childhoods and avoiding emotional connections. When their mission goes awry and they end up bringing Miri home, there is only one reasonable thing to do: return Miri to her mother. But the girl\'s innocent laugh and pure worldview quickly enamor her to Kazuki, who secretly enjoys playing a parent, and it is not long before Rei\'s impenetrable heart makes room for Miri.\n\nMiri\'s every move is unpredictable, and Kazuki and Rei find raising an energetic child harder than any of their missions. Although it presents a great risk to their careers, Kazuki and Rei—both assuming the affectionate nickname \"papa\"—decide to provide Miri with a normal childhood despite all the odds stacked against them.\n\n[Written by MAL Rewrite]', '2023-01-07', 'https://cdn.myanimelist.net/images/anime/1553/133767l.jpg', 'Action, Comedy', 'Anime'),
(399, 'Yuanshen: Hai Dengjie CM Duanpian - Ming Xiao Huanmeng', 'On the first full moon of the year on the continent of Teyvat, members of the seven nations meet in Liyue to celebrate Lantern Rite. As a festival that honors fallen heroes from the Archon War and invigorates the soldiers of today, Lantern Rite is Liyue\'s most significant celebration, and its festivities are highly anticipated all across Teyvat. Participants of the five-day-long event spend time together eating, drinking, and sightseeing as lanterns rise once more.\n\n[Written by MAL Rewrite]', '2023-01-22', 'https://cdn.myanimelist.net/images/anime/1336/132963l.jpg', 'Fantasy', 'Anime'),
(400, 'Isekai Quartet', 'It is a normal day; everyone from deranged military girl Tanya Degurechaff and 16-year-old isekai protagonist Satou Kazuma to expansionist overlord Ainz Ooal Gown and demon sisters Rem and Ram go on with their daily lives. Suddenly, a conspicuous red button begging to be pressed appears before them. Overcome by curiosity, the otherworldly characters push the button, sending them to an unfamiliar world.\n\nWith no way of escaping, the characters must lead a normal school life and make acquaintances with the others. One thing is certain: the classroom full of fan-favorite eccentric personalities never gets boring!\n\n[Written by MAL Rewrite]', '2019-04-10', 'https://cdn.myanimelist.net/images/anime/1965/99667l.jpg', 'Comedy, Fantasy', 'Anime'),
(401, 'Poketoon', 'Animations released on Pokémon Kids TV Japan YouTube channel.\n\nEpisodes:\n#1: Zuruggu to Mimikkyu - Chase the Beans (ズルッグとミミッキュ), animated by Dandelion Animation Studio, released June 4, 2020.\n#2: Hero ni Naritai Yanchamu (ヒーローになりたいヤンチャム), animated by Pancakes, released May 5, 2021.\n#3: Yume no Tsubomi (ユメノツボミ), animated by Studio Colorido, released June 6, 2021.\n#4: Mattete ne! Koiking (まっててね！コイキング), animated by Studio Colorido, released July 2, 2021.\n#5: Pokapoka Magumaggu House (ぽかぽかマグマッグハウス), animated by Studio Colorido, released August 5, 2021.\n#6: Gengar ni Nacchatta!? (ゲンガーになっちゃった！？), animated by Studio Colorido, released September 10, 2021.\n#7: Fubuki no Natsu Yasumi (ふぶきのなつやすみ), animated by Mimoid, released October 8, 2021.\n#8: Purin no Uta (プリンのうた), animated by StudioGOONEYS, released December 28, 2021.', '2020-06-04', 'https://cdn.myanimelist.net/images/anime/1941/117693l.jpg', 'Adventure, Comedy', 'Anime'),
(402, 'Doraemon Movie 40: Nobita no Shin Kyouryuu', 'Nobita and the gang travel 66 million years into the past to bring a pair of adorable dinosaur twins back to where they belong.\n\n(Source: Netflix)', '2020-08-07', 'https://cdn.myanimelist.net/images/anime/1745/108659l.jpg', 'Adventure, Comedy, Sci-Fi', 'Anime'),
(403, 'Tensei shitara Dainana Ouji Datta node, Kimama ni Majutsu wo Kiwamemasu', 'In his past life, Prince Lloyd de Saloum was a commoner who could not become adept at magic, no matter how knowledgeable or obsessed he was about it. Now reincarnated into his current royal lineage, he receives a body with seemingly endless mana, making his desire to master all things arcane attainable. Moreover, as the seventh prince of the kingdom, Lloyd has no claim to the throne, allowing him to nurture his abilities as freely as he wants.\n\nUnfortunately for Lloyd, ancient seals that imprison powerful demons begin to break down and release the horrors within, endangering the peace. With these monstrosities roaming around, Lloyd\'s overwhelming magical prowess is the ultimate weapon that can neutralize these threats before all things descend to chaos.\n\n[Written by MAL Rewrite]', '2024-04-02', 'https://cdn.myanimelist.net/images/anime/1580/141243l.jpg', 'Adventure, Fantasy', 'Anime'),
(404, 'Tonikaku Kawaii 2nd Season', 'In the wake of their first home burning down, Nasa and Tsukasa Yuzaki are seeking temporary shelter at the Arisugawas\' bathhouse. Though they have only been married for a short time, their relationship has only become sweeter by the day. Nasa is determined to spend as much time with his wife as possible, basking in the happiness of their marriage.\n\nThe newlyweds find new ways to explore their relationship. From adopting a cat, going to an amusement park, and even watching an impromptu romantic comedy featuring Nasa\'s former teacher, every day is a new experience. But while Tsukasa continues to meet the people in Nasa\'s life, Nasa has yet to meet more of Tsukasa\'s family. Though they appear to be the picture-perfect couple to everyone around them, Nasa begins to wonder if he will ever learn more about his wife\'s mysterious past.\n\n[Written by MAL Rewrite]', '2023-04-08', 'https://cdn.myanimelist.net/images/anime/1996/133361l.jpg', 'Comedy, Romance', 'Anime'),
(405, 'Fuuto Tantei Movie: Kamen Rider Skull no Shouzou', '\"How were Gaia Memories created?\" \"Why did W begin to fight?\" To answer Tokime\'s questions, Shoutarou quietly begins to tell a story. He speaks of his meeting and parting with a man he admired and called his old man—his mentor, Soukichi Narumi.\n\nMysterious people called Dopants, who utilized the powers of Gaia Memories, had begun appearing in the shadows of Fuuto, the windy city. A young Shoutarou had become an assistant of the detective Soukichi and, though called half-baked, began to follow in his footsteps. Unaware that, in addition to his detective work, Soukichi was secretly acting as Skull, Shoutarou began to grow frustrated with his mentor. That was when the Narumi Detective Agency received a phone call—a request from Hell inviting Shoutarou and company to a fateful night! When Shoutarou tracked down Soukichi to deliver the \"trump card\" bestowed by the mysterious caller, what did he see?\n\nShoutarou and Philip. The one detective made of two and the night when Kamen Rider W began. That whole story will finally be revealed.\n\n(Source: Official site, translated)', '2024-11-08', 'https://cdn.myanimelist.net/images/anime/1242/145324l.jpg', 'Action, Mystery, Supernatural', 'Anime'),
(406, 'Id:Invaded', 'The Mizuhanome System is a highly advanced development that allows people to enter one of the most intriguing places in existence—the human mind. Through the use of so-called \"cognition particles\" left behind at a crime scene by the perpetrator, detectives from the specialized police squad Kura can manifest a criminal\'s unconscious mind as a bizarre stream of thoughts in a virtual world. Their task is to explore this psychological plane, called an \"id well,\" to reveal the identity of the culprit.\n\nNot just anyone can enter the id wells; the prerequisite is that you must have killed someone yourself. Such is the case for former detective Akihito Narihisago, who is known as \"Sakaido\" inside the id wells. Once a respected member of the police, tragedy struck, and he soon found himself on the other side of the law.\n\nNevertheless, Narihisago continues to assist Kura in confinement. While his prodigious detective skills still prove useful toward investigations, Narihisago discovers that not everything is as it seems, as behind the seemingly standalone series of murder cases lurks a much more sinister truth.\n\n[Written by MAL Rewrite]', '2020-01-06', 'https://cdn.myanimelist.net/images/anime/1889/105337l.jpg', 'Mystery, Sci-Fi, Suspense', 'Anime'),
(407, 'Poputepipikku 2nd Season', 'High school girl duo Popuko and Pipimi are back and more unhinged than ever after their initial efforts to create a full-fledged anime production were met with a great reception. With no regard for their audience, they continue to live their reckless everyday lives consisting of comedy skits and parodies of epic proportions. No one is immune to the effects of their antics—including hapless live actor Shouta Aoi, who is on the run and stuck trying to be a hero in the wrong series.\n\n[Written by MAL Rewrite]', '2022-10-02', 'https://cdn.myanimelist.net/images/anime/1237/128067l.jpg', 'Comedy', 'Anime'),
(408, 'Doupo Cangqiong 3rd Season', 'To obtain the Magic Flame, Xiao Yan and his teacher went to a desert full of snakes, which angered the Master of the Snake Tribe, Yue Mei. When Xiao Yan was on the very edge of death, he was rescued by the Master of Fight, whose face was hidden by a mask. As it turned out, he was also looking for the Magic Flame. The Snake Tribe refused to hand over the Magic Flame to the Master of Fight, but when he attacked the Queen of the tribe, it turned out that it was just a shell, and the real queen is preparing to absorb the Magic Flame in order to become the God of Fight. The Snake Tribe attacked those who dared to raise their hand against their queen, while Xiao Yan was able to find traces of the Magic Flame in the midst of the battle and hunt down the Queen...', '2019-07-21', 'https://cdn.myanimelist.net/images/anime/1643/102418l.jpg', 'Action, Adventure, Fantasy, Romance, Supernatural', 'Anime'),
(409, 'Sentai Daishikkaku', 'For the past 13 years, the Nefarious Monster Army have appeared beneath their floating fortress every Sunday to advance their goal of conquering Earth. Luckily, the Dragon Keepers are here to save the day! Having defeated the majority of the monsters during their initial invasion, the heroes now routinely show up to clear away any remnants of resistance. Unbeknownst to the public, however, every fight beyond the first has been a deliberate show put on by both sides: the Dragon Keepers reap the fame and prestige from fighting imaginary enemies, while the surviving weakest monsters, altogether called Dusters, are allowed to live for another day.\n\nSentouin D, a Duster tired of living this life of shame, leaves the fortress in an attempt to overturn his fate. With the unexpected help of the mysterious ranger Yumeko Suzukiri, he discovers the key to defeating the Dragon Keepers lies in their Divine Artifacts—ultimate weapons crucial to the rangers\' transformation and unique powers. Teaming up with Suzukiri to infiltrate the garrison of Red Keeper Sousei Akabane, Sentouin D must defy all expectations to save his species from the cruel hands of humans.\n\n[Written by MAL Rewrite]', '2024-04-07', 'https://cdn.myanimelist.net/images/anime/1183/141489l.jpg', 'Action, Fantasy', 'Anime'),
(410, 'Precure Miracle Leap Movie: Minna to no Fushigi na Ichinichi', 'The story begins when the protagonist Hikaru meets aliens Lala, Prunce, and Fuwa while watching the night sky. She learns of the \"Star Palace,\" where the 12 Star Princesses of the constellations kept the balance of the universe until they were attacked. Lala is searching for the legendary Precure warriors to help find the 12 scattered \"Princess Star Color Pens\" and revive the princesses. When Fuwa is captured by an enemy, Hikaru wishes to save Fuwa, and a Star Color Pendent and a Star Color Pen appear to allow her to transform into Cure Star. From then on she works to collect the pens and raise Fuwa, who is the key to reviving the princesses.', '2020-10-31', 'https://cdn.myanimelist.net/images/anime/1934/119222l.jpg', 'Action', 'Anime'),
(411, 'Tensei shitara Slime Datta Ken 2nd Season', 'Taking a break from his time as a teacher, the powerful slime Rimuru Tempest returns to his kingdom, eponymously named Tempest, just in time to begin negotiations with a nearby nation—the Kingdom of Eurazania. While the negotiations are anything but peaceful, they do end successfully, allowing Rimuru to return and finish teaching. When trying to again return to Tempest, this time permanently, Rimuru is stopped by a mysterious figure who is somehow able to constrain the many magical abilities he has at his disposal. \n\nIn Tempest, the situation is even worse. A group of unknown humans has invaded the land and are assaulting its citizens, both influential and innocent. They are not just trying to bring harm either—they have the intent to kill. Can Rimuru overcome his powerful and dangerous foe and return to Tempest before it is too late?  \n\n[Written by MAL Rewrite]', '2021-01-12', 'https://cdn.myanimelist.net/images/anime/1271/109841l.jpg', 'Action, Comedy, Fantasy', 'Anime'),
(412, 'Dr. Stone: Ryuusui', 'Now that brains and brawns have united forces, the next step in Senkuu\'s plan to unravel the mystery behind the green light that once petrified humanity is to go to the other side of the Earth and investigate its origin. However, to achieve this, Senkuu must first build a ship.\n\nWith the help of Tsukasa Shishiou\'s former underlings, the base of the ship is rapidly assembled, but there is one missing piece: a skilled captain. During their search, Senkuu and his crew come across a petrified Ryuusui Nanami—the heir of the biggest maritime conglomerate, known for his vast knowledge of sailboats but unpleasant personality. Despite this, Senkuu takes the risk and revives Ryuusui.\n\nRyuusui, upon realizing there are no ownership rights in this new civilization, is excited at the prospect of claiming everything for himself. But before he agrees to play a crucial part in their upcoming journey and command the vessel through the restless seas, he and Senkuu must find the king of fuels to power the ship—oil.\n\n[Written by MAL Rewrite]', '2022-07-10', 'https://cdn.myanimelist.net/images/anime/1071/124921l.jpg', 'Adventure, Comedy, Sci-Fi', 'Anime'),
(413, 'Mairimashita! Iruma-kun 3rd Season', 'Following their heroic efforts at Walter Park, the students of the misfit class return to Babyls Demon School after their summer vacation. What awaits them is not only adoration and admiration but also the shocking revelation that, in order to stay in the luxurious Royal One classroom, the entire class must be promoted to Dalet rank before entering the second year.\n\nAs the Harvest and Music Festivals are right around the corner, there seem to be ample opportunities to rank up. Doing so will not be simple, however, as no class thus far has managed to accomplish such a feat. Hoping to give the misfit class a chance to achieve the improbable, the school appoints special tutors to aid in confronting the challenges that lie ahead.\n\nWith his sights set beyond Dalet, Iruma Suzuki decides to take strides toward the goal of ranking up, starting with gaining acknowledgement from his special tutor: the short-tempered and selfish Bachiko Barbatos.\n\n[Written by MAL Rewrite]', '2022-10-08', 'https://cdn.myanimelist.net/images/anime/1688/128720l.jpg', 'Comedy, Fantasy', 'Anime'),
(414, 'Uta no☆Prince-sama♪ Movie: Maji Love Kingdom', 'Idol groups ST☆RISH, QUARTET NIGHT, and HE★VENS take to the stage in this feature-length animated concert. The three groups sing, dance, and welcome cheering fans to the Maji Love Kingdom.\n\n(Source: ANN)', '2019-06-14', 'https://cdn.myanimelist.net/images/anime/1685/102221l.jpg', NULL, 'Anime'),
(415, 'Violet Evergarden: Recollections', 'Recap of Violet Evergarden.', '2021-10-29', 'https://cdn.myanimelist.net/images/anime/1902/143097l.jpg', 'Drama', 'Anime'),
(416, 'Yuuseiboushi', 'Music video for Eve\'s song \"Yuuseiboushi.\"', '2021-09-11', 'https://cdn.myanimelist.net/images/anime/1606/117753l.jpg', NULL, 'Anime'),
(417, 'Yuru Camp△ Season 3', 'Within the narrow walls of the Outdoor Activities Club room, the few but lively members carry on the camping spirit as they have fun with DIY club experiments. Exciting experiences such as these have brought Nadeshiko Kagamihara deep into the world of camping, making her want to once again go on a solo trip.\n\nHowever, other plans come first, as Ayano Toki and Rin Shima invite Nadeshiko to camp near Ooi River. Eager to go on their first journey together, the girls set off to forge precious memories that will stick with their hearts for years to come.\n\n[Written by MAL Rewrite]', '2024-04-04', 'https://cdn.myanimelist.net/images/anime/1178/142710l.jpg', 'Slice of Life', 'Anime'),
(418, 'Di Yi Xulie', 'A new era begins in a devastated world gripped by nuclear winter. Humans are no longer in control of the world, and crises emerged one after another. As mankind tried to rebuild order, the protagonist Ren Xiaosu stepped up with his positive energy, and in the process changed the world.', '2023-07-19', 'https://cdn.myanimelist.net/images/anime/1130/137242l.jpg', 'Action, Adventure, Fantasy, Sci-Fi', 'Anime'),
(419, 'Watashi ni Tenshi ga Maiorita! Special', 'Hinata Hoshino, Hana Shirosaki, and Noa Himesaka are off to the countryside for a camping trip. At Hinata\'s behest, her elder sister, Miyako, reluctantly tags along. Seeing how gloomy Miyako is, the trio do their best to get her to enjoy herself too.\n\nBesides the camping trip, Watashi ni Tenshi ga Maiorita! Special contains three more short stories of the girls. Although their lives seem normal, one thing is certain: there is definitely no shortage of cuteness here!\n\n[Written by MAL Rewrite]', '2019-05-24', 'https://cdn.myanimelist.net/images/anime/1057/98215l.jpg', 'Comedy', 'Anime'),
(420, 'Berserk: Ougon Jidai-hen - Memorial Edition', 'Fleeing a traumatic childhood, lone mercenary Guts drifts from battle to battle, striking down powerful enemies with his unwieldy sword. After one skirmish, Guts clashes with the mystifying Griffith and his small army known as the Band of the Hawk. The victorious Griffith drafts Guts into his ranks, granting the swordsman a kinship unlike anything he has ever known.\n\nAlongside the skilled warrior Casca, Guts helps Griffith guide the band to fame and glory. But as he gains military prestige, Griffith becomes the target of assassination attempts and political schemes. He uses Guts to further his ambitious rise to power, taking advantage of the swordsman\'s lack of aspiration.\n\nEven as he grows closer to Casca, Guts\' absence of direction robs him of any sense of belonging. Fostering opposing desires, Guts and Casca fight for Griffith\'s dream—although fractures forming among the trio threaten to disrupt their world.\n\n[Written by MAL Rewrite]', '2022-10-02', 'https://cdn.myanimelist.net/images/anime/1607/127730l.jpg', 'Action, Adventure, Drama, Fantasy, Horror', 'Anime'),
(421, 'Chainsaw Man', 'Denji is robbed of a normal teenage life, left with nothing but his deadbeat father\'s overwhelming debt. His only companion is his pet, the chainsaw devil Pochita, with whom he slays devils for money that inevitably ends up in the yakuza\'s pockets. All Denji can do is dream of a good, simple life: one with delicious food and a beautiful girlfriend by his side. But an act of greedy betrayal by the yakuza leads to Denji\'s brutal, untimely death, crushing all hope of him ever achieving happiness.\n\nRemarkably, an old contract allows Pochita to merge with the deceased Denji and bestow devil powers on him, changing him into a hybrid able to transform his body parts into chainsaws. Because Denji\'s new abilities pose a significant risk to society, the Public Safety Bureau\'s elite devil hunter Makima takes him in, letting him live as long as he obeys her command. Guided by the promise of a content life alongside an attractive woman, Denji devotes everything and fights with all his might to make his naive dreams a reality.\n\n[Written by MAL Rewrite]', '2022-10-12', 'https://cdn.myanimelist.net/images/anime/1806/126216l.jpg', 'Action, Fantasy', 'Anime'),
(422, 'Xian Wu Chuan', 'As a loyal disciple, Ye Chen dedicated himself to guard the spiritual medicine field for his sect. But, during a fight with enemies, the spiritual field was destroyed. His loyalty and dedicating to the sect could not save him. The loyalty he thought he had obtained from his peers and lover, could not save him from betrayal. Thus, he was shamelessly banished from the sect. With the help of a flame falling from heaven, Ye Chen began to develop himself into a stronger cultivator. Battled against his opponents, unfolded his legendary life and rewrote his own story...', '2023-03-19', 'https://cdn.myanimelist.net/images/anime/1401/126049l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(423, 'Majo no Tabitabi', 'Since childhood, Elaina has always been fascinated by the stories written within her favorite book, especially those about Nike, a renowned witch who had numerous great travels across the world. Wanting to experience the awe of adventure herself, Elaina strives to become a witch, and despite the numerous trials that come her way, she eventually succeeds.\n\nNow a full-fledged witch, Elaina finally embarks on her long-awaited journey, in which she meets many people along the way, learning their various stories. Through all of this, she explores the world at its fullest—experiencing both its bright and dark sides—starting her legendary tale.\n\n[Written by MAL Rewrite]', '2020-10-02', 'https://cdn.myanimelist.net/images/anime/1802/108501l.jpg', 'Adventure, Fantasy', 'Anime'),
(424, 'Super Crooks', 'One last heist. That\'s what they all say, right? Just one final score, and everyone can retire and take up fishing. Thing is, the jails are filled with super villains who thought the same thing, and got busted. But the Heat\'s in a jam. He\'s run up the kind of gambling debt that - if he can\'t pay it back in cash - will be paid in blood. Nobody wants to see the most beloved supercrook of all time rubbed out by the mob - especially his biggest fan, Johnny Bolt. And Johnny\'s got a plan to help the Heat and make all his buddies disgustingly rich at the same time. Unfortunately for Johnny\'s recruits, they have to head to Spain and rob the world\'s most notorious super villain blind. And that\'s where things get tricky. \n\n(Source: Marvel Comics)', '2021-11-25', 'https://cdn.myanimelist.net/images/anime/1579/118015l.jpg', 'Action, Drama, Suspense', 'Anime'),
(425, 'Yong Sheng: Qizhuang Shanhe', 'How can the hero Fang Han use his own strength to traverse the vast fantastical world? By clinging to an unwavering refusal to accept defeat, he cracked the code of supernatural abilities and transformed his mortal body into an immortal one. Fang Han will reveal a new and prosperous world filled with immortals, demons, and mortals, along with countless innovative magic weapons. In addition, Fang Han will encounter conflicts between immortals and demons, love and hate. It will eventually lead to success.\n\n(Source: bilibili)', '2024-04-19', 'https://cdn.myanimelist.net/images/anime/1586/142081l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(426, 'Gyokou no Nikuko-chan', 'Kikuko Misuji, more often called \"Nikuko-chan,\" is known by everyone in her small northern town as the happy fat lady at the grill. Having lived arduously traveling from man to man and town to town for the bulk of her life, Nikuko-chan finally seems to have settled down on a houseboat docked in the bay with her daughter—also named Kikuko.\n\nTogether, the pair does their best to find their place in the world. For the bold and brash Nikuko-chan, her spirited behavior easily guides her toward the earnest goal. However, for the quiet and reserved Kikuko, who is often embarrassed by her mother\'s antics, each day can be just as uninspiring as the last. From middle school drama to solving the mystery of her strange classmate Ninomiya, Kikuko\'s adolescence is full of many twists and turns.\n\n[Written by MAL Rewrite]', '2021-06-11', 'https://cdn.myanimelist.net/images/anime/1747/116922l.jpg', 'Award Winning, Drama', 'Anime'),
(427, 'Trigun Stampede', 'On the planet Noman\'s Land, reporters Meryl Stryfe and Roberto De Niro traverse the desert in search of the infamous outlaw Vash the Stampede. But the man they find near the desolate town of Jeneora Rock is a far cry from the lethal terrorist they expect. In reality, Vash is a passive and carefree drifter; he is a proponent of peace, beloved by the residents of the town. His inaccurate reputation actually stems from the widespread atrocities committed by his twin brother Knives Millions. Still, Vash is dubbed \"The Humanoid Typhoon\'\' due to the tendency for violent chaos to follow in his wake.\n\nChaos soon arrives in the form of bounty hunters seeking the high price on Vash\'s head, and their violent pursuit poses great danger to the town and its precious power plant. Thanks to his gunslinging prowess, Vash is able to resist most of these nefarious forces. Yet he must soon face off against the ultimate evil: the unstoppable destructive power of his malevolent brother.\n\n[Written by MAL Rewrite]', '2023-01-07', 'https://cdn.myanimelist.net/images/anime/1426/129194l.jpg', 'Action, Adventure, Sci-Fi', 'Anime'),
(428, 'Ling Jian Zun 4th Season', 'Fourth season of Ling Jian Zun.', '2020-09-08', 'https://cdn.myanimelist.net/images/anime/1972/108157l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(429, 'Yoru no Kuni', '22-ji no Annaibito (The 22 O\'Clock Guide)\nRefusing to accept the death of her beloved dog, Choco, a young girl named Chiyo falls asleep, only to wake up in the Night World. She is greeted by Yoru, an entity that guides her through the realm of the darkest, most beautiful time of day. As Chiyo learns to cope with the loss in her heart, the starless world around her begins to light up.\n\n26-ji no Sagashimono (The 26 O\'Clock Search)\nSince childhood, best friends Hina and Tsumugi have used an exchange diary as a token of their friendship. Angered that Hina wants to open up the diary to include a new girl she has befriended, the jealous Tsumugi throws it away. Upon falling asleep, she wakes up in front of a labyrinth within the Night World. Initially refusing to take Yoru\'s help, Tsumugi searches for an answer to her predicament, but she is confronted by her feelings of loneliness instead. \n\n4-ji no Tegami (The 4 O\'Clock Letter)\nAnother morning is approaching, and the thought fills Akatsuki with dread. Dejected from her inability to build a career, she begins to throw away her art pieces, stumbling upon an old sketchbook in the process. Within the book is a letter from a former friend who, a long time ago, had given her hope. As she continues going through her belongings, Akatsuki starts to remember the friend\'s identity—and she might even discover her fading passion for painting.\n\n[Written by MAL Rewrite]', '2021-04-16', 'https://cdn.myanimelist.net/images/anime/1674/114425l.jpg', 'Fantasy, Slice of Life', 'Anime'),
(430, 'Dinghai Fusheng Lu', 'Immortal arts, magic weapons, magical powers, and the boundless spiritual qi between heaven and earth vanished into obscurity overnight, and all exorcists turned to mere mortals.\n\nThree hundred years later, the Five Hus traversed the pass, it was a prelude to an era of great turmoil in China. They heralded the end of the world, where thousands of drought fiends stalked the night—the collapse of the Divine Land is imminent.\n\nFortunately, within this long, dark night where silence had fallen on all magic, a lone star still glistened brightly on the horizon.\n\nThe Heart Lamp appeared, illuminating the vast expanse around it. A 16-year-old young man, who will end his life on his twentieth birthday, embarked on a journey to reclaim the spiritual qi of heaven and earth that had been sealed away—only four years remain.\n\nThe road ahead was filled with countless thistles and thorns, and it seemed improbable for him to succeed.', '2021-07-15', 'https://cdn.myanimelist.net/images/anime/1943/115892l.jpg', 'Action, Fantasy', 'Anime'),
(431, 'Huan Chong Shi', 'The young Chu Mu was plotted against and implanted with the White Nightmare by Xia Guanghan, and was taken to the Green Nightmare Island. Under the control of the Nightmare Palace, he and his soul pet Mo Xie were forced to fight bloody battles for survival, and eventually became the youngest king of the Prison Island. He became famous in front of the princess and was promoted to the Nightmare Master of Henghai. Chu Mu had some freedom and immediately returned to Gangluo City to save his family from danger. At the same time, Mo Xie\'s talent attracted Xia Guanghan\'s covetousness. Chu Mu fought again, and after a narrow victory, he was saved by his mother whom he had not seen for many years...\n\n(Source: Bilibili, translated)', '2024-05-26', 'https://cdn.myanimelist.net/images/anime/1502/142278l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(432, 'Re:Zero kara Hajimeru Isekai Seikatsu - Hyouketsu no Kizuna', 'Covered in ice and snow, Elior Forest is the home to dangerous magical beasts and 50 elves frozen in ice. One day, the great spirit Puck helps a young girl break out of her ice prison. Her name is Emilia, a half-elf born with silver hair, long ears, and amethyst eyes—features that resemble the evil Witch who destroyed half the world long ago. \n\nShunned by society because of her appearance, Emilia dwells in the forest with Puck as her sole companion and family. Burdened with a sin of destruction she does not remember committing, she spends her days trying to find a way to help her frozen kin. But when the great spirit Melakuera, the Arbitrator of the world, finds Emilia, her right to stay alive is brought into question. Will the bonds of ice she formed with Puck prove to be the warm thread that defies fate?\n\n[Written by MAL Rewrite]', '2019-11-08', 'https://cdn.myanimelist.net/images/anime/1238/104023l.jpg', 'Drama, Fantasy, Suspense', 'Anime'),
(433, 'Niehime to Kemono no Ou', 'Located at the end of the world, the Kingdom of Ozmargo is inhabited by beasts of all shapes and forms, ruled by a fearsome nameless king. After a hundred-year war between Ozmargo and the neighboring human kingdom ended, a peace treaty was signed: every year, a sacrifice must be sent to be devoured by the king on the night of revelation.\n\nSariphi is the 99th and latest human sacrifice. Although frail-looking, she neither fears the king nor has a family or home to return to should she manage to escape from her impending demise. Intrigued by the audacious girl, the king lets Sariphi roam around the palace despite the disapproval of his advisor, Anubis.\n\nLittle by little, the king and Sariphi begin to warm up to each other, but the night of revelation is fast approaching. Unbeknownst to them, the fateful day unleashes a series of events that will change the course of destiny of not only Sariphi and the king but also of their respective worlds.\n\n[Written by MAL Rewrite]', '2023-04-20', 'https://cdn.myanimelist.net/images/anime/1397/133339l.jpg', 'Fantasy, Romance', 'Anime'),
(434, '5-toubun no Hanayome Movie', 'Fuutarou Uesugi\'s efforts as the Nakano quintuplets\' private tutor are finally paying off. The academic performances of the five sisters are steadily improving, and they are each closer than ever to achieving their respective dreams. However, it appears that Fuutarou has become more than a teacher for the girls, who urge him to sort out his feelings.\n\nThe undecided young man promises to make a decision by the end of the school festival. However, Fuutarou\'s task will not be easy, as the Nakano sisters pull out all the stops to win his heart before it is too late.\n\n[Written by MAL Rewrite]', '2022-05-20', 'https://cdn.myanimelist.net/images/anime/1037/122516l.jpg', 'Comedy, Romance', 'Anime'),
(435, 'Yakusoku no Neverland', 'Surrounded by a forest and a gated entrance, the Grace Field House is inhabited by orphans happily living together as one big family, looked after by their \"Mama,\" Isabella. Although they are required to take tests daily, the children are free to spend their time as they see fit, usually playing outside, as long as they do not venture too far from the orphanage—a rule they are expected to follow no matter what. However, all good times must come to an end, as every few months, a child is adopted and sent to live with their new family, never to be heard from again.\n\nHowever, the three oldest siblings have their suspicions about what is actually happening at the orphanage, and they are about to discover the cruel fate that awaits the children living at Grace Field, including the twisted nature of their beloved Mama.\n\n[Written by MAL Rewrite]', '2019-01-11', 'https://cdn.myanimelist.net/images/anime/1830/118780l.jpg', 'Mystery, Suspense', 'Anime'),
(436, 'Isekai Shikkaku', 'Just as the famous writer Sensei is about to accomplish his life ambition and commit double suicide with his lover Sacchan, he is hit by a truck and transported to another world. Deemed an adventurer by the local priestess Annette, Sensei is given the daunting mission of slaying the demon king. Refusing to play into his new role, Sensei decides his efforts are better served looking for Sacchan in the hope that she is somewhere in this new world.\n\nEarly on in his journey, Sensei crosses paths with the martial artist Tama and unexpectedly saves her from mortal peril. Grateful for his actions, Tama decides to escort him. The pair are soon joined by Annette who, seduced by the writer\'s strong personality, has sworn to protect Sensei\'s life.\n\nAs the unlikely trio wander the dangerous, monster-infested lands, they soon realize that human beings might be the true threats to the peace of the world—and Sensei might be the only one with the power to stop them.\n\n[Written by MAL Rewrite]', '2024-07-09', 'https://cdn.myanimelist.net/images/anime/1252/143457l.jpg', 'Adventure, Comedy, Fantasy', 'Anime'),
(437, 'Heya Camp△: Sauna to Gohan to Sanrin Bike', 'Upon returning from school one day, Rin Shima encounters an unfamiliar three-wheeled motorcycle parked outside her house. After asking her father about it, she learns that the vehicle is a temporary loaner while her moped undergoes its annual maintenance.  \n\nWith arrangements to go camping at Yatsugatake the next day, Rin has no choice but to utilize the three-wheeler. As she embarks on her trip, Rin\'s traveling experience soon shifts gears, and she discovers a refined driving performance on new unexplored roads.\n\n[Written by MAL Rewrite]', '2020-05-27', 'https://cdn.myanimelist.net/images/anime/1909/105734l.jpg', 'Slice of Life', 'Anime'),
(438, 'Yuanshen: Jinzhong Ge', 'Animated short film about the backstory of the Knave from Genshin Impact.', '2024-04-17', 'https://cdn.myanimelist.net/images/anime/1229/142648l.jpg', 'Action, Drama, Fantasy', 'Anime'),
(439, 'Shingeki no Kyojin Movie: Kanketsu-hen - The Last Attack', 'A compilation movie for Shingeki no Kyojin: The Final Season - Kanketsu-hen.', '2024-11-08', 'https://cdn.myanimelist.net/images/anime/1379/145452l.jpg', 'Action, Drama, Suspense', 'Anime'),
(440, 'Hanma Baki: Son of Ogre', 'The mauling of a vicious, prehistoric-sized African elephant makes international headlines. Featured in reports of the aftermath, the sole survivor of one of the animal\'s rampages attributes its death to a lone, unarmed man—unknowingly describing Yuujirou Hanma, nicknamed the \"Ogre\" and often labeled as the \"strongest creature on Earth.\" Elsewhere, Yuujirou\'s 18-year-old son Baki spars with an equally formidable beast: a praying mantis.\n\nContent with his training and determined to overtake his father, Baki abducts American President George Bosch to begin his plans. This leads to his deliberate imprisonment at the infamous Arizona State Prison where Oliva Biscuit resides—the strongest man in the United States and an inmate allowed to leave of his own volition. Hoping to gauge his abilities, Baki challenges Oliva to a fight; but Oliva is preoccupied with his eccentric rival, Jun Guevaru. Known as the \"Second,\" he is the only other prisoner to receive special treatment from the guards.\n\nBewildered yet intrigued, Baki learns about his fellow inmates and tolerates the hellish conditions of prison life while waiting for an opportunity to present itself.\n\n[Written by MAL Rewrite]', '2021-09-30', 'https://cdn.myanimelist.net/images/anime/1628/119353l.jpg', 'Sports', 'Anime'),
(441, 'You Shou Yan 3rd Season', NULL, '2024-05-17', 'https://cdn.myanimelist.net/images/anime/1102/142342l.jpg', 'Comedy, Fantasy', 'Anime'),
(442, 'Aria the Crepuscolo', 'Aspiring Orange Company Undine Anya Dostoyevskaya feels dejected upon learning that her gondolier mentor, Alice Carroll, is not spending much time with her own mentor, Athena Glory. Athena—the Undine-turned-opera singer—has been attempting to arrange a meeting with Alice, but the latter seems to be avoiding her for unknown reasons.\n\nTo try and resolve this predicament, Anya calls upon her fellow Undines Ai Aino and Azusa B. McLaren. As the trio works to bring Alice and Athena together, Anya gains a deeper insight into her seniors\' feelings, which might just be the key to untangling the uncertainties between them.\n\n[Written by MAL Rewrite]', '2021-03-05', 'https://cdn.myanimelist.net/images/anime/1934/111002l.jpg', 'Sci-Fi, Slice of Life', 'Anime'),
(443, 'Isekai Kita no de Sukebe Skill de Zenryoku Ouka Shiyou to Omou The Animation', 'Tatsuo is a skilled masturbator who suddenly dies from masturbating too much. After dying, his soul was transferred to an isekai. An isekai goddess grant him a wish, then Tatsuo told him that he wanted a super cock that could make all women sigh with pleasure and make all women unable to live without it. He wants to make a harem with women who are already addicted to his super cock.\n\n(Source: Nekopoi, translated)', '2022-12-27', 'https://cdn.myanimelist.net/images/anime/1270/128666l.jpg', 'Hentai', 'Anime'),
(444, 'Ano Yume wo Nazotte', 'Music video animated by Koronosuke Koron for the song Ano Yume wo Nazotte by YOASOBI.', '2020-01-18', 'https://cdn.myanimelist.net/images/anime/1535/118640l.jpg', 'Romance', 'Anime'),
(445, 'Mushen Ji', 'In the Disabled Elderly Village, there live nine elderly people with unpredictable origins and the young man Qin Mu they raised. One day, the cows that Qin Mu was responsible for grazing began to speak human words. From then on, Qin Mu became more aware of the dangers and beauty of Daxu, a land abandoned by gods: demons descended with darkness, divine bones danced in the ruins, and dragon bones protected their young, a giant ship that drags the sun... No matter what kind of danger he faces, Qin Mu is fearless. He has integrated the skills passed down by the Nine Elders and vowed to carve out a world with his unparalleled hegemony. \n\n(Source: Bilibili, Google translated)', '2024-10-27', 'https://cdn.myanimelist.net/images/anime/1848/145764l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(446, 'Edens Zero 2nd Season', 'Now in possession of the Edens Zero, Shiki Granbell has gathered the Four Shining Stars. With the help of his new friends, Shiki will be able to breach Dragonfall—the border of the Sakura Cosmos swarming with mechanical dragons. Once that is achieved, he can continue his quest to find the goddess Mother.\n\nBefore the Edens Zero crew can advance their journey, they notice a mysterious warship following them. Upon learning that the ship—the Belial Gore—belongs to Drakken Joe, Shiki and his crew attempt to infiltrate it, intent on figuring out why the Dark Alchemist is after them. In the process, the Edens Zero is taken hostage by Drakken\'s subordinates.\n\nThough they are in a tight situation, Shiki refuses to back down. Working together with his friends, Shiki will have to take down the Dark Alchemist if he hopes to make it out of the Belial Gore alive.\n\n[Written by MAL Rewrite]', '2023-04-02', 'https://cdn.myanimelist.net/images/anime/1943/135100l.jpg', 'Action, Adventure, Fantasy, Sci-Fi', 'Anime'),
(447, 'Dragon Quest: Dai no Daibouken (2020)', 'A long time ago, there was a valiant swordsman who came to be known simply as \"the hero.\" There was a demon who has caused people suffering. The hero and his companions arrived to challenge the demon to a battle and by combining their powers, the battle was brought swift conclusion. With no one around to cause trouble, the island became a quiet place where everyone could live together in peace.\n\nSeveral years later, the demon is revived. Our present-day protagonist, Dai, lives on a remote island in the southern seas and dreams of becoming a great hero. When he hears about the demon\'s revival, Dai and his friends take it upon themselves to stop him and the evil force that revived him. Along the way, Dai discovers the identity of \"the hero,\" the truth behind the evil force who revived the demon, and Dai\'s own hidden powers that surface in times of peril.\n\n(Source: MU, edited)', '2020-10-03', 'https://cdn.myanimelist.net/images/anime/1499/109126l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(448, 'Wu Geng Ji Zhi San Jie', 'Third season of Wu Geng Ji.', '2019-12-20', 'https://cdn.myanimelist.net/images/anime/1000/116470l.jpg', 'Action, Fantasy, Supernatural', 'Anime');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(449, 'Bai Yao Pu 3rd Season', 'Third season of Bai Yao Pu.', '2022-07-25', 'https://cdn.myanimelist.net/images/anime/1889/119939l.jpg', 'Adventure, Mystery, Supernatural', 'Anime'),
(450, 'Luo Xiao Hei Zhan Ji: Zhongsheng Zhi Men', 'Second season of Luo Xiao Hei Zhan Ji.', '2021-04-24', 'https://cdn.myanimelist.net/images/anime/1909/114536l.jpg', 'Comedy, Supernatural', 'Anime'),
(451, 'Seitokai ni mo Ana wa Aru! PV', 'A promotional video advertising the Seitokai ni mo Ana wa Aru! manga.', '2024-07-09', 'https://cdn.myanimelist.net/images/anime/1485/144185l.jpg', 'Comedy', 'Anime'),
(452, 'JoJo no Kimyou na Bouken Part 6: Stone Ocean Part 2', 'Thrown into solitary confinement after a daring rescue attempt, Jolyne Kuujou fights to uncover the sinister plot of Whitesnake, an enemy Stand whose mysterious wielder remains unknown to her.\n\nWhitesnake\'s user is actually Enrico Pucci, priest and chaplain of Green Dolphin Street Prison. Pucci shares a deep connection with a villain who once plagued the Joestar bloodline, making his feud with Jolyne and her father, Joutarou, a personal one. Intent on executing the master plan of his deceased friend, Pucci uses the prison and its inmates to fulfill his nefarious schemes.\n\nAssisted by fellow prisoners, like Ermes Costello and Foo Fighters, Jolyne battles several enemy Stand users. As the ramifications of Pucci\'s plot spread beyond the confines of the prison and begin to threaten the rest of the world, Jolyne embraces her family lineage and risks her life to put an end to evil.\n\n[Written by MAL Rewrite]', '2022-09-01', 'https://cdn.myanimelist.net/images/anime/1051/121959l.jpg', 'Action, Adventure', 'Anime'),
(453, 'Princess Principal: Crown Handler Movie 2', 'The problem with assassinations is that bullets are cheap, fanatics are fanatical, and even when an attempt fails, there\'s always a chance for follow-ups. So even if the attack on Prince Richard by a supposed foreign sniper fails to put his royal highness six feet under, it soon becomes clear that it\'s open hunting season for Royals when assassins strike again. Now Team White Pigeon\'s priorities must be split between locating the deadly Cavorite bombs smuggled into the country and protecting Princess Charlotte\'s sister Mary, the next in line... which, given that Charlotte herself is also a target and currently posing as White Pigeon\'s Ange, only redoubles the peril she\'s already found herself in! The fuses are primed, and the timers are counting down in the second shocking and explosive installment of Princess Principal: Crown Handler!\n\n(Source: Sentai Filmworks, edited)', '2021-09-23', 'https://cdn.myanimelist.net/images/anime/1244/116570l.jpg', 'Action, Mystery', 'Anime'),
(454, 'Isekai Ojisan', 'After a fatal encounter with a truck, Takafumi Takaoka\'s uncle, Yousuke \"Ojisan\" Shibazaki, lies comatose for 17 years. When he finally regains consciousness, Ojisan begins to ramble in a foreign tongue and reveals that he had been transported to a magical world called Gran Bahamal. Takafumi dismisses his uncle\'s claims as nonsense until an incantation makes a cup of water hover in the air. In a flash of brilliance, the pair creates a YouTube channel to showcase Ojisan\'s magical abilities.\n\nThe responsibility now falls on Takafumi\'s shoulders to acquaint Ojisan with everything that has transpired during his absence, including getting him up to speed with the internet, new technology, and surprisingly, the outcome of the \'90s console war—the result of which was especially distressing for a hardcore SEGA fan. With Ojisan\'s wisdom from his other world experiences, they grow their YouTube channel and tackle online comments and trolls. The journey of this uncle-nephew duo promises to be anything but conventional.\n\n[Written by MAL Rewrite]', '2022-07-06', 'https://cdn.myanimelist.net/images/anime/1743/125204l.jpg', 'Comedy, Fantasy', 'Anime'),
(455, 'Mama x Holic: Miwaku no Mama to Amaama Kankei - The Animation', NULL, '2021-11-26', 'https://cdn.myanimelist.net/images/anime/1067/117537l.jpg', 'Hentai', 'Anime'),
(456, 'Sword Art Online: Alicization - War of Underworld 2nd Season', 'The final battle against the Dark Territory drags on, as players from all over the world flood the Underworld\'s servers and plunge the Human Empire into utter chaos. Asuna Yuuki and her friends defend their new allies with everything they have, but their numbers are falling. Meanwhile, Alice Zuberg heads toward the World\'s End Altar while Gabriel \"Vecta\" Miller relentlessly pursues her.\n\nMeanwhile, members of Rath strategize a plan in an attempt to restore Kirito\'s damaged fluctlight. However, the intruders occupying the main control room have other plans. Surrounded by death and despair, when all hope seems to be lost, one voice reaches out to Kirito—a familiar one saying, \"I will always be by your side.\"\n\nSword Art Online: Alicization - War of Underworld 2nd Season is the epic conclusion to Akihiko Kayaba\'s dream of creating artificial human intelligence. Now it is up to Kirito and his friends to protect this collapsing world from the people that still think it is just a game.\n\n[Written by MAL Rewrite]', '2020-07-12', 'https://cdn.myanimelist.net/images/anime/1438/105106l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(457, 'Dr. Stone: Stone Wars - Kaisen Zenya Special Eizou', 'A recap episode with additional scenes which was screened on Jump\'s official YouTube channel for Jump Special Anime Festa 2020.', '2020-10-11', 'https://cdn.myanimelist.net/images/anime/1097/109900l.jpg', 'Adventure, Comedy, Sci-Fi', 'Anime'),
(458, 'Yuru Camp△ Season 3 Specials', 'Specials included in the BD/DVD release of Yuru Camp△ Season 3.', '2024-06-26', 'https://cdn.myanimelist.net/images/anime/1597/143098l.jpg', 'Slice of Life', 'Anime'),
(459, 'Benghuai: Xing Qiong Tiedao - Xuanhuang', 'In the Year 4800 of the Star Calendar, the five lineages of the Vidyadhara made alliance on the Yuque, putting their sacred vow into writing. \"This oath shall remain unbroken, standing stronger than even earth and steel.\" — History of the Xianzhou: Exodus of the Five Dragons\n\nIn the Year 7379 of the Star Calendar, the Imbibitor Lunae Dan Feng caused turmoil that threatened the sacred wood. The Cloud Knights joined forces with the Vidyadhara Preceptors to assault him. — History of the Xianzhou: Cloud Knights War Records\n\n\"Noble successor of the Azure Dragon, bearer of divine blessings from the heavens. Traversing clouds and bestowing rain, shaping forms as the world\'s essence beckons.\"\n\nHe dreamed of shouldering his responsibilities, performing the ritual dance gracefully, and sealing the Ambrosial Arbor. He dreamed of stepping into a battlefield where sharp blades and arrows fell like rain, and meted out punishment from the sky. He dreamed of being chained between jade pillars, pierced by long nails, sealed in darkness. He dreamed of wandering aimlessly in the darkness, chased by lurking shadows.\n\nIn all the dreams, he was a dragon, a hero, a sinner, but never a person with love, hatred, sorrow, or joy like everyone else in this world.\n\n(Source: YouTube)', '2023-08-29', 'https://cdn.myanimelist.net/images/anime/1783/138114l.jpg', 'Action, Fantasy, Sci-Fi', 'Anime'),
(460, 'Fanren Xiu Xian Chuan: Chongzhi Ban', 'Remaster of the first season of Fanren Xiu Xian Chuan.', '2023-02-05', 'https://cdn.myanimelist.net/images/anime/1287/133320l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(461, 'Himesama \"Goumon\" no Jikan desu', 'As the commander of the Imperial Army\'s Third Legion, the Royal Empire\'s princess has led humanity to countless victories against the demonic Hellhorde. However, she has now been captured by the enemy and confined to the dungeons, with her sentient sword, Ex, as her only company.\n\nDue to her royal status, the princess knows invaluable secrets that would help the Hellhorde achieve dominance. To have her reveal all the information they need, the demons do not hesitate to subject the princess to the most vile forms of torture—that is, tempting her with delicious food, lasting friendships, adorable animals, and the most enjoyable experiences imaginable.\n\n[Written by MAL Rewrite]', '2024-01-09', 'https://cdn.myanimelist.net/images/anime/1056/139398l.jpg', 'Comedy, Fantasy, Gourmet', 'Anime'),
(462, 'One Piece: Gyojin Tou-hen', 'Two years after the Summit War, Monkey D. Luffy plans to reunite with the Straw Hat Pirates in the Sabaody Archipelago. However, the Marines obstruct Luffy\'s path with overwhelming force. Meanwhile, the Straw Hats must also foil the schemes of a group of impersonators acting in their likenesses.\n\nWith two years of intensive training with allies old and new, Luffy regroups with his friends aboard the Thousand Sunny to set sail for the New World. As the Straw Hat Crew departs for Fish-Man Island, new threats creep up from the abyss. But more determined than ever to become the King of the Pirates, Luffy is prepared to defeat any enemy that may stand between him and his dream.\n\n[Written by MAL Rewrite]', '2024-11-03', 'https://cdn.myanimelist.net/images/anime/1928/146063l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(463, 'Kimi wa Houkago Insomnia', 'High schooler Ganta Nakami has trouble falling asleep most nights. As a result, he is irritable at school, always searching for an opportunity to find a secluded place to doze off. On the other hand, Isaki Magari is a free spirit who is well liked by her friends, but no one is aware of her sleep disorder. She makes use of the school\'s abandoned astronomy club observatory as her secret sleeping bunker when she needs to get some shut-eye. \n\nAs fate would have it, Nakami finds Magari napping in the observatory. When Magari discovers that she and Nakami have something in common, she offers to share her secret sleeping spot with her fellow insomniac. As the two find warmth in each other\'s company, the struggles they face start to become easier to confront.\n\n[Written by MAL Rewrite]', '2023-04-11', 'https://cdn.myanimelist.net/images/anime/1402/134007l.jpg', 'Romance', 'Anime'),
(464, 'Lupin III: The First', 'The iconic \"gentleman thief\" Lupin III returns in an action-packed, continent-spanning adventure, as Lupin III and his colorful underworld companions race to uncover the secrets of the mysterious Bresson Diary, before it falls into the hands of a dark cabal that will stop at nothing to resurrect the Third Reich. The gang undertakes trap-filled tombs, aerial escapades, and daring prison escapes with the trademark wit and visual finesse that have made Lupin the 3rd one of the most storied animation franchises in the world, in a thrilling new caper that is sure to delight fans old and new.\n\n(Source: GKIDS, edited)', '2019-12-06', 'https://cdn.myanimelist.net/images/anime/1572/108506l.jpg', 'Action, Adventure, Comedy, Mystery', 'Anime'),
(465, 'Lagtrain', 'A music video for the song Lagtrain by inabakumori.', '2020-07-16', 'https://cdn.myanimelist.net/images/anime/1287/122186l.jpg', NULL, 'Anime'),
(466, 'Sekaiichi Hatsukoi: Propose-hen', 'Even at their colleagues\' wedding, the sparkling members of Marukawa Publishing\'s Emerald Department stand out. Having been invited to assist in providing entertainment for the guests, Masamune Takano, Ritsu Onodera, Yoshiyuki Hatori, Shouta Kisa, Kanade Mino, as well as Takafumi Yokozawa enjoy the festivities as much as their work allows.\n\nAs love blossoms between two individuals, marriage marks a momentous occasion fit for self-reflection. Whether they like it or not, the men of Marukawa need to consider where their own relationships are headed.\n\n[Written by MAL Rewrite]', '2020-02-21', 'https://cdn.myanimelist.net/images/anime/1896/102829l.jpg', 'Boys Love', 'Anime'),
(467, 'Binghuo Mochu', 'Nian Bing is the son of a fire mage and an ice mage. After both of his parents were killed by the Ice Lord, Nian Bing received both of his parents\' magic gems. When Nian Bing was trying to escape from the Ice Lord\'s followers, he managed to cast both fire and ice magic at the same time. An impossible feat for a mage. He fell from the cliff, unconscious, and was saved by an oldman. After he woke up, the oldman gave him a food so delicious he never tasted before. It turned out that the oldman was a genius chef, once called a spirit chef. And he wants Nian Bing to be his disciple no matter what! Is Nian Bing able to seek vengeance while aiming to become the greatest chef?\n\n(Source: MU)', '2021-12-11', 'https://cdn.myanimelist.net/images/anime/1915/132368l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(468, 'Benriya Saitou-san, Isekai ni Iku', 'Despite being a handyman with a wide range of skills, Saitou is severely undervalued and underpaid. When he complains, his boss fires him, claiming that he is easily replaceable. As if his luck was not bad enough, Saitou soon finds himself about to be run over by a truck on his way home.\n\nSurprisingly enough, Saitou does not die; instead, he is transported to another world. There, he meets a party composed of the female knight Raelza, the moonlight fairy Lafanpan, and the mage Morlock, who are all coincidentally looking to recruit a new member with a skill set like Saitou\'s.\n\nThroughout their time together, Saitou uses his expertise to assist his fellow party members and soon comes to receive the recognition he never thought was possible. However, Saitou\'s presence may just be the catalyst that will connect a diverse cast of people from different places, slowly uncovering the fate that could bring a great change to this world.\n\n[Written by MAL Rewrite]', '2023-01-08', 'https://cdn.myanimelist.net/images/anime/1805/132335l.jpg', 'Adventure, Comedy, Fantasy', 'Anime'),
(469, 'Shi Yi Chang An: Mingyue Jishi You Er', 'Second season of Shi Yi Chang An: Mingyue Jishi You.', '2021-04-15', 'https://cdn.myanimelist.net/images/anime/1805/113688l.jpg', 'Romance', 'Anime'),
(470, 'BanG Dream! Film Live 2nd Stage', 'The second animated live movie for the BanG Dream! franchise and the sequel to BanG Dream! FILM LIVE.\n\n(Source:BanG Dream! Wikia)', '2021-08-20', 'https://cdn.myanimelist.net/images/anime/1229/117735l.jpg', NULL, 'Anime'),
(471, 'Shinchou Yuusha: Kono Yuusha ga Ore Tueee Kuse ni Shinchou Sugiru', 'There is a popular saying: \"you can never be too careful.\" It is very important to prepare for every situation you may face, even if it seems like an unnecessary waste of time. Also, in games like RPGs, it is good to exceed the level of your enemies to achieve total victory.\n\nThese words describe Seiya Ryuuguuin a little too perfectly. After being summoned by the goddess Ristarte to save the world of Gaeabrande from destruction, the hero prepares himself for his noble journey. While this might be normal, he spends a very long time training himself, despite having overpowered stats. He fights weak enemies using his strongest skills and buys excessive amounts of supplies and potions—all to stay safe.\n\nWhile his attitude may be a bit annoying, it might just be the saving grace of Gaeabrande, especially considering that it is a world where the forces of evil dominate each and every expectation.\n\n[Written by MAL Rewrite]', '2019-10-02', 'https://cdn.myanimelist.net/images/anime/1715/103419l.jpg', 'Action, Adventure, Comedy, Fantasy', 'Anime'),
(472, 'Jibaku Shounen Hanako-kun', 'The famous Seven Mysteries that every school seems to have are a staple of Japanese urban legends. One of the most well-known of these tales is that of Hanako-san: the ghost of a young girl who haunts the school\'s bathrooms.\n\nKamome Academy has its own version of Hanako-san\'s legend. Rumors claim that if one successfully manages to summon Hanako-san, she will grant her summoner any wish. Lured by the gossip, many people have tried to call upon her, yet every attempt has failed. However, when Nene Yashiro, a girl hoping for romantic fortune, dares to summon Hanako-san, she discovers that the rumored \"girl\" is actually a boy!\n\nAfter a series of unfortunate events involving Yashiro\'s romantic desires, she is unwillingly entangled in the world of the supernatural, becoming Hanako-kun\'s assistant. Soon, she finds out about Hanako-kun\'s lesser-known duty: maintaining the fragile balance between mortals and apparitions.\n\n[Written by MAL Rewrite]', '2020-01-10', 'https://cdn.myanimelist.net/images/anime/1050/111687l.jpg', 'Supernatural', 'Anime'),
(473, 'Artiswitch', 'There is a rumor doing the rounds in Harajuku: somewhere in the back streets of Ura-Harajuku, a witch and her mysterious shop serve those whose wishes have gone unheard, giving them an opportunity to unlock their hearts\' greatest desires.\n\nBelieving this to be an ideal arrangement, the proud apprentice witch Nina strives to fulfill her customers\' wishes while her power and influence grow accordingly. However, not all wishes are meant to come true—and not all of them lead to a happy ending. As Nina is compelled to peer deeper into the human psyche, she soon discovers the dark side of a witch\'s obligations, and her ambitions begin to clash with her wish to comfort the entire world.\n\n[Written by MAL Rewrite]', '2021-05-28', 'https://cdn.myanimelist.net/images/anime/1805/115216l.jpg', 'Drama, Fantasy', 'Anime'),
(474, 'Dr. Stone: New World', 'With the ambitious Ryuusui Nanami on board, Senkuu Ishigami and his team are almost ready to sail the seas and reach the other side of the world—where the bizarre green light that petrified humanity originated. Thanks to the revival of a skillful chef, enough food is being prepared for the entire crew, and the incredible reinvention of the GPS promises to ensure safety on the open sea.\n\nPreparations for the upcoming journey progress swimmingly until Senkuu receives an eerie message from a mysterious source. More driven than ever, the scientist sets out to explore the new world and discover what it can offer for his scientific cause. Though the uncharted territories may hide unkind surprises, Senkuu, with a little help from science, is ready to take on any challenge.\n\n[Written by MAL Rewrite]', '2023-04-06', 'https://cdn.myanimelist.net/images/anime/1316/136268l.jpg', 'Adventure, Comedy, Sci-Fi', 'Anime'),
(475, 'Psycho-Pass: Sinners of the System Case.3 - Onshuu no Kanata ni＿＿', 'Shinya Kougami continues to wander the Southeast Asian Union (SEAUn) away from the eyes of the Sibyl System in Japan. While traveling through the Tibet-Himalayan Alliance Kingdom, Kougami encounters Guillermo Garcia—commander of a paramilitary group attempting to unite the local factions and bring peace to the war-torn nation. Wary of joining another mercenary group, Kougami declines to join his cause, but agrees to be driven to the nearby Tibetan capital by one of Garcia\'s men.\n\nHowever, Kougami\'s plan to remain uninvolved is short-lived when a bus of refugees are ambushed by armed guerrillas. Among them is a half-Japanese, half-Tibetan girl named Tenzing Wangchuck. Impressed with Kougami\'s fighting prowess as he single-handedly takes the attackers out, Wangchuck requests him to teach her how to fight so she can take revenge against the warlord who murdered her family. \n\nKnowing first-hand that there is no turning back to the person you were once you take a human life, Kougami is initially reluctant to accept her request. But faced with the girl\'s desire for vengeance that mirrors the haunting abyss inside his own heart, will he train her?\n\n[Written by MAL Rewrite]', '2019-03-08', 'https://cdn.myanimelist.net/images/anime/1819/97220l.jpg', 'Action, Mystery, Sci-Fi, Suspense', 'Anime'),
(476, 'Rurouni Kenshin: Meiji Kenkaku Romantan - Kyoto Douran', 'After living peaceful days at the Kamiya dojo, Kenshin Himura finds himself at a crucial crossroads, as his vow to never end a life is put to the ultimate test.\n\nFollowing the murder of his former commander, he now has to retread the road of violence and blood to take down Makoto Shishio—the assassin prodigy who calls himself the notorious Battousai\'s successor. With ambitions to overthrow the Meiji government and establish his dominion in Kyoto, Shishio has meticulously schemed for a decade, building a formidable anti-government military force. Now, Shishio has turned his sights toward recruiting Aoshi Shinomori, a cold-blooded killer and the former leader of the legendary Oniwaban Group warriors.\n\nAs Kenshin travels through a village abandoned by the government and currently under the iron fist of Shishio\'s henchmen, he is determined to prevent the country from spiraling back into civil war. He allies with his former rival, Hajime Saitou, forging a fragile partnership in a battle against Shishio\'s empire that will determine the fate of Japan.\n\n[Written by MAL Rewrite]', '2024-10-04', 'https://cdn.myanimelist.net/images/anime/1314/145530l.jpg', 'Action', 'Anime'),
(477, 'Suzume no Tojimari', 'On her way to school one day, Suzume Iwato stumbles upon Souta Munakata, a young man searching for abandoned areas. The high school girl directs Souta to a nearby ruin, but out of pure curiosity, she herself decides to head to the same destination.\n\nOnce there, Suzume discovers an isolated door with a dreamlike universe lying beyond it—a place that she can see and feel, but not enter. A strange stone rests on the ground nearby, but it turns into a cat-like creature and scurries away when Suzume lifts it. Suddenly afraid, she heads back toward her school, not realizing that her act of leaving the door open will have consequences.\n\nWith the \"keystone\" released, the evil within the other universe can now freely escape and wreak havoc throughout Japan. Intending to correct her dangerous mistake, Suzume joins Souta—whose true goal is to prevent evil from festering—in finding and locking all open doors before the country is destroyed.\n\n[Written by MAL Rewrite]', '2022-11-11', 'https://cdn.myanimelist.net/images/anime/1598/128450l.jpg', 'Adventure, Supernatural', 'Anime'),
(478, 'Kaguya-sama wa Kokurasetai? Tensai-tachi no Renai Zunousen', 'After a slow but eventful summer vacation, Shuchiin Academy\'s second term is now starting in full force. As August transitions into September, Miyuki Shirogane\'s birthday looms ever closer, leaving Kaguya Shinomiya in a serious predicament as to how to celebrate it. Furthermore, the tenure of the school\'s 67th student council is coming to an end. Due to the council members being in different classes, the only time Kaguya and Miyuki have to be together will soon disappear, putting all of their cunning plans at risk.\n\nA long and difficult election that will decide the fate of the new student council awaits, as multiple challengers fight for the coveted title of president.\n\n[Written by MAL Rewrite]', '2020-04-11', 'https://cdn.myanimelist.net/images/anime/1764/106659l.jpg', 'Comedy, Romance', 'Anime'),
(479, 'Nanatsu no Taizai: Mokushiroku no Yonkishi 2nd Season', 'Second season of Nanatsu no Taizai: Mokushiroku no Yonkishi.', '2024-10-06', 'https://cdn.myanimelist.net/images/anime/1109/145389l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(480, 'Meitantei Conan Movie 23: Konjou no Fist', 'The world\'s greatest blue sapphire, the \"blue lapis fist\", said to have sunk in a pirate ship in the late 19th century, on the coasts of Singapore. A local millionaire plots to retrieve it, and when it\'s exhibited in an exhibition at the Singaporean Marina Sands hotel, a murder takes place. A bloody Kaitou Kid announcement card is found in the crime scene.\n\nIn the meantime, Ran and Sonoko have come to Singapore to see a karate tournament held there. Conan, who doesn\'t have a passport and can\'t travel overseas, was supposed to stay at home. But Kid, who wants to make use of him, uses a magical trick to forcibly drag him to Singapore. Conan must obey Kid if he wants to get back to Japan, gets his glasses, wristwatch and clothes, amongst others, all stolen from him and he has to disguise himself.\n\nRan, who doesn\'t realize who he is, asks him his name and he improvises the name Arthur Hirai. Kid eventually gets a hold of information about the \"fist\" being stored in a manor\'s underground vault. Just when he was thinking that he\'d made it inside very easily, he finds a dangerous trap awaiting him. Facing him is the strongest karateka with 400 consecutive victories: Makoto Kyogoku.\n\n(Source: Detective Conan World)', '2019-04-12', 'https://cdn.myanimelist.net/images/anime/1010/98309l.jpg', 'Action, Comedy, Drama, Mystery', 'Anime'),
(481, 'Shishunki no Obenkyou', NULL, '2021-12-17', 'https://cdn.myanimelist.net/images/anime/1853/139250l.jpg', 'Hentai', 'Anime'),
(482, 'Princess Principal: Crown Handler Movie 3', 'While the funeral of the assassinated Prince Edward, who was the first in line to succeed the throne, is being held, the nobles of the Kingdom of Albion discuss topics such as whether the second-in-line Princess Mary or the third-in-line Duke of Arkham, Prince Richard, will succeed the throne, and how the Duke of Normandy will act.\n\nThe Duke of Arkham asks Princess if she will side with him or the Duke of Normandy. While wishing to change the world so that all people are equal, Princess is shaken by the Duke of Arkham, who is the mastermind behind Edward\'s assassination. Meanwhile, Ange and Dorothy are given a mission to infiltrate as Mary\'s maids and investigate the state of the royal family by the Commonwealth\'s control. Mary is crushed and exhausted due to the pressure of becoming first in line to the throne. As chaos surrounds the succession to the throne, the Duke of Arkham\'s plot finally begins to unfold.\n\nThe darkness writhing in the Kingdom of Albion begins to swallow up Team White Pigeon.\n\n(Source: Official site, translated)', '2023-04-07', 'https://cdn.myanimelist.net/images/anime/1570/130995l.jpg', 'Action, Mystery', 'Anime'),
(483, 'Bokutachi no Remake', 'Life is not going well for 28-year-old Kyouya Hashiba. Having left his office job to pursue a career in the video game industry, his internship at a popular game studio abruptly ends, leaving him unemployed and forcing him to move back in with his parents. Additionally, his jealousy toward the success of the \"Platinum Generation\"—a group of similarly-aged creators—has caused him to regret his decision to attend a traditional university instead of an arts college. Even though he believes there are no second chances in life, Kyouya is suddenly given one when he wakes up one day and finds himself 10 years in the past.\n\nInstead of choosing business school like he originally had, Kyouya decides to pursue his passions and attends the Oonaka University of Art. There, he meets classmate Eiko Kawasegawa, the woman who had hired him as an intern in the present, alongside his new housemates and future Platinum Generation members: underachieving artist Aki Shino, aspiring singer and actress Nanako Kogure, and naturally-gifted writer Tsurayuki Rokuonji.\n\nWith each project they complete together, Kyouya and his friends venture closer to discovering their true potential as creators and remaking their lives into the ideal versions they desire.\n\n[Written by MAL Rewrite]', '2021-07-03', 'https://cdn.myanimelist.net/images/anime/1871/118309l.jpg', 'Drama, Romance', 'Anime'),
(484, 'Li Linke de Xiao Guaner 2nd Season', NULL, '2023-01-30', 'https://cdn.myanimelist.net/images/anime/1918/132125l.jpg', 'Gourmet, Slice of Life', 'Anime'),
(485, 'Wonderful Precure!', 'The Wonderful Precure! anime is set in Animal Town, a town where animals and people live together in harmony. Second-year junior high school student Iroha Inukai is best friends with her dog named Komugi. Out for a walk one day, Iroha and Komugi encounter a mysterious creature named Garugaru, who goes on a rampage in the city. Komugi suddenly transforms into a Pretty Cure named Cure Wonderful, to protect Iroha.\n\n(Source: ANN)', '2024-02-04', 'https://cdn.myanimelist.net/images/anime/1852/140786l.jpg', 'Action', 'Anime'),
(486, 'Promare', 'Thirty years ago, a new race of flame-wielding mutants suddenly appeared, destroying a large portion of humanity. These so-called “Burnish” have continued to appear at random, leaving a trail of death and destruction in their wake.\n\nThe autonomous republic of Promepolis is a thriving nation thanks to the incredible efforts of their leader, Kray Foresight, against the Burnish. A team of firefighters known as the Burning Rescue is tasked with stopping these horrifying monsters, using the most performant technology available thanks to their incredible mechanic Lucia Fex. Galo Thymos is an energetic young man, who considers Foresight his hero for saving his life and is the rescue team\'s most recent recruit. \n\nA terrorist group calling themselves Mad Burnish has been causing havoc all over the nation. After an encounter with Mad Burnish leader Lio Fotia, Galo sets out on his fated journey to find the truth about these mutants, ultimately leading him to question everything he previously held to be true.\n\n[Written by MAL Rewrite]', '2019-05-24', 'https://cdn.myanimelist.net/images/anime/1008/101845l.jpg', 'Action, Sci-Fi', 'Anime'),
(487, 'Yamiyo', 'Official music video for Eve\'s song Yamiyo, the song was used as the second ED to the Dororo TV series. The song was on EVE\'s digital album release the following day.', '2019-06-24', 'https://cdn.myanimelist.net/images/anime/1389/101642l.jpg', NULL, 'Anime'),
(488, 'Isekai Quartet Movie: Another World', 'The class arrives in another world and they encounter a desolate environment dominated by a rampaging magical automaton.', '2022-06-10', 'https://cdn.myanimelist.net/images/anime/1222/122000l.jpg', 'Comedy, Fantasy', 'Anime'),
(489, 'Jigokuraku', 'Sentenced to death, ninja Gabimaru the Hollow finds himself apathetic. After leading a blood-soaked life, Gabimaru believes he deserves to die. However, every attempt to execute him inexplicably fails. Finally, Sagiri Yamada Asaemon, a fledgling member of a famed executioner clan, is asked to take Gabimaru\'s life; yet Sagiri makes no move to kill him as requested.\n\nInsisting that Gabimaru will not die because of his love for his wife, Sagiri instead offers him the chance to obtain a full pardon for his crimes. If he can travel to the island of Shinsekyo and obtain the Elixir of Life—which supposedly grants immortality—and bring it back for the shogun, then his freedom will be assured.\n\nBut of the many who have traveled to Shinsekyo in search of the mythical Elixir, not a single person has returned sound of mind, if at all. Though unaware of the numerous dangers ahead, Gabimaru decides to accept the offer—alongside ten other death row convicts—in hope that he and his wife may finally live in peace.\n\n[Written by MAL Rewrite]', '2023-04-01', 'https://cdn.myanimelist.net/images/anime/1075/131925l.jpg', 'Action, Adventure, Supernatural', 'Anime'),
(490, 'Fanren Xiu Xian Chuan: Yan Jia Bao Dazhan', 'Episodes 18-21 of Fanren Xiu Xian Chuan.', '2021-01-31', 'https://cdn.myanimelist.net/images/anime/1323/114855l.jpg', 'Action, Adventure, Fantasy', 'Anime'),
(491, 'Otome Game Sekai wa Mob ni Kibishii Sekai desu', 'Blackmailed into playing a dating simulator set in a matriarchy, an ordinary man must put up with the unbearable and convoluted world until he clears the game. After countless days of grinding, he finally manages to beat it, but his hardcore gaming comes at a cost: extreme sleep deprivation and hunger.\n\nWhile heading out to the convenience store to solve one of these problems, the man tumbles down the stairs and falls unconscious, only to wake up to the worst possible realization—he has been reincarnated into the game as the mob character Leon Fou Bartfort. Now trapped in a world he despises, Leon must use his knowledge of the game to navigate through the plot safely and sustain himself in a society where the odds are heavily stacked against him.\n\n[Written by MAL Rewrite]', '2022-04-03', 'https://cdn.myanimelist.net/images/anime/1161/121462l.jpg', 'Action, Fantasy, Romance', 'Anime'),
(492, 'Romantic Killer', 'Anzu Hoshino needs only three things in her life: video games, chocolate, and her beloved cat. Unlike other high school girls, Anzu has no time for or interest in romance. But as she begins playing a poorly programmed 3D otome game, a bizarre flying wizard named Riri emerges from the screen and calls Anzu \"subject one,\" the first person who will experience a dating game harem storyline in real life.\n\nDespite Anzu\'s fiery protests, Riri confiscates her favorite things to force her to focus on love. Riri orchestrates a series of unlucky incidents and romantic cliches that lead her to meet Tsukasa Kazuki, one of the most attractive boys in her school. Still enraged, Anzu is adamant about resisting Tsukasa\'s charm. As all the ridiculous fabricated scenarios help Anzu warm up to Tsukasa\'s pleasant nature, Riri throws other stereotypical pretty boys her way—and avoiding romance quickly becomes almost impossible.\n\n[Written by MAL Rewrite]', '2022-10-27', 'https://cdn.myanimelist.net/images/anime/1764/142001l.jpg', 'Comedy, Romance, Supernatural', 'Anime'),
(493, 'Meitantei Conan Movie 24: Hiiro no Dangan', 'Japan is about to celebrate the world\'s largest sports festival, \"WSG-World Sports Games\", in Tokyo. In line with the opening ceremony, it is announced that the world\'s first \"Vacuum Superconducting Linear\" train, boasting a maximum speed of 1,000 km/h which combined all of Japan\'s technologies, will be opened to the public between Shin-Nagoya Station and Shibahama Station and established in Tokyo. As the world\'s attention is garnered, an incident occurs at a party venue where famous tournament sponsors are gathered, leading to an abnormal situation where top dogs of companies are kidnapped one after another. Behind the scenes are Shuichi Akai who monitors the incident, and the FBI who waits for orders from Akai.\n\nConan\'s reasoning reveals the relevance of the apocalyptic WSG kidnapping incident that occurred in Boston, USA, fifteen years ago, and that the incident was also under the jurisdiction of the FBI. Is this a coincidence? What is going to happen in Japan, where many types of people from all over the world are gathered?\n\n(Source: Detective Conan World)', '2021-04-16', 'https://cdn.myanimelist.net/images/anime/1306/112616l.jpg', 'Action, Comedy, Drama, Mystery', 'Anime'),
(494, 'Wu Shan Wu Xing: Xichuan Huan Zi Lin', 'Second season of Wu Shan Wu Xing.', '2023-07-26', 'https://cdn.myanimelist.net/images/anime/1983/147467l.jpg', 'Action, Fantasy, Supernatural', 'Anime'),
(495, 'Douluo Dalu: Daoyan Jianji Ban', 'The director\'s version of the film retells the events of the last three episodes of the series with the addition of some changes.', '2023-12-02', 'https://cdn.myanimelist.net/images/anime/1825/140196l.jpg', 'Action, Adventure, Fantasy, Supernatural', 'Anime'),
(496, 'Liehuo Jiao Chou', 'In the current era, a small percentage of people called \"Special Abilities\" have skills and powers normal humans do not possess. An autonomous organization, the Deviant Control Office, keeps these Special Abilities in check. Though some wish to maintain this order and peace, some wish to take advantage of their abilities and obtain more power in this world.', '2021-10-07', 'https://cdn.myanimelist.net/images/anime/1042/119432l.jpg', 'Action, Drama, Supernatural', 'Anime'),
(497, 'Yuanshen: Tiwate Pian Mu Jian PV - Dong Ye Yu Xi', 'Promotional video showcasing the aftermath of the Inazuma storyline of  Genshin Impact from the Eleven Fatui Harbingers\' side.', '2022-07-11', 'https://cdn.myanimelist.net/images/anime/1695/142650l.jpg', 'Fantasy', 'Anime'),
(498, 'Xue Ying Ling Zhu 3rd Season', 'The third season of Xue Ying Ling Zhu.', '2021-12-27', 'https://cdn.myanimelist.net/images/anime/1490/120175l.jpg', 'Action, Adventure, Fantasy, Romance', 'Anime'),
(499, 'Monsters: Ippyaku Sanjou Hiryuu Jigoku', 'A samurai\'s path leads him to a young waitress whose hometown was destroyed by a dragon. He doesn\'t want any trouble, but it finds them anyway.\n\n(Source: Netflix)', '2024-01-22', 'https://cdn.myanimelist.net/images/anime/1929/140372l.jpg', 'Fantasy', 'Anime'),
(500, 'Aria the Benedizione', 'The successor and branch manager of the Himeya Company—one of the many Undine associations housing female gondoliers—Aika S. Granzchesta surprises everyone when she rejects tradition and refuses to inherit the company\'s legendary gondola. Aika\'s apprentice Azusa B. McLaren, unable to wrap her mind around her mentor\'s unexpected decision, confronts her directly but to little effect. To better understand her reasoning, Azusa and her fellow Undines secretly plan to arrange a meeting with Aika.\n\nWith the much-awaited winter days in sight, accompanied by the tranquility and sublimity of Neo-Venezia, Aika reminisces about her journey as an Undine that forged her into the person she is today. As she vividly remembers all those invaluable experiences of the past, she trusts they will continue to guide her into the unknown yet boundless future.\n\n[Written by MAL Rewrite]', '2021-12-03', 'https://cdn.myanimelist.net/images/anime/1707/117069l.jpg', 'Sci-Fi, Slice of Life', 'Anime'),
(501, 'The Dangerous Convenience Store', 'College student Yeo Euijoon has little going for him. To pay his living expenses, tuition, and even his comatose brother\'s hospital bills, Euijoon spends his nights working at a convenience store. However, it is by no means an ordinary store; it is situated in a dangerous neighborhood, and all sorts of crooks and gangsters tend to come by and stir up trouble. Still, Euijoon never loses his lively spark and greets everyone with a smile.\n\nAlthough most thugs pick fights with Euijoon, one tall, handsome, and well-dressed returning customer makes Euijoon all flustered. Beom Geonwoo is a man of very few words, slightly older than Euijoon, and certainly not a stranger to blood and violence. But Euijoon thinks him sweet, and when Geonwoo by chance catches Euijoon in a sticky personal situation, they start a casual fling that may just turn life-changing for the both of them.\n\n[Written by MAL Rewrite]', '2020-11-08', 'https://cdn.myanimelist.net/images/manga/2/272466l.jpg', 'Boys Love, Erotica', 'Manga'),
(502, 'Tsuihou sareru Tabi ni Skill wo Te ni Ireta Ore ga, 100 no Isekai de 2-shuume Musou', 'A mysterious god-like entity has given Ed a crazy ordeal in which he must be expelled from a party of 100 heroes in 100 different worlds in order to return to his original world, but he finally achieves the condition and is able to return to his original world. However, as a final additional condition, he is given the chance to \"see what happens to the worlds he has been banished from.\"... This is where he learns a shocking fact.\n\n\"All right, I\'ll do it! I\'ll go there again and be banished for good all over again!\"\n\nOnly this time he is accompanied to these 100 worlds by a former companion...\n\n\"Fufu~, don\'t worry! I\'ll be with you this time!\"\n\n\"Yeah, I\'m more worried...\"\n\n(Source: Shousetsuka ni Narou, translated)', '2022-07-26', 'https://cdn.myanimelist.net/images/manga/1/278728l.jpg', 'Fantasy', 'Manga'),
(503, 'Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su', 'Second year high school student Rakurou Hizutome is interested in one thing only: finding \"shitty games\" and beating the crap out of them. His gaming skills are second to none, and no game is too bad for him to enjoy. So when he\'s introduced to the new VR game Shangri-La Frontier, he does what he does best—min-maxes and skips the prologue to jump straight into the action. But can even an expert gamer like Rakurou discover all the secrets that Shangri-La Frontier hides...?\n\n(Source: Kodansha USA)', '2020-07-15', 'https://cdn.myanimelist.net/images/manga/3/235471l.jpg', 'Action, Adventure, Award Winning, Fantasy', 'Manga'),
(504, 'After School Lessons for Unripe Apples', 'Kim Cheol detests nothing more than attention, yet his oppressive height and a scar under his eye make him stick out like a sore thumb. In contrast, Cheol\'s new seatmate, Hwang Mi-ae, is incredibly outgoing and the shortest in their class. They look comical next to each other, and to add to their embarrassment, their names are the same as those of a famous but extremely ridiculous dancing duo.\n\nCheol struggles with controlling his temper and avoids others by any means necessary, while all Mi-ae is interested in are comics, her favorite boy band, and going out with her friends. However, he is her new neighbor, and they even knew each other in early childhood. Despite everyone\'s fear of Cheol, Mi-ae notices his awkwardness and selfless nature and tries to befriend him. He may be difficult to approach for now, but through the busy days of studying for the high school entrance exams, Cheol will soon become Mi-ae\'s most precious person.\n\n[Written by MAL Rewrite]', '2020-12-23', 'https://cdn.myanimelist.net/images/manga/1/261508l.jpg', 'Romance', 'Manga'),
(505, 'Tokidoki Bosotto Russia-go de Dereru Tonari no Alya-san', 'Smart, refined, and strikingly gorgeous, half-Russian half-Japanese Alisa Mikhailovna Kujou is considered the idol of her school. With her long silver hair, mesmerizing blue eyes, and exceptionally fair skin, she has captured the hearts of countless male students while being highly admired by all others. Even so, due to her seemingly unapproachable persona, everyone remains wary around the near-flawless girl.\n\nOne of the few exceptions is Alisa\'s benchmate Masachika Kuze, a relatively average boy who spends his days watching anime and playing gacha games. Despite his nonchalant demeanor, Masachika is the sole student to receive Alisa\'s attention. Unable to be fully honest, Alisa is frequently harsh on Masachika and only expresses her affection in Russian. Unbeknownst to her, however, Masachika actually understands the language yet simply pretends otherwise for his own amusement.\n\nAs the odd pair continues to exchange witty and playful remarks, their relationship gradually grows more romantic and delightful—and Alisa might finally learn to freely convey her true feelings.\n\n[Written by MAL Rewrite]', '2021-02-27', 'https://cdn.myanimelist.net/images/manga/3/241840l.jpg', 'Comedy, Romance', 'Manga'),
(506, 'The Legend of the Northern Blade', 'For decades, the brave warriors of the Northern Heavenly Sect fought to keep the world safe from the evil Silent Night. But when the fourth generation leader is accused of colluding with the enemy, he is forced to disband the sect and commit suicide to protect his son, Moowon. With no family and allies left, Moowon leads a dreary life under close surveillance... until a surprise attack from the Silent Night gives him a chance to escape to the mountains. There, the young warrior trains to master the fighting techniques of his predecessors, before the mysterious disappearance of a loved one brings him back to the mainland. Follow Moowon as he embarks on a journey to avenge his father\'s death and take down the villains who threaten to plunge the world into darkness!\n\n(Source: Tappytoon)', '2019-12-31', 'https://cdn.myanimelist.net/images/manga/3/243483l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(507, 'Sayonara Eri', 'Suffering from a terminal illness, Yuuta\'s mother asks him to film her last moments, which he does. From her radiant smile when she is with her family to the times when sickness ravages her body in the hospital, he records hours upon hours of footage. After her passing, Yuuta compiles her life into a movie to screen at his school, deciding to add a bit of fantasy to the ending of his film, Dead Explosion Mother, with a literal explosion!\n\nFollowing the backlash caused by his supposedly tone-deaf portrayal of his mother\'s death, Yuuta trudges to the hospital roof to take his own life—but there, he meets a girl named Eri. Captivated by his film, Eri requests Yuuta to make a new  one that will blow the previous out of the water and prove his critics wrong. The movie they set out to make will stand apart by blurring the line between fact and fiction. And of course, it wouldn\'t be a Yuuta film if it didn\'t have his personal flavor—just a dash of fantasy.\n\n[Written by MAL Rewrite]', '2022-04-11', 'https://cdn.myanimelist.net/images/manga/3/263979l.jpg', 'Drama', 'Manga'),
(508, 'Semantic Error', 'Chu Sangwoo, a computer science student, is an uncompromising creature of habit who follows a meticulously organized schedule, drinks the same coffee every day, and sits in the same spot in each class. Tasked with doing a group assignment alongside freeloaders, Sangwoo decides that it is only logical not to credit them. However, his strict treatment causes his popular senior Jang Jaeyoung to lose the opportunity to graduate and study abroad. Seeing as he did nothing wrong, Sangwoo avoids Jaeyoung\'s constant phone calls.\n\nAs fate would have it, the two men meet when Sangwoo needs a new graphic designer for the 2D game he is making. Jaeyoung is known for his charming personality, but he actually hides a hot temper. Despite his unchanging situation, Jaeyoung cannot stand Sangwoo\'s apathetic attitude and decides to get revenge by interrupting everything Sangwoo spent years carefully planning. Sangwoo tries his best to keep his calm, but Jaeyoung\'s presence and attractive smile may prove to be more than just a bug in his perfectly coded life.\n\n[Written by MAL Rewrite]', '2020-07-27', 'https://cdn.myanimelist.net/images/manga/1/259484l.jpg', 'Boys Love', 'Manga'),
(509, 'The Knight Only Lives Today', '\"You\'re a genius.\" Those words he heard as a child were poison. Encrid dreamed of becoming a knight, but he soon realized it was futile. \"You want to live by the sword with that level of skill?\" Some laughed at him. \"Just give up.\" Some advised him against it. Despite that, his dream remained steadfast. He slept less, ran more, and trained harder. One day, he died, having been stabbed in the neck. Encrid opened his eyes again to \"today\'s\" morning.\n\n(Source: Naver Corporation, translated)', '2024-05-17', 'https://cdn.myanimelist.net/images/manga/1/303264l.jpg', 'Action, Fantasy', 'Manga'),
(510, 'Love Bullet', 'Trading love\'s bows and arrows for firearms, these cupids are heart snipers.\n\nKoharu, an indecisive novice cupid, joins her senpais, who are full of individuality, in this romantic gun action series.\n\n(Source: Kadokawa, translated)', '2023-10-05', 'https://cdn.myanimelist.net/images/manga/3/307661l.jpg', 'Action, Drama, Girls Love, Supernatural', 'Manga'),
(511, 'Unnamed Memory', '\"My wish as champion is for you to descend the tower and be my wife.\" Climbing a deadly tower, Oscar seeks the power of its master, the Witch of the Azure Moon. He hopes her incredible magic can break a curse that will kill any woman he takes for a wife. When the prince sees how beautiful Tinasha is, though, he has a better idea—since she\'s surely strong enough to survive his curse, she should just marry him instead! Tinasha isn\'t keen on the idea, but agrees to live with Oscar in the royal castle for a year while researching the spell placed on the prince. The witch\'s pretty face hides several lifetimes of dark secrets, however—secrets that begin resurfacing...\n\n(Source: Yen Press)', '2019-01-17', 'https://cdn.myanimelist.net/images/manga/3/245253l.jpg', 'Adventure, Fantasy, Romance', 'Manga'),
(512, 'Kininatteru Hito ga Otoko ja Nakatta', 'The black-clad boy that Aya Oosawa likes is perfect: he is effortlessly nonchalant, has a sharp sense of style, and listens to the best music. Ever since the trendy Aya stumbled upon a small CD store to enjoy the rock classics her friends are not familiar with, the mysterious employee behind the counter has been on her mind. Meanwhile, the quiet and aloof Mitsuki Koga listens to her popular classmate Aya rave about her crush, tormented by a nagging thought: how to tell Aya that the guy she is interested in is not a guy at all!\n\nIn reality, when Mitsuki sheds her plain high school uniform, she is the one manning the counter at her uncle Joe\'s CD shop. She wrestles with how to reveal her identity, but flirting with the stunning and clueless Aya is just too tempting. As music becomes their shared passion, it seems that Aya\'s feelings will remain unchanged—even when Mitsuki\'s secret comes to light.\n\n[Written by MAL Rewrite]', '2023-04-19', 'https://cdn.myanimelist.net/images/manga/3/288182l.jpg', 'Girls Love', 'Manga'),
(513, 'Bungou Stray Dogs: Beast', 'Ryuunosuke Akutagawa lives in the slums, using his ability to beat up anyone who dares lay a finger on his sister, Gin, or his friends. But his life takes a turn for the worse when armed criminals come after his gang, killing them in the process. In an attempt to avenge his friends, Akutagawa finds himself on the verge of death. A mysterious man dressed in black greets him, saying that he will take care of his sister until Akutagawa is ready to challenge him again.\n\nMore than four years have passed, and there is still no sign of the man in black or Gin. Even so, Akutagawa refuses to give up on his search. When Sakunosuke Oda takes pity on his living conditions and invites him to become a member of the Armed Detective Agency, an opportunity arises for Akutagawa to finally get a lead on Gin\'s whereabouts.\n\nUnbeknownst to him, however, Gin is guarded by none other than Port Mafia\'s wicked leader, Osamu Dazai, and his successor, Atsushi Nakajima—the infamous \"White Reaper.\" To save his sister, Akutagawa must overcome his weakness and sacrifice it all.\n\n[Written by MAL Rewrite]', '2019-12-26', 'https://cdn.myanimelist.net/images/manga/2/234643l.jpg', 'Action, Mystery, Supernatural', 'Manga');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(514, 'My Bias Gets on the Last Train', '\"Meeting her on the last train again today, if only I could talk to her!\"\n\nCollege student Lee Yeowoon works late and takes the last train every night. Each time, he runs into Shin Haein, a woman carrying a guitar. As if by chance, as if by fate, the two keep meeting and discover that their favorite artist is the indie musician \"Long Afternoon.\" They gradually grow closer, and so the story begins.\n\n(Source: Naver Corporation, translated)', '2024-12-14', 'https://cdn.myanimelist.net/images/manga/2/318971l.jpg', 'Romance', 'Manga'),
(515, 'Lost in the Cloud', 'Skylar has a secret hobby—taking photos of his crush, Chan-il. But when Cirrus stumbles upon Skylar\'s cloud storage with its impressive collection of Chan-il\'s photos, things escalate pretty quickly. At first confident his secret is safe with Cirrus, Skylar continuously finds himself in compromising situations, making him question Cirrus\' true motives.\n\n(Source: Lezhin Comics)', '2020-11-20', 'https://cdn.myanimelist.net/images/manga/3/260548l.jpg', 'Boys Love', 'Manga'),
(516, 'Debut or Die!', 'Falling drunk after failing the civil service exam again, Ryu Gunwoo is shocked to wake up in a motel with an unfamiliar appearance. Somehow, not only is he inhabiting the body of Park Moondae—a 20-year-old orphan who took his own life—but he has also regressed three years into the past. Furthermore, he is unable to find information about his original body anywhere.\n\nRecovering from his surprise, Moondae wonders if his present situation is similar to the action fantasy novels he knows of. To test his theory, he calls for a status window, which actually appears, albeit bearing the worst news possible: \"Debut or Die.\" Unless he debuts as an idol within a year, he will perish.\n\nTo avoid his deadly fate, Moondae must secure a spot on the idol survival show Idol Inc. and improve his abilities to the maximum. Due to his past job as a paparazzo, at least Moondae has some insight into the idol experience. However, one wrong step could put his future career—and entire existence—in jeopardy.\n\n[Written by MAL Rewrite]', '2022-08-01', 'https://cdn.myanimelist.net/images/manga/3/283354l.jpg', 'Drama', 'Manga'),
(517, 'Define the Relationship', 'Alphas lust for Omegas, and Omegas want Alphas. That\'s the way of the world, but Karlyle isn\'t your typical Alpha. He doesn\'t thirst after every Omega he sees—well, let\'s say that things are complicated. Karlyle feels no need to change, but when troubles occur with his sex life his doctor suggests something surprising. Try sleeping with Alphas, instead of Omegas. Karlyle finds this solution strange, but the doctor says he knows just the person to help him out. Ash comes into Karlyle\'s life just like that, and Karlyle finds himself thinking about Ash more and more. More than friends, but not quite lovers—how can we define this relationship?\n\n(Source: Lezhin Entertainment)', '2021-06-16', 'https://cdn.myanimelist.net/images/manga/3/288206l.jpg', 'Boys Love, Erotica', 'Manga'),
(518, 'Webtoon Character Na Kang Lim', 'Na Kang Lim, a high school student who enjoys reading webtoons, experiences a strange event one day when the female lead from his favorite webtoon appears before him. Even more surprising, the same incidents that put her in danger in the webtoon start happening in real life. The problem is, there\'s no protagonist in the real world to save her! Ultimately, Na Kang Lim takes on the role of the protagonist, looping through time to save her.\n\n(Source: Naver Corporation, translated)', '2021-05-04', 'https://cdn.myanimelist.net/images/manga/1/292948l.jpg', 'Comedy, Romance, Supernatural', 'Manga'),
(519, 'Chi. Chikyuu no Undou ni Tsuite', 'In fifteenth-century Europe, heretics are being burned at the stake. Rafal, a brilliant young man, is expected to enter university at an early age and study the era\'s most important field, theology. But Rafal values Reason above all else, which leads him both to the shocking conclusion that the Earth orbits the Sun, and into the hands of the Inquisition!\n\nA decade later, two members of the Watch Guild, the dour young Oczy and the cynical Gras, find a hidden stone chest that details the secrets of the universe Rafal left behind. Dare they try to change their own stars by selling the heretical texts, or would that only lead to the stake and the fire?\n\n(Source: Seven Seas Entertainment)', '2020-09-14', 'https://cdn.myanimelist.net/images/manga/2/246956l.jpg', 'Award Winning, Drama', 'Manga'),
(520, 'The Greatest Estate Developer', 'There is no bigger scum of the earth than Lloyd Frontera. He is the eldest son, yet all he does is drink and intimidate others, depleting what little is left of his family\'s wealth. The Fronteras\' knight, Javier Asrahan, is destined to become a renowned swordmaster, and Lloyd\'s family will face pitiful deaths as their entire land falls to ruin under insurmountable debt.\n\nThough at some point Kim Suho was an average civil engineering student in Korea, he suddenly wakes up on a dirt road as none other than Lloyd, an ungrateful hooligan from the beginning of a book following Javier, the protagonist. While a sassy status window offers some clarity about his new identity, Suho is rather worried about his imminent downfall.\n\nTo avoid becoming a beggar—and ultimately lead a sweet and comfortable life—Suho decides to fix Lloyd\'s scumbag image. With his engineering expertise and magical construction skills boost, Suho introduces modern innovations and city developments to this medieval-like world, drastically improving the people\'s quality of life—all for a nice sum of money.\n\n[Written by MAL Rewrite]', '2021-07-30', 'https://cdn.myanimelist.net/images/manga/1/290131l.jpg', 'Adventure, Comedy, Fantasy', 'Manga'),
(521, 'Hotaru no Yomeiri', 'Satoko, the eldest daughter of the honorable Kirigaya family, has received many marriage proposals from men captivated by her beauty and grace. However, she has turned them all down due to her secret heart defect. Despite her condition, Satoko is still willing to find a husband to ease her beloved father\'s concerns.\n\nWhile on a stroll, Satoko is kidnapped by a group of mercenaries, one of them being Shinpei Gotou—a legendary assassin tasked with executing her. Satoko tries to bribe Gotou into freeing her, but it proves unsuccessful. Out of options, Satoko makes a desperate gamble: under the pretense of love at first sight, she asks him to marry her.\n\nUnexpectedly, Gotou takes the bait and vows to protect her. As the couple escapes to freedom, Satoko struggles to keep up the ruse and make sense of the mysterious man she has eloped with.\n\n[Written by MAL Rewrite]', '2023-01-01', 'https://cdn.myanimelist.net/images/manga/3/283419l.jpg', 'Romance', 'Manga'),
(522, 'Gimai Seikatsu', 'When his father remarries, Yuuta Asamura winds up sharing a roof with a brand-new stepsister, who is also the hottest girl in his grade! But Yuuta and his new sister, Saki Ayase, have no delusions—they both carry trauma from their parents\' difficult divorces, and they agree to keep a respectful distance. As it turns out, however, the two have a lot in common, and slowly, cautiously, they grow closer. But is the emotion blooming between them simple admiration, familial love, or something more?\n\n(Source: Yen Press)', '2021-01-25', 'https://cdn.myanimelist.net/images/manga/2/240697l.jpg', 'Romance, Slice of Life', 'Manga'),
(523, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 0', 'This may be a story of the past that had been concealed, and mustn\'t be seen.\n\nAbout 20 years before Kiyotaka Ayanokouji enrolled at Advanced Nurturing High School. There was a man. Atsuomi Ayanokouji, aged 31. A politician. Atsuomi was born as a \"have-not\" in Japan\'s society of disparity, but there was one thing he possessed more than anybody else: his uncontrollable, ever-expanding \"ambition.\"\n\nAtsuomi had been doing dirty work for Jinnosuke Naoe, the head of the Naoe faction that he was a part of. As a chance to reward all the hard work that he had done, Naoe offers him a top-secret project: the founding of an institution for a \"Talented Persons Nurturing Program,\" which is under the direct control of the government. Atsuomi, who is busy pursuing his ambitions, brings them to fruition and names the institution he establishes the White Room. He had also started on another project: to get his own biological child to join him in the White Room.\n\nThis is the beginning of everything. A story about the \"dissection\" of Kiyotaka Ayanokouji. Within a cold white room, what does the future look like in the eyes of a young child?\n\n(Source: Kadokawa, translated)', '2022-12-23', 'https://cdn.myanimelist.net/images/manga/2/295562l.jpg', 'Drama', 'Manga'),
(524, 'Killer Crush', 'A killer must be prepared to put on the perfect act for their assassination to be successful. They must be exceptionally meticulous when erasing any trace of evidence, and they must absolutely never be caught. These are some of the simple rules that Joo Taeman has followed for 14 years, never allowing his emotions to interfere.\n\nMeanwhile, the famous actor Kang Dahyeok, nicknamed the \"Heart Assassin\" due to his attractive looks and dreamy eyes, is a huge fan of gritty film noirs. He has always dreamt of starring in something with an edge, but he keeps getting stuck with swoony romantic dramas. After witnessing Taeman\'s ability to effortlessly switch from a scowl to a smile, Dahyeok is determined to befriend him and learn the trick. However, Taeman falls for Dahyeok at first sight, facing a dangerous challenge: how to separate his high-risk profession and this deadly, killer crush!\n\n[Written by MAL Rewrite]', '2021-09-02', 'https://cdn.myanimelist.net/images/manga/2/299703l.jpg', 'Boys Love, Comedy', 'Manga'),
(525, 'Spy x Family', 'For the agent known as \"Twilight,\" no order is too tall if it is for the sake of peace. Operating as Westalis\' master spy, Twilight works tirelessly to prevent extremists from sparking a war with neighboring country Ostania. For his latest mission, he must investigate Ostanian politician Donovan Desmond by infiltrating his son\'s school: the prestigious Eden Academy. Thus, the agent faces the most difficult task of his career: get married, have a child, and play family.\n\nTwilight, or \"Loid Forger,\" quickly adopts the unassuming orphan Anya to play the role of a six-year-old daughter and prospective Eden Academy student. For a wife, he comes across Yor Briar, an absent-minded office worker who needs a pretend partner of her own to impress her friends. However, Loid is not the only one with a hidden nature. Yor moonlights as the lethal assassin \"Thorn Princess.\" For her, marrying Loid creates the perfect cover. Meanwhile, Anya is not the ordinary girl she appears to be; she is an esper, the product of secret experiments that allow her to read minds. Although she uncovers their true identities, Anya is thrilled that her new parents are cool secret agents! She would never tell them, of course. That would ruin the fun.\n\nUnder the guise of \"The Forgers,\" the spy, the assassin, and the esper must act as a family while carrying out their own agendas. Although these liars and misfits are only playing parts, they soon find that family is about far more than blood relations.\n\n[Written by MAL Rewrite]', '2019-03-25', 'https://cdn.myanimelist.net/images/manga/3/219741l.jpg', 'Action, Comedy', 'Manga'),
(526, 'Watashi no Oshi wa Akuyaku Reijou.: Revolution', 'Ordinary office worker Rei Oohashi wakes up in the body of the protagonist of her favorite otome game, Revolution. To her delight, the first person to greet her is also her favorite character, Claire Francois—the main antagonist of the story! Now, Rei is determined to romance Claire instead of the game\'s male leads. But how will her villainous ladylove react to this new courtship?!\n\n(Source: Seven Seas Entertainment)', '2021-12-18', 'https://cdn.myanimelist.net/images/manga/1/253475l.jpg', 'Comedy, Fantasy, Girls Love', 'Manga'),
(527, 'Kimi wa Houkago Insomnia', 'It all started with the death of one of the Astronomy Club\'s members. From this, the rumored ghost of the club came to life.\n\nGrumpy insomniac Ganta Nakami stumbles across the moderately rebellious yet easygoing Isaki Magari in the Astronomy Club\'s abandoned observatory. Magari is jolted awake and tries to escape from the scene, only to have a broken door prevent that, forcing the two inside. The two forge an unlikely friendship, leading them to use the observatory as a safe space for them to interact.\n\nKimi wa Houkago Insomnia follows the insomniacs Nakami and Magari\'s time in the starlit observatory as they help each other cope with insomnia and the lasting effects it has on student life.\n\n[Written by MAL Rewrite]', '2019-05-20', 'https://cdn.myanimelist.net/images/manga/2/221335l.jpg', 'Romance', 'Manga'),
(528, 'Mystical', 'Garam has always loved to draw, but his dreams of being an artist have been on hold ever since his mother passed away. Wanting to become more independent and focus on his art, he moves into his grandmother\'s empty house by the ocean. There, he meets his greatest muse: a mystical water creature with no memories of her past. Now it\'s up to Garam to help her uncover what she has forgotten.\n\n(Source: Webtoon Entertainment)', '2020-02-19', 'https://cdn.myanimelist.net/images/manga/2/244674l.jpg', 'Drama, Romance, Supernatural', 'Manga'),
(529, 'Sakamoto Days', 'Tarou Sakamoto was considered the greatest hitman of all time. Feared by many, he stood at the top of the underground world until he met and fell in love with a woman. As a result, Sakamoto abandoned his life of crime and now works as a convenience store clerk.\n\nLeaving his shady past behind proves more difficult than Sakamoto initially imagined. Many of his former rivals and partners do not believe that he has truly left the business and show up in hopes of taking him out. Barred from killing, Sakamoto must find creative ways to subdue his enemies and prevent them from bringing harm to his family, his store, and the small town he resides in.\n\n[Written by MAL Rewrite]', '2020-11-21', 'https://cdn.myanimelist.net/images/manga/1/242919l.jpg', 'Action, Comedy', 'Manga'),
(530, 'Yuki no Yousei', 'Haruki Homura lives in solitude in the snowy countryside of Hokkaido. Hiding all his emotions in his lonely heart, he can not help but detest the bleak, colorless world around him.\n\nOne day, Haruki meets the outgoing photographer Akihito Narumi, who came from Tokyo to capture the elusive snow fairies with his camera. With no place to stay amidst the snowy conditions, Haruki decides to let Narumi stay at his house for the winter. As the affable photographer cracks open his host\'s frozen heart, Haruki slowly warms up to the beauty of the world around him. Gradually developing a close bond, these polar opposites begin to dread the arrival of spring, as their time together will come to an end once the cold winter passes.\n\n[Written by MAL Rewrite]', '2021-07-16', 'https://cdn.myanimelist.net/images/manga/3/257952l.jpg', 'Boys Love', 'Manga'),
(531, 'Daytime Star', 'Hwang Yura has always dreamed of becoming a star. Unfortunately, luck does not seem to be on her side, as she has yet to land a major role despite making her debut seven years ago. Still, Yura continues to put her best foot forward and receives a role in a movie destined for success. Much to her dismay, she is once again cast in a minor role.\n\nOnce on set, Yura runs into two familiar faces—her narcissistic ex-boyfriend Kim Jeong-u and famous actor Kang Seunghyeon. While Yura promises herself to keep her head in the game despite Jeong-u\'s egotistical presence, the handsome Seunghyeon takes an interest in her due to the circumstances of their previous encounters. Through the strenuous filming, the unknown actress and the lead star form a unique relationship. All the while, Yura tackles the relentless challenges of the entertainment industry on her journey to stardom.\n\n[Written by MAL Rewrite]', '2021-06-25', 'https://cdn.myanimelist.net/images/manga/2/265157l.jpg', 'Romance', 'Manga'),
(532, 'Pink Heart Jam', 'Hailing from the countryside, Yuuki Haiga, an endearing and approachable freshman, quickly adapts to university life, easily making friends and winning the favor of girls. But senior Ryou Hanae is the only person that manages to leave Haiga awestruck: with his glorious long hair, stunning features, and incredible musical talent, Hanae finds a lasting spot in Haiga\'s mind.\n\nWhen Haiga loses a bet against his friends, he finds himself at a box spa—a secluded place that offers intimate same-sex services. Fostering lingering doubts about being bisexual, Haiga sees this as an opportunity to come to a definitive answer. However, in his nervous state, Haiga is unaware that he bought time with none other than his beautiful senior, Hanae.\n\nAll Haiga asks for is an honest conversation about sexual identity, but Hanae insists on a more hands-on approach. Unable to stay away, Haiga continues returning for more, but he must determine if his feelings are genuine love or merely admiration.\n\n[Written by MAL Rewrite]', '2020-08-25', 'https://cdn.myanimelist.net/images/manga/1/263201l.jpg', 'Boys Love, Erotica', 'Manga'),
(533, 'On the Way to Meet Mom', 'One day, after being discovered in an abandoned house by a rescue team, Mori suddenly finds himself in a children\'s protection center. Here, he begins to learn a new way of life—one that includes grand care packages sent by a mysterious patron. But when his closest friend is reunited with her mother and leaves the center, Mori learns for the first time the existence of a mother for every child, and decides to embark on a journey to find his own. But what sort of obstacles wait along the way?\n\n(Source: Webtoon Entertainment)', '2024-11-25', 'https://cdn.myanimelist.net/images/manga/3/318287l.jpg', 'Adventure, Fantasy', 'Manga'),
(534, 'Murderous Lewellyn\'s Candlelit Dinner', 'The apartment complex on the infamous Ira Street is a last resort for those fortunate enough to scrape together a few pennies. People deal with poverty and violence daily, and now a string of murders has solidified fear into their bones. Shavonne, an aspiring young writer, is no exception: he struggles to hold a job, his love life is in shambles, and it seems like he even has a stalker. But the bleakness of his days changes when he meets his next-door neighbor, Lewellyn.\n\nLewellyn is charming and undoubtedly handsome, but he is rather eccentric. Day after day, he sits on the staircase and peels onions, and his wealth is too suspicious for an Ira Street resident. Despite the warning signs, Shavonne accepts a dinner invitation from Lewellyn. However, during the candlelit dinner, Shavonne stumbles upon a mutilated corpse—later discovered as evidence of the Ira Street murderer\'s latest crime.\n\nAs Shavonne tiptoes around Lewellyn trying to save his own skin, strange things begin to happen, and he wonders if Lewellyn is his enemy or the only one truly on his side.\n\n[Written by MAL Rewrite]', '2020-06-25', 'https://cdn.myanimelist.net/images/manga/3/287569l.jpg', 'Boys Love, Suspense', 'Manga'),
(535, 'Omniscient Reader\'s Viewpoint', 'Kim Dokja does not consider himself the protagonist of his own life. Befitting the name his parents gave him, he is a solitary person whose sole hobby is reading web novels. For over a decade, he has lived vicariously through Yoo Joonghyuk, the main character of the web novel Three Ways to Survive the Apocalypse (TWSA). Through Joonghyuk, Dokja has experienced secondhand the trials of repeatedly regressing in time, in search of an end to life-threatening \"scenarios\" that force people to act out narratives for the amusement of god-like \"Constellations.\"\n\nAfter reading 3,149 chapters—long after all other readers lost interest—Dokja finally resigns himself to the story ending. However, he receives an enigmatic message from the author, stating that the story will soon be monetized, before his surroundings suddenly go dark. He swiftly realizes that fiction has become reality and he is now living through TWSA. Although he is the singular omniscient reader of the events yet to come, his success in the scenarios is not guaranteed—but perhaps his advantage will empower him to step into the protagonist role that never suited him before.\n\n[Written by MAL Rewrite]', '2020-05-26', 'https://cdn.myanimelist.net/images/manga/2/238873l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(536, 'Teito Seihai Kitan: Fate/type Redline', 'A remake of the comedy spin-off manga Koha-Ace GO: Teito Seihai Kitan.', '2019-12-20', 'https://cdn.myanimelist.net/images/manga/2/234884l.jpg', 'Action, Comedy, Fantasy, Supernatural', 'Manga'),
(537, 'Mayonaka Heart Tune', 'When Arisu Yamabuki was all alone in bed at night, he was able to find solace in the voice of a radio host who went by \"Apollo.\" However, one day, she simply stopped broadcasting without any explanation. Years then passed, and Arisu is now a second-year high-schooler. He makes it his mission to search for Apollo, as there is something he wants to tell her. He doesn\'t know what she looks like, or even what her real name is, but he manages to get some leads on her in his school\'s broadcasting club. That\'s where he meets four girls who all dream to get a job where they can make full use of their voices! Just who is Apollo, and how will those four\'s dreams pan out?\n\n(Source: Kodansha USA)', '2023-09-20', 'https://cdn.myanimelist.net/images/manga/1/293386l.jpg', 'Comedy, Romance', 'Manga'),
(538, 'Souyaku Toaru Majutsu no Index', 'As Christmas Eve approaches Academy City, an array of decorative festivities adorn the streets. While the rest of the city is getting into the merry mood, it seems gloom is all that Touma Kamijou experiences. After suffering from one misfortune after another, he encounters Mikoto Misaka escaping from the watchful eyes of Tokiwadai Middle School in an attempt to enjoy the Christmas atmosphere. The two agree on making the most out of this dreadful holiday; however, unbeknownst to them, a mysterious third party observes their every move.\n\nElsewhere, the newly instated Academy City Board Chairman initiates his first operation—a plan that will turn the entire city\'s framework upside down. Naturally, as he seeks to leave every stone unturned, previously hidden enemies begin to reveal themselves along with their malicious intents...\n\n[Written by MAL Rewrite]', '2020-02-07', 'https://cdn.myanimelist.net/images/manga/3/229100l.jpg', 'Action, Comedy, Fantasy, Sci-Fi, Supernatural', 'Manga'),
(539, 'Hirano to Kagiura', 'The diligent high school freshman Akira Kagiura and his senior Taiga Hirano have been roommates for half a year. Kagiura used to be anxious about his future dormitory life, but thanks to his energetic senior looking out for him, he has come to feel content and at ease. As he continues to rely on Hirano more and more each day, he develops strong feelings for his selfless friend. In the six months they have left as roommates, Kagiura is determined to put a name to the relationship he cherishes so dearly before it comes to an end.\n\n[Written by MAL Rewrite]', '2019-03-15', 'https://cdn.myanimelist.net/images/manga/2/221355l.jpg', 'Boys Love, Slice of Life', 'Manga'),
(540, 'Tsukuritai Onna to Tabetai Onna', 'Yuki Nomoto, although a complete amateur, enjoys cooking more than anything. The young office worker has big ambitions for the dishes she wants to create, but there is a recurring problem: she has no one to share her cooking with. Much like an artistic masterpiece that never sees the light of day, Nomoto feels her efforts are wasted and her options limited if she only cooks for herself.\n\nBy a stroke of luck, Nomoto bumps into Totoko Kasuga, her neighbor two doors down, who is carrying a feast of fast food to consume all by herself. Kasuga may be intimidating at first glance, but her love for food in large quantities is exactly what Nomoto needs to push her culinary skills to the next level. With each meal Nomoto prepares for Kasuga, the two women slowly begin to open up their lives and hearts to one another.\n\n[Written by MAL Rewrite]', '2021-01-08', 'https://cdn.myanimelist.net/images/manga/1/250171l.jpg', 'Girls Love, Slice of Life', 'Manga'),
(541, 'Nick to Lever', 'The wacky story of Nick and Lever, two foreign men living in Japan.', '2020-10-12', 'https://cdn.myanimelist.net/images/manga/1/282286l.jpg', 'Comedy', 'Manga'),
(542, 'Loop 7-kaime no Akuyaku Reijou wa, Moto Tekikoku de Jiyuu Kimama na Hanayome Seikatsu wo Mankitsu suru', 'Rishe, the daughter of a duke, is stuck in a time loop that begins at the moment her engagement is annulled and ends with her early demise at the age of 20. She has now begun her seventh loop. In her past do-overs, Rishe experienced various occupations, including being a merchant, a pharmacist, and a knight. But this time around, she simply wishes to live a long and leisurely life!\n\nThat was the plan, only for it to be derailed by an unprecedented marriage proposal from her killer in the previous loop, the neighboring country\'s Crown Prince—?!\n\n(Source: Overlap, translated)', '2020-10-25', 'https://cdn.myanimelist.net/images/manga/1/241432l.jpg', 'Fantasy, Romance', 'Manga'),
(543, 'Haruka Tooki Ie', 'In the winter of 1990, a young man named Alan finds himself lost and searching for direction. He currently cannot find it at home nor through the church. But when he meets Hayden, a free-spirited cook, he at least finds someone he can relate with. He may not know where his life is going but at least he has someone to lean on. But Alan\'s new life, filled with new feelings and many new challenging experiences, may force him to find his path on the road...\n\n(Source: Denpa)', '2020-09-19', 'https://cdn.myanimelist.net/images/manga/1/246458l.jpg', 'Boys Love, Drama', 'Manga'),
(544, 'Sensou Kyoushitsu', 'In Arboral Year 1294, the world is dominated by nine massive towers known as the Spires, remnants of an ancient civilization. Filled with lost secrets and powerful knowledge, nations struggle to possess them. Luca is a bugler in a mercenary company who wants nothing more than to leave the battlefield behind and become a true musician, a maestro. But marked as one of the enigmatic Branch-hexed, and gifted with the strange ability to see the sound of his instrument, Luca finds himself drawn reluctantly into a war of epic proportions!\n\n(Source: VIZ Media)', '2022-06-03', 'https://cdn.myanimelist.net/images/manga/1/267772l.jpg', 'Action, Fantasy', 'Manga'),
(545, 'Akuyaku Reijou no Naka no Hito: Danzai sareta Tenseisha no Tame Usotsuki Heroine ni Fukushuu Itashimasu', 'Although Emi Kobayashi is heartbroken over her own death, she realizes she has reincarnated as her favorite character from an otome game—the villainess Remilia Rosa Graupner. Emi is kind and generous by nature and therefore determined to give Remilia the life she deserves. Her warmth soon charms every key character, and she ensures Remilia\'s bright future. For a decade, Remilia has watched over Emi from the inside, satisfied as long as the tender-hearted Emi was happy herself.\n\nThe arrival of the protagonist, Pina Blanche, envelops Emi\'s world in darkness. From the beginning, Pina shows her true colors, resorting to underhanded methods to destroy Remilia\'s reputation until everyone turns against her. When despair overwhelms Emi, control over her body returns to Remilia. But Remilia is not so forgiving that she will simply let Pina have her way. She swears to take revenge and show everyone who wronged Emi the power of a true villainess.\n\n[Written by MAL Rewrite]', '2021-11-19', 'https://cdn.myanimelist.net/images/manga/2/263563l.jpg', 'Drama', 'Manga'),
(546, 'Mushoku Tensei: Dasoku-hen', 'Rudeus Greyrat has finally emerged victorious from the showdown at Biheiril Kingdom. With his hard-fought battle over, he can finally rest easy and put his adventuring days behind him. Yeah right! The epic fight may be done, but the story of the Jobless Reincarnation cast is far from over. There\'s still Norn\'s wedding, Lucie\'s first day at school, hunting down marriage partners for Dohga and Isolde, and then...is that Ghislaine?! Get ready for a bounty of antics and action from the Mushoku Tensei universe as the story continues!\n\n(Source: Seven Seas Entertainment)', '2023-06-23', 'https://cdn.myanimelist.net/images/manga/2/283797l.jpg', 'Fantasy, Slice of Life', 'Manga'),
(547, 'How to Win My Husband Over', 'To protect herself from her abusive adoptive family, an orphan mastered the act of being a gleeful and submissive daughter. When she dies in an accident, she believes that she is finally free. However, fate cannot be more cruel; she is reincarnated as Rudbeckia \"Ruby\" de Borgia, a minor villainess from a novel who grows up in a violent household and dies at the hands of her husband.\n\nRuby\'s father, the power-hungry pope, wishes to ruin the Britanya Kingdom by marrying Ruby off to Britanya\'s mightiest knight, Iske van Omerta, and having her poison his beloved sister, Elenia. But Ruby knows his plan will ultimately fail, and no member of the Borgias family will escape Iske\'s wrath and revenge alive. In order to prove her innocence when the time comes, Ruby must act as an oblivious and docile wife, for only by winning her husband over can she hope to survive.\n\n[Written by MAL Rewrite]', '2021-10-21', 'https://cdn.myanimelist.net/images/manga/2/283080l.jpg', 'Drama, Fantasy', 'Manga'),
(548, 'Love Bullet', 'Trading love\'s bows and arrows for firearms, these cupids are heart snipers.\n\nKoharu, an indecisive novice cupid, joins her senpais, who are full of individuality, in this romantic gun action series.\n\n(Source: Kadokawa, translated)', '2023-10-05', 'https://cdn.myanimelist.net/images/manga/3/307661l.jpg', 'Action, Drama, Girls Love, Supernatural', 'Manga'),
(549, 'Dandadan', 'After being aggressively rejected, Momo Ayase finds herself sulking when she stumbles across a boy being bullied. Saved by her rash kindness, the occult-obsessed boy attempts to speak to her about supernatural interests he believes they share. Rejecting his claims, Ayase proclaimed that she instead is a believer in ghosts, starting an argument between the two over which is real.\n\nIn a bet to determine who is correct, the two decide to separately visit locations associated with both the occult and the supernatural—Ayase visiting the former and the boy visiting the latter. When the two reach their respective places, it turns out that neither was wrong and that both the occult and ghosts do exist.\n\nThis marks the beginning of Ayase and the boy\'s adventure, as they attempt to fix the surreal, supernatural, and occult elements around them to return to a normal life.\n\n[Written by MAL Rewrite]', '2021-04-06', 'https://cdn.myanimelist.net/images/manga/2/248746l.jpg', 'Action, Comedy, Supernatural', 'Manga'),
(550, 'Myst, Might, Mayhem', 'Jeong, the Slaughtering Scythe Demon, feels joy in killing others. He happens to look just like Mok Gyeongwoon, the third young master of the Mok Sword Manor...\n\n\"Be my substitute, and I\'ll let you out of prison.\"\n\"That opportunity. Will you give it to me?\"\nCrack!!!\n\nHe kills the Third Young Master and decides to become the real one. Can the fake Mok Gyeongwoon survive as the real one? The serial killer begins his new life as the Third Young Master of the Great Mok Sword Manor.\n\n(Source: Naver Corporation, translated)', '2024-03-04', 'https://cdn.myanimelist.net/images/manga/3/300118l.jpg', 'Action, Fantasy', 'Manga'),
(551, 'Veil', 'Entirely in color, this manga is a representation of small moments of life between the two protagonists, a police officer and a woman who ran away from home.', '2019-11-15', 'https://cdn.myanimelist.net/images/manga/1/239756l.jpg', 'Romance, Slice of Life', 'Manga'),
(552, '[Oshi no Ko]', 'Sixteen-year-old Ai Hoshino is a talented and beautiful idol who is adored by her fans. She is the personification of a pure, young maiden. But all that glitters is not gold.\n\nGorou Amemiya is a countryside gynecologist and a big fan of Ai. So when the pregnant idol shows up at his hospital, he is beyond bewildered. Gorou promises her a safe delivery. Little does he know, an encounter with a mysterious figure would result in his untimely death—or so he thought.\n\nOpening his eyes in the lap of his beloved idol, Gorou finds that he has been reborn as Aquamarine Hoshino—Ai\'s newborn son! With his world turned upside down, Gorou soon learns that the world of showbiz is paved with thorns, where talent does not always beget success. Will he manage to protect Ai\'s smile that he loves so much with the help of an eccentric and unexpected ally?\n\n[Written by MAL Rewrite]', '2020-04-23', 'https://cdn.myanimelist.net/images/manga/3/233991l.jpg', 'Drama, Supernatural', 'Manga'),
(553, 'The Extra\'s Academy Survival Guide', 'Ed Rothstaylor is a third-rate villain in a game, disowned by his family and kicked out of the dormitory for his misdeeds. One day, our main character wakes up as this very Ed, and realizes he must earn a scholarship so he can graduate and be set for life. Now living in the woods, he resolves to keep away from the protagonists, but four of the female leads just won\'t leave him alone. Not only that, his presence starts to change the timeline and events of the game! Can Ed help the story progress while staying out of the limelight?\n\n(Source: Webtoon Entertainment)', '2023-12-28', 'https://cdn.myanimelist.net/images/manga/2/296379l.jpg', 'Action, Fantasy', 'Manga'),
(554, 'Medalist', 'Becoming an ice dancer was not what Tsukasa Akeuraji had aimed for when he decided to take on the figure skating world. However, it is where he ended up, as he \"started too late\" to follow his true solo-skating dreams.\n\nFor years, he was content with being a shell of his former ambitions—that is, until he met a little girl in whom he saw himself. Inori Yuitsuka, a fifth-grader so desperate to skate that she practiced in secret, had visited Tsukasa\'s rink with her mother to ask for lessons. She was branded as useless by everyone around her, told it was \"too late\" for her to begin, and that catching up to other skaters was impossible.\n\nWith a newfound conviction and unwillingness to let another passionate skater go down the same road as him, Tsukasa takes on the responsibility of coaching her and promises to make Inori a medalist.\n\n[Written by MAL Rewrite]', '2020-05-25', 'https://cdn.myanimelist.net/images/manga/3/235204l.jpg', 'Award Winning, Drama, Sports', 'Manga'),
(555, 'Pick Me Up', 'In a mobile gacha game infamous for its atrocious difficulty, the master ranked 5th in the world, Loki, loses consciousness while raiding the dungeon.\n\n\"What? I\'m a game character now?\" After waking up, Loki realizes he has turned into a level 1, 1-star hero—Han Yslat. To return to Earth, he must lead the newbie master and heroes and clear the 100th floor of the dungeon! \"You messed with the wrong guy.\" This is the story of hard carrying by master Loki who never accepts even a single defeat.\n\n(Source: Kakao Entertainment Corp., translated)', '2022-12-28', 'https://cdn.myanimelist.net/images/manga/1/274166l.jpg', 'Action, Fantasy', 'Manga'),
(556, 'Natsu e no Tunnel, Sayonara no Deguchi', 'There is a strange rumor surrounding the Urashima Tunnel: it grants the wish of those who enter at the cost of their lifespan. Kaoru Touno did not think much of this silly urban legend until he stumbled across a dark tunnel one night.\n\nInitially dismissing the idea of going in, Kaoru is enticed by the possibility of bringing back his sister, Karen. Karen had died in an accident five years prior as a result of Kaoru\'s carelessness. As he enters the tunnel, what Kaoru discovers within is not quite the same as the rumors imply. The rules of the tunnel are uncertain, but that does not stop him from testing the waters.\n\nUnbeknownst to Kaoru, his aloof classmate Anzu Hanashiro follows him on one of his expeditions. Much to his reluctance, she is intrigued by the tunnel and wants to team up with him. Although he is wary of her intentions, Kaoru accepts Anzu\'s offer and spends the summer with her in hopes of reviving his sister.\n\n[Written by MAL Rewrite]', '2019-07-18', 'https://cdn.myanimelist.net/images/manga/1/247761l.jpg', 'Drama, Mystery, Sci-Fi', 'Manga'),
(557, 'Konjiki no Gash!! 2', '100 demon children fought to determine the new king of the demon world. Once the war ended, the new king was crowned, and the demon world was at peace... or so you thought! The shocking reality of the current-day demon world is now revealed—and deep in the maw of despair, three demon children make a dangerous gambit.\n\n(Source: Birgdin Board, translated)', '2022-03-14', 'https://cdn.myanimelist.net/images/manga/2/269154l.jpg', 'Action, Adventure, Comedy, Supernatural', 'Manga'),
(558, 'SSS-Class Revival Hunter', 'After the Tower suddenly appeared, individuals who wished to pursue their personal values began to inhabit it, coming to be called \"hunters.\" Everyone had their own goals, but only a chosen few were acknowledged and given powerful skills by the mysterious structure. Kim Gong-Ja, a weak F-Class hunter without any skills, is envious of those who were blessed by the Tower. Letting his jealousy overcome him one day, Gong-Ja abruptly receives a S-Class skill that allows him to copy a skill from someone else—after they kill him.\n\nSooner than he likes, Gong-Ja gets to test his newly acquired ability on the legendary hunter known as the Flame Emperor. As he is dying, Gong-Ja learns the evil truth about the man he once admired the most. Receiving another potent skill that allows him to revive and go back in time by 24 hours, Gong-Ja devises a plan to travel 11 years into the past to eliminate the Flame Emperor and cement himself as the world\'s best hunter.\n\n[Written by MAL Rewrite]', '2020-12-31', 'https://cdn.myanimelist.net/images/manga/1/263446l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(559, 'Houkago Kitaku Biyori', 'Shun is invited to join the Going-Home Club by Naoki Satou (aka Naoki-chan). Despite trying to refuse, he is strong-armed into accepting the invitation! This is a romantic comedy about a girl who can\'t help but take detours and a boy looking for purpose in life.\n\n(Source: Futabasha, translated)', '2023-08-01', 'https://cdn.myanimelist.net/images/manga/1/295999l.jpg', 'Romance', 'Manga'),
(560, 'Super no Ura de Yani Suu Futari', 'The sole thing that gets the middle-aged Sasaki through his soul-sucking job is a cheerful smile from Yamada—the young woman who works at a nearby 24-hour supermarket he frequents. After every tiring day of getting berated by his boss, Sasaki stops by the store to have his spirit healed by his favorite cashier.\n\nAfter a particularly grueling day, Sasaki shows up at the supermarket, only to find that Yamada\'s shift has already ended. Disappointed, he searches for a place to smoke when a woman from behind the store calls him over to join her. The bold and dangerously playful Tayama is quick to call out Sasaki\'s peculiar habit of always seeking out her coworker—even going as far as telling Yamada about Sasaki\'s vested interest in her.\n\nNow, in addition to seeing his adored cashier Yamada, Sasaki also visits the store to see if his new smoking partner Tayama is around. But there is more to Tayama\'s mischievousness than she initially lets on. With every cigarette, an unlikely friendship begins to blossom.\n\n[Written by MAL Rewrite]', '2022-08-25', 'https://cdn.myanimelist.net/images/manga/3/267255l.jpg', 'Romance', 'Manga'),
(561, 'Tian Guan Cifu', '800 years ago, Xie Lian was a pure-blooded and noble Crown Prince, a well-regarded child of Heaven with unlimited potential. But who knew that, after he ascended and became a god with tens of thousands of worshippers, his fate would take such a sharp downhill turn? He was demoted again and again, and fell to rock bottom.\n\n800 years later, Xie Lian ascended again, but this time, without worshippers and without incense. One day, after returning from collecting scraps, he took a mysterious young man home. And this young man was the Ghost King that made others pale in fear whenever discussed—Hua Cheng.\n\n(Source: Bilibili Comics)', '2019-10-19', 'https://cdn.myanimelist.net/images/manga/2/258222l.jpg', 'Action, Adventure, Boys Love, Drama, Fantasy', 'Manga'),
(562, 'Tian Guan Cifu', 'Born the crown prince of a prosperous kingdom, Xie Lian was renowned for his beauty, strength, and purity. His years of dedication and noble deeds allowed him to ascend to godhood. But those who rise, can also fall...and fall he does, cast from the Heavens again and again and banished to the mortal realm.\n\nEight hundred years after his mortal life, Xie Lian has ascended to godhood for the third time. Now only a lowly scrap collector, he is dispatched to wander the earthly realm to take on tasks appointed by the heavens to pay back debts and maintain his divinity. Aided by old friends and foes alike, and graced with the company of a mysterious young man with whom he feels an instant connection, Xie Lian must confront the horrors of his past in order to dispel the curse of his present.\n\n(Source: Seven Seas Entertainment)', '2021-02-04', 'https://cdn.myanimelist.net/images/manga/3/258775l.jpg', 'Action, Adventure, Boys Love, Fantasy', 'Manga'),
(563, 'Our Secret Alliance', 'While Kim Jaeha and Yun Se-i were childhood friends, they started to drift apart as they grew older. Due to strict parents who set extreme restrictions, the two have formed a secret alliance where they act like best friends in front of their parents, but become total strangers when out of their sight. Nonetheless, Jaeha secretly harbors feelings for Se-i.\n\nSoon, Jaeha and Se-i face difficulties when Se-i\'s mother asks them to perform a song together as a couple at her second wedding. The pair hesitantly decides to humor the request, only to end up in more complicated situations. However, all of these troubles are advantageous to Jaeha as he tries to make Se-i reciprocate his feelings.\n\n[Written by MAL Rewrite]', '2022-01-18', 'https://cdn.myanimelist.net/images/manga/3/297993l.jpg', 'Romance', 'Manga'),
(564, 'Therapy Game: Restart', 'Shizuma and Minato are officially a couple. But Shizuma—now a resident veterinarian—is so busy he barely has time to catch his breath, let alone go on a date. When he finally manages to find time for Minato, the universe intervenes once again, and he learns quickly that his feisty new beau is not to be ignored!\n\n(Source: SuBLime)', '2019-10-12', 'https://cdn.myanimelist.net/images/manga/2/239827l.jpg', 'Boys Love, Erotica', 'Manga'),
(565, 'Kimi to Tsuzuru Utakata', 'The self-conscious Shizuku Hoshikawa is on her way to dispose of her first and last novel. But before she can do so, the charismatic Kaori Asaka bumps into her and ends up taking the novel home. This turn of events greatly distresses Shizuku, as she does not want anyone to read the depressing story she wrote for her own satisfaction.\n\nInitially expecting the worst, Shizuku finds herself in tears of joy when Kaori tells her the novel deeply moved her. Kaori wishes to read more of her stories, but as Shizuku did not plan on writing anything else, she has no idea what to write. As a result, Kaori comes up with a bizarre suggestion—their love.\n\nShizuku is skeptical of Kaori\'s intention and somewhat uneasy about what secrets she may be hiding behind her smile. Nevertheless, the two begin their odd summer vacation in pursuit of their own love story.\n\n[Written by MAL Rewrite]', '2020-05-18', 'https://cdn.myanimelist.net/images/manga/1/239675l.jpg', 'Girls Love', 'Manga'),
(566, 'Make Heroine ga Oosugiru!', 'Plain, boring, and friendless Kazuhiko Nukumizu has witnessed something completely baffling: popular girl Anna Yanami was friend-zoned by her childhood friend and crush! In fact, all the popular girls around him are getting similarly rejected by the boys they like. Without realizing it, Kazuhiko becomes entangled in the relationship drama where all the leading heroines are losing out on love! Can he keep their spirits up and help them find happiness?\n\n(Source: Seven Seas Entertainment)', '2021-07-21', 'https://cdn.myanimelist.net/images/manga/2/248592l.jpg', 'Comedy, Romance', 'Manga'),
(567, 'Kinou no Haru de, Kimi wo Matsu', 'Two years ago, high schooler Kanae left his small island community of Sodeshima to pursue his academic dreams in Tokyo. When that life falls short of his expectations, he runs away from home to return to Sodeshima and his childhood friend, Akari. But before they can rekindle their old feelings for each other, the clock strikes six and Kanae finds himself inexplicably thrust forward four days into the future. Worse, he learns that Akito, Akari\'s older brother—and Kanae\'s childhood hero—is dead.\n\nExcept death might not be the end for Akito. As Kanae tries to fill in the four-day gap of his memories, Akari explains: he\'s about to relive those four days in reverse order in a phenomenon known as \"Rollback.\" Kanae himself explained it to her...in a past he hasn\'t yet experienced. Armed with this new knowledge, Kanae is determined to leverage Rollback however he can to save Akito\'s life—and Akari\'s heart.\n\n(Source: Seven Seas Entertainment)', '2020-04-17', 'https://cdn.myanimelist.net/images/manga/2/264712l.jpg', 'Mystery, Romance, Supernatural', 'Manga'),
(568, 'Guimi Zhi Zhu', 'With the rising tide of steam power and machinery, who can come close to being a Beyonder? Shrouded in the fog of history and darkness, who or what is the lurking evil that murmurs into our ears?\n\nWaking up to be faced with a string of mysteries, Zhou Mingrui finds himself reincarnated as Klein Moretti in an alternate Victorian era world where he sees a world filled with machinery, cannons, dreadnoughts, airships, difference machines, as well as Potions, Divination, Hexes, Tarot Cards, Sealed Artifacts...\n\nThe Light continues to shine but mystery has never gone far. Follow Klein as he finds himself entangled with the Churches of the world—both orthodox and unorthodox—while he slowly develops newfound powers thanks to the Beyonder potions.\n\nLike the corresponding tarot card, The Fool, which is numbered 0—a number of unlimited potential—this is the legend of \"The Fool.\"\n\n(Source: Webnovel)', '2020-05-01', 'https://cdn.myanimelist.net/images/manga/2/287344l.jpg', 'Action, Mystery, Supernatural, Suspense', 'Manga'),
(569, 'Sasayaku You ni Koi wo Utau', 'Yori Asanagi is a mature girl in many ways but is still pure when it comes to romance. That sentiment is proven when an underclassman, Himari Kino, suddenly confesses love to her after her band performance at the freshman opening ceremony.\n\nConfused and surprised, Yori asks her friends for consultation, but they tease her by saying that she is experiencing love. Yori soon makes up her mind and tries to return Himari\'s feelings, but in a twist of events, she realizes that what Himari loved was not her, but her music!\n\n[Written by MAL Rewrite]', '2019-02-18', 'https://cdn.myanimelist.net/images/manga/1/219489l.jpg', 'Girls Love', 'Manga'),
(570, 'Natsu e no Tunnel, Sayonara no Deguchi: Gunjou', 'Kaoru Tono heard a rumor: The laws of space and time mean nothing to the Urashima Tunnel. If you find it, walk through and you\'ll find your heart\'s desire on the other side...in exchange for years of your own life. On the night Kaoru just so happens to find himself standing in front of a tunnel that looks suspiciously like the one the rumor describes, he finds himself thinking of Karen, the sister he lost in an accident five years ago. To Kaoru\'s surprise, he\'s been followed by the new transfer student Anzu Hanaki, who promises to help him experiment with the mysterious tunnel—but what does she want from Kaoru in exchange? And what will he have left to give, after the tunnel\'s done with him?\n\n(Source: Seven Seas Entertainment)', '2020-07-11', 'https://cdn.myanimelist.net/images/manga/2/247760l.jpg', 'Drama, Mystery, Sci-Fi', 'Manga'),
(571, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e: 2-nensei-hen', 'As Kiyotaka Ayanokouji and his classmates begin their second-year life, changes are seen everywhere throughout Tokyo Metropolitan Advanced Nurturing High School. With the third-years having graduated and incoming first-years entering the school, alliances are well underway. Additionally, now that Miyabi Nagumo is the student council president, the promise of turning the school into a meritocracy may become a reality.\n\nMeanwhile, conflicts between classes continue to build as the class point totals draw close. With another special exam looming ahead, will Ayanokouji remain in the shadows, or will he finally enter the spotlight and help his class rise to the illustrious Class A?\n\n[Written by MAL Rewrite]', '2020-01-24', 'https://cdn.myanimelist.net/images/manga/3/235363l.jpg', 'Drama', 'Manga'),
(572, 'Imaizumin Chi wa Douyara Gal no Tamariba ni Natteru Rashii', 'Some gyarus have decided to use Imaizumi\'s house as a gathering spot to play video games and eat snacks. When Reina gets bored with video games, she sets her sights on another toy in the house: Imaizumi himself...\n\n(Source: Irodori Comics)', '2019-08-11', 'https://cdn.myanimelist.net/images/manga/1/242797l.jpg', 'Hentai', 'Manga');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(573, 'A Stepmother\'s Märchen', 'It is a mystery why the late Marquess Johannes von Neuschwanstein decided to marry a 16-year-old girl barely older than his eldest child. Whatever the reason, Shuli is left to shoulder heavy responsibilities as marchioness after his death. On top of the responsibility to manage a prestigious household with close ties to the empire\'s royal family, she becomes stepmother to four children who deeply mistrust her.\n\nFor seven years, Shuli dedicates herself to raising the children well and safeguarding the family fortune. She believes she only has to wait until her son Jeremy will take over as head of the family—then she can live freely. However, on the long-awaited day of his wedding, she is caught up in a tragic accident.\n\nWhen Shuli next opens her eyes, she finds herself in the past, hours before Johannes\' funeral. Although uncertain why she has been granted a second chance at life, this time she is determined to build relationships with the children as well as allow for her own happiness.\n\n[Written by MAL Rewrite]', '2019-07-04', 'https://cdn.myanimelist.net/images/manga/2/236778l.jpg', 'Drama, Fantasy, Romance', 'Manga'),
(574, 'Sousou no Frieren', 'The Demon King has been defeated, and the victorious hero party returns home before disbanding. The four—mage Frieren, hero Himmel, priest Heiter, and warrior Eisen—reminisce about their decade-long journey as the moment to bid each other farewell arrives. But the passing of time is different for elves, thus Frieren witnesses her companions slowly pass away one by one.\n\nBefore his death, Heiter manages to foist a young human apprentice called Fern onto Frieren. Driven by the elf\'s passion for collecting a myriad of magic spells, the pair embarks on a seemingly aimless journey, revisiting the places that the heroes of yore had visited. Along their travels, Frieren slowly confronts her regrets of missed opportunities to form deeper bonds with her now-deceased comrades.\n\n[Written by MAL Rewrite]', '2020-04-28', 'https://cdn.myanimelist.net/images/manga/3/232121l.jpg', 'Adventure, Award Winning, Drama, Fantasy', 'Manga'),
(575, 'Seasons of Blossom', 'Oh, to be young and in love. Oh, to be wild and carefree. The springtime of life is intense, tumultuous, and at times, oh so confusing. Spring, summer, fall and winter—love blossoms in all seasons.\n\n(Source: Webtoon Entertainment)', '2020-06-24', 'https://cdn.myanimelist.net/images/manga/3/257932l.jpg', 'Romance', 'Manga'),
(576, 'Surviving Romance', 'Sighs of awe follow Eun Chaerin wherever she goes, as expected for the perfect protagonist of a run-of-the-mill romance novel. She was once the novel\'s reader in the real world, and now she has the opportunity to live it herself and have her storybook ending with the male lead, Yu Jeha. But everything goes south on the day Jeha is supposed to confess his feelings, for he turns into a disfigured zombie and bites Chaerin.\n\nInstead of dying, Chaerin is forced to relive the same day, trapped in the loop of a bizarre zombie outbreak, unable to save Jeha. She desperately clings to him, as he is the only person she can see—all the background characters appear as nothing more than dark silhouettes to her. After almost four hundred repetitions, something unprecedented happens: a formless classmate pulls Chaerin to safety, and she catches a glimpse of their true appearance before dying again.\n\nThe possibility of unlocking and revealing the extra characters fills Chaerin with new vigor. If she forgets about saving Jeha and focuses on finding this unknown extra in her next regression, she may be able to reach her happy ending after all.\n\n[Written by MAL Rewrite]', '2021-01-14', 'https://cdn.myanimelist.net/images/manga/2/270717l.jpg', 'Horror, Suspense', 'Manga'),
(577, 'Kieta Hatsukoi', 'A heated rooftop confession takes place between two men, but not all is as it seems. The good-natured Souta Aoki has had his heart stolen by the angelic smile and kind actions of his female crush, Mio Hashimoto. Unfortunately, he is devastated when she lends him an eraser with another classmate\'s name—Ida—engraved on top. When Kousuke Ida spots his name on the eraser, he is led to believe that Aoki is the one harboring romantic feelings for him. Aoki is left struggling to clear up the situation alone without revealing Hashimoto\'s feelings for Ida. Fake and honest pinings mix as misunderstandings abound in this heart-pounding triangle of first loves.\n\n[Written by MAL Rewrite]', '2019-06-13', 'https://cdn.myanimelist.net/images/manga/2/235088l.jpg', 'Award Winning, Boys Love, Comedy, Romance', 'Manga'),
(578, 'Hikaru ga Shinda Natsu', 'Best friends Yoshiki and Hikaru have been stuck together like glue for most of their lives. Living in a small village and being the only children their age, the two boys find solace in each other\'s company. Their friendship seems picturesque at first glance, but Yoshiki has noticed a shift in Hikaru\'s demeanor ever since one fateful summer.\n\nThe \"Hikaru\" that sits beside him now is nothing like his friend. Despite his physical appearance and memories remaining exactly the same, Yoshiki knows something is amiss and that the Hikaru he once knew is gone. When he brings this up, Hikaru partially transforms into an otherworldly being, threatening to kill Yoshiki if he cannot accept it—while also professing its love for him.\n\nWracked with grief and unable to let go of his best friend, Yoshiki struggles to move on with his life as he finds himself getting closer to the new Hikaru. At the same time, strange occurrences begin to plague their village, bringing unsettling chaos.\n\n[Written by MAL Rewrite]', '2021-08-31', 'https://cdn.myanimelist.net/images/manga/2/256448l.jpg', 'Horror, Mystery, Supernatural', 'Manga'),
(579, 'Our Sunny Days', 'Sung Ho\'s not the kind you\'d typically expect to settle down in the countryside. He\'s in his late 20s, ex-military, and...a single father with a year-old baby his ex-girlfriend pawned off on him. Jobless and without any prospects but a house, Sung Ho hopes the peaceful Nuldongmae village will make a good new home for him and his daughter. Rumor has it that the head of the village, despite his young age, is a real jerk... But he won\'t have to deal with that, will he? But on the very day he moves in, Sung Ho clashes with a tall, good-looking guy who\'s got quite the temper and accuses Sung Ho of stealing from his store. This new guy really gets on his nerves, but he does seem to know a lot about the village... Sung Ho\'s always been a bit of a lone ranger wherever he goes, so will he be able to let someone else in his life for sunny days up ahead?\n\n(Source: Lezhin Entertainment)', '2023-08-16', 'https://cdn.myanimelist.net/images/manga/1/309563l.jpg', 'Boys Love, Slice of Life, Erotica', 'Manga'),
(580, 'JoJo no Kimyou na Bouken Part 9: The JoJoLands', 'On the Hawaiian Islands, siblings Dragona and Jodio Joestar commit petty crimes to provide aid for their ailing mother Barbara Ann. Under the orders of Meryl May Qi, both a crime lord and their high school principal, the siblings work alongside fellow teenagers Usagi Alohaoe and Paco Laburantes. Together, the gang engages in outright robbery, fraudulent activity, and other schemes to rip off unsuspecting tourists and civilians.\n\nFifteen-year-old Jodio admires his older brother\'s strong sense of identity and his mother\'s incredible work ethic, but there is a darkness within him, one characterized by violent outbursts that he carries out with a cold stoicism. Diagnosed as a sociopath, Jodio is quick to brutalize those who threaten his loved ones. His one objective is to make money by any means necessary, both to support his family and to become filthy rich in his own right.\n\nOn one particular heist, the gang robs manga artist Rohan Kishibe of a seemingly ordinary lava rock. However, they soon find that the rock draws any object of high value that it touches to its wielder, no matter the distance or bizarre chain of circumstances it takes to get there. With this new power in hand, Jodio and his allies set out to become wealthier than they ever dreamed possible.\n\n[Written by MAL Rewrite]', '2023-02-17', 'https://cdn.myanimelist.net/images/manga/1/286969l.jpg', 'Action, Adventure, Supernatural', 'Manga'),
(581, 'Telework Yotabanashi', 'Amidst a pandemic, system engineer Nokoru Mitsuhashi is ordered to telework. Spending far more time at home than he knows what to do with, he eventually meets Natsu Izumi, an archeology grad student living next door. While adjusting to life during the lockdown, Nokoru discovers newfound emotions as he navigates his relationship with Natsu, who—unbeknownst to him—is his future wife!\n\n[Written by MAL Rewrite]', '2020-08-02', 'https://cdn.myanimelist.net/images/manga/3/282072l.jpg', 'Romance', 'Manga'),
(582, 'Nano Machine', 'Nanotechnology meets martial arts at the Mashin Academy. Yeo-un\'s mother may not be one of the High Priest\'s six official wives, but his father\'s blood still qualifies him for a chance at the position of Minor Priest. Will a mysterious nanomachine injection from a future descendent help Yeo-un in this fierce competition against his powerful half-siblings?\n\n(Source: Webtoon Entertainment)', '2020-06-10', 'https://cdn.myanimelist.net/images/manga/1/312579l.jpg', 'Action, Adventure, Fantasy, Sci-Fi', 'Manga'),
(583, 'Look Back', 'Fourth grader Ayumu Fujino regularly draws four-panel manga for her school newspaper and is lauded as having the best artwork in her class. One day, she is asked by her teacher to turn over one of her manga slots in the school newspaper to a truant student named Kyomoto. When Kyomoto\'s manga pops up alongside Fujino\'s, it receives high praise for its detailed artwork, making Fujino furiously jealous.\n\nRefusing to be beaten by someone who barely attends school, Fujino devotes herself to learning to create manga. As time goes on though, her goal of outshining Kyomoto seems to only get further and further away; and Fujino, now in sixth grade, eventually gives up and quits making manga.\n\nGraduation day arrives, and Fujino is asked to deliver Kyomoto\'s graduation certificate to her. Through chance, the two end up coming face to face, and their unexpected meeting will end up having consequences far beyond what either of them could ever predict.\n\n[Written by MAL Rewrite]', '2021-07-19', 'https://cdn.myanimelist.net/images/manga/3/249833l.jpg', 'Drama', 'Manga'),
(584, 'I Love Amy', 'Bibi is a bubbly girl who\'s deeply obsessed with Peter, the cutest boy at her high school. So when she sees a random girl talking to him, Bibi invites her to a sleepover with malicious intent... only to have a surprisingly nice time! That\'s how she makes friends with Amy, a shy and sweet girl who agrees to help Bibi get with Peter. But as they cook up all sorts of love schemes to win Peter over, Amy\'s place in Bibi\'s heart grows bigger and bigger by the day...\n\n(Source: Tappytoon)', '2022-01-26', 'https://cdn.myanimelist.net/images/manga/2/311477l.jpg', 'Drama, Girls Love', 'Manga'),
(585, 'Muse on Fame', 'Meet Myeong, a struggling actress who spends her days auditioning for small roles and cleaning houses on the side to make ends meet. She\'s always had a burning passion for acting, but the road to stardom has been anything but easy. Despite her relentless efforts, Myeong remains relatively unknown in the industry.\n\nIronically, Myeong\'s name means fame, which only adds to the frustration of her current situation. But one day, while wandering through the city, she stumbles upon a photo exhibition featuring stunning images of her younger self, captured by a mysterious photographer.\n\nAs she gazes at the pictures, Myeong is transported back to a time when she was filled with hope and optimism. Seeing herself through the lens of another\'s perspective ignites a new fire within her. Could this photographer be the key to unlocking her potential and finally achieving the fame she was destined for?\n\nWith newfound determination, Myeong sets out to find the photographer and learn more about the person behind the camera. As they begin to collaborate, sparks fly and Myeong begins to see herself in a whole new light. Will she be able to capture the attention of the industry as this photographer\'s muse? Only time will tell, but Myeong is ready to take on the challenge and prove that she\'s meant for greatness.', '2022-10-19', 'https://cdn.myanimelist.net/images/manga/2/279732l.jpg', 'Drama', 'Manga'),
(586, 'Return of the Blossoming Blade', 'When Cheongmyeong of the Mount Hua Sect awakens a hundred years in the future, his last memories are of a bloody battle against the Leader of the Demonic Cult, the evil Cheonma. The battle almost saw the end of the Ten Great Sects of ancient China, when Cheongmyeong ended the hard-fought struggle by striking down Cheonma. Soon after, he succumbed to his wounds, filled with regret at their pyrrhic victory. All is not lost, however, as he awakens to his second chance at life. Shocked to find his beloved Mount Hua Sect reduced to a mere shadow of itself in the present day, Cheongmyeong embarks on a journey to restore Mount Hua to its former glory.\n\n(Source: Webtoon Entertainment)', '2021-03-23', 'https://cdn.myanimelist.net/images/manga/2/275074l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(587, 'Villains Are Destined to Die', 'The latest otome game is all the rage recently, so a regular university student decides to see for herself if its fame is well-deserved. She clears the normal mode in no time and finds herself pitying the villainess, Penelope Eckhart. Penelope is a fake―a replacement for the duke\'s missing daughter, the protagonist of the game.\n\nInitially confident about clearing the hard mode as well, the woman is shocked by the sheer leap in the level of difficulty, eventually passing out from exhaustion. However, when she wakes up, she no longer recognizes her surroundings, for she has been reincarnated into the body of the villainess!\n\nIn a world where everyone seems to be out for her blood, Penelope must make wise decisions that keep her away from the death route. A tyrant prince, a suspicious magician, a nobleman from a fallen nation, or one of her nasty adoptive brothers―whose affections will she win?\n\n[Written by MAL Rewrite]', '2020-05-01', 'https://cdn.myanimelist.net/images/manga/5/303096l.jpg', 'Drama, Fantasy, Romance', 'Manga'),
(588, 'Virtual Strangers', 'After a stalking incident, Yoon Ji-gu has become understandably wary of strangers. So when an odd man moves in next door, he immediately suspects the worst. Little does he know, Yeowoon is just a regular guy trying to land a job and enjoy his free time—until he finds himself dealing with a hostile neighbor. As their real-life misunderstandings escalate, the two unknowingly team up in their favorite online game, forming an unexpected duo. \n\n(Source: Lezhin Entertainment)', '2023-06-13', 'https://cdn.myanimelist.net/images/manga/1/319543l.jpg', 'Boys Love, Comedy', 'Manga'),
(589, 'Re:Zero kara Hajimeru Isekai Seikatsu: Dai-4 Shou - Seiiki to Gouyoku no Majo', 'On to the next stage: the witch\'s tomb known as the Sanctuary-Determined to release Rem from a mysterious slumber, Subaru and Emilia return to Roswaal\'s manor in search of clues on how to reach the Sanctuary, the secret location to which Ram and Roswaal escaped. But the way there is fraught with the unexpected-especially for Subaru, who finds himself in the company of a curious figure. A new chapter begins, and with it, a new adventure...\n\n(Source: Yen Press)', '2019-09-27', 'https://cdn.myanimelist.net/images/manga/2/227408l.jpg', 'Drama, Fantasy, Suspense', 'Manga'),
(590, 'Kaoru Hana wa Rin to Saku', 'Despite being adjacent to one another, Chidori Public High School and the all-girls Kikyo Private Academy seem to exist in two different worlds. While the latter boasts an immaculate reputation and favors students from wealthy backgrounds, the former is a nest for dim-witted delinquents. Everyone at Kikyo harbors a deep hatred for their Chidori neighbors.\n\nSixteen-year-old Rintarou Tsumugi is a student at Chidori whose intimidating face leads people to avoid him. Rintarou pays no mind to this, as he is content with his group of friends. However, there is something he has not told them yet: sometimes, he helps out at his family\'s cake shop.\n\nOne day at work, Rintarou sees a customer at a table, but she runs off before he can talk to her. The next day, he receives an apology from the girl, Kaoruko Waguri, who explains that she did not run away because of his appearance and that she believes Rintarou is a kind-hearted person. Although he is not used to Kaoruko\'s bright personality, Rintarou looks forward to forming a friendship with her. There is just one obstacle that stands in his way: Kaoruko is a Kikyo student!\n\n[Written by MAL Rewrite]', '2021-10-21', 'https://cdn.myanimelist.net/images/manga/5/256607l.jpg', 'Drama, Romance', 'Manga'),
(591, 'Roxana', 'The Abysmal Flower tells a tragic tale of romance. The heroine, Sylvia Pedelian, is at the heart of a gory and erotic reverse harem story about her revenge for the disappearance of her brother, Cassis. When a Korean student suddenly awakens in the world of the novel, she realizes she has become the ill-fated Roxana—a villainous daughter of the Agreces, the Pedelians\' sworn enemies. As it is her father, Lante, who captures and abuses Cassis, Roxana devises a plan befitting the wickedness of her family name to save Cassis and, consequently, herself.\n\nThe Agrece castle is an unforgiving realm of betrayal, violence, and bloodshed. Over the years, Roxana has watched her father and half-siblings commit unspeakable atrocities, waiting for the day she can finally meet the shackled and battered Cassis. After Roxana shows rare interest in personally torturing and disciplining a prisoner, she is given the opportunity to secretly nurture the apprehensive Cassis back to health. Witnessing the lengths that Roxana goes to for his sake—at the expense of her own physical and mental wellbeing—Cassis resolves to one day return the favor.\n\n[Written by MAL Rewrite]', '2021-01-31', 'https://cdn.myanimelist.net/images/manga/2/261513l.jpg', 'Drama, Fantasy, Romance', 'Manga'),
(592, 'The Boxer', 'Having suffered ruthless bullying for the better part of his life, 17-year-old Yu has become emotionally numb and dissociated from reality, no longer able to act like a normal human being. Although he possesses the exceptional talent to dodge punches, Yu prefers to let his perpetrators beat him down as he finds no meaning in his survival.\n\nThings begin to look up when Yu meets an old boxing trainer nicknamed \"K.\" Having raised five champions, K\'s years of experience and an impressive gut feeling allow him to recognize Yu\'s near-superhuman fighting charisma immediately. K rushes to take Yu under his wing, despite the latter\'s apparent lack of interest.\n\nHowever, after being reminded of a bright memory from the past, Yu has a change of heart and accepts K\'s offer, hoping to experience the same light once again. Thus, Yu enters a world full of formidable adversaries—righteous and monstrous alike—and for the first time ever, he has no choice but to fight back.\n\n[Written by MAL Rewrite]', '2019-12-04', 'https://cdn.myanimelist.net/images/manga/3/251281l.jpg', 'Drama, Sports', 'Manga'),
(593, 'Ao no Hako', 'Taiki Inomata, a third-year student in junior high, attends Eimei Academy, an integrated school with a major sports program. Having joined the high school badminton team, Taiki tries to attend open practice as early as possible. But no matter how early he goes, he always arrives second in the gymnasium. The person one step ahead of him is Chinatsu Kano, a first-year student in senior high and Taiki\'s crush.\n\nChinatsu is the rising star of the basketball team, and the gap between her and Taiki could not be greater. Although Taiki is a decent badminton player, his popularity is nowhere near Chinatsu\'s, making it even less likely for his feelings to be reciprocated. However, in a strange twist of fate, she ends up living in Taiki\'s house!\n\nWanting to become a worthy match for Chinatsu, Taiki pursues the same dream as his crush: to partake in the Nationals. Taiki starts training harder than ever before, all for the sake of building a strong relationship with his new housemate.\n\n[Written by MAL Rewrite]', '2021-04-12', 'https://cdn.myanimelist.net/images/manga/2/248748l.jpg', 'Romance, Sports', 'Manga'),
(594, 'Hirayasumi', 'Living in Asagaya, 29-year-old Hiroto Ikuta spends his days working at his part-time job and chatting with the locals. He likes visiting Hanae Wada most, a grumpy yet kind elderly woman whom Hiroto calls \"Granny.\" Hiroto\'s time with Granny is sadly cut short when she passes away from a heart attack. To his surprise, Hiroto inherits Granny\'s house as she never married or had children.\n\nThree months later, 18-year-old Natsumi Kobayashi moves from her hometown to attend art school. With nowhere else to go, she stays with her cousin Hiroto, whom she has not seen in years. Despite their opposing personalities, the pair begin living under the same roof as they struggle through their seemingly mundane lives.\n\n[Written by MAL Rewrite]', '2021-04-26', 'https://cdn.myanimelist.net/images/manga/2/249992l.jpg', 'Slice of Life', 'Manga'),
(595, 'Whale Star: The Gyeongseong Mermaid', '\"If the life that you had regained, was one that I had breathed back into you... Is it too much to hope for you to love me back with that life?\" \n\nThe year is 1926, in Japan-occupied Joseon. 17-year-old Soo-a is an illiterate handmaiden working for the household of a prominent Japanese collaborator. One day, she discovered an injured young man lying unconscious at the beach, an independence activist called Eui-hyeon. The sweet and innocent Soo-a nursed him back to health, and Eui-hyeon told her the tale of the \"Little Mermaid,\" a princess of the sea who saved a prince from his death. Having fallen in love with Eui-hyeon, Soo-a was determined to meet him once again. But she knew not then, of the fate that awaited the \"Little Mermaid\" on her quest to reunite with her beloved.\n\n(Source: MU)', '2019-06-21', 'https://cdn.myanimelist.net/images/manga/3/237965l.jpg', 'Drama, Romance', 'Manga'),
(596, 'Trapped', 'Chae-a Han and Yunsu Park may be perfect angels at church, but Chae-a is really a foul-mouthed ex-convict, and Yunsu is... a vampire? When Yunsu blackmails Chae-a with a murder she didn\'t commit, she begins searching for ways to escape the situation until the perfect opportunity presents itself. With Yunsu\'s life now at her mercy, the two begin a life-or-death game of cat and mouse, only to find themselves falling deeper and deeper into each other\'s traps...\n\n(Source: Webtoon Entertainment)', '2019-09-02', 'https://cdn.myanimelist.net/images/manga/2/265222l.jpg', 'Romance, Suspense', 'Manga'),
(597, 'Yamada-kun to Lv999 no Koi wo Suru', 'After her boyfriend cheats on her with another girl he met in-game, Akane Kinoshita learns the hard way that gamer boyfriends can be just as bad as the offline variety. As she vents her anger by beating mob monsters to a pulp, she has a chance encounter with Akito Yamada, a guildmate with an afro and Noh mask.\n\nYamada is unsociable and curt, hardly the type of person to make Akane swoon. However, while his gaming stats might be maxed out, Yamada is inexperienced in matters of the heart, and against all odds, she finds herself moved by him. Making new friends along the way, can Akane shake the heart of Yamada, a final boss-level high school boy?\n\n[Written by MAL Rewrite]', '2019-03-07', 'https://cdn.myanimelist.net/images/manga/2/228144l.jpg', 'Romance', 'Manga'),
(598, 'Shimeji Simulation', 'After locking herself inside her closet for two years, Shijima Tsukishima finally comes out of isolation to attend high school. However, when she looks at herself in the mirror, she discovers two shimeji mushrooms growing on the top of her head. This odd occurrence, combined with a lack of social ability and being bullied in middle school, leads Shijima to keep to herself when she arrives at school.\n\nWhile reading alone, Shijima is approached by her classmate, Majime Yamashita, an eccentric girl with a fried egg on her head. Majime pesters Shijima to be her friend, giving her the nickname \"Shimeji\" upon seeing the mushrooms growing on her head. After enough insistence on friendship, Shimeji gives in and decides to keep Majime company. Shimeji tries to get through a less-than-normal high school life as she explores the mysteries and wonders of this strange world with her new tenacious companion.\n\n[Written by MAL Rewrite]', '2019-01-26', 'https://cdn.myanimelist.net/images/manga/2/227584l.jpg', 'Slice of Life', 'Manga'),
(599, 'Amayo no Tsuki', 'One day, while rushing to a piano lesson, a girl named Saki collides with someone on the street. As Saki collects herself, the stranger picks up the sheet music Saki dropped, hands it to Saki together with a band-aid, and continues on her way—all without saying a word. Saki is left wondering about the identity of the tall, lovely stranger, only to discover the next day that she is one of her classmates at her new high school. The girl\'s name is Kanon, and though she is hearing impaired, she refuses any kind of support or \"special treatment\" from her teachers or classmates. Over the course of the year, Saki slowly grows closer to Kanon and begins to chip away at her cold exterior.\n\n(Source: Kodansha USA)', '2021-06-12', 'https://cdn.myanimelist.net/images/manga/3/253111l.jpg', 'Drama, Girls Love', 'Manga'),
(600, 'Goukon ni Ittara Onna ga Inakatta Hanashi', 'College student Tokiwa gets invited to a mixer by his female classmate Suo. But when he arrives with his friends, they’re greeted by three dazzlingly handsome men?!\n\n(Source: Square Enix)', '2021-02-12', 'https://cdn.myanimelist.net/images/manga/3/254144l.jpg', 'Comedy, Romance', 'Manga'),
(601, 'Yofukashi no Uta', 'Kou Yamori seems like a typical middle school student on the surface. Relatively good at studies and amiable with his classmates, he puts a lot of effort into maintaining this facade. One day, however, he decides to stop pretending and quits school, developing insomnia as a result of having no daytime outlet for his energy. When taking walks alone at night, he feels marginally better, though he is aware that his inability to sleep should be considered a serious problem.\n\nOn one such walk, Kou meets a weird girl, Nazuna Nanakusa, who diagnoses the cause of his sleeplessness: despite making changes in his life, he is still holding himself back from experiencing true freedom. She says that he won\'t be able to sleep unless he is satisfied with how he spends his waking hours. When it appears that she has resolved his current worries, Nazuna invites him back to her apartment to share her futon. After a while, unaware that he is only feigning unconsciousness, she leans over him—and bites his neck!\n\n[Written by MAL Rewrite]', '2019-08-28', 'https://cdn.myanimelist.net/images/manga/3/224212l.jpg', 'Award Winning, Romance, Supernatural', 'Manga'),
(602, 'Nan Hao Shang Feng', 'A comedy about two ordinary high school boys.', '2021-04-30', 'https://cdn.myanimelist.net/images/manga/1/254654l.jpg', 'Comedy', 'Manga'),
(603, 'Bungou Stray Dogs: Dazai, Chuuya, Juugosai', 'Yokohama\'s Suribachi district is a lawless zone swarming with all kinds of people. To protect each other, a group of teenagers created a self-defense organization called Sheep, with 15-year-old Chuuya Nakahara as their \"King.\" Thanks to Chuuya\'s powerful ability to control gravity, few dare oppose the Sheep.\n\nHowever, worrying news spread around Suribachi: the Port Mafia\'s deceased leader has been witnessed roaming around. His successor, Ougai Mori, sends his protege Osamu Dazai to uncover the truth. While investigating, Dazai runs into Chuuya, and a fight erupts between the two. But before Chuuya can deal the final blow, the Port Mafia captures him.\n\nMori offers Chuuya a deal: if the teenager helps unravel the mystery behind his predecessor\'s alleged resurrection, the Port Mafia will not harm any of Sheep\'s members. Backed into a corner, Chuuya reluctantly accepts. As he and Dazai are paired together, they must overcome their disdain for each other to save Yokohama. Unfortunately, the appearance of Arahabaki, the \"God of Calamity,\" threatens to hinder their plans.\n\n[Written by MAL Rewrite]', '2022-09-26', 'https://cdn.myanimelist.net/images/manga/1/276010l.jpg', 'Action, Supernatural', 'Manga'),
(604, 'Omniscient Reader\'s Viewpoint', 'In the web novel Three Ways to Survive the Apocalypse, people are forced to fight monsters and each other for coins, food, and—ultimately—survival. While mysterious \"Constellations\" watch the unwilling participants for their own entertainment, one man emerges as the protagonist: Yoo Joonghyuk, who repeatedly lives and dies in an endless struggle to close the book on this indiscriminate torture.\n\nKim Dokja has lived a challenging and action-packed life through Joonghyuk for over a decade. While other readers abandoned the story early on, Dokja has remained its sole reader until the very last chapter. At that time, he receives a puzzling message from the author, and the novel\'s inhumane world suddenly becomes reality.\n\nAs the only person aware of what lies ahead, Dokja realizes that he must utilize his omniscience to navigate the deadly scenarios and stay alive. Dokja was never meant to play a main part, but in defiance of those who wish to spell his fate, he might just have to take the lead in writing his own conclusion.\n\n[Written by MAL Rewrite]', '2022-01-20', 'https://cdn.myanimelist.net/images/manga/1/265768l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(605, 'I Shall Master This Family', 'The Lombardis were the most powerful family that ever existed in the empire. With unimaginable wealth, they shaped history, culture, and the arts—their influence rivaling that of the emperor. However, the family collapsed after making an alliance with the first prince, which resulted in futility as the second-born Perez Brivachali Durelli was crowned instead.\n\nA Korean woman is reincarnated as Firentia, the daughter of a Lombardi and a commoner. Despite her status as an illegitimate child, her father and grandfather love her, and she works hard to keep her family\'s prestige intact. After the two pass away, Firentia is kicked out and has since regretted how her relatives have torn the Lombardi name to shreds.\n\nOn the verge of dying due to a carriage accident, Firentia is mysteriously given another chance in life and wakes up as her seven-year-old self. Firentia will not waste this opportunity, and if she wants to save her father and prevent the Lombardi\'s fall, she must prove to her grandfather her merit to become the next head of the family.\n\n[Written by MAL Rewrite]', '2021-02-28', 'https://cdn.myanimelist.net/images/manga/3/274102l.jpg', 'Fantasy', 'Manga'),
(606, 'Ponkotsu Ponko', 'The near future, in a quiet seaside town. Yoshioka, who had recently lost his wife, just wants to spend the rest of his days in peace. However, Yoshioka\'s children, worried about their father\'s health, sent a housekeeping robot to help him. Yoshioka\'s quiet life is now changing.\n\n(Source: Shogakukan, translated)', '2019-03-25', 'https://cdn.myanimelist.net/images/manga/1/220644l.jpg', 'Comedy, Slice of Life', 'Manga'),
(607, 'Your Throne', 'Cunning and ruthless, Lady Medea Solon has only had one goal in her life: to become the princess of the Vasilios Empire by marrying Crown Prince Eros Orna Vasilios. However, Medea\'s ambitious scheme collapses when the crown prince chooses naive Psyche Callista as his fiancée instead of her. As a result, she resolves to remove Psyche by any means necessary and secure her place on the throne.\n\nHowever, not all goes according to her plan. At the Yearly Prayer held in the Temple, Medea confronts Psyche and her ignorance toward possessing unfathomable authority. In an instant, Medea falls into a seemingly bottomless fountain, unable to reach the surface. Believing that God is responsible, she prays to be the one who rules the empire.\n\nThe deity grants Medea\'s wish at the cost of exchanging bodies with Psyche, a twist of fate that may reveal more than what meets the eye.\n\n[Written by MAL Rewrite]', '2020-01-06', 'https://cdn.myanimelist.net/images/manga/1/236523l.jpg', 'Drama, Fantasy, Romance', 'Manga'),
(608, 'Shinai naru Gene e', 'New York, \'70s. Trevor Edwards is a successful lawyer who just recently broke things off with his fiancée. One night, Trevor realizes that he lost important documents pertaining to a client and doesn\'t seem to be able to find them anywhere. As he\'s ready to accept defeat and the end of his career, his salvation comes in the form of Gene, a young man who works as a cleaner on the same building as Trevor\'s lawyer firm, and who saw him drop his documents on his way out. After he hands them back to him and Trevor learns that the young man is homeless, Trevor invites him to stay over at his house as to escape the cold winter night. But is that enough to thank his savior?\n\n(Source: MU)', '2019-08-31', 'https://cdn.myanimelist.net/images/manga/3/237923l.jpg', 'Boys Love, Drama, Erotica', 'Manga'),
(609, 'Hikaeme ni Ittemo, Kore wa Ai', 'Risa Amakawa is only in high school, but she is extraordinarily self-sufficient. With the tools inside her seemingly bottomless bag, she is prepared for any freak incident that lady luck chooses to throw her way. So when Risa encounters a delinquent—all battered and bruised—on a rainy afternoon, she takes advantage of the power bestowed upon her by her own sense of caution and uses it to help him. What she does not expect is the victim, Zen Oohira, to take a liking to her.\n\nZen checks all the boxes of a typical delinquent; he has an air of nonchalance about him and even owns a motorcycle. Even so, he is oddly cheerful and sweet, going so far as to give Risa a \"help coupon\" as thanks for her aid in his time of need. When an unforeseen episode forces Risa to redeem her coupon, she realizes that Zen can be far more charming than he lets on. But is she prepared to sacrifice her meticulousness for a carefree gamble on romance?\n\n[Written by MAL Rewrite]', '2021-07-26', 'https://cdn.myanimelist.net/images/manga/1/253097l.jpg', 'Romance', 'Manga'),
(610, 'What Happens Inside the Dungeon', 'The revered Swordmaster Hoss sets out to defeat the formidable Shell Dragon! But when people find his cold dead body amidst the remains of a fierce battle, they make a shocking new discovery. Now, with monster hunters discovering new ways to utilize their spoils for more private (?) pleasures, a bizarre sexual hype sweeps through the lands—and Cheong, as innocent as she is, must make her way through this mess. Join Cheong as she embarks on her raunchy new adventure!\n\n(Source: Lezhin Comics)', '2019-06-26', 'https://cdn.myanimelist.net/images/manga/2/263315l.jpg', 'Adventure, Fantasy, Erotica', 'Manga'),
(611, 'Uma Musume Cinderella Gray', 'Uma Musume Cinderella Gray is a spin-off title of the Uma Musume project by Cygames. It follows Oguri Cap through her time at Kasamatsu Training Center Academy and on her journey of becoming a legendary horse girl.\n\n(Source: MU)', '2020-06-11', 'https://cdn.myanimelist.net/images/manga/3/240780l.jpg', 'Drama, Slice of Life, Sports', 'Manga'),
(612, 'Mairimashita! Iruma-kun: If Episode of Mafia', 'In this brand-new spinoff of the runaway hit series, Iruma is a dirt-poor but unfailingly cheerful young boy who grows up in a ruthless city slum. One day, Iruma gives an injured old man his last loaf of bread and nurses the stranger back to health—only to find out that the elder gent is none other than Don Sullivan, head of the Babyl Mafia! Soon after, Don Sullivan comes back, whisks Iruma away, and begs the boy to become his grandson. And just like that, Iruma begins his new life as the next in line to lead a gigantic gang of—dare we say—demonic mafiosos!\n\n(Source: Kodansha USA)', '2023-09-12', 'https://cdn.myanimelist.net/images/manga/3/293165l.jpg', 'Fantasy', 'Manga'),
(613, 'Yubisaki to Renren', 'Yuki Itose is a hearing-impaired university student whose world has been shrouded with silence since birth. She has lived in the same place her whole life, and rarely interacts with others save for her best friend, Rin Fujishiro. During her commute one day, she meets the silver-haired and multilingual Itsuomi Nagi, a mutual friend of Rin. Unlike most, Itsuomi is unwavering when he learns of Yuki\'s impairment; this, along with his experiences abroad, fascinates and touches her. After they part, her fondness of him starts to grow. A new world begins to open for both Yuki and Itsuomi as they learn about each other\'s different lives.\n\nYubisaki to Renren is a lighthearted, romantic comedy that illustrates the silent life of a university student and how one man sharing his world starts to change her own.\n\n[Written by MAL Rewrite]', '2019-07-24', 'https://cdn.myanimelist.net/images/manga/5/262471l.jpg', 'Romance', 'Manga'),
(614, 'Killer Crush', 'A killer must be prepared to put on the perfect act for their assassination to be successful. They must be exceptionally meticulous when erasing any trace of evidence, and they must absolutely never be caught. These are some of the simple rules that Joo Taeman has followed for 14 years, never allowing his emotions to interfere.\n\nMeanwhile, the famous actor Kang Dahyeok, nicknamed the \"Heart Assassin\" due to his attractive looks and dreamy eyes, is a huge fan of gritty film noirs. He has always dreamt of starring in something with an edge, but he keeps getting stuck with swoony romantic dramas. After witnessing Taeman\'s ability to effortlessly switch from a scowl to a smile, Dahyeok is determined to befriend him and learn the trick. However, Taeman falls for Dahyeok at first sight, facing a dangerous challenge: how to separate his high-risk profession and this deadly, killer crush!\n\n[Written by MAL Rewrite]', '2021-09-02', 'https://cdn.myanimelist.net/images/manga/2/299703l.jpg', 'Boys Love, Comedy', 'Manga'),
(615, 'One Piece: Episode A', 'The infamous Portgas D. Ace\'s departure from Dawn Island marks the beginning of his pirate adventure, and he immediately finds himself deserted on an uninhabited, desolate island. There, he meets a mysterious man, who quickly becomes drawn to Ace\'s personality and befriends him. Aiming to get themselves off the island, the duo decides to work together to build a boat.\n\nHowever, due to a lack of food on the isle, the pair only have so much time to finish making their craft, causing tension to arise between the two. Nonetheless, the appearance of a special fruit may give them the hope needed to escape the island—because if they succeed, they vow to sail the Grand Line together.\n\n[Written by MAL Rewrite]\n\nIncluded one-shots:\nVolume 1: Roronoa Zoro, Umi ni Chiru (Zolo Overboard)\nVolume 2: Nami vs. Kalifa', '2020-09-16', 'https://cdn.myanimelist.net/images/manga/2/266074l.jpg', 'Action, Adventure, Fantasy', 'Manga'),
(616, 'Boku ga Otto ni Deau made', 'On October 10, 2016, Ryousuke Nanasaki married the love of his life, Ryousuke. But the time leading up to this day was anything but easy. Feelings of self-hatred, heart-wrenching breakups, and coming out to his family—it was all an uphill battle.\n\nBased on the autobiographical web essay of the same title, Boku ga Otto ni Deau made follows Nanasaki\'s life and his journey to discover a happy ending together with his husband.\n\n[Written by MAL Rewrite]', '2020-04-29', 'https://cdn.myanimelist.net/images/manga/1/243238l.jpg', 'Boys Love, Drama', 'Manga'),
(617, 'Under the Greenlight', 'Cheongwoo Jin has led a lonely existence of promiscuity, violence, and drugs. Dabbling in both legal and criminal activities, he has created a name for himself and an extravagant lifestyle he can enjoy. His newest venture is to buy the construction rights for an expensive plot of land, where his boss plans to build an art museum. By chance, this simple job leads him to encounter Matthew Raynor—a young sculpture student who is expressionless and mysterious yet completely enchanted by Jin.\n\nDesperate to keep Jin in his life and unintimidated by his threatening attitude, Matthew asks him to model for his sculpturing project. Despite it being an outrageous request, Jin accepts the offer in exchange for sex, agreeing to regularly meet in Matthew\'s studio. As enemy organizations compete for the same lot as Jin, his sketchy past begins to catch up to him, and he wonders if he is truly going insane by deciding to risk everything to protect one innocent student.\n\n[Written by MAL Rewrite]', '2021-03-05', 'https://cdn.myanimelist.net/images/manga/2/265446l.jpg', 'Boys Love, Drama, Erotica', 'Manga'),
(618, 'Yoake no Uta', 'On a certain island, there are individuals chosen to protect the common folk from creatures emerging from the sea. Elva—one of the chosen ones—fulfills this duty, beset with a cursed body that has stopped growing, and in isolation from others. When a boy named Alto learns of Elva\'s circumstances, he wishes to free Elva from this role. In order to support him, Alto reaches out to Elva, whom no one had dared approach before, and vows to stay by his side forever. After eight years that these two opposites had lived together like master and servant, like a family... Elva\'s body, supposedly only holding out for a few years, has started showing signs of recovery for an unknown reason.\n\n(Source: Shu-Cream, translated)', '2020-08-21', 'https://cdn.myanimelist.net/images/manga/2/265253l.jpg', 'Boys Love, Fantasy', 'Manga'),
(619, 'See You in My 19th Life', 'Jieum Ban has an extraordinary ability: she can remember the memories of all her past lives. After her previous life is cut short by a tragic accident, she sets out to reconnect with the people of her past life in her current one. Will memories of her 18th life sabotage romance in her 19th? Or will love endure across different lives?\n\n(Source: Webtoon Entertainment)', '2020-06-05', 'https://cdn.myanimelist.net/images/manga/3/264868l.jpg', 'Romance', 'Manga'),
(620, 'Kimi no Yoru ni Fureru', 'Chinatsu and his older brother, Fuyuki, have been trained by their father to become professional assassins for their whole lives. However, Fuyuki is slain as a result of Chinatsu failing at his first job. Chinatsu is discovered by a blind boy who lends him a shoulder to cry on.\n\nThe trauma still haunts Chinatsu five years later, and he is unable to kill any of his targets as a result. While waiting around the streets, he recovers a stolen object owned by Kasumi, the blind boy he had met back then. As a token of gratitude, Kasumi invites the assassin to his home that is located in a traditional Japanese inn. Chinatsu learns that the boy sees himself as a burden to his family due to his disability.\n\nDespite being complete strangers, Kasumi feels a connection with Chinatsu and asks him to be his friend, to which the assassin readily agrees. But Chinatsu discovers more from being around Kasumi\'s kindhearted nature, and he realizes he may have found a way through the darkness of his life: a light worth protecting amidst the abyss.\n\n[Written by MAL Rewrite]', '2021-08-20', 'https://cdn.myanimelist.net/images/manga/2/269777l.jpg', 'Boys Love, Drama', 'Manga'),
(621, 'Otonari no Tenshi-sama ni Itsunomanika Dame Ningen ni Sareteita Ken', 'After catching a cold by giving his only umbrella to a girl sitting in the rain, Amane Fujimiya only expects her to eventually return it. However, Mahiru Shiina, the \"Angel\" of Amane\'s school and his neighbor, instead gives him a lot more than that. Instead of just the umbrella, she insists on returning the favor by helping him recover from his cold. However, she is oblivious to the battlefield that is Amane\'s apartment.\n\nThe only word Mahiru finds from her mouth to describe the chaos is \"unsightly.\" But despite her unsympathetic description, Mahiru proceeds to help the hopeless Amane. Otonari no Tenshi-sama ni Itsunomanika Dame Ningen ni Sareteita Ken follows Amane as he is taken care of by Mahiru, who attends to various chores—from cleaning his apartment to cooking dinner. Is there anything that the Angel can not do?\n\n[Written by MAL Rewrite]', '2019-06-14', 'https://cdn.myanimelist.net/images/manga/2/235341l.jpg', 'Comedy, Romance', 'Manga'),
(1122, 'Lost in the Grotto: Thievery', 'An FPS game where players navigate dungeon landscapes, unravel mysteries, and master the art of thievery.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9u5p.jpg', 'Simulator, Strategy', 'Jeu video'),
(1123, 'Korean Drone Flying Tour Hwado-myeon', NULL, '2025-04-30', '', 'Simulator, Arcade', 'Jeu video'),
(1124, '#7-J5Z: The Driftwood Experiment', 'A simple and short cozy game where you play as an unusual robot, exploring an underwater cave system.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sv7.jpg', 'Adventure, Indie', 'Jeu video'),
(1125, 'Neko no Sentouki', 'An Adventure Visual Novel where you can choose your protagonist – Play as Aiko or Hikaru as they try to uncover the secrets that lurk all around them in this character-driven story. Every choice you make will have an impact on the story.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sr6.jpg', 'Adventure, Indie, Visual Novel', 'Jeu video'),
(1126, 'Dandelions and Me', 'Dandelions and Me is a short psychological horror game about searching for your lost dog in an abandoned dungeon.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s8c.jpg', NULL, 'Jeu video'),
(1127, 'DIY Horse Race Thing', 'A small little toy that lets you make small maps with obstacles and walls, and then let little horses run around, until one bumps into the carrot and wins. The idea is to play with friends and bet who will end up winning!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s0l.jpg', 'Simulator', 'Jeu video'),
(1128, 'G-Mode Archives+: Amored Core Mobile Mission', 'Gear up, customize your mech, and take on high-stakes missions! Simple yet deep—experience the thrill of mech action on the battlefield!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rv8.jpg', NULL, 'Jeu video'),
(1129, 'Dance On Radar', NULL, '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sgj.jpg', 'Arcade', 'Jeu video'),
(1130, 'Absurdika: Rebuild', NULL, '2025-04-30', '', 'Platform, Puzzle, Adventure, Arcade', 'Jeu video'),
(1131, 'Arcade Archives: Super Xevious', NULL, '2025-04-30', '', 'Shooter, Arcade', 'Jeu video'),
(1132, 'Trainlax: Railway Puzzle Simulator', NULL, '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sgh.jpg', 'Puzzle, Simulator, Strategy, Arcade', 'Jeu video'),
(1133, 'MazeSlug', 'This is an immersive first-person single-player horror game. Players will take on the role of an ordinary person returning home late at night, who inexplicably steps into a special space on a familiar path. You must explore and move forward in this space filled with unknown fears.', '2025-04-30', '', 'Role-playing (RPG), Simulator, Adventure, Indie', 'Jeu video'),
(1134, 'Corcovado\'s Night Guard', 'You are Vicente, a night guard that works in Corcovado, taking care of this brazilian tourist spot, christ the redeemer. A first person, singleplayer, walk-simulator experience. Investigate what is happening and try to escape this nightmare.', '2025-04-30', '', 'Simulator, Adventure, Indie', 'Jeu video'),
(1135, 'Spectre Vigil', 'Spectre Vigil is an Observation-Duty style horror game with a unique twist: Detecting ghosts! Spot many different abnormalities and handle terrifying entities, all whilst keeping track of what happens and figuring out what ails this location!', '2025-04-30', '', 'Strategy, Indie', 'Jeu video'),
(1136, 'SoulPactum', 'SoulPactum is a brutal 2D platformer where every wrong jump ends in failure. Precise timing and patience are the keys to finally making it through the deadly levels.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rsg.jpg', 'Platform, Adventure, Indie', 'Jeu video'),
(1137, 'Single\'s Inferno: Choices', 'Experience your own romance in the emotional pressure cooker of \"Single\'s Inferno,\". In this choice-driven game, you and a group of other highly eligible contestants live and look for love on a remote tropical island, where your decisions shape the story.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rq7.jpg', 'Simulator', 'Jeu video'),
(1138, 'Minuto: Galactic Deliveries', 'A puzzle game about connecting planets, timing deliveries, and figuring out the best routes. Plan carefully, adapt to cosmic chaos, and uncover hidden lore as you deliver packages to the strangest customers in the galaxy!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ro6.jpg', 'Puzzle, Indie', 'Jeu video'),
(1139, 'Diplomacy Is Not an Option: Shareware', 'Diplomacy is Not an Option: Shareware is a free prequel to the original game. In a medieval fantasy world, you are to build settlements, raise huge armies, and defend against massive hordes of enemies. Learn how Ironbrow clan shaped the world\'s map the first time - if you survive, that is.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rou.jpg', 'Simulator, Strategy', 'Jeu video');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(1140, 'Backrooms: Extractions', 'Backrooms: Extractions is a 1-6 player co-op horror game set in 2062. As a MEG operative, enter the Backrooms to locate and extract lost agents while evading lurking entities. Use advanced tools, solve tense puzzles, and survive eerie environments. Stay alert: every sound could be your last!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rh0.jpg', 'Indie', 'Jeu video'),
(1141, 'What Lies Frozen', 'A Psychological Horror game. Featuring puzzles, immersive environment, a tense atmosphere, and a unique hand-drawn art style.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rgm.jpg', 'Puzzle, Simulator, Indie', 'Jeu video'),
(1142, 'Karma Clicker', 'the old gods demand worshippers\n\na short incremental clicker game', '2025-04-30', '', 'Simulator', 'Jeu video'),
(1143, 'Salvage Protocol', 'A short horror about exploring abandoned space stations and collecting junk in order to pay off your S.R.P.O debt.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sx9.jpg', 'Indie', 'Jeu video'),
(1144, 'MemoRemovers', 'With a sharp eye, and keen memory you will navigate 5 distinct levels that change around you. Report what happened and where with the handy reporting panel before the changes have a chance to pile up. Can you last until the timer runs out?', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rfn.jpg', 'Puzzle, Indie', 'Jeu video'),
(1145, 'Back: Fade', '《Back：Fade》 is a full-motion audio live horror game. Special Note 1: This game is very supernatural and scary, timid or heart disease players do not buy ！！！！ The game will reveal different ending plots step by step through various searches and choices for your character.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rfi.jpg', 'Adventure', 'Jeu video'),
(1146, 'Through the Fog', 'You will take on the role of a detective and dive into a dark world from a first-person perspective. What will you have to do? Explore locations in search of clues. Make assumptions and write them down in your diary. Solve puzzles.Run away and hide from your demons.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rfh.jpg', 'Adventure, Indie', 'Jeu video'),
(1147, 'Seedsow Lullaby', NULL, '2025-04-30', '', 'Adventure', 'Jeu video'),
(1148, 'Fantasy RPG: Raid Legends', NULL, '2025-04-30', '', 'Role-playing (RPG)', 'Jeu video'),
(1149, 'Meow Moments: Celebrating Geeks & Athletes', 'Join cute cats in festive scenes! Find feline friends and pop balloons as you explore Olympicats—a thrilling global sports event—and Comic Cat Con, an exciting pop culture convention.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r7y.jpg', NULL, 'Jeu video'),
(1150, 'Icy Gifts', 'A thrilling and engaging chain reaction game that will keep you hooked till the end!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r7s.jpg', 'Shooter', 'Jeu video'),
(1151, 'The Mr. Rabbit Magic Show', 'The incredible Mr. Rabbit invites you all to a mysterious magic show! Celebrate 10 years of Rusty Lake with a new free-to-play point-and-click adventure that promises to delight and… shock you with its sleight of hand!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rkn.jpg', 'Point-and-click, Puzzle, Adventure, Indie', 'Jeu video'),
(1152, 'Warhammer 40,000: Rogue Trader - The Shovel DLC', 'A free DLC collaboration between Owlcat and Fatshark, bringing the Sapper Shovel from Warhammer 40,000: Darktide into Rogue Trader - a brutal weapon from Atoma Prime, now repurposed for the cold void of the Koronus Expanse.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r4i.jpg', 'Role-playing (RPG), Strategy, Turn-based strategy (TBS), Tactical, Adventure, Indie', 'Jeu video'),
(1153, 'League of Legends: 2025 Season Two - Spirit Blossom Beyond', 'Atakhan reveals to LeBlanc that the Darkin weapon she is seeking is somewhere in Ionia, where the Spirit Blossom Festival is currently taking place. At the same time Xin Zhao, the Seneschal of Demacia and a former pit Reckoner of Noxus, has decided to return to his birthplace of Ionia and discover more about its culture and his connection with the land of the spirits.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r3p.jpg', 'Role-playing (RPG), Strategy, MOBA', 'Jeu video'),
(1154, 'Demining', 'Demining is a 1-4 player semi open-world horror experience where every step could be your last. Work together or by yourself as you disarm deadly mines, delve into bountiful ruins, and fight to see another day.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r37.jpg', 'Adventure, Indie', 'Jeu video'),
(1155, 'Mystic Pathways', 'Embark on a magical journey with Mystic Pathways, a puzzle game that challenges your logic and creativity. Manipulate enchanted trails on a beautifully designed hexagonal board to guide mystical fairies in collecting magical crystals and activating sacred altars.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r69.jpg', 'Puzzle, Strategy', 'Jeu video'),
(1156, 'Maline', 'The zany and heartfelt story of Maline, a kind devil girl from Hell who discovers the true power of Kindness one day by giving a generic demon a compliment... and the chance to truly make everyone friends! Is this a dream come true, or just another demonic swindle?', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r1a.jpg', 'Adventure, Visual Novel', 'Jeu video'),
(1157, 'Nanika Game Online', 'Choose from a variety of “Nanika,” each with unique skills, and build your very own original deck to challenge other players. Merge identical Nanika to evolve them, master the perfect timing for skill activation, and aim for victory!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qvi.jpg', 'Puzzle, Real Time Strategy (RTS), Indie', 'Jeu video'),
(1158, 'Pokémon Trading Card Game Pocket: Celestial Guardians', 'First-partner Pokémon Rowlet, Litten, and Popplio make their Pokémon debuts, alongside the mighty Legendary Pokémon Solgaleo and Lunala, and beloved Trainers from Alola. Celestial Guardians features over 200 cards waiting to be collected, including powerful new Pokémon ex and the first immersive Supporter card! Take a sneak peek below at some cards you can expect to see in the new expansion.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qas.jpg', NULL, 'Jeu video'),
(1159, 'Goblintown: Really Hard Driving Game', 'Do you have the skill, the moxie, and (most importantly) the FLAPS to be McGoblin Burger’s Greatestest Delivery Gob EVER?? Speed your way through a sadistic gauntlet of hairpin turns, explosions, and other mayhem designed to ruin your run - and don’t forget to SCREAM!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pmr.jpg', 'Platform, Racing, Adventure, Indie', 'Jeu video'),
(1160, 'Fantastic Petty', 'An adorable, fantastic, poppy, and slightly bizarre 2D side-scrolling shooter game! Conquer all 5 stages in order to bring back spring to the island of Esideci!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pi1.jpg', 'Indie', 'Jeu video'),
(1161, 'Gloamvault', '\"90s Black Metal Monster Collector!\" In Gloamvault, you can charm any monster you encounter and add it to your party. Create a party with up to five minions and descend into the depths of the dungeon. Fuse any two monsters together to create stronger ones. Good luck surviving...', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9o2v.jpg', 'Role-playing (RPG)', 'Jeu video'),
(1162, 'Pixel Quest: Realm Eater', 'Build hero squads, forge ancient relics & save pixel realms in this strategic idle RPG.', '2025-04-30', '', NULL, 'Jeu video'),
(1163, 'Bill Wants to Retire', 'By day a cozy farming sim, by night a doom like boomer shooter. Farm, gather resources, and craft powerful weapons because when night comes so do the wolves. Can you protect your chickens and make it to retirement?', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lmy.jpg', 'Indie', 'Jeu video'),
(1164, 'MotoGP 25', 'Join the official Championship and step into the boots of your favorite riders. Master the most iconic bikes and tracks of the season and challenge the best riders in the world. Feel the authentic race thrills thanks to an overhauled sound design, recorded on-site from official bikes.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rdb.jpg', 'Racing, Simulator, Sport', 'Jeu video'),
(1165, 'Magic Construct', 'Magic Construct is an action-survival game where you freely edit skills. Upgrade, make fateful choices, and use a simple connection mechanic to create unique skills. Survive and grow stronger in a challenging world.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9la3.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1166, 'Gogh: Focus with Your Avatar', 'gogh: Focus with Your Avatar is more than a focus tool – it’s a cozy blend of avatar creation, room design, and virtual pet game. Build your perfect space, vibe with Lofi beats, and let your cute avatar and quirky companion turn work into pure fun!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9g7d.jpg', 'Simulator, Indie', 'Jeu video'),
(1167, 'Cafe Dreamland', 'This is Cafe \"DReAMLAND\". Grant your \"customers\'\" wishes by serving them drinks mixed with a hint of blasphemy! Cafe simulation x Exploration x Multiple endings Let your choices decide the final outcome.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9g72.jpg', 'Adventure', 'Jeu video'),
(1168, 'Veloria: The Knot of Candles', 'Veloria: The Knot of Candle is a new type of role-playing game that integrates puzzles, level design, visual effects, and music. A girl wakes up from a nightmare to find herself in an orphanage that had long been burned down. Pushing open the charred door, the childhood nightmare strikes again.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9e5a.jpg', 'Adventure, Indie', 'Jeu video'),
(1169, 'Kwun Tong', 'Made in Hong Kong. By Unreal Engine 5.4.4. Escape from Kwun Tong.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9d76.jpg', 'Adventure', 'Jeu video'),
(1170, 'Cataclysm Wars', 'The Empire is under attack, and only its mighty armies can save it! Shame you aren\'t in charge of those, then. Lead an outmatched militia through overwhelming odds in this turn-based strategy game, and save your nation from collapse. Or, lead the dogged Syrinx foe and crush the Empire!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99c1.jpg', 'Strategy, Turn-based strategy (TBS), Indie', 'Jeu video'),
(1171, 'Conquest Dark', 'Experience an ARPG\'s rapid ascension to power in minutes, packed with savage, survivors-like action and devastating sword & sorcery combat. Perfect your builds through Dark Ritual runs that will decide humanity\'s future as you battle endless hordes across haunting ruins and cursed kingdoms.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co972e.jpg', 'Role-playing (RPG), Indie', 'Jeu video'),
(1172, 'Pizza Delivery in a Storm', 'A motorbike action game where you deliver pizzas in a storm', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wyi.jpg', 'Racing, Indie', 'Jeu video'),
(1173, 'Noroi Kago: The Grudged Domain', 'Noroi Kago: The Grudged Domain is a four-player co-op survival horror game centered on the supernatural \"Yokai\" from Japanese folklore. Trapped in a cursed domain, you and your companions must work together to endure the curse, hide from the terrifying Yokai, and find a way to escape.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8vlw.jpg', 'Adventure, Indie', 'Jeu video'),
(1174, 'Skyline Savior', 'Control Sam’s car in Skyline Savior with arcadey movement, jumping, dashing, slow motion, and downforce skills. Conquer obstacles in regular, pretty hard, and impossible modes for the ultimate challenge.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8k0f.jpg', 'Adventure, Indie', 'Jeu video'),
(1175, 'All the Darkest Places', 'Step into Alex, an upcoming college freshman battling depression. Living with his widowed father, Alex prepares to move in with Laura, a friend of his late mother. Guide Alex through university life, navigating personal struggles, forming connections, friendship and support.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8o0q.jpg', 'Simulator, Adventure', 'Jeu video'),
(1176, 'Hyas: The Side Effects Within', 'Once a person\'s will is \"corroded,\" their soul will forever be lost in oblivion. You will navigate between the past and the present, exploring environments, gathering clues, avoiding unknown life forms, deducing mysteries, and ultimately uncovering the truth to return to the real world.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8820.jpg', 'Role-playing (RPG), Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1177, 'Dark Pact', 'Manipulate enemy positioning and use the environment to your advantage. Utilize clever combos to defeat overwhelming odds in this tactical turn-based strategy game with a focus on creativity rather than number crunching.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9o2z.jpg', 'Role-playing (RPG), Strategy', 'Jeu video'),
(1178, 'Squirrels Gone Nuts', 'Squirrels Gone Nuts is a fast-paced, multiplayer, arena shooter. Play as a speedy squirrel able to run on any surface and wield various guns. Procedurally generated arenas paired with an innovative game mode that blends capture the flag with king of the hill ensures a fresh experience every match.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9g3r.jpg', 'Indie', 'Jeu video'),
(1179, 'A Weekend Trip', 'A short narrative about a trip with friends over the weekend. Play as River as they throughout the trip. Choose what River does during the trip. Will they hang out with their friends? Will they explore the cabin? Or will they choose to just let the trip pass by as quickly as possible.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r2e.jpg', 'Point-and-click, Puzzle, Adventure, Indie, Visual Novel', 'Jeu video'),
(1180, 'Versebound', 'Slay hordes of enemies and fight mythical bosses in this challenging action roguelike. In a desperate fight for survival you must perform rituals, buildcraft and learn from every misstep to become stronger. Use unique abilities and powerful artifacts to beat every trial in the world of Kalevala!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ko3.jpg', 'Indie', 'Jeu video'),
(1181, 'Error_Boy.exe', 'The games have mixed up due to an error! Defeat the enemies by using items from various games! 1000101 1101110 1101010 1101111 1111001 100001', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7cyj.jpg', 'Indie', 'Jeu video'),
(1182, 'TaskTwist', 'Bored with regular chores? In the VR simulation game TaskTwist, even cleaning can become a shocking adventure! Dive in and see if you can conquer the house without getting zapped!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co770u.jpg', 'Simulator, Adventure', 'Jeu video'),
(1183, 'Broken Life', 'BROKEN LIFE is an atmospheric, fully voiced point-and-click adventure set in a war-torn world. Follow Leo, a former soldier, as he returns to his hometown to uncover the fate of his family, restore his home, and confront the dark secrets hidden within.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s3c.jpg', 'Point-and-click, Puzzle, Adventure, Indie', 'Jeu video'),
(1184, 'Memoriapolis', 'From Antiquity to the Age of Enlightenment, imagine, build and manage a city capable of spanning almost 2,500 years of history. Transform your explorers\' camp into a world-renowned Capital. But beware: Each age brings its own challenges!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qs0.jpg', 'Simulator, Strategy, Indie', 'Jeu video'),
(1185, 'Da Paper Boy', 'Get locked and loaded as 3 Teens run through the town delivering mail in a whole new modern way! As you generate points on the leaderboard while dodging OG granny and the neighborhood watch. Only one question remains... Are you the best paper boy or paper girl? Let your score tell it all!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6upv.jpg', 'Role-playing (RPG), Strategy, Adventure, Indie', 'Jeu video'),
(1186, 'Wagon', 'Wagon is a 1-bit card game where you make tough decisions to try and survive winter on the Oregon Trail.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ok3.jpg', 'Simulator, Strategy, Indie, Card & Board Game', 'Jeu video'),
(1187, 'Kiborg', 'Kiborg is a fast-paced, story-driven action game with rogue-lite encounters. Each challenge is unique and the narrative always moves forward, win or lose. Become an unstoppable war machine and face the consequences of your actions as you lead a resistance group on a faraway prison planet.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tma.jpg', 'Fighting, Shooter, Hack and slash/Beat \'em up, Indie', 'Jeu video'),
(1188, 'BeDo', 'Traverse galactic phases and find the Dough scattered throughout space in an addictive adventure of precision and relaxing floating', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dwc.jpg', 'Adventure', 'Jeu video'),
(1189, 'Bleeding Deities', 'Bleeding Deities is a hand-drawn action-adventure 2D platformer inspired in the ancient tribes. A Ruthless World with Dark Secrets and Evil Deities Go in search of the Legendary Baktun Stone and bring the peace back to your people ​ ​', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6cx9.jpg', 'Adventure, Indie', 'Jeu video'),
(1190, 'StarVaders', 'Defend the Earth from an alien invasion in the ULTIMATE fusion of deckbuilding and grid-based tactics. Pilot a mech, discover game-breaking combos, and protect the future of humanity in this endlessly replayable roguelike.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rla.jpg', 'Strategy, Turn-based strategy (TBS), Indie', 'Jeu video'),
(1191, 'Infinity War Land', '\"Infinity War Land\" is a roguelite dungeon shooter.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5fyk.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1192, 'Haunted House Renovator', 'Get ready to fight evil entities that roam in abandoned houses! Become the world\'s first paranormal renovator and set off to restore haunted mansions to their former glory. Make sure that the houses you work on look pleasing to your customers... even if you have to hide a few skeletons in a closet.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5e4a.jpg', 'Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1193, 'Sir Galgano: A Medieval Tale', 'Sir Galgano is a side-scrolling medieval beat ‘em up game with RPG elements', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ltd.jpg', 'Adventure, Indie', 'Jeu video'),
(1194, 'Rebellion Godsoul: Awakening', '\"GODSOUL\" is a story-driven, Hyper-visually RPG. Team with \"rebel\" girls who love gaming and drawing (and more), resist villains and enjoy a mix of cyber reality, fantastical worlds, and card game action.', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ks9.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1195, 'Moroi', 'Moroi is a grimdark fairytale with an even darker sense of humor. Experience frantic combat, perplexing puzzles, and a twisting narrative anchored by a bizarre cast of characters. Can you break free from eternal madness?', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9a0m.jpg', 'Hack and slash/Beat \'em up, Adventure', 'Jeu video'),
(1196, 'Skin Deep', 'Skin Deep is an immersive first-person shooter. We got sneezing. We got things getting stuck in your feet. Stalk through a vast non-linear starship and sneak, subvert, and sabotage to survive in this stellar sandbox. You\'re outnumbered, outgunned, and have no shoes. Welcome to Skin Deep!', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qg3.jpg', 'Music, Simulator, Adventure, Indie', 'Jeu video'),
(1197, 'Sylia', 'Three gigantic and mysterious Cubes have landed on Sylia\'s main islands. Inside them, unknown creatures (… Aliens) are gathered and plot on how to take control of the lands and ultimately extract the planet\'s energy – that would be the end of all life. Is Sylia a realm about to fall?\n\nMaybe not! A group of heroes is not willing to let that happen! They are Sylia\'s finest knight, wizardress, cleric and warrior. Supported and guided by their nation, they must enter the Cube where the Aliens\' Queen (a mysterious woman by the name of Lady Godiva) is and stop her! But the task seems overwhelming…\n\nWho is going to win the fight for Sylia? Will the land thrive or will the Aliens gain its energy and destroy every life form in the process?', '2025-04-30', 'https://images.igdb.com/igdb/image/upload/t_cover_big/qacigcmnfybhraqeruts.jpg', 'Role-playing (RPG), Strategy, Adventure, Indie', 'Jeu video'),
(1198, 'Rogue Scum', 'Sci-fi action-roguelike survivors bullet-hell with dialogs.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9t2e.jpg', 'Shooter, Role-playing (RPG), Indie, Arcade', 'Jeu video'),
(1199, 'Star Wars: Grand Collection', NULL, '2025-04-29', '', NULL, 'Jeu video'),
(1200, 'Due Last Week', 'Due Last Week is a short indie horror experience where you play as Miles Kent, a struggling construction worker who lives in a town called Wickerford, barely scraping by. With no money for streaming services, you find comfort in renting cheap VHS tapes from Reel Time Rentals, a run-down but familiar store you visit often.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9svh.jpg', NULL, 'Jeu video'),
(1201, 'Why Jump', 'Why Jump? Because the only way is up. Why Jump is a vertical platformer where one wrong move can cost you — but don\'t worry, there are checkpoints to catch your breath. Sometimes. Test your patience, sharpen your skills, and see how high you can climb.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rfe.jpg', 'Adventure', 'Jeu video'),
(1202, 'Squirrel Madness', NULL, '2025-04-29', '', 'Simulator', 'Jeu video'),
(1203, 'Cryphora', 'A remote mountain cabin, a raging snowstorm, and the line between reality and madness begins to blur. Make difficult choices, explore surreal worlds, and confront what waits in the dark.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9scc.jpg', 'Adventure, Indie', 'Jeu video'),
(1204, 'Adventures In Time & Space', '~ Escape from the Pharaoh\'s Tomb + Pirates on Target + Xatrom Command ~', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r7x.jpg', NULL, 'Jeu video'),
(1205, 'Mining Company', 'Online co-op horror for 1-4 players. Mine nearby asteroids for gems to pay for your new company\'s spaceship. Time your orbits, day-trade the minerals market, and avoid deadly monsters at night. Create your own public or private server and see how many days your crew can stay in business!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qzq.jpg', 'Adventure, Indie', 'Jeu video'),
(1206, 'Detective Club: Missing in the Fog - Collector\'s Edition', NULL, '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qwe.jpg', NULL, 'Jeu video'),
(1207, 'Obscula', 'Obscula is a first-person psychological horror game where players navigate a fragile reality distorted by fear, hallucinations, and memory.\n\nArmed with only a mysterious vintage camera, you explore forgotten places and capture the unseen to uncover fragments of a haunting narrative. As the line between reality and delusion blurs, each photograph reveals more than what the eye can see.\n\nBuilt in Unreal Engine 5, Obscula delivers a cinematic and immersive experience with atmospheric storytelling, fully voiced characters, and disturbing soundscapes. Nothing you see is certain — are you brave enough to document the truth?', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pmx.jpg', 'Puzzle, Adventure, Indie', 'Jeu video'),
(1208, 'Wuthering Waves: Fiery Arpeggio of Summer Reunion', 'Version 2.3 of Wuthering Waves, including:\n• New characters: Zani and Ciaccona\n• New story quests\n• First anniversary celebrations\n• New echoes, events and more!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pcq.jpg', 'Role-playing (RPG), Adventure', 'Jeu video'),
(1209, 'Rammy no Daibouken 1&2 Remake', NULL, '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r0p.jpg', 'Role-playing (RPG)', 'Jeu video'),
(1210, 'That Village', 'As the village of Yugra forgets its past, the power of an ancient community awakens once more. Twelve objects, as part of a ritual, lead the villagers toward a dark future. Galip embarks on a journey to stop the magic and uncover its secrets.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lul.jpg', 'Adventure, Indie', 'Jeu video'),
(1211, 'Fear of Hot Water Ghost', '\"Watch out! The terrifying sexy water ghost is here!\" A survival horror action-adventure where you escape from a nightmarish city that has suddenly gone mad.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jcb.jpg', 'Adventure, Indie', 'Jeu video'),
(1212, 'Many Nights a Whisper', 'A short interactive essay on dreams, pressure, and expectations. Take part in an ancient ritual where one shot determines the fate of a generation.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jcv.jpg', 'Adventure, Indie', 'Jeu video'),
(1213, 'Spooky Survivors', 'Spooky Survivors puts you in the shoes of Van Hobo, a quirky hero battling the supernatural! Start with all unlocks BUT choose which to level up as you face endless waves. Equip powerful gear and unlock unique abilities. Outlast the nightmare and prove yourself as the ultimate spooky survivor!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gqf.jpg', 'Indie', 'Jeu video'),
(1214, 'Battle Bits', 'Defend the system in Battle Bits! In this 2D game, you are a brave Arroba (@) fighting a computer virus. Face enemies from A to Z and bosses from 0 to 9 using signs as weapons. Use Bits to upgrade and defeat the final boss, 9, in this exciting retro adventure!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9imr.jpg', 'Adventure, Indie', 'Jeu video'),
(1215, 'Mayhem Maidens', 'Ready for some chaos? Command 5 characters in this Roguelite Tower Defense! Build your dream team, crush enemies, and have a blast with adorable pixel art!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qf1.jpg', 'Simulator, Strategy, Indie', 'Jeu video'),
(1216, 'One Room Dungeon', 'A roguelike team builder, auto-battler meets inventory management, where you are a little dungeon keeper who has to fit minions, artifacts, and items in a very tidy way in his tiny one-room dungeon to empower himself to protect the dungeon from the raiding adventurers.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wrb.jpg', 'Role-playing (RPG), Simulator, Strategy', 'Jeu video'),
(1217, 'Deadzone: Rogue', 'Deadzone: Rogue is a roguelite first-person shooter set in deep space. Slay hordes of enemies, loot powerful gear, and customize your loadout during each unique run. Uncover fragments of your past as you piece together the truth behind your mission. Fight. Die. Revive. Repeat.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rsi.jpg', 'Shooter', 'Jeu video'),
(1218, 'Beastkin Training: The Trials of a Beastkin Noblewoman', 'You are a former servant, sold off as an instructor to take care of a Beastkin! Flatter the Beastkin by having chats, gifting presents, and more. Whether or not you can take great care of her is up to you.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8trc.jpg', 'Simulator, Adventure, Indie, Visual Novel', 'Jeu video'),
(1219, 'SubwaySim 2', 'Dive into Simuverse Interactive\'s new public transport simulation!\nSubwaySim 2 allows you to explore not only the underground network of Hamburg but now also that of the German capital Berlin! Face various unique scenarios and transport your passengers safely and punctually from station to station.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rxr.jpg', 'Racing, Simulator', 'Jeu video'),
(1220, 'Russian CyberVillage Simulator', 'Develop a village colony on Mars, using various resources and bringing the unique flavor of Russian culture to the distant space.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mt8.jpg', 'Role-playing (RPG), Simulator, Adventure, Indie', 'Jeu video'),
(1221, 'K2: Digital Edition', 'Easy to play, hard to survive. Rush to the summit before weather breaks or set up camps and prepare to push later. Choose the right cards for the right moment. Play turn based strategy with friends, AI or in single player mode. Popular board game adaptation consulted with real K2 climbers.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97s6.jpg', 'Strategy, Indie', 'Jeu video'),
(1222, 'Path of Kung Fu', 'Path of Kung Fu is a Wuxia RPG that blends classic martial arts storytelling with open-world freedom. Master kung fu, navigate the Jianghu\'s bloody conflicts, and rise from a novice to a legendary hero. Subscribe to top-rated Workshop MODs to elevate your experience to the next level!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r14.jpg', 'Role-playing (RPG), Adventure, Indie', 'Jeu video'),
(1223, 'Spellslayer', 'Take on the role of a spellcasting slayer puzzle tactics roguelite. Use a combination of clever positioning, strategic thinking and pure casting power to vanquish your enemies and claim the ultimate power source!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72j0.jpg', 'Indie', 'Jeu video'),
(1224, 'The Lost Glitches', 'The Lost Glitches is a Techno-Optimist set Trading Card Game with RPG progression. Head-to-head PvP battles require strategy, unique deck construction and clever wits to climb the ladder.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ppb.jpg', 'Role-playing (RPG), Strategy, Indie', 'Jeu video'),
(1225, 'Eydigard', 'Eydigard is a coop RPG drawing from Scandinavian and Sami folklore. As an adventuring shapeshifter, you\'re tasked to reclaim and cleanse farmlands infected by a relentless plague, while navigating the intricate politics of rival clans. Each decision impacts your path and the world around you.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kpk.jpg', 'Role-playing (RPG), Adventure, Indie', 'Jeu video'),
(1226, 'Dimensionals', 'Dimensionals is an RPG that combines fast paced, action packed tactics with deep rogue-like replayability. Collect powerful heroes and fight epic bosses. Every run is unique, so equip your heroes carefully to pull off insane combos. Dimensionals is a total reimagining of the rogue-like genre!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vyu.jpg', 'Role-playing (RPG), Strategy, Turn-based strategy (TBS), Adventure, Indie', 'Jeu video'),
(1227, 'Cosplay Club', 'In this tactical turn-based RPG you\'ll embark on the journey of becoming a Magical Girl cosplayer! But don\'t let this journey fool you, because this is not just roleplaying: your costumes will give you real life powers, and the world\'s fate will be in your hands!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7g4o.jpg', 'Role-playing (RPG), Tactical, Adventure, Indie', 'Jeu video'),
(1228, 'Wizordum', 'Wizordum is a retro-inspired FPS with a focus on action and light puzzles. It blends the best features of classic fantasy shooters from the 90s with some modern aspects making it a unique experience. Take the role of a Cleric and fight against Chaos that roams the land - smash, burn and loot!', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qvz.jpg', 'Shooter, Puzzle, Indie', 'Jeu video'),
(1229, 'KreatureKind', 'KreatureKind is an approachable and wholesome Card Battler/Deck Builder game about helping monsters, rather than killing them.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39lq.jpg', 'Strategy, Adventure, Indie, Card & Board Game', 'Jeu video'),
(1230, 'Crypterion', 'Crypterion is an open-world visual novel in a distant future where anyone can rise to power—including you. As a new arrival in the Rimshot system, you are free to forge your own destiny, conquering space by mastery of trade, politics, celebrity status through galactic TV or... Other means.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co90sb.jpg', 'Simulator, Adventure, Indie', 'Jeu video'),
(1231, 'Approaching Infinity', 'A sci-fi turn-based, tile-based Traditional Rogue-Like of incredible scope, accessible to new players, challenging to experienced rogue-likers. Explore an infinite procedural open-world universe full of unique environments as you lead your ship and crew to victory or death. Okay, mostly death.', '2025-04-29', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ir7.jpg', 'Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1232, 'Crusader kings III: Khans of the Steppe', 'The winds sweep across the Great Steppe as you look over your people, preparing to ride toward the horizon in search of greener pastures, lands to conquer, and new treasures to claim. In Khans of the Steppe, the second Core Expansion for Crusader Kings III, the nomadic life takes center stage, offering a rich tapestry of new challenges and opportunities. Become — or defeat — the Great Khan as you harness the unique powers of the nomads, navigate the ever-changing Steppe Seasons, and bend the world to your will.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tuo.jpg', 'Real Time Strategy (RTS), Role-playing (RPG), Strategy', 'Jeu video'),
(1233, 'Glamour Riot', 'This is an absurd and hilarious action game where you play as a beauty pageant contestant. Ruthlessly beat up your rivals backstage while delivering flawless performances on stage. Ruin their faces, knock them out, and impersonate them to sabotage everything. You’ll become the beauty queen!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ror.jpg', 'Fighting', 'Jeu video'),
(1234, 'Hidden Capybaras with Orange: Collection', NULL, '2025-04-28', '', 'Puzzle, Arcade', 'Jeu video'),
(1235, 'Helluva Brawl', 'This is based on the online cartoon series \"Hazbin Hotel\" and \"Helluva Boss\" by Vivienne Medrano. You can play as the original I.M.P. trio or two new fan characters - Harley and Coco - to defeat Valentino!\n\nUse guns, martial arts, shurikens, your bare hands, horns or hooves or anything else necessary to pummel your way to the V Tower and rescue Toni - an imp kidnapped by Valentino, and he\'s not going to let you get to her easily.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rvp.jpg', 'Fighting, Platform, Adventure, Indie', 'Jeu video'),
(1236, 'Councell for the Best Death', NULL, '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r4k.jpg', NULL, 'Jeu video'),
(1237, 'Pharabis', 'Hidden in the cursed pyramid, a powerful mask awaits. It controls the elements, but only Pharaohs can use it. Many have tried to find it, but none have returned. Will you be the one to uncover its secret?', '2025-04-28', '', 'Adventure, Indie', 'Jeu video'),
(1238, 'Plaything', 'You wake up in a deranged captor\'s dungeon, treated as a prized plaything. He subjects you to deadly games testing your worthiness—failure means death, success could add you permanently to his collection. Your only chance is to escape, but beware: getting caught trying means certain doom.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rap.jpg', 'Simulator, Adventure, Indie', 'Jeu video'),
(1239, 'Where They Wait', NULL, '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qv7.jpg', 'Indie, Visual Novel', 'Jeu video'),
(1240, 'The Anomaly Experiment', 'A Psychological Horror where you’re offered freedom by joining a trial for a new drug. The experiment is simple: enter the room, observe, and identify what has changed. Complete all tasks, and your sentence is commuted.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qxz.jpg', 'Adventure, Indie', 'Jeu video'),
(1241, 'Market Simulator', 'Build, manage, and dominate the retail world — from a humble shop to a thriving supermarket empire in Market Simulator.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qss.jpg', 'Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1242, 'Infinity Nikki: Bubble Season', 'The Sea of Stars stretches endlessly, where past, present, and future converge. The stars hold the truth—resonate with them, and receive their blessing.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r9h.jpg', 'Platform, Role-playing (RPG), Simulator, Adventure', 'Jeu video'),
(1243, 'Dawn of Ages', 'At the dawn of medieval history, build your castle and evolve your army using real weapons and armor from ages past. March against hostile civilizations as you re-trace the steps of history. Engage your rivals and crush their empires in battle!\n\n️No Dragons, No Magic, Not Now, Not Ever.\n\nDawn of Ages is a game that’s grounded in historical accuracy. No fantasy creatures, no mystical spells, just real, historical empires and war strategy games like no other. Every weapon, armor, and tactic you use is based on the reality of ancient battlefields.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9puy.jpg', 'Strategy', 'Jeu video'),
(1244, 'Helluva Brawl', 'This is based on the online cartoon series \"Hazbin Hotel\" and \"Helluva Boss\" by Vivienne Medrano. You can play as the original I.M.P. trio or two new fan characters - Harley and Coco - to defeat Valentino!\n\nUse guns, martial arts, shurikens, your bare hands, horns or hooves or anything else necessary to pummel your way to the V Tower and rescue Toni - an imp kidnapped by Valentino, and he\'s not going to let you get to her easily.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9psu.jpg', 'Hack and slash/Beat \'em up', 'Jeu video'),
(1245, 'Idle Farming Business', 'Build your farm empire', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9oae.jpg', 'Simulator', 'Jeu video'),
(1246, 'V Rising: Invaders of Oakvale', NULL, '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9nm2.jpg', NULL, 'Jeu video'),
(1247, 'Combolite', 'In this satisfying roguelike deckbuilder, every weapon you buy matters! Strategically order them to trigger powerful combos, send the enemy flying with physics-based hits, and watch your damage reach MILLIONS and above!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9moc.jpg', 'Strategy, Indie', 'Jeu video'),
(1248, 'A.C.E', NULL, '2025-04-28', '', NULL, 'Jeu video'),
(1249, 'Flibbius McDoogle and the Mysterious Flying Machine', 'Flibbius McDoogle and the Mysterious Flying Machine is a short adventure puzzle game. Use your wits, creativity and puzzle solving ability to help Flibbius take to the skies!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9oiw.jpg', 'Puzzle, Adventure', 'Jeu video'),
(1250, 'Medieval Legacy', 'Start as a humble commoner and guide your family through generations in this family sim meets city builder. Climb the ranks of society to become the most influential family in the land. With wit, strategy, and a bit of luck, build your legacy - just try not to trip over your ambition!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ran.jpg', 'Simulator', 'Jeu video'),
(1251, 'Govnovoz', 'Become the king of the sewage business in this insane mix of racing, arcade mini-games, and a hilarious storyline! Transport passengers in your vacuum truck, drift through chaotic races, fend off a wicked utility worker, and uncover a conspiracy tied to ancient otherworldly forces.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mjb.jpg', 'Racing, Indie', 'Jeu video'),
(1252, 'There\'s No Dragons', 'There\'s No Dragons is a hidden object game with a selection of 9 locations and random dragons to find for each of them.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dy7.jpg', 'Point-and-click, Puzzle, Indie', 'Jeu video'),
(1253, 'Office Simulator', 'Ready to climb the career ladder? In Office Simulator, start as an intern and rise through the corporate ranks. Gain experience, earn promotions, and when the time comes, launch your own company to begin a new business adventure.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co96on.jpg', 'Simulator, Indie', 'Jeu video'),
(1254, 'Kaamos', 'Kaamos is a bite-sized turn-based puzzle roguelike where battles are fought by matching tiles on a grid with looping rows and columns. Build your character and deck of tiles by looting equipment from your foes. Traverse a dark medieval world where the Sun went down and never rose again.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gcx.jpg', 'Role-playing (RPG), Strategy, Adventure, Indie', 'Jeu video'),
(1255, 'Cargo', 'Cargo is a space shooter where you collect packages from planets and try to deliver them to other planets without being killed.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99f4.jpg', 'Simulator, Strategy, Indie', 'Jeu video'),
(1256, 'Card Summoner', 'Card Summoner is a CCG, where you journey to various villages and engage in local clan tournaments to elevate your rank. Duel villagers and collect unique cards while fulfilling your summoner duties by battling monsters in the void dungeons.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8jnr.jpg', 'Role-playing (RPG), Simulator, Strategy, Adventure', 'Jeu video'),
(1257, 'Soar: Pillars of Tasneem', 'Experience a beautiful world of floating islands through the eyes of a dragon', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7z2c.jpg', 'Adventure, Indie', 'Jeu video'),
(1258, 'Miro', 'Explore vibrant worlds while uncovering the mysteries of your origin. Overcome the dangers that await you in the vast unknown fields of unexplored planets. The truth reveals itself to those who seek, but remember that your destiny depends solely on you.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co81t5.jpg', 'Adventure, Indie', 'Jeu video'),
(1259, 'Collateral Dungeon', 'Collateral Dungeon is a tactical puzzle dungeon crawler. Explore as an archaeologist trapped in your most recent dig: an enemy-infested dungeon. However, you are a lover, not a fighter. Without weapons, you must turn to your wit and clever traps to defeat enemies lest you relive your failings.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vvq.jpg', NULL, 'Jeu video'),
(1260, 'Warfare Legacy Collection', 'Warfare 1917 and Warfare 1944, updated for modern hardware, join forces in Warfare Legacy Collection. Experience the intense tug-of-war of WW1 and WW2 and engage in strategic battles that defined an era. Command waves of troops, unleash tactical prowess, and even customize your own battlefields!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7sfk.jpg', 'Simulator, Strategy', 'Jeu video'),
(1261, 'Kingdom\'s Deck', 'Kingdom\'s Deck is a city-builder and deck-builder game where you embark on a journey to transform your humble hamlet into a formidable empire. Deploy your cards wisely, defend your walls from sieges, manage your resources, respond to various exciting events, and create the ultimate Kingdom\'s deck!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kgv.jpg', 'Role-playing (RPG), Simulator, Strategy, Indie', 'Jeu video'),
(1262, 'Navigating the Labyrinth', 'Navigating the Labyrinth is a classic first-person party-based dungeon crawler RPG with grid-based movement and turn-based combat. Discover the secrets and riches of the labyrinths, and save your dying city.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9f8w.jpg', 'Role-playing (RPG)', 'Jeu video'),
(1263, 'Mythical Concept Starnaut', '\"STARNAUT\" is an easy-to-learn, hard-to-master \"survivor-like\" game from the creators of El Shaddai: Ascension of the Metatron, that emphasizes massive Nitro Jumps and Dashes, evading with verticality, synergizing extremely powerful weapons, deep and considered lore, satire, and of course, the strongest force in the universe....love!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9suy.jpg', 'Indie', 'Jeu video'),
(1264, 'Icaria', 'Automate a team of robots to gather resources, scale up production, reshape terrain, and expand your colony on a procedurally generated alien world.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8eer.jpg', 'Simulator', 'Jeu video'),
(1265, 'Private Military Manager: Tactical Auto Battler', 'You are the CEO of a private military company. Recruit capable mercenaries, purchase weapons, and develop your mercenaries according to their roles and characteristics. Observe how your mercenaries perform in combat and plan your tactics to ensure mission success.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99j2.jpg', 'Simulator, Strategy, Tactical', 'Jeu video'),
(1266, 'Skogdal', 'Skogdal is the rock \'n roll deckbuilder adventure game about a crazy Norwegian town during the 90\'s. Draft cards, recruit followers and explore the town across multiple runs. Why have the people of Skogdal gone mad? Play cards and find out!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ygs.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1267, 'Badlands Crew', 'Create, customize and command your battle wagon to conquer crazed enemy factions and save innocent survivors scattered throughout the lawless Badlands in the aftermath of a devastating apocalypse. Do you have what it takes to Build, Evolve and Fight to survive?', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8odg.jpg', 'Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1268, 'Castle Craft', 'Castle Craft is a game where players build huge castles in an ancient war-torn world and defend them against hordes of enemies in chaotic siege battles of epic proportions. Castle Craft is a unique blend of voxel sandbox, action, and horde defence.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ozp.jpg', 'Simulator, Strategy, Hack and slash/Beat \'em up', 'Jeu video'),
(1269, 'Xion Leak', 'Cooperate quickly as a duo and set the fastest times to win the trophies! Escape before the Xion gas fries your precious circuits! Run fast, be in sync, and avoid the countless dangers that the mysterious Foreman has placed in your path.', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88d5.jpg', 'Adventure, Indie', 'Jeu video'),
(1270, 'Age of Reforging: The Freelands', 'Welcome to medieval high-freedom sandbox adventure CRPG!You\'ll be a reforger in freelands chosen by the Goddess to embark on medieval adventure tour at your own pace, gathering teammates, seeking survival, and craft your unique legend!', '2025-04-28', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qvs.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1271, 'The Heart of Influencer', NULL, '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rng.jpg', NULL, 'Jeu video'),
(1272, 'Snekburd', 'Snekburd is a Pico-8 demake of Snakebird, by Noumenon Games, with new puzzles and mechanics! Navigate the snakebirds to eat all the fruit and head through the portal to complete the levels on each island. The first island\'s levels should serve as a quick tutorial to new players or a refresher for returning ones.\n\nThe full game has about 70 levels in it, ranging from a little tricky to absurdly hard, and is available for free (donations enabled with Noumenon Games\' permission).', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r9e.jpg', 'Puzzle', 'Jeu video'),
(1273, 'Blitz: Race Against Time', 'A 32 map megawad created by the Russian Doom community, featuring maps of various themes and gameplay styles, all centered around a single concept: The exit permanently closes after 30 seconds.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r5r.jpg', 'Shooter', 'Jeu video'),
(1274, 'Hell Froze Over', 'In this puzzle game you freeze the enemies into solid cubes by guiding them to an Ice Crystal. Move the enemies around and match them into lines of 3 or more to destroy them. Finish all 21 levels of mind-bending puzzle!', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r6o.jpg', 'Puzzle', 'Jeu video');
INSERT INTO `oeuvre` (`idOeuvre`, `titre`, `synopsis`, `dateSortie`, `couverture`, `genres`, `type`) VALUES
(1275, 'Let\'s Meet Tomorrow', 'After countless nights spent talking online, you’re finally meeting Silas, the friend who made you laugh, listened to your secrets, and quietly stole your heart. He\'s visiting your country for a few days, and you’re determined to make every moment count. Maybe even confess how you really feel.', '2025-04-27', '', NULL, 'Jeu video'),
(1276, 'Keep of the Knights', 'Keep of the Knights is a battle simulator game where you can battle hordes of barbarians and other monsters. Upgrade your armor and weapons, hire allies, and, of course defend your keep!!!', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qri.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1277, 'Sword Tale: Lost Excalibur', 'Sword Tale: Lost Excalibur is an Action-Adventure game. It can be played using both a mouse and keyboard. Players embark on a journey to help a mysterious girl escape from a group of knights intent on harming her.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qqb.jpg', 'Adventure, Indie', 'Jeu video'),
(1278, 'Pipeline Crawl', 'Trapped inside a narrow pipeline, your only choices are to move forward or backward. Deadly obstacles stand in your way, and a single mistake means starting over. Can you escape?', '2025-04-27', '', 'Indie', 'Jeu video'),
(1279, 'Thrice Cursed', 'A roguelike game with Souls-style combat. Fight with a customised character through quests in a random order with randomised loot. Your character\'s build will be influenced by what you can find or buy. Every run feels a little different.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qqa.jpg', 'Role-playing (RPG), Adventure, Indie', 'Jeu video'),
(1280, 'Forgot to Poo', 'A dog that forgot to poo trying to poo at it\'s favorite poo place.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qpa.jpg', 'Platform, Adventure, Indie', 'Jeu video'),
(1281, 'Labyban', 'Liuri wakes up, alone, deep inside a mine on an abandoned floating island. He doesn’t know how he got there or why. There’s only one thing to do: explore.\n\nA tribute to the timeless Sokoban genre, LABYBAN modernizes the puzzle game experience with an accessible, intuitive, and stimulating approach. Across more than 140 levels, each puzzle pushes the gameplay mechanics even further.\n\nTeleporters, slippery surfaces, conveyor belts... and many more surprises await!\n\nThe world of LABYBAN is made up of seven distinct biomes, each with a strong visual identity and unique gameplay mechanics. Some introduce new ways to play, while others combine and transform previous challenges, ensuring a smooth and varied progression.\n\nWill you manage to escape the island?', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sv5.jpg', 'Puzzle, Adventure, Indie', 'Jeu video'),
(1282, 'Demon Corporation: Onboarding', 'This game is a strategy RPG with the theme of anti-work from 9 am to 9 pm, six days a week. The gameplay inherits from the classic \"Magic Tower\" series, combining elements such as pigeons and BD combinations. Please play with caution under the age of 35 to avoid dissing and hurting the boss!', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9iig.jpg', 'Role-playing (RPG), Indie', 'Jeu video'),
(1283, 'Sunken Veins', 'Sunken Veins is a resource management horror game where you mine for coal and survive against monsters in an underwater coal mine. Keep the furnace powered, drain away water and repair leaks within the facility to complete your shift on time.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qn8.jpg', 'Strategy, Indie', 'Jeu video'),
(1284, 'Propa.', 'In this RTS game, control your virus to replicate and evolve against a powerful immune system. Equip gene segments to create unique viral armies. Use tactics to eliminate immune cells or achieve escape. Develop strategies for domination and enjoy endless strategic fun!', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co96kz.jpg', 'Simulator, Strategy', 'Jeu video'),
(1285, 'Cats and Seek: Tokyo', 'The 4th Cats and Seek series is here! We\'re off to Tokyo to find cats playing all around the city . Can you spot them all?', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rb6.jpg', 'Indie', 'Jeu video'),
(1286, 'Hexdo', 'Ever wanted to be a light and purify the world from evil spirits? Well, I hope you already are, but if not, you can play as one! Hexdo is a simple puzzle game. There is no score, no quests, no save games, you can just play through an endless stream of levels while listening to relaxing music.', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8q87.jpg', 'Indie', 'Jeu video'),
(1287, 'Ninjam!', '\"Ninjam! is a multiplayer action game for up to 4 players where cute ninja characters move freely and compete against each other on a 3D map.\"', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co982p.jpg', 'Indie', 'Jeu video'),
(1288, 'Premier Servi', 'Eat the cake before your friends without getting spotted ! Premier Servi (First Arrived, First Served) is a colorful Party Game featuring delicious French Pastry', '2025-04-27', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8el1.jpg', 'Racing, Strategy, Indie', 'Jeu video'),
(1289, 'Only Up 3', 'After reaching the heights of the favelas, Jacky embarks on a spaceship that takes him straight to Grekko Island; but as soon as he arrives on this new planet he will have to start an ascent to the skies in this new ONLY UP .', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s29.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1290, 'The Cursed Garden', 'I was an ordinary caretaker of a quiet garden, routine nights, sounds of nature, and nothing to worry about...\n\nUntil he came that night.\n\nStrange sounds, shadows moving on their own, and symbols carved into trees that never existed before.\n\nThe calm turned into a nightmare. And the garden... is no longer what it was.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rqk.jpg', NULL, 'Jeu video'),
(1291, 'Bootleg in Wonderland: Pastel Paradise', 'Bootleg rookie magician Yuuto Ichika finds herself lost in a strange, yet familiar world, only to be found by the young magician Alice.\n\nWhat adventures await them in Wonderland?\n\nJourney with Yuuto and Alice through a bullet hell adventure in Bootleg in Wonderland ~ Pastel Paradise!\n\nThis game was made in two weeks for the Touhou FnC Jam - Moriya Cleaning Game Jam!', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rhf.jpg', 'Shooter, Indie, Arcade', 'Jeu video'),
(1292, 'Splatter Blocks', NULL, '2025-04-26', '', 'Simulator, Strategy, Arcade', 'Jeu video'),
(1293, 'Internet Club & Cafe Simulator', NULL, '2025-04-26', '', 'Simulator, Adventure', 'Jeu video'),
(1294, 'Fantasy Grove', NULL, '2025-04-26', '', 'Adventure, Arcade', 'Jeu video'),
(1295, 'Cozy Tides', NULL, '2025-04-26', '', 'Adventure, Arcade', 'Jeu video'),
(1296, 'Paperents', 'After moving into their new home, 10-year-old Liam begins to sense an unsettling presence lurking in the dark corners of his room.\n\nStrange noises echo through the house, and his parents grow increasingly bizarre and terrifying.\n\nParalyzed and confined to his bed, Liam finds himself trapped in a room filled with unspeakable horrors, slowly sinking into endless desperation.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rb9.jpg', NULL, 'Jeu video'),
(1297, 'Toy Drop Balance Challenge', 'Toy Drop Balance Challenge is an endless arcade game that tests your precision and balancing skills. Toys drop from above, landing on a tower of blocks. Your goal? Tap to destroy blocks, score points, and keep the tower balanced. The higher the score, the greater the challenge how long can you keep your tower standing?', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r6n.jpg', 'Puzzle', 'Jeu video'),
(1298, 'Nip For Speed 2: Search For Pussy', 'On still waters with a dog at the wheel, a catnip trace ahead. Mist, moonlight, and the unknown—what could be out there?', '2025-04-26', '', 'Indie', 'Jeu video'),
(1299, 'Abyssal Trench', 'Abyssal Trench is a first-person underwater horror game where you play as a lone explorer waking from cryo-sleep after a failed mission. With your pod out of fuel and your crew gone, a mysterious AI voice guides you to collect data from three abandoned drilling sites deep beneath the ocean.', '2025-04-26', '', 'Simulator, Adventure, Indie', 'Jeu video'),
(1300, 'Submeris', 'Submeris is an underwater mining adventure set beneath a mysterious island. Dig, upgrade your gear, survive dangerous depths, and uncover the legendary treasure hidden far below the ocean floor!', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qp9.jpg', 'Simulator, Strategy, Adventure, Indie', 'Jeu video'),
(1301, 'Goofy Lil Guys', 'In this action real time local PvPvE game, players will collect a team of adorable creatures and harness their unique abilities in order to grow stronger before the final fight to the death. 2-4 local players can engage in this cute spin of split-screen battleroyale creature collection.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qmm.jpg', 'Indie', 'Jeu video'),
(1302, 'Deductopia Chapter 1: Bring Your Pet to School Day', 'Can you sort out this chaotic classroom? Six kids, six pets, six desks--but whose is whose? Drag the right names and pictures to the right desks to win!', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9i4o.jpg', 'Adventure', 'Jeu video'),
(1303, 'Void Collector', 'Void Collector is a fast-paced first person shooter with a unique weapon switching system and a focus on speedrunning.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tod.jpg', 'Shooter, Platform, Indie', 'Jeu video'),
(1304, 'Rise & Fall: Online Digital Edition', 'Risse & Fall is a game involving strategic units positioning, territory control and opportunity seizing designed by Christophe Boelinger (Dungeon Twister, Earth Reborn, Archipelago, Living Planet...). Each player leads a nation trying to expand and progress in a fantasy world.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8d69.jpg', 'Strategy', 'Jeu video'),
(1305, 'Stress Ball', 'Experience the blend of fun and challenge with Stress Ball! In this 3D ball game, your character bounces through platforms toward the goal. As levels intensify, and a dark theme adds depth to the atmosphere, immerse yourself in the thrill of overcoming increasingly difficult obstacles.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7q2g.jpg', 'Adventure, Indie', 'Jeu video'),
(1306, 'Dinosaur World', 'Dinosaur World is a survival game about dinosaurs. You can tame and hunt dinosaurs, ride them, grow crops, craft a variety of weapons, build houses and furniture.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wo0.jpg', 'Adventure, Indie', 'Jeu video'),
(1307, 'MiniWarfare', 'MiniWarfare is a stylized tactical third-person shooter where two military outposts battle to take control of all nuclear access codes needed to wipe out the enemy team. Explore the island, loot, trade, complete tasks, and collect airdrops to obtain better gear and give your team a major advantage.', '2025-04-26', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5les.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1308, 'A Blackout Protocol Report', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9twr.jpg', NULL, 'Jeu video'),
(1309, 'The Jumping Cheese Maze', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9syq.jpg', NULL, 'Jeu video'),
(1310, 'Paper Plane', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sas.jpg', 'Simulator, Arcade', 'Jeu video'),
(1311, 'Tank Operations: Diary of the War', 'Experience World War II\'s defining battles from a new perspective! In Tank Operations: Diary of the War, you command Allied forces through intense, turn-based warfare. Master battlefield tactics, upgrade your troops, and face an expansive campaign.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rxd.jpg', 'Strategy, Turn-based strategy (TBS)', 'Jeu video'),
(1312, 'Under the Streetlights of the Reiche', '\"Under the Streetlights of the Reiche\" is an omnibus-style adventure game. Experience one man\'s last day in the town. A good man who is well-liked by those around him loses his job and is forced to leave the town he has lived in for a long time.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rv6.jpg', 'Adventure, Indie', 'Jeu video'),
(1313, 'Hydra: Poseidon\'s Сonspiracy', 'An agent probing a Third Reich bunker on a desolate island faces a survival horror nightmare. Battle deep-sea monsters in FPS or TPP camera mode. Forge your fate with 5 unique endings in a chilling descent into cosmic dread.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rk7.jpg', 'Shooter, Puzzle, Adventure', 'Jeu video'),
(1314, 'Hero Collection 3 in 1', NULL, '2025-04-25', '', NULL, 'Jeu video'),
(1315, 'Spy Guy Jigsaw Fun', NULL, '2025-04-25', '', 'Puzzle, Adventure', 'Jeu video'),
(1316, 'Monster Survivors', NULL, '2025-04-25', '', 'Adventure', 'Jeu video'),
(1317, 'Magic Valley Hike', NULL, '2025-04-25', '', 'Adventure, Arcade', 'Jeu video'),
(1318, 'Korean Drone Flying Tour Donggeom-do', NULL, '2025-04-25', '', 'Simulator, Arcade', 'Jeu video'),
(1319, 'Korean Drone Flying Tour Ilsan Lake Park', NULL, '2025-04-25', '', 'Simulator, Arcade', 'Jeu video'),
(1320, 'Euro Car Parking Simulator 2025', NULL, '2025-04-25', '', 'Racing, Simulator, Sport', 'Jeu video'),
(1321, 'Extreme Ride Legacy', NULL, '2025-04-25', '', NULL, 'Jeu video'),
(1322, 'Clothes & Outlet Supermarket Store Simulator', NULL, '2025-04-25', '', 'Simulator, Adventure', 'Jeu video'),
(1323, '8Floor Bundle 4 in 1 part 8', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r83.jpg', NULL, 'Jeu video'),
(1324, 'Builder Liquidator Bundle', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r82.jpg', NULL, 'Jeu video'),
(1325, 'Frozen Way Tri-Bundle', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r7z.jpg', NULL, 'Jeu video'),
(1326, 'Hairdresser Liquidator Bundle', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r80.jpg', NULL, 'Jeu video'),
(1327, 'Akinakes', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r7r.jpg', 'Shooter', 'Jeu video'),
(1328, 'Urban Showdown', NULL, '2025-04-25', '', 'Fighting, Arcade', 'Jeu video'),
(1329, 'Sky Revolver', 'Sky Revolver is a guns blazing old-school shoot-em-up game just like they did in ‘90s! You play as a hotheaded space pilot destined to destroy the evil Empire. Your main goal is to survive through the endless waves of enemy spaceships and shuttles and to defeat the high command!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r5x.jpg', 'Shooter, Arcade', 'Jeu video'),
(1330, 'Goddess Krypton Gold System', NULL, '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qrt.jpg', NULL, 'Jeu video'),
(1331, 'Dead Hourz', '\"Dead Hourz\" is a thrilling survival adventure set in a post-apocalyptic world. In a land ravaged by zombies, bandits, and scarcity, you must protect your family by gathering resources and making tough choices.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qs7.jpg', 'Simulator, Adventure, Indie', 'Jeu video'),
(1332, 'Shimagami', 'Shimagami is an open-world RPG with anime-style visuals and deep lore. Battle fierce monsters in action combat, solve puzzles, and conquer challenges to uncover the mysteries of Shimagami. A diverse cast of demi-human heroines awaits—find your perfect companion and shape your adventure!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qrj.jpg', 'Adventure, Indie', 'Jeu video'),
(1333, 'SignaNota', 'As the fallen god, \'Signa,\' leave a myth of light on this land. We introduce you \'SignaNota\'. A roguelike slingshot adventure game that you can simply enjoy.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qr5.jpg', 'Role-playing (RPG), Adventure, Indie', 'Jeu video'),
(1334, 'Aooni: The Horror of Blueberry Onsen', 'Challenge yourself while being chased by fear! A horror puzzle action adventure! A completely new version of the legendary horror game \"Ao Oni\"!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qkk.jpg', 'Puzzle, Role-playing (RPG), Adventure, Indie', 'Jeu video'),
(1335, 'Friday Night Funkin\': vs Impostor', 'What started as a passion project has now evolved into a complete overhaul of the iconic VS IMPOSTOR mod. Codenamed UPDOG, this brand-new version is a full-on reimagining built from the ground up. Every aspect, from visuals to vocals, has been carefully redesigned to fully reach the potential it once had.\n\nWhether you’re a longtime fan or a total newcomer, VS IMPOSTOR delivers a fresh experience! with new remixes of classic songs, completely overhauled visuals, a brand new menu, and maybe even a few secrets.', '2025-04-25', '', 'Music', 'Jeu video'),
(1336, 'Little House', 'Waking up from an unknown dream you enter your house, only to find that everything is not as it should be. Now you must explore, solve surreal and challenging puzzles and encounter strange beings as you search for your house... inside your house!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qhm.jpg', 'Puzzle, Adventure, Indie', 'Jeu video'),
(1337, 'Vietnam War', 'Open world single-player FPS. Command your squad in battle across jungles, hills and villages of Vietnam. Fight as U.S or Vietcong. Vast arsenal of weapons and 50+ vehicles', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qor.jpg', NULL, 'Jeu video'),
(1338, 'The Ghost of Alcantra', 'The Ghost of Alcantra is a free kinetic romance/mystery vn that alternates between two perspectives, one focusing on a blossoming romantic relationship, and another focused on unraveling a murder mystery.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qp4.jpg', 'Simulator, Adventure, Indie, Visual Novel', 'Jeu video'),
(1339, 'Overseer', 'The Overseer, a being who watches over the souls of the land. After gifting life to yet another lost spirit, it sets out into the world. What is his will? What does he wish to change in this land? What does this mean to the spirit and their kin?\n\nTo humanity, these spirits are mere demons; monsters set on their destruction. Perhaps this is their will, but perhaps not. Venture forth into this dying world and decide for yourself.\n\nThis is a story for you to witness and interpret.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tfk.jpg', 'Platform, Adventure', 'Jeu video'),
(1340, 'Koegasuru', 'Create your own music video by controlling Hatsune Miku! When you solve the 4 riddles, a music video will be created of you solving the riddles! It is an escape room game set in the music video \"KOEGASURU\" by TEMPLIME!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qfm.jpg', 'Adventure, Indie', 'Jeu video'),
(1341, 'Hispalis Cardgame', 'Developed by the creators of the original fangame, this app will be updated and growing every month with new updates.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qhv.jpg', 'Card & Board Game', 'Jeu video'),
(1342, 'Sunseed Island', 'Welcome to Sunseed Island, a calming farming simulation where you create your own magical paradise. Grow crops, build up your farm, and rebuild your village, while discovering the secrets of the Tree of Life. This cozy experience lets you settle into a slow rhythm, whether you want to explore the sunny island archipelago or simply relax while tending to your land.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qei.jpg', 'Puzzle, Simulator, Adventure, Indie, Arcade', 'Jeu video'),
(1343, 'At Death\'s Door', 'At Death\'s Door is a psychological horror game focused on eerie exploration and puzzle-solving. As a ghost hunter in an abandoned psychiatric hospital, use specialized tools to capture paranormal evidence and save your TV show, all while navigating atmospheric, non-linear environments.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qcf.jpg', NULL, 'Jeu video'),
(1344, 'To Find Her', '《寻踪》is an immersive adventure puzzle game with simple controls, perfect for beginners. ,crack codes, solve literary puzzles, and evade capture. With over 10 gameplay elements and a micro-horror atmosphere, the game offers a thrilling experience as you uncover the truth behind a girl\'s disappearance.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qsa.jpg', 'Strategy, Adventure, Indie', 'Jeu video'),
(1345, 'Killer Karnival', 'Killer Karnival is a first-person survival horror stealth game ​where players are trapped in an abandoned carnival ​and hunted by killer clowns, each with unique senses. The player must escape by solving puzzles while remaining hidden to avoid becoming the carnival\'s next victim.', '2025-04-25', '', 'Strategy, Adventure, Indie', 'Jeu video'),
(1346, 'Misuzu no Kuni', 'Made as a promotion for Kirin no Kuni. Gold prize in the 10th Freem! Game Contest.\n\nOne day, Misuzu ceased to be human. According to legal jurisdiction, she had become a Tengu.\n\nShe had two options in front of her: Live the rest of her life under government surveillance and have all her basics freedoms stripped away from her, or venture onwards to the realm of the Tengu.\n\nThis is a story of hardships, setbacks, farewells and chances encounters. This is Misuzu\'s story.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9q5v.jpg', 'Adventure, Indie, Visual Novel', 'Jeu video'),
(1347, 'Captain Edward Continues', 'Want to continue playing as a time traveling pirate? Now is your chance with Captain Edward Continues. 100s of cutscenes, jokes, and other oddities to make you and your friends laugh. Want to just shoot robots, goblins, and gang members? You can do that, too!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qhw.jpg', 'Adventure, Indie', 'Jeu video'),
(1348, 'Beaver Rampage', 'BEAVER RAMPAGE is a crazy game about a killer beaver! Bite humans, cut trees, build bridges, destroy stuff, shoot guns, dodge traps, and wear funny hats. Low poly style, low system requirements, save system, and frequent updates with new levels!', '2025-04-25', '', 'Simulator, Adventure, Indie', 'Jeu video'),
(1349, 'Enormosword', 'The prequel to the redeveloped Ginormo Sword. An early showcase of what is to come.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9py0.jpg', 'Point-and-click, Role-playing (RPG), Hack and slash/Beat \'em up, Adventure, Indie', 'Jeu video'),
(1350, 'Schedule I: Drug Empire', 'Step into the shadows of a world where power is taken, not given. In this underground simulator, you\'re building more than a business—you\'re creating an empire from nothing. No cash, no allies—just ambition, strategy, and the will to rise. Every move matters. Every mistake leaves a mark.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9swh.jpg', 'Simulator', 'Jeu video'),
(1351, 'Colorful Boi 2', 'Get ready for a pulse-pounding platforming challenge in Colorful Boi 2! With 74 meticulously designed levels, you\'ll test your reflexes, precision, and patience against a gauntlet of devious traps and hazards.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r6k.jpg', 'Arcade', 'Jeu video'),
(1352, 'Mortality Decomp. Killers', 'MORTALITY DECOMP. KILLERS is a short, fast-paced 3rd person horror/comedy hybrid of games like Hotline Miami and Post Void, with hand-drawn visuals inspired loosely by retro detective comics. You\'ll step into the well-polished shoes of Clive, an undead detective working to take down the criminals that initially killed him.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mei.jpg', 'Shooter, Indie', 'Jeu video'),
(1353, 'Atari Arcade 2', 'Enjoy 10 classic early ’80s arcade games from Atari on Evercade, including the legendary Berzerk and its sequel Frenzy, plus cult favourites like Maze Invaders, Fire Truck and more!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lxx.jpg', NULL, 'Jeu video'),
(1354, 'The Junkyard', 'Explore a network of tunnels that lead to several different rooms. There are various creatures to frighten and hinder you, which grow stronger and more numerous. Defeat bosses. Experience the dramatic and mysterious plot of the life of Joseph, the main character, but be careful not to go mad...', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lmx.jpg', 'Shooter, Adventure, Indie', 'Jeu video'),
(1355, 'I Commissioned Some Snails 2', 'I paid artists to hide snails and lettuce in 15 more artworks. Can you find them all? Warning: Relaxing.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9l21.jpg', 'Indie', 'Jeu video'),
(1356, 'Supermarket CEO Simulator', 'Supermarket CEO Simulator – Build your retail empire and become the market leader!\nTake charge of your own business and turn a small store into a thriving supermarket chain! In Supermarket CEO Simulator, you have full control over every aspect of supermarket management – from stocking shelves and hiring staff to marketing and expanding your business. The competition is fierce, and customers have high expectations – do you have what it takes to become a retail mogul?', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r6m.jpg', 'Simulator, Strategy', 'Jeu video'),
(1357, 'The Whispering Woods', 'Detective Lukas Berger is investigating the sudden disappearance of several residents from a remote village. Clues are scarce until he receives a call from his colleague John: an abandoned house deep in the forest might hold the key. But as Lukas arrives, he quickly realizes that something is not right. Dark shadows, unexplainable noises, and an eerie presence await him.\n\nExplore the mysterious house in this first-person horror game and face the unknown. Solve challenging puzzles and uncover the truth behind the disappearances – but beware: some secrets are better left undiscovered...', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kbu.jpg', 'Adventure, Indie', 'Jeu video'),
(1358, 'Soldiers From The Sky', 'A real-time strategy game that does not require micro operations', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hwh.jpg', 'Strategy, Indie', 'Jeu video'),
(1359, 'Bubble Battle', 'Bubble Battle is a retro online/local multiplayer fighting game inspired by arcade classics. Players fly around with one simple objective: burst opponents’ bubbles before they burst yours. Collect powerups and out-maneuver opponents for fast-paced, addictive fun!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9h8u.jpg', NULL, 'Jeu video'),
(1360, 'Magic Rune Stone', 'An action-packed rogue-lite adventure game where you will play different roles with different equipment and blessings. With the blessing of treasures, you will constantly challenge powerful enemies and kill bosses.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9l88.jpg', 'Adventure, Indie', 'Jeu video'),
(1361, 'Tomb Raider Collection 2', 'The legend of Lara Croft continues on Evercade! Uncover an ancient Egyptian mystery and prevent the end of the world in Tomb Raider: The Last Revelation, and relive a series of Lara’s most noteworthy adventures from her past in Tomb Raider: Chronicles. Also includes a brand-new version of a special bonus level, previously only distributed for home computers.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9glz.jpg', 'Shooter, Platform, Puzzle, Adventure', 'Jeu video'),
(1362, 'Cardinal Sequence', 'Cardinal Sequence is a relaxing sci-fi deckbuilder where you play cards by matching patterns, assemble game-changing synergies and watch your score reach into the stratosphere and beyond.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ldx.jpg', 'Strategy, Indie', 'Jeu video'),
(1363, 'Fuel Harvest Together', 'Play solo or co-op with up to 5 players to find oil, store crude, refine fuels, and sell them at gas stations and shop. Dig for gems and fossils, upgrade your gear, lease new land, and dominate the city as the biggest oil supplier!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kjb.jpg', 'Simulator, Indie', 'Jeu video'),
(1364, 'Cauldron\'s Rift', 'A chaotic platform arena brawler where you can use rifts to gain new weapons or unlock quirky abilities, all while using the environment to your advantage.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gq5.jpg', 'Shooter, Platform, Hack and slash/Beat \'em up, Indie', 'Jeu video'),
(1365, 'Days Gone: Broken Road', 'Days Gone – Broken Road DLC is an expansion to Days Gone, an open-world action-adventure game set in a harsh wilderness two years after a devastating global pandemic. Days Gone – Broken Road DLC features all new content and features that will enhance your Days Gone experience as you fight for tomorrow in this brutal relentless world.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9e5t.jpg', 'Adventure', 'Jeu video'),
(1366, 'Days Gone Remastered', 'Ride into a desperate, dog-eat-dog world in the definitive Days Gone experience, remastered for the PlayStation5 console.\n\nFight to survive an environment ravaged by a deadly pandemic as former outlaw biker, Deacon St. John. Risk the threats of the Broken Road on the back of your trusty Drifter bike as you face terrifying hordes of relentless feral Freakers – as well as dangerous gangs of humans.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9e1e.jpg', 'Shooter, Adventure', 'Jeu video'),
(1367, 'Dreamy Syrup', '\"Sato Ama,\" whom you met by chance at university, is an ardent fan of the virtual idol \"Amaha Shiroppu\" just like you! The two hit it off and go out together, talk about their favorite idols, and gradually become closer. However... \"I almost got found out.\" A certain comment made by Amaha Shiroppu during a stream raises a question: \"Could it be that Amaha Shiroppu is... Sato Ama?\" Will you witness the virtual idol \"Amaha Shiroppu\" being found out? A thrilling love comedy where \"dreams\" and \"reality\" intersect!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dox.jpg', 'Simulator, Adventure, Visual Novel', 'Jeu video'),
(1368, 'Emergency Exit', 'Communicate. Cooperate. Escape. aEmergency Exit is an online cooperative escape/puzzle game with asymmetric gameplay. Separated and unable to see each other’s actions, players must cooperate to reach the exit before time runs out, solving puzzles and uncovering hidden secrets.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9b4m.jpg', 'Simulator, Indie', 'Jeu video'),
(1369, 'Vertigo 2: Into the Aether', 'Into the Aether is a story expansion for Vertigo 2. Embark on an interdimensional expedition to the oldest and most mysterious universe, discover new weapons and tools, and defeat fearsome new enemies.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ox7.jpg', 'Adventure, Indie', 'Jeu video'),
(1370, 'Space Menace 2', 'Start small, expand your fleet, rise to power, and eventually command entire factions in this seamless blend of sci-fi space RTS and battle game. With strategic gameplay and evolving challenges, every decision shapes your legacy in the stars.', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co955x.jpg', 'Real Time Strategy (RTS), Simulator, Strategy, Indie', 'Jeu video'),
(1371, '100 in 1 Game Collection', 'Meet Magrat the witch, Harvey the weird fish, Stephanie the green cow and all their beloved friends, and embark on an epic journey through 100 arcade games that blend classic gameplay from your favorite retro titles with new concepts that are reinventing the arcade genre! Score as much as you can, then improve and challenge yourself to get all stars in solo or with your friends!', '2025-04-25', 'https://images.igdb.com/igdb/image/upload/t_cover_big/co94hs.jpg', 'Arcade', 'Jeu video');
INSERT INTO `utilisateur` (`idUtilisateur`, `prenom`, `nom`, `email`, `motDePasse`, `numeroTel`, `condUtilisation`) VALUES
(2, 'Bouzid', 'Ghlamallah', 'bouzid.ghlamallah@lycee-pardailhan.fr', '$2y$10$yRGnrLLbuN06lDPgbvam9Os9oxD2IjSLZaH35sayJ4X1/FOOjn2la', '0768776846', 1),
(12, 'Elie', 'Bourguet', 'lucas.bourguet1@lycee-pardailhan.fr', '$2y$10$UOlWK6.tqmgpEnieUfQpeuIaHtyAqOhyB75.DpVfwMoMQ5w8teIhi', '', 1);
